// Объёмный режим: комната, по которой можно пройти.
//
// Требование G205, шаг первый (таск 146). Слова заказчика: «просто открывается
// окно, где можно перемещаться по комнатам», «От первого лица», «Всё видно,
// полноценная комната с потолком и полом», «Проходим сквозь нарисованные
// двери», «с затенением», «Давай всю схему».
//
// ——— чем рисуем и почему ————————————————————————————————————————————————
//
// Свой рисовальщик по обычному холсту. Решение то же и по той же причине, что
// в [ADR 007](../docs/adr/007-pdf-without-library.md): чужой бандл в сборку не
// кладётся (`build.js` склеивает модули в одну область видимости), а покупать
// у библиотеки было бы нечего — сцена маленькая, перспектива одна формула,
// порядок граней решает сортировка.
//
// Числа посчитаны на настоящем объекте заказчика (две схемы, 28 обведённых
// помещений, 132 вершины контуров). Стены по контурам комнат, по одному проёму
// на помещение и по окну на наружные грани дают **чуть больше тысячи граней**
// на схему — то есть около четырёх тысяч вершин на кадр. Перевод вершины в
// экран — девять умножений; отсечение по ближней плоскости и сортировка по
// дальности на тысяче граней — доли миллисекунды. Узкое место не арифметика, а
// заливка: тысяча `fill()` по холсту 1400 × 700. Замер живого прогона — в
// отчёте таска.
//
// WebGL руками дал бы на порядок больший запас, но стоил бы второго способа
// рисовать то же самое: у холста 2D уже есть всё, чем рисуется план и
// развёртка, и путь «нет контекста — нет картинки» пришлось бы заводить
// отдельно. Запас не нужен: сцена не растёт от числа меток, она растёт от
// числа стен, а стен в квартире сотня.
//
// ——— что этот модуль делает и чего не делает ———————————————————————————
//
// Здесь только счёт: сцена из объекта, камера, затенение, порядок граней,
// столкновения. Ни DOM, ни строк интерфейса; холст приходит аргументом, как в
// `render.js`. Окно, клавиши и фон — `panels/volume.js`.
//
// Отдельный модуль, а не часть `render.js`: общего у них нет ничего. `render`
// живёт в долях плана и в его пикселях, объём — в миллиметрах чертежа и в
// третьей оси. Положи их рядом — и в одном файле окажутся два разных
// пространства с похожими именами.
//
// **G68: режим только читает.** Ни одной записи в объект, ни одного нового
// поля. Объект без чертежа честно отвечает `empty`.
import {
  OPENING_GLASS_FRAME_MM,
  drawingBoundsMm,
  findScheme,
  schemeObjectKeyOf,
  findType,
  findWall,
  hexToRgb,
  labelOf,
  markIsComment,
  markSizes,
  markWall,
  markWallSideOn,
  openingArchDropMm,
  openingArchGeometry,
  openingFaceGrid,
  openingFoldLinks,
  openingOpens,
  openingSlatted,
  openingFamilyOf,
  openingGlazed,
  openingHasLeaf,
  openingLeavesOf,
  openingMotionOf,
  openingWalkThrough,
  openingsInWall,
  outlinesInOrder,
  planFractionToMm,
  roomAtPoint,
  roomHasFloor,
  planMmToFraction,
  projectCoords,
  projectTopAzimuth,
  SCHEME_ANCHOR_OBJECT_KEYS,
  schemeStairArrivalKeys,
  SCHEME_STAIR_OBJECT_KEYS,
  schemeAnchorOriginMm,
  schemeFloorOf,
  schemeObjectCorners,
  schemeObjectsOnScheme,
  schemesInOrder,
  segmentDistanceMm,
  styleOf,
  typeChannels,
  typeObjectView,
  WALL_HEIGHT_FALLBACK_MM,
  wallHeightOf,
  wallHeightOnSide,
  wallVectors,
  wallsOnScheme,
} from "./model.js";
import { MARK_BOX_FRAME_DEPTH_MM, markBoxMm } from "./markBox.js";
import { objectViewByName, objectViewForShape } from "./objectViews/registry.js";
import { MODEL_CYL_SIDES } from "./objectModels/kit.js";
import { objectLineModel, objectModelByKey, objectModelChannels } from "./objectModels/registry.js";

// ——— числа ——————————————————————————————————————————————————————————————

/** Высота глаз стоя. С таска 159 она не единственная — см. `VOLUME_CROUCH_MM`. */
export const VOLUME_EYE_MM = 1600;
/**
 * Радиус тела. Он же — страховка от того, чем кончается «камера упёрлась носом
 * в стену»: радиус заведомо больше ближней плоскости, поэтому грань стены
 * никогда не проходит сквозь камеру и геометрия не выворачивается.
 */
export const VOLUME_BODY_MM = 220;
/** Ближняя плоскость. Меньше радиуса тела — см. выше. */
export const VOLUME_NEAR_MM = 80;
/**
 * Порог, через который переступают. Проём, у которого низ не выше порога,
 * пропускает человека; окно на высоте 800 мм — нет, под ним глухая стена.
 */
export const VOLUME_STEP_MM = 300;
/** Макушка: под тем, что выше неё, проходят не нагибаясь. */
export const VOLUME_HEAD_MM = 1900;

// ——— стойка: присед и прыжок (G234, таск 159) ——————————————————————————
//
// Слова заказчика: «Сделай на клавишу Control функцию Присесть, а на пробел -
// прыжок». Это **квартира, а не игра**: числа взяты у человека, а не у
// платформера, и названы здесь все до одного.
//
// Высота глаз больше не постоянная, и прежняя оговорка «приседать и прыгать
// незачем» снята его словом. Что при этом не изменилось: в объект по-прежнему
// не пишется ничего (G68) — стойка живёт в сеансе, как двери и выделение.

/**
 * От глаз до макушки — 300 мм, и это не новое число, а то же самое: стоя глаза
 * на 1600, макушка на 1900. Поэтому присед считается **один раз** — опускаются
 * и глаза, и макушка, — и столкновения с глазами не расходятся никогда.
 */
export const VOLUME_CROWN_MM = VOLUME_HEAD_MM - VOLUME_EYE_MM;
/**
 * Насколько опускается присед: 550 мм. Глаза уходят с 1600 на **1050**,
 * макушка — с 1900 на **1350**.
 *
 * Числа человеческие: у сидящего на корточках взрослого глаза как раз около
 * метра, а 1350 — та высота, под которой он проходит. Проверяется это не
 * рулеткой, а квартирой: низ навесного шкафа кухни — 1400–1500 мм, низ марша
 * лестницы над проходом — от 1300, и присед обязан пускать именно туда.
 * Возьми меньше (скажем, 1000 мм приседа) — и под шкаф человек не пролезет,
 * то есть клавиша не будет делать ничего; возьми больше — он поползёт по полу,
 * чего заказчик не просил.
 */
export const VOLUME_CROUCH_MM = 550;
/**
 * Скорость приседа и подъёма — 3000 мм/с, то есть **0,18 с** на все 550 мм.
 *
 * Не мгновенно, и причина не в красоте: Control на главном экране соседствует с
 * Ctrl+Z, Ctrl+C и Ctrl+V, и между нажатием Control и буквой проходит
 * десятая доля секунды. Мгновенный присед дёргал бы кадр на каждой отмене;
 * плавный за это время едва начинается и возвращается назад сам (см.
 * `volumeStanceKey`).
 */
export const VOLUME_CROUCH_MM_S = 3000;
/**
 * Высота прыжка — 300 мм. Это ступенька, а не прыжок на месте в игре: взрослый
 * с места подпрыгивает на 30–40 см, и двух метров в квартире не нужно.
 */
export const VOLUME_JUMP_MM = 300;
/** Падение — настоящее земное ускорение, 9,81 м/с². Второго числа тут незачем. */
export const VOLUME_FALL_MM_S2 = 9810;
/**
 * Начальная скорость прыжка — та, что даёт ровно `VOLUME_JUMP_MM` и ни
 * миллиметром больше: v = √(2gh) = 2426 мм/с. Отсюда **взлёт 0,25 с, падение
 * 0,25 с**, вся дуга — полсекунды.
 */
export const VOLUME_JUMP_MM_S = Math.sqrt(2 * VOLUME_FALL_MM_S2 * VOLUME_JUMP_MM);
/**
 * Перемычка, ниже которой проём держит стоя, — 1700 мм.
 *
 * Заказчик назвал проём среди низких мест, где «встать нельзя». Но высота
 * проёма в чертеже — это высота полотна, а не просвет над головой: дверь 1800
 * в чьём-то уже размеченном объекте не должна перестать пускать человека,
 * который вчера через неё ходил. Поэтому держит только то, что низко
 * **несомненно**: 1700 мм — высота, под которой головой не наклонишься, а
 * присядешь. Проём 1500 мм пропускает присед (макушка 1350) и не пускает стоя;
 * дверь 2100 мм остаётся дырой в любой стойке, как и была.
 */
export const VOLUME_LINTEL_MM = 1700;
/**
 * Свободное место вокруг, ниже которого окно говорит «тесно».
 *
 * Это ответ на узкий санузел, где камера упирается носом в стену. Ломаться там
 * нечему — радиус тела больше ближней плоскости, и грань сквозь камеру не
 * пройдёт никогда, — но кадр становится ровным полем в сорок сантиметров
 * стены, и человек решит, что сборка сломалась. Поэтому окно не подменяет
 * решение за него (ни выталкивания в середину комнаты, ни поля зрения
 * нараспашку), а называет происходящее словом и показывает выход: обзор.
 * Полметра — половина прохода между стеной и ванной.
 */
export const VOLUME_TIGHT_MM = 500;
/**
 * Поле зрения по длинной стороне окна.
 *
 * Девяносто, а не привычные семьдесят пять, и причина измеримая. Стоя
 * посередине комнаты 4 × 3 м с глазами на 1,6 м, человек видит низ дальней
 * стены под 49° к горизонту: при поле 75° по ширине окна 1400 × 700 на
 * вертикаль остаётся 48°, то есть ±24°, — и пол в кадр не попадает вовсе, пока
 * взгляд не опустят. Это не придирка: заказчик сказал «Всё видно, полноценная
 * комната с потолком и полом», а кадр без пола этого обещания не держит.
 */
export const VOLUME_FOV_DEG = 90;
/**
 * Наклон взгляда, с которым встают на пол. Небольшой, вниз: ровно горизонтально
 * в комнате видно только стену — пол уходит под нижний край кадра (см. выше), а
 * комната узнаётся как раз по тому, где стена сходится с полом.
 */
export const VOLUME_START_PITCH_DEG = -10;
/**
 * С какого расстояния до лестницы спрашивают про этаж (таск 149).
 *
 * Метр с небольшим от её габарита — расстояние, с которого человек на неё
 * **подошёл**, а не прошёл мимо: лестница стоит у стены, проход рядом с ней
 * шириной в метр, и шаг в сторону из прохода уже упирается в саму лестницу
 * (тело выталкивается в 220 мм от неё). Больше — вопрос задавался бы из
 * соседней комнаты, меньше — не задавался бы вовсе: ближе 220 мм подойти
 * нельзя, лестница не пускает.
 */
export const VOLUME_STAIR_REACH_MM = 1100;
/** Ход и бег, миллиметры в секунду. */
export const VOLUME_WALK_MM_S = 2400;
export const VOLUME_RUN_MM_S = 4800;
/** Куда можно задрать и опустить взгляд. */
export const VOLUME_PITCH_MAX_DEG = 85;
/** Сколько экранных точек поворачивают голову на градус. */
export const VOLUME_LOOK_DEG_PX = 0.22;
/** Наклон обзора по умолчанию: смотрим сверху вниз. */
export const VOLUME_AROUND_PITCH_DEG = -42;
/** Насколько обзор отходит, когда его зовут к человеку. */
export const VOLUME_AROUND_NEAR_MM = 7000;
/**
 * Пределы меры обзора (`volumeAroundReach`): ближе полутора метров и дальше
 * четырёхсот она не считается. Ближний нужен у самой земли, где до пола по
 * взгляду ноль, а шаг колеса и скорость полёта обязаны остаться живыми.
 */
export const VOLUME_AROUND_MIN_MM = 1500;
export const VOLUME_AROUND_MAX_MM = 400000;
/**
 * Самый положий взгляд, на котором ещё считают пол: синус двадцати градусов.
 *
 * Предел один на двоих, и это нарочно. У `volumeAroundPan` он держит поправку
 * на сжатие пола: у почти горизонтального взгляда пол под пальцем лежит у
 * горизонта, и один мах уносил бы обзор за километры. У `volumeAroundReach`
 * (таск 207) — ровно то же самое: «докуда до пола» при взгляде в горизонт
 * обращается в бесконечность, и мера, которой меряют и шаг колеса, и скорость
 * полёта, ушла бы туда же.
 */
export const VOLUME_AROUND_TILT_MIN = Math.sin((20 * Math.PI) / 180);
/**
 * За сколько секунд обзор пролетает то, на что смотрит (таск 207, G311).
 *
 * Заказчик отменил своё же «скорость для камеры как и сейчас для полёта»
 * (G306): на «Всей схеме» крупного объекта камера стоит в десятках метров и
 * ползёт шагом пешехода. Число выбрано **отношением, а не скоростью**: сколько
 * бы ни было до того, на что смотрит обзор, он покрывает это за полторы
 * секунды — и управление чувствуется одинаково и над домом, и в комнате.
 *
 * Полторы, а не одна и не три: за секунду кадр не успевает прочитаться на
 * размахе, а за три пролёт через квартиру снова становится ожиданием. Счёт для
 * этого объекта — у `volumeAroundSpeed`.
 */
export const VOLUME_AROUND_FLY_S = 1.5;
/**
 * Ярусы, в которых грани ложатся на холст (дефект живого прогона).
 *
 *   0 — **плита под чертежом**. Одна грань на всю схему, по габариту чертежа,
 *       то есть по осевым линиям наружных стен. Нужна не для красоты: в пороге
 *       двери пола нет вовсе (комнаты кончаются у внутренних граней, а между
 *       ними лежит толщина стены), и сквозь эту щель был виден задник —
 *       зелёная полоса поперёк каждого проёма. Той же щелью отзывается контур,
 *       обведённый рукой чуть мимо стены. Плита закрывает оба случая разом и
 *       наружу не вылезает: за осевой линией её прячет сама стена.
 *   1 — **тень дома на земле** (D43). Своим ярусом, и это починка дефекта D49 —
 *       разбор числами ниже.
 *   2 — **полы и потолки** помещений.
 *   3 — **солнечное пятно на полу комнаты** (таск 196, D51): проёмом пущенный
 *       в комнату свет. Ярус ровно тот же урок, что у тени, только с другой
 *       стороны пола: пятно обязано лежать **выше** пола своей комнаты и ниже
 *       всего, что в комнате стоит. Дальностью это не решается по той же
 *       причине, по которой не решилось у тени, — пятно и пол коплоскостны
 *       (оба на нулевой отметке), и спор их середин переворачивается от часа.
 *       Разбор числами — у `volumeSunSpotFaces`.
 *   4 — **всё остальное**: стены, объекты, полотна, рамы.
 *   5 — **кружок «вы здесь»**. Он рисуется поверх всего, и это не оплошность:
 *       он не часть комнаты, а указатель. Обзор смотрит под углом, и ближняя
 *       стена высотой 2,7 м прячет за собой полосу пола метра в три — то есть
 *       ровно того человека, ради которого обзор и открыли («без него не
 *       понять, где стоишь»). Указатель, видный сквозь стену, отвечает на этот
 *       вопрос всегда; сама стена при этом остаётся на месте и читается как
 *       стена.
 *
 * Ярус сильнее дальности, и это правило, а не ускорение: под плитой нет
 * ничего, под полом нет ничего, а потолок, видимый снизу, не закрывает ничего,
 * кроме себя. Будь они в общем потоке, пол комнаты, в которой стоишь, оказался
 * бы ближе дальней стены и закрасил бы её низ.
 *
 * ——— почему у тени свой ярус (дефект D49) ———————————————————————————————
 *
 * Слова заказчика по снимку обзора: «баг отрисовки тени внутри дома —
 * просвечивает пол». В части комнат вместо пола лежала зелень, в части пол был
 * на месте.
 *
 * Разбор числами. Стенд — две комнаты 4 × 3 м через общую стену, обзор с 14 м,
 * наклон −42°, поле 972 × 778. Внутри яруса очередь считается **по дальности**
 * (у всех, кого нет в дереве порядка, `order = −depth`), а грани тени лежали
 * тем же ярусом, что полы. Тень стены уходит от неё на полторы высоты — то есть
 * у половины стен внутрь дома, — и спор решает не смысл, а то, чья середина
 * ближе к камере:
 *
 *   10:00, солнце на `az` 15°: пол комнаты `depth` 12 770, тень 10 825 →
 *          последней ложится **тень**, и точка пола получает `rgb(101,131,80)`;
 *   15:00, солнце на юге:      пол 12 770, тень 12 353 → снова тень,
 *          `rgb(89,115,67)` вместо пола `rgb(85,71,55)`;
 *   19:00, солнце на `az` 150°: тень 13 285, пол 12 770 → пол на месте.
 *
 * Отсюда и «в части комнат»: сравнение середин переворачивается и от часа, и от
 * комнаты. Обещание таска 178 «внутри дома тень не видна — полы рисуются после
 * неё» дальностью не держится никогда; держится оно только ярусом. Тень лежит
 * **на земле**: выше плиты, ниже всего остального — так теперь и написано.
 */
export const VOLUME_LAYER_BASE = 0;
export const VOLUME_LAYER_SHADOW = 1;
/**
 * **Ярус полов и потолков пуст с таска 211** — и это не забывчивость, а
 * разбор дефектов D62 и D63.
 *
 * Слова заказчика: «И где же перекрытия между этажами? Они не должны быть
 * прозрачными» и следом «И снизу, с 1 этажа тоже видно второй насквозь».
 *
 * Причина была в этом номере. Кадр выкладывает многоугольники **сперва по
 * ярусу, и только внутри яруса — по дереву**, а горизонтали перекрытия лежали
 * в ярусе 2, тела — в ярусе 4. Значит любое тело любого этажа рисовалось
 * поверх любого пола и любого потолка. Замер на объекте заказчика (два этажа,
 * 15 391 грань) в одной точке кадра:
 *
 *   - снизу, стоя на первом этаже под вещью второго: ярус 2 — потолок (z
 *     3000), ярус 3 — низ плиты (3000) и потолок второго (6000), ярус 4 —
 *     **вещь второго этажа (4300), и видно именно её**;
 *   - сверху, отвесно: ярус 0 — земля, ярус 2 — пол первого (0), ярус 3 — пол
 *     второго (3200), ярус 4 — **вещь второго (5400)**. А по всему кадру
 *     сверху: 23 % точек показывали нутро **первого** этажа сквозь плиту
 *     второго, и 0 % — потолок.
 *
 * Заказчик это и заметил: «а у перекрытий, кстати, появляются боковые грани» —
 * кромка плиты (таск 209) стоит в ярусе тел и закрывает как следует, а её
 * собственные верх и низ не закрывали ничего.
 *
 * Поэтому полы, потолки и плита переведены в ярус тел: порядок им считает
 * дерево, точно и в каждом пикселе. Номер оставлен в сборке — на него смотрят
 * тень (D49) и солнечное пятно, которым важно лечь **между** землёй и телами.
 */
export const VOLUME_LAYER_GROUND = 2;
export const VOLUME_LAYER_SUN = 3;
export const VOLUME_LAYER_BODY = 4;
export const VOLUME_LAYER_MARK = 5;
/**
 * Предел уса на изломе полосы (D38): во сколько раз смещение угла может
 * превысить половину ширины. Четыре — то же число, которым ограничивают ус
 * обводки в SVG и в вебовской канве; приходится оно на излом примерно в 151°,
 * и полос круче этого в чертеже не рисуют. За пределом ус срезается.
 */
export const VOLUME_MITER_MAX = 4;
/** Ниже этого `1 + n₁·n₂` считается полным разворотом: стыковать нечего. */
const VOLUME_MITER_EPS = 1e-6;

/**
 * Зазор, внутри которого точка считается лежащей **на** плоскости грани
 * (дерево порядка, см. `volumeOrderTree`).
 *
 * Двадцатая доля миллиметра — заведомо меньше всего, что в сцене отодвинуто
 * нарочно: вещь стоит перед стеной на 2 мм (`VOLUME_MARK_LIFT_MM`), контур
 * поднят над лицом вещи на 1 мм (`VOLUME_VIEW_LIFT_MM`). И заведомо больше
 * погрешности, с которой миллиметровые координаты складываются в double.
 */
export const VOLUME_PLANE_EPS_MM = 0.05;
/** Сколько плоскостей примеряется в узле дерева, прежде чем выбрать лучшую. */
const VOLUME_ORDER_TRIES = 12;
/** Во сколько раз разрез дороже перекоса: цена лишней грани против цены глубины. */
const VOLUME_ORDER_SPLIT_COST = 8;
/** Сколько раз выталкиваем тело из стен за шаг: угол держат два прохода. */
const VOLUME_PUSH_PASSES = 4;
/**
 * Сотая доля миллиметра: ниже неё сдвиг считается нулевым, а «стало глубже» —
 * не считается вовсе (D39). Заведомо меньше всего, что человек увидит, и
 * заведомо больше погрешности, с которой миллиметры складываются в double.
 */
const VOLUME_PUSH_EPS_MM = 0.01;
/** Светлота самой тёмной и самой светлой грани. */
const VOLUME_SHADE_MIN = 0.46;
const VOLUME_SHADE_MAX = 1;
/**
 * Направление, по которому считается светлота. Светлее всех грань, смотрящая
 * навстречу, темнее — отвёрнутая. У него отрицательная `z`, и из этого прямо
 * следует требование заказчика «пол темнее потолка»: низ потолка смотрит вниз
 * (навстречу), верх пола — вверх (от).
 */
const VOLUME_LIGHT = volumeNormalize({ x: -0.42, y: -0.33, z: -0.84 });

// Цвета материалов. Чернила чертежа (`DRAWING_WALL` и соседи) здесь не годятся:
// там тушь по бумаге, а тут поверхность комнаты, и затенение гонит её светлоту
// в обе стороны. Поэтому палитра своя и к `mono.js` отношения не имеет —
// объёмный вид не печатают.
/**
 * Тень на земле (D43): земля, помноженная на 0,72.
 *
 * Не «серый с прозрачностью» и не вторая палитра: тень — это та же земля, до
 * которой не дошёл свет, и взята она от неё же. Сплошная, потому что тени
 * соседних стен перекрываются, а дом отбрасывает **одно** пятно: сложи их
 * прозрачностью — и в углу дома вышло бы вдвое темнее, чем вдоль стены.
 *
 * 0,72 — примерно то же отношение, что между самой светлой и самой тёмной
 * гранью сцены (`VOLUME_SHADE_MIN` = 0,46 … 1): тень читается, но не чернит
 * траву.
 */
export const VOLUME_SHADOW_RGB = [89, 115, 67];
/**
 * Запас земли за тенью дома (D43): плита кончается не там, где кончается тень,
 * а на три метра дальше. Своего числа у выноса нет — он считается от самой
 * тени (`volumeShadowShift`), то есть от высоты стен и высоты солнца.
 */
export const VOLUME_LAND_OUT_MM = 3000;
export const VOLUME_WALL_RGB = [216, 212, 204];
export const VOLUME_FLOOR_RGB = [170, 142, 110];
export const VOLUME_CEILING_RGB = [238, 238, 236];
/**
 * Кромка перекрытия (таск 209, дефект D60). Бетон темнее стены: перекрытие —
 * это то, что **между** этажами, и в кадре оно обязано читаться полосой, а не
 * сливаться со стеной в один белый блок.
 */
export const VOLUME_SLAB_RGB = [186, 181, 173];
export const VOLUME_OBJECT_RGB = [150, 126, 190];
export const VOLUME_DOOR_RGB = [176, 132, 92];
/** Ручка двери — металл: светлее полотна и холоднее его (G207). */
export const VOLUME_HANDLE_RGB = [186, 190, 198];
export const VOLUME_FRAME_RGB = [240, 242, 244];
/**
 * **Стекло двери** (таск 180, G269) — холодный блик, а не цвет: сквозь него
 * видно соседнюю комнату, и своего тона у него ровно столько, чтобы полотно
 * читалось стеклом, а не дыркой. Плотность у него **именованная**
 * (`VOLUME_CLEAR_ALPHAS.glass`, таск 189): своего числа у двери нет.
 */
export const VOLUME_GLASS_RGB = [196, 216, 224];
export const VOLUME_MARKER_RGB = [31, 111, 235];

/**
 * Радиус кружка «вы здесь» на обзоре (G212). Полтора дециметра — это полшага
 * человека: указатель виден, а пол под ним — тоже, и клик по месту за ним
 * (перенос) не упирается в собственный указатель.
 */
export const VOLUME_MARKER_MM = 150;

/**
 * **Насколько вещь чертежа отдаёт своего цвета** (таск 169, требование G251).
 *
 * Слова заказчика: «сделай так же все объекты (мебель, сантехника и т.д.)
 * полупрозрачными, что бы можно было видеть метки, которые, например в шкафу, и
 * взаимодействовать с ними».
 *
 * Четыре десятых — и число это посчитано, а не выбрано на глаз. Считать его
 * по одной грани нельзя: у модели вещи тел несколько, и луч сквозь шкаф
 * проходит **две** лицевые грани — фасад (`door`) и лицо корпуса (`case`), —
 * потому что отсеиваются только отвёрнутые грани, а не те, что стоят друг за
 * другом. Прозрачность на пути перемножается, и за двумя гранями остаётся
 * `0.6 × 0.6 = 0.36` того, что за ними: **треть** — ровно столько, сколько
 * нужно, чтобы розетка в шкафу читалась цветом, а не угадывалась. Возьми
 * половину — за фасадом осталась бы четверть, и на тёмном полу метка пропала
 * бы; возьми треть — сама вещь перестала бы читаться формой.
 *
 * Форму держит не только заливка: кадр обводит каждую грань её же цветом
 * (`volumeDraw`, иначе между соседними гранями видна волосяная щель от
 * сглаживания), и у прозрачной грани эта обводка ложится на свою же заливку.
 * Кромка выходит плотнее середины — `1 − 0.6²` по внутренней половине
 * обводки, а на общем ребре двух граней и того больше. Это не изъян, а то, чем
 * вещь и читается: середина лица просвечивает, рёбра остаются рёбрами.
 *
 * **Стены, пол, потолок, полотно двери и сами метки прозрачными не делаются**
 * (правило таска 146 и прямое слово тикета): сквозь стену видно быть не
 * должно, а метку смотрят, а не смотрят сквозь.
 */
export const VOLUME_CLEAR_ALPHA = 0.4;

/**
 * **Полотнище шторы** — плотность ткани (таск 191, требование G297). Слова
 * заказчика: «давай шторе поставим прозрачность 0.6, сейчас её почти не видно,
 * да, получилось как тюль, но всё-таки хотелось бы понагляднее, потому что там
 * штора будет по факту и её должно быть видно».
 *
 * Шесть десятых. Прежнего довода здесь **нет нарочно**, а не рядом: таск 189
 * выводил 0,3 из службы **окну** — «за двумя полотнищами окну остаётся
 * половина», `(1 − a)² ≥ 0.5`, то есть `a ≤ 0.29`, — и заказчик, посмотрев
 * кадр, назвал это провалом с другой стороны. За меткой стоит **штора**: вещь,
 * которую он размечает, вешает и считает. Её смотрят, а не смотрят сквозь, и
 * «почти не видно» для неё — такой же провал задания, каким для окна было бы
 * «угадывается». Ткань служит себе, окно берёт остаток.
 *
 * Слоёв на луче **один, редко два, трёх не бывает**. Это замер, а не догадка:
 * живой объект заказчика (линейный карниз, три метки, 72 ракурса — два отхода
 * и шесть углов падения до 75° с каждой стороны, 3,9 млн точек кадра, попавших
 * на ткань) — 1,04 слоя в среднем; один слой в 96,4 % точек, два в 3,6 %, три
 * не встретились ни разу. Два набегает там, где волна складок ставит полотнища
 * друг за друга по косому взгляду; в лоб они стоят в ряд и не перекрываются.
 * На точечной метке то же самое: три складки в ряд, косой луч задевает две.
 *
 * **Окно за тканью не пропадает**, и это тоже замер — сравнением с кадром, из
 * которого ткань убрана. Окну остаётся 0,40 своего света за одним полотнищем
 * (было 0,70) и 0,16 за двумя (было 0,49), но светлее стены оно остаётся
 * всегда: материал полотнища сам светлый, и в точках окна яркость держится
 * 155…176 из 255 против 117…150 у стены за той же тканью. Разница падает с 46
 * единиц до 26 — знак не меняется ни на одном из 72 ракурсов. То есть окно
 * читается сквозь ткань светлым прямоугольником: 0,6 — это штора на просвет, а
 * не портьера.
 *
 * Прозрачность вещей (0,4) переиспользовать нельзя по-прежнему, только теперь
 * с другой стороны: ткань **плотнее** вещи, и порядок этот осмысленный — см.
 * `VOLUME_CLEAR_ALPHAS`.
 *
 * Имя мерки осталось прежним — `sheer`, «тюль» (`MODEL_CLEARS` и описания
 * моделей в `objectModels/`). Это имя **слота плотности**, а не обещание
 * тонкой ткани: переименуй его, и правка поедет в два описания модели и тест,
 * не добавив ни одного ответа.
 *
 * Видимой ткань при этом остаётся не одной заливкой: кадр обводит каждую грань
 * её же цветом, и у прозрачной грани обводка ложится на свою же заливку —
 * кромка плотнее середины. У штор это ровно то, чем ткань и узнаётся: складки
 * стоят волной, и между полотнищами идёт двойная кромка.
 */
export const VOLUME_SHEER_ALPHA = 0.6;

/**
 * **Стекло двери** (таск 180, G269): четверть своего цвета, три четверти —
 * тому, что за ним. Самое прозрачное в сборке, и порядок этот не случаен:
 * штору (0,6) **смотрят** — она вещь объекта; вещь чертежа (0,4) просвечивает
 * ради метки за ней; а стекло двери смотрят **насквозь** — в соседнюю комнату
 * или на улицу.
 *
 * Держит его форму не заливка, а рама по контуру и кромка грани: кадр обводит
 * каждую грань её же цветом, и у прозрачной обводка ложится на свою заливку.
 */
export const VOLUME_GLASS_ALPHA = 0.25;

/**
 * **Плотности прозрачных поверхностей: имя → сколько своего цвета остаётся.**
 *
 * Одно место на всю сборку, и это не украшение. Прозрачность называется в
 * описаниях моделей (`MODEL_CLEARS` в `objectModels/kit.js`), а шторы описаны
 * дважды — моделью у точечной метки и повтором у линейной. Жили бы числа там,
 * они разошлись бы первой же правкой; здесь они обязаны совпасть, и что у
 * каждого имени число есть, проверяет тест.
 *
 * `thing` — вещь чертежа целиком (таск 169), её признак приходит не из
 * описания, а из `volumeObjectFaces`.
 */
export const VOLUME_CLEAR_ALPHAS = {
  thing: VOLUME_CLEAR_ALPHA,
  sheer: VOLUME_SHEER_ALPHA,
  // Стекло двери (таск 180, G269) — самое прозрачное из трёх, и это не вкус, а
  // порядок вещей: штору смотрят, и окно за ней остаётся светлым пятном, а не
  // видом; сквозь шкаф смотрят, чтобы разглядеть в нём розетку; а сквозь стекло
  // двери **просто видно** — в соседнюю комнату или на улицу. Четверть
  // своего цвета оставляет полотну форму: рама по контуру и кромка грани (кадр
  // обводит грань её же цветом) очерчивают его и на светлой стене.
  glass: VOLUME_GLASS_ALPHA,
};

/**
 * Сколько своего цвета остаётся грани: `1` — плотная.
 *
 * `true` — вещь чертежа (так её помечает `volumeObjectFaces`), строка — имя
 * плотности из описания тела. Незнакомое имя остаётся **прозрачным** (общая
 * плотность вещи), а не плотным: опечатка должна быть видна, а не выглядеть
 * нормой.
 */
export function volumeClearAlpha(clear) {
  if (!clear) return 1;
  const named = VOLUME_CLEAR_ALPHAS[clear === true ? "thing" : clear];
  return named === undefined ? VOLUME_CLEAR_ALPHA : named;
}

// ——— мелкая векторная арифметика ————————————————————————————————————————
//
// Своя, в три строки: выносить её в модель незачем — ни одна сущность объекта
// третьей оси не знает.

function volumeNormalize(vector) {
  const length = Math.hypot(vector.x, vector.y, vector.z);
  if (!(length > 0)) return { x: 0, y: 0, z: 0 };
  return { x: vector.x / length, y: vector.y / length, z: vector.z / length };
}

/**
 * Нормаль грани по трём первым вершинам. Направление задаёт обход: у плановых
 * многоугольников, записанных по часовой на экране (ось `y` смотрит вниз),
 * «левая» нормаль ребра смотрит наружу — то же соглашение, что у стены
 * (`wallVectors`), и второго в сборке нет.
 */
export function volumeFaceNormal(points) {
  if (!points || points.length < 3) return { x: 0, y: 0, z: 1 };
  const [a, b, c] = points;
  const ux = b.x - a.x;
  const uy = b.y - a.y;
  const uz = b.z - a.z;
  const vx = c.x - a.x;
  const vy = c.y - a.y;
  const vz = c.z - a.z;
  return volumeNormalize({ x: uy * vz - uz * vy, y: uz * vx - ux * vz, z: ux * vy - uy * vx });
}

/** Светлота грани по её направлению: одна формула, ни текстур, ни света. */
export function volumeShade(normal) {
  const dot = normal.x * VOLUME_LIGHT.x + normal.y * VOLUME_LIGHT.y + normal.z * VOLUME_LIGHT.z;
  return VOLUME_SHADE_MIN + ((VOLUME_SHADE_MAX - VOLUME_SHADE_MIN) * (dot + 1)) / 2;
}

/**
 * Час суток в цвете: материал, сведённый к тону ночи (таск 181, G282).
 *
 * **Единственное место, где темнеет вечер.** Им красится и грань сцены
 * (`volumeFill` ниже), и поле панорамы, и тень дома — а это три разные
 * поверхности, которые обязаны совпасть в тон: земля у дома, земля за ним и
 * её собственная тень. Разойдись у них счёт — дом снова «залетал» бы над
 * землёй, ровно как в G237, только теперь к ночи.
 *
 * `tint` — `{rgb, share}`: куда и насколько тянется цвет. `null` и нулевая
 * доля значат полдень, то есть цвет как написан.
 */
export function volumeTintRgb(rgb, tint) {
  const share = tint ? Math.max(0, Math.min(1, Number(tint.share) || 0)) : 0;
  if (!(share > 0)) return rgb;
  const to = tint.rgb || VOLUME_NIGHT_RGB;
  return [
    Math.round(rgb[0] * (1 - share) + to[0] * share),
    Math.round(rgb[1] * (1 - share) + to[1] * share),
    Math.round(rgb[2] * (1 - share) + to[2] * share),
  ];
}

/** Тот же час, но строкой холста: `rgb(...)` для заливок панорамы. */
export function volumeTintCss(rgb, tint) {
  return "rgb(" + volumeTintRgb(rgb, tint).join(",") + ")";
}

/**
 * Цвет грани: материал, умноженный на светлоту и сведённый к тону часа.
 *
 * `alpha` меньше единицы — грань просвечивает (вещь чертежа, таск 169), и
 * прозрачность пишется **в сам цвет**, а не в состояние холста: кадр от этого
 * не меняется ни одной строкой — рисование так и остаётся одной заливкой на
 * многоугольник (`volumeDraw`), и цена кадра та же самая.
 *
 * `tint` — час суток (таск 181). Он стоит здесь, а не завесой поверх кадра, и
 * это главное решение в освещении объёма: завеса легла бы и на небо, а небу
 * ночью нужна своя темнота, глубже комнатной, — и ни одна завеса не дала бы
 * **светящемуся** окну города остаться светящимся. Здесь же цена нулевая: три
 * умножения на грань в том же счёте, где уже считается светлота.
 */
export function volumeFill(rgb, shade, alpha = 1, tint = null) {
  const hour = volumeTintRgb(rgb, tint);
  const channel = (value) => Math.max(0, Math.min(255, Math.round(value * shade)));
  const parts = channel(hour[0]) + "," + channel(hour[1]) + "," + channel(hour[2]);
  if (!(alpha < 1)) return "rgb(" + parts + ")";
  return "rgba(" + parts + "," + Math.round(alpha * 100) / 100 + ")";
}

// ——— грани ———————————————————————————————————————————————————————————————
//
// Грань — плоский многоугольник в миллиметрах чертежа плюс третья ось: `z`
// отсчитывается от пола вверх. `layer` — ярус отрисовки (см. выше), `both`
// помечает двустороннюю грань (дверное полотно, брусок рамы).

function volumeFace(points, rgb, options = {}) {
  const normal = options.normal || volumeFaceNormal(points);
  return {
    p: points,
    n: normal,
    rgb,
    layer: options.layer === undefined ? VOLUME_LAYER_BODY : options.layer,
    both: Boolean(options.both),
    // Грань без затенения (G237): цвет берётся как написан. Это земля — она
    // освещена тем же небом, что поле панорамы, и обязана совпасть с ним в
    // тон, а лампа сцены увела бы её вдвое в темноту.
    flat: Boolean(options.flat),
    // Грань просвечивает (таск 169): вещь чертежа — и тюль шторы (таск 189).
    // Признак доезжает до двух мест и больше никуда: до цвета (`volumeFill`
    // отдаёт `rgba`) и до взгляда (`volumeSightAt` сквозь такую грань смотрит
    // дальше — но не сквозь метку, см. там). Порядок прозрачная грань не
    // меняет: он и так точен в каждом пикселе — см. `volumeOrderTree`.
    clear: Boolean(options.clear),
    // **Насколько** просвечивает: доля своего цвета (таск 189). У плотной
    // грани единица, у ткани шторы 0,6, у вещи 0,4 — считает это одно место
    // (`volumeClearAlpha`), а кадр берёт готовое число.
    alpha: volumeClearAlpha(options.clear),
    // Чья это грань: по ней кадр отвечает, во что попал клик (таск 148).
    // У стен, пола и вещей чертежа хозяина нет — и попадать в них незачем.
    markId: options.markId || null,
    // Чья это клавиша (таск 177, G274): по ней кадр отвечает, в какой **канал**
    // попал клик. Стоит только у клавиш выключателя — у рамки, у корпуса и у
    // любой другой грани `null`, и щелчок по ним значит «вся метка», как
    // значил.
    channel: options.channel === undefined ? null : options.channel,
    // Чьё это полотно: по нему кадр отвечает, какую дверь открывает E (G207).
    // Есть только у полотна и его ручки — больше ни у чего в сцене.
    doorId: options.doorId || null,
  };
}

/**
 * **Линия в сцене**: ломаная, которая не заливается, а обводится (таск 148).
 *
 * Заведена ради двух вещей, которые гранями не рисуются: контур изображения
 * объекта на лицевой стороне вещи и стрелка связи. И то и другое — **рисунок**,
 * а не поверхность: толщина у него в экранных точках, иначе контур розетки в
 * трёх метрах пропадает вовсе, а в полуметре превращается в кляксу.
 *
 * `normal` необязательна: с ней линия отсекается по направлению, как грань
 * (контур на лицевой стороне не виден с изнанки), без неё видна всегда —
 * стрелке связи так и надо.
 */
export function volumeLine(points, color, options = {}) {
  return {
    p: points,
    line: true,
    color,
    width: options.width === undefined ? 1.4 : options.width,
    closed: Boolean(options.closed),
    dash: options.dash || null,
    arrow: Boolean(options.arrow),
    n: options.normal || null,
    layer: options.layer === undefined ? VOLUME_LAYER_BODY : options.layer,
    markId: options.markId || null,
  };
}

function volumeAt(point, z) {
  return { x: point.x, y: point.y, z };
}

/**
 * Куда уходит тень точки, поднятой на `heightMm` (D43).
 *
 * Кладёт её **солнце, нарисованное на небе** (`VOLUME_SUN_AT`), и это
 * единственный разумный хозяин: тень, лежащая не в ту сторону от видимого
 * солнца, кричит о подделке громче, чем её отсутствие.
 *
 * Лампа сцены (`VOLUME_LIGHT`) для этого не годится вовсе, и это стоит сказать
 * прямо: у неё отрицательная `z` и светлее всех грань, **смотрящая вниз** (так
 * сделано нарочно — «пол темнее потолка», требование заказчика ещё из таска
 * 146). Светит она, выходит, снизу — а свет снизу тени на земле не кладёт.
 * Лампа красит грани, солнце кладёт тень; смешивать их нельзя.
 *
 * Длина — из высоты солнца над горизонтом: `h / tg(rise)`. При 14° стена
 * 2800 мм даёт тень 11 230 мм — длинную, как и положено низкому солнцу.
 * Направление — ровно прочь от солнца: `az + 180°`.
 *
 * `at` — где солнце стоит **сейчас** (таск 181): с идущим временем оно ходит
 * по небу, и тень ходит за ним. Умолчание — полдень при верхе чертежа на
 * север (`VOLUME_SUN_AT`), и по нему же считается вынос земляной плиты: плита
 * обязана держать тень в любой час, а размер её — часть сцены, которую нельзя
 * пересобирать каждую секунду. Поэтому высота солнца для тени **снизу не
 * опускается ниже полуденной** (`VOLUME_SUN_AT.rise`): тень не длиннее той, на
 * которую плита рассчитана, а у горизонта она не тянется в бесконечность, а
 * гаснет — см. `volumeShadowFaces`.
 */
export function volumeShadowShift(heightMm, at = VOLUME_SUN_AT) {
  const want = Number(at && at.rise);
  const rise = Math.max(Number(VOLUME_SUN_AT.rise) || 1, Number.isFinite(want) ? want : 0) * DEG;
  const reach = Number(heightMm) / Math.tan(rise);
  const away = (Number(at && at.az) || 0) + 180;
  if (!Number.isFinite(reach)) return { x: 0, y: 0 };
  return { x: Math.cos(away * DEG) * reach, y: Math.sin(away * DEG) * reach };
}

/**
 * Силуэт тени прямой призмы: выпуклая оболочка её габарита и того же габарита,
 * сдвинутого на вынос тени. Одной только сдвинутой крышкой обойтись нельзя —
 * между стеной и её тенью осталась бы светлая щель, то есть ровно то «дом не
 * касается земли», от которого всё и затевалось.
 */
export function volumeShadowOutline(corners, heightMm, at = VOLUME_SUN_AT) {
  const shift = volumeShadowShift(heightMm, at);
  const points = [];
  for (const point of corners) {
    points.push({ x: point.x, y: point.y });
    points.push({ x: point.x + shift.x, y: point.y + shift.y });
  }
  return volumeHull(points);
}

/**
 * Грани тени дома в этот час (таск 181).
 *
 * `boxes` — габариты стен из сцены (`scene.shadowBoxes`), `shadow` — где стоит
 * солнце и насколько тень видна (`mood.shadow`).
 *
 * **Ярус у тени свой** (`VOLUME_LAYER_SHADOW`, дефект D49): она лежит выше
 * плиты и ниже полов. Дальностью это не решается — внутри яруса очередь считают
 * середины граней, и тень, уходящая от стены внутрь дома, оказывается то дальше
 * пола, то ближе него, от часа и от комнаты. Числа — у объявления яруса.
 *
 * **Гаснет тень цветом, а не прозрачностью.** Солнце у горизонта — тень
 * сводится к самой земле (`VOLUME_LAND_RGB`) и исчезает, ночью её нет вовсе.
 * Прозрачностью этого делать нельзя: тени соседних стен перекрываются, и в
 * углу дома вышло бы вдвое темнее, чем вдоль стены (та же причина, по которой
 * тень сплошная с таска 178).
 */
export function volumeShadowFaces(boxes, shadow, out = []) {
  const fade = shadow ? Math.max(0, Math.min(1, Number(shadow.fade))) : 1;
  if (!boxes || boxes.length === 0 || !(fade > 0)) return out;
  const rgb = [
    Math.round(VOLUME_LAND_RGB[0] + (VOLUME_SHADOW_RGB[0] - VOLUME_LAND_RGB[0]) * fade),
    Math.round(VOLUME_LAND_RGB[1] + (VOLUME_SHADOW_RGB[1] - VOLUME_LAND_RGB[1]) * fade),
    Math.round(VOLUME_LAND_RGB[2] + (VOLUME_SHADOW_RGB[2] - VOLUME_LAND_RGB[2]) * fade),
  ];
  const at = shadow ? { az: shadow.az, rise: shadow.rise } : VOLUME_SUN_AT;
  for (const box of boxes) {
    // `box.baseMm` — где лежит земля под этим габаритом (таск 202). У одной
    // схемы это ноль, у стопки этажей — пол нижнего этажа: тень кладут все
    // этажи разом, но ложится она на одну землю.
    const baseMm = Number(box.baseMm) || 0;
    out.push(
      volumeFace(
        volumeClockwise(volumeShadowOutline(box.corners, box.heightMm, at)).map((point) => volumeAt(point, baseMm)),
        rgb,
        { normal: { x: 0, y: 0, z: 1 }, layer: VOLUME_LAYER_SHADOW, flat: true },
      ),
    );
  }
  return out;
}

// ——— солнце в комнате (таск 196, дефект D51, требование G301) —————————————
//
// Слова заказчика: «почему-то теперь в доме вообще нет тени ни через двери ни
// через окна».
//
// **Сломанного нет, и это надо сказать прямо.** Внутреннего света в сборке не
// было никогда: тень дома (таск 178) лежит только на земле, а внутри комнат её
// не видно нарочно — ярусом (D49). Раньше сквозь щели в полу местами светила
// зелёная земля, и это читалось тенью; таск 190 щели закрыл, и «тень» вместе с
// ними исчезла. То есть заказчик просит не починки, а того, чего не было:
// света, который солнце кладёт на пол через проём.
//
// **Это проекция проёма, а не трассировка лучей.** Проём — прямоугольник в
// стене (низ, верх, ширина вдоль стены); солнце даёт направление; пятно — тот
// же прямоугольник, снесённый по направлению света на пол. Низ проёма сносится
// на `низ / tg(высота солнца)`, верх — на `верх / tg(...)`, и прямоугольник
// становится **параллелограммом**: смещение растёт с высотой линейно, а стороны
// проёма вдоль стены параллельны. Ни карт теней, ни отражений, ни света на
// стенах, ни второго шага (из комнаты в комнату через внутреннюю дверь) здесь
// нет — что из этого стоит сделать дальше, сказано в отчёте таска.
//
// ——— один шаг света: солнечная сторона проёма обязана быть улицей ————————
//
// У проёма две стороны, и обе спрашиваются у контуров помещений:
//
//   - **принимающая** (та, куда идёт свет) обязана быть комнатой — иначе пятну
//     негде лежать: свет уходит из дома на улицу;
//   - **солнечная** (та, откуда идёт свет) обязана быть улицей — иначе свет
//     пришёл бы из соседней комнаты, то есть сам был бы пятном от другого
//     проёма, а это уже второй шаг и трассировка.
//
// Отсюда сразу три ответа, которых иначе пришлось бы искать по отдельности:
//
//   1. **дверь между двумя комнатами пятна не даёт вовсе** — у неё обе стороны
//      комнаты, значит светить в неё нечему. Цена названа прямо: сквозь
//      внутреннюю дверь солнце в этой сборке не проходит, даже когда соседняя
//      комната залита светом. Врать красивее было бы дороже: пятно за
//      внутренней дверью появлялось бы и там, где его кормить нечем — у двери
//      в середине квартиры;
//   2. **солнце с другой стороны стены** — окно в северной стене в полдень не
//      светит: принимающей стороной оказывается улица, и проём отбрасывается
//      тем же условием, а не отдельной проверкой стороны света;
//   3. **проём в стене, у которой комнат нет совсем** (сарай на чертеже),
//      молчит.
//
// На объекте заказчика из 13 проёмов пятно могут дать 5 (четыре окна и входная
// дверь), остальные 8 — внутренние.

/**
 * Светлота пола: та же, которой красит его лампа сцены.
 *
 * Пол — **самая тёмная грань сцены** по построению (у `VOLUME_LIGHT`
 * отрицательная `z`: «пол темнее потолка», требование заказчика из таска 146).
 * Числом это `volumeShade({0,0,1})` = **0,502**, то есть пол `170·142·110`
 * показывается как `85·71·55` — то же число, которым считался дефект D49.
 */
const VOLUME_SUN_SPOT_DIM = volumeShade({ x: 0, y: 0, z: 1 });

/**
 * Цвет солнечного пятна: **тот же пол, которому досталась самая светлая грань
 * сцены вместо самой тёмной.**
 *
 * Мера взята из уже существующих, а не придумана: снаружи тень — это земля,
 * помноженная на 0,72 (`VOLUME_SHADOW_RGB`, доля взята от разброса светлот
 * `VOLUME_SHADE_MIN`…`VOLUME_SHADE_MAX` = 0,46…1); внутри всё ровно наоборот —
 * комната в полумраке, и солнце её местами освещает, то есть пятно это пол,
 * которому досталась светлота 1 вместо своей 0,502, — светлее себя же ровно
 * **вдвое** (1,99). Второй краски для пятна нет вовсе: `VOLUME_FLOOR_RGB`,
 * нарисованный без затенения (`flat`), и есть пятно — `170·142·110` против
 * пола `85·71·55`.
 *
 * **Гаснет пятно цветом, как и тень** — по тому же `fade`, которым гаснет она:
 * `fade` = 1 даёт полный свет, `fade` = 0 сводит пятно к самому полу, и в
 * сумерках оно исчезает, не мигнув. Прозрачностью этого делать нельзя по той же
 * причине, что у тени: пятна двух окон одной комнаты перекрываются, и на
 * пересечении вышло бы вдвое светлее.
 *
 * Ночь пятно не красит сама: `tint` кладёт на него тот же час, что на все грани
 * сцены (`volumeFrame` → `volumeFill`), — но ночью `fade` и так ноль, и пятен
 * нет: луна их не даёт, света у неё для этого нет.
 *
 * **Пятно на стене — то же правило, а не второе** (дефект D70): у грани берётся
 * её собственный цвет и её собственная светлота, и светлота поднимается до
 * единицы тем же `fade`. Пол — частный случай с самой тёмной светлотой сцены,
 * поэтому он и стоит умолчанием; стена `216·212·204` при светлоте 0,62…0,84
 * поднимается в себя же без затенения. Главное свойство у обоих одно и то же:
 * при `fade` = 0 пятно совпадает со своей гранью точка в точку — ни ступеньки,
 * ни канта.
 */
export function volumeSunSpotRgb(fade, rgb = VOLUME_FLOOR_RGB, dim = VOLUME_SUN_SPOT_DIM) {
  const share = Math.max(0, Math.min(1, Number(fade) || 0));
  const lift = dim + (1 - dim) * share;
  return [Math.round(rgb[0] * lift), Math.round(rgb[1] * lift), Math.round(rgb[2] * lift)];
}

/**
 * Насколько глубоко в комнату заходит щуп, которым спрашивают сторону проёма.
 *
 * Полтора сантиметра от грани стены: контур помещения обводят по подложке
 * рукой, и промахнуться на сантиметр-другой — обычное дело (то же наблюдение,
 * из которого вышел напуск пола `VOLUME_FLOOR_LAP`). Больше брать нельзя:
 * перегородка в сто миллиметров, и щуп, заведённый на полметра, ушёл бы в
 * комнату за ней. Замер на объекте заказчика: все 13 проёмов отвечают одно и то
 * же при щупе 50, 150 и 400 мм — то есть выбор внутри этого разброса ни на что
 * не влияет, и взята середина.
 */
export const VOLUME_SUN_PROBE_MM = 150;

/**
 * Какую долю проёма штора должна закрыть, чтобы погасить пятно, — **половину**.
 *
 * Полупятен не бывает (см. `volumeSunOpenings`), значит порог обязан быть, и
 * половина — единственный, который не выдуман: он симметричен и не требует
 * второго числа. Промахи названы прямо: штора, закрывающая 0,6 широкого окна,
 * гасит пятно целиком, а закрывающая 0,4 — не гасит вовсе.
 */
export const VOLUME_SHEER_SHARE = 0.5;

/** Ткань ли это: у тела модели стоит именованная плотность (таск 189). */
function volumeSheerParts(parts) {
  return Array.isArray(parts) && parts.some((part) => part && part.clear);
}

/**
 * Штора ли эта метка — спрашивается **у модели, а не у кода типа**.
 *
 * Ткань в этой сборке уже помечена: у полотнищ стоит `clear: "sheer"` (таск
 * 189) — и у модели точечной шторы (`things.js` → `curtainRail`), и у повтора
 * вдоль пути у линейной (`lines.js` → `КШ`). Поэтому вопрос «что висит перед
 * проёмом» задаётся тому же признаку, которым ткань рисуется: завёл человек
 * свой тип с тюлевой моделью — он гасит пятно даром, а список кодов пришлось бы
 * править. Труба карниза плотная и в счёт не идёт — у неё `clear` нет.
 */
export function volumeSheerPlace(place) {
  if (!place) return false;
  if (place.repeat && volumeSheerParts(place.repeat.parts)) return true;
  return Boolean(place.model && volumeSheerParts(place.model.parts));
}

/**
 * Шторы схемы — те метки, которые **можно открыть и закрыть** (G332).
 *
 * Отбор один на две задачи: счёт пятна берёт отсюда ткань перед проёмом, а окно
 * — список для строки «Шторы: открыто N из M» и для ответа «а есть ли они
 * вообще». Второго отбора заводить нельзя: разойдись они — окно обещало бы
 * открыть штору, которую свет не спрашивает.
 *
 * Условие то же, что было внутри счёта: тюлевое тело модели (`volumeSheerPlace`)
 * **и** привязка к стене с габаритом — без стены и ширины связать её с проёмом
 * нечем.
 */
export function volumeSheerPlaces(places) {
  const out = [];
  for (const place of places || []) {
    if (!place || place.mode !== VOLUME_MARK_WALL || !place.wallId || !place.frame) continue;
    if (!volumeSheerPlace(place)) continue;
    out.push(place);
  }
  return out;
}

/**
 * Открыта ли эта штора. Список пустой или не дан — закрыты все (G301).
 *
 * **Отметка состояния, а не поле объекта** — ровно как у двери
 * (`volumeDoorOpen`, G207): открытые шторы живут экраном, в `project.json` о
 * них ни строки (G68). Открывание в этом таске не делается нарочно — слова
 * заказчика «потом сделаем их открытие», — но счёт пятна уже спрашивает
 * **состояние**, а не «штора есть»: включить открывание значит положить id
 * метки в это множество (`volumeScene(..., { openCurtainIds })`) и дать ему
 * клавишу в `panels/volume.js`, где уже лежит такое же множество дверей.
 * Переписывать счёт пятна для этого не придётся.
 */
export function volumeCurtainOpen(openCurtainIds, markId) {
  if (!openCurtainIds || !markId) return false;
  if (typeof openCurtainIds.has === "function") return openCurtainIds.has(markId);
  return Array.isArray(openCurtainIds) && openCurtainIds.includes(markId);
}

/**
 * Проёмы, через которые солнце может положить пятно, — **без часа**.
 *
 * Собирается вместе со сценой и живёт в ней (`scene.sunSpots`), потому что от
 * времени здесь не зависит ничего: ни геометрия проёма, ни сторона, где комната,
 * ни штора перед ним. Час добавляет только направление света
 * (`volumeSunSpotFaces`) — тот же раздел труда, что у тени дома (таск 181):
 * сцена держит габариты, час кладёт грани.
 *
 * **Штора связывается с проёмом по стене и перекрытию вдоль неё.** Правило:
 * штора гасит проём, если она висит на **той же стене** и закрывает **не меньше
 * половины** его ширины. Стену и отступы называет сама метка (`markWall`,
 * привязка к стене с `atMm`…`toMm`) — это данные, а не догадка о расстоянии, и
 * второго хозяина у вопроса «на какой стене висит метка» в сборке нет.
 * Сторона стены при этом **не спрашивается**: ткань, повешенная перед проёмом,
 * заслоняет его с любой стороны, а спроси я сторону — штора, размеченная с
 * улицы, пропускала бы солнце.
 *
 * Промахи правила названы прямо: штора на соседней стене того же окна (эркер,
 * размеченный одной линией по двум стенам) гасит только проёмы своей стены;
 * штора, задвинутая на треть окна, не гасит ничего; «половина» порога — число,
 * а не измерение света.
 *
 * **Закрытое глухое полотно света не пропускает** (дефект D69). До этого таска
 * полотно в счёт не шло вовсе: закрытая дверь пропускала пятно, как пустой
 * проём. Спрашивается здесь ровно то же, что у шторы, — **состояние**
 * (`openDoorIds`, G207), а не вид: закрытая глухая гасит, открытая пропускает.
 * Стекло спрашивается отметкой (`openingGlazed`, таск 215), а не видом: у
 * стеклянной двери вместо глухого полотна рама и стекло, и закрытой она светит
 * так же, как окно. «Есть ли полотно» спрашивает `openingOpens` — тот же
 * вопрос, по которому собран список дверей сцены, поэтому гаснут и ворота,
 * которых `openingHasLeaf` не считает.
 */
export function volumeSunOpenings(project, schemeId, rooms, places, heightOf, options = {}) {
  const openCurtainIds = options.openCurtainIds || null;
  const openDoorIds = options.openDoorIds || null;
  const spots = [];
  if (!rooms || rooms.length === 0) return spots;
  const walls = wallsOnScheme(project, schemeId);
  // Пятну нужен **пол**: в помещении без пола (двусветное пространство, таск
  // 209) лежать ему не на чем, и такая комната для света — та же улица. Светить
  // сквозь дыру в перекрытии сборка не умеет и не делает вид, что умеет: дыра
  // ведёт на **чужой этаж**, а этажи собираются порознь (таск 202) — см. разбор
  // у `volumeSunBeam`.
  const roomAt = (point) =>
    rooms.find((room) => room.hasFloor !== false && volumePointInside(point, room.pointsMm)) || null;
  // Тюль по стенам: отступы вдоль стены, посчитанные один раз на сцену.
  const sheers = [];
  for (const place of volumeSheerPlaces(places)) {
    if (volumeCurtainOpen(openCurtainIds, place.markId)) continue;
    sheers.push(place);
  }
  // Перекрытия шторами — по стене и **один раз на сцену**: их спрашивает и сам
  // проём, и проём на пути света (G332), а считать их дважды значило бы завести
  // второго хозяина порога `VOLUME_SHEER_SHARE`.
  const curtainsOf = new Map();
  for (const place of sheers) {
    const wall = walls.find((item) => item.id === place.wallId);
    const vectors = wall ? wallVectors(wall) : null;
    if (!vectors) continue;
    const middle =
      (place.frame.at.x - Number(wall.aMm.x)) * vectors.u.x + (place.frame.at.y - Number(wall.aMm.y)) * vectors.u.y;
    const reach = Math.max(0, Number(place.frame.widthMm) || 0) / 2;
    const list = curtainsOf.get(wall.id) || [];
    list.push({ markId: place.markId, fromMm: middle - reach, toMm: middle + reach });
    curtainsOf.set(wall.id, list);
  }
  /** Чья штора закрывает этот отступ стены, или `null`. Порог — половина ширины. */
  const sheerOver = (wallId, fromMm, toMm) => {
    const widthMm = toMm - fromMm;
    const found = (curtainsOf.get(wallId) || []).find(
      (curtain) => Math.min(curtain.toMm, toMm) - Math.max(curtain.fromMm, fromMm) >= widthMm * VOLUME_SHEER_SHARE,
    );
    return found ? found.markId : null;
  };
  // Что света не пропускает: закрытое глухое полотно (D69) или закрытая штора
  // перед проёмом (G301) — один ответ на оба места, где это спрашивают.
  const shutOf = (wall, opening, fromMm, toMm) =>
    volumeOpeningShut(opening, openDoorIds) || Boolean(sheerOver(wall.id, fromMm, toMm));
  // Помещение со стенами по рёбрам — **один раз на сцену и на помещение**: от
  // часа это не зависит, а свет спрашивает его на каждом пересчёте часа.
  const lights = new Map();
  const lightOf = (room, steps) => {
    if (!room) return null;
    const key = room.pointsMm;
    const held = lights.get(key);
    if (held && held.steps >= steps) return held.light;
    const light = volumeRoomLight(room, {
      walls,
      heightOf,
      openingsOf: (wall) => openingsInWall(project, wall.id),
      roomAt,
      shutOf,
      steps,
      lightOf,
    });
    lights.set(key, { steps, light });
    return light;
  };
  const lightAt = (point) => lightOf(roomAt(point), VOLUME_SUN_STEPS - 1);
  for (const wall of walls) {
    const vectors = wallVectors(wall);
    if (!vectors) continue;
    const openings = openingsInWall(project, wall.id);
    if (openings.length === 0) continue;
    const { u, n, len } = vectors;
    const half = Number(wall.thicknessMm) / 2;
    const heightMm = Number(heightOf ? heightOf(wall) : 0) || 0;
    const at = (alongMm, across) => ({
      x: Number(wall.aMm.x) + u.x * alongMm + n.x * across,
      y: Number(wall.aMm.y) + u.y * alongMm + n.y * across,
    });
    for (const opening of openings) {
      const fromMm = Math.max(0, Math.min(len, Number(opening.atMm)));
      const toMm = Math.max(fromMm, Math.min(len, fromMm + Number(opening.widthMm)));
      const bottomMm = Math.max(0, Number(opening.heightAboveFloorMm || 0));
      const topMm = heightMm > 0 ? Math.min(heightMm, bottomMm + Number(opening.heightMm)) : bottomMm + Number(opening.heightMm);
      if (!(toMm > fromMm) || !(topMm > bottomMm)) continue;
      const middleMm = (fromMm + toMm) / 2;
      // Штора считается закрывающей, когда перекрытие вдоль стены больше
      // половины ширины проёма.
      const covered = sheerOver(wall.id, fromMm, toMm);
      spots.push({
        openingId: opening.id || null,
        wallId: wall.id,
        aMm: { x: Number(wall.aMm.x), y: Number(wall.aMm.y) },
        u: { x: u.x, y: u.y },
        n: { x: n.x, y: n.y },
        halfMm: half,
        fromMm,
        toMm,
        bottomMm,
        topMm,
        // **Лицо проёма ломаной** (дефект D71): у прямоугольного верха четыре
        // точки, у арки — дуга. Считает его одно место на все поверхности
        // (`volumeOpeningFaceMm`), второго счёта дуги в сборке нет.
        faceMm: volumeOpeningFaceMm(opening, fromMm, toMm, bottomMm, topMm),
        // Помещения по обе стороны проёма: контур плюс стены по его рёбрам
        // (`volumeRoomLight`). `null` — улица.
        left: lightAt(at(middleMm, half + VOLUME_SUN_PROBE_MM)),
        right: lightAt(at(middleMm, -half - VOLUME_SUN_PROBE_MM)),
        sheerMarkId: covered,
        // Закрытое глухое полотно (дефект D69): пятна нет вовсе.
        shut: volumeOpeningShut(opening, openDoorIds),
      });
    }
  }
  return spots;
}

/**
 * Пересечение многоугольника с **выпуклым** многоугольником (обход
 * Сазерленда — Ходжмана, по одной полуплоскости на ребро отсечки).
 *
 * Режется контур помещения выпуклым параллелограммом пятна, а не наоборот, и
 * порядок здесь не вкус: алгоритм требует выпуклости **отсекающего**, а контур
 * помещения выпуклым не бывает — его обводят рукой, и Г-образная комната
 * обычное дело. Сторона «внутри» берётся у середины отсечки: у выпуклого
 * многоугольника она заведомо внутри, и обход контура — по часовой или
 * против — перестаёт значить что-либо.
 */
export function volumeClipPolygon(subject, clip) {
  if (!subject || subject.length < 3 || !clip || clip.length < 3) return [];
  let out = subject.map((point) => ({ x: point.x, y: point.y }));
  let cx = 0;
  let cy = 0;
  for (const point of clip) {
    cx += point.x;
    cy += point.y;
  }
  cx /= clip.length;
  cy /= clip.length;
  for (let index = 0; index < clip.length; index += 1) {
    const a = clip[index];
    const b = clip[(index + 1) % clip.length];
    const side = (point) => (b.x - a.x) * (point.y - a.y) - (b.y - a.y) * (point.x - a.x);
    const want = side({ x: cx, y: cy }) >= 0 ? 1 : -1;
    const inside = (point) => side(point) * want >= 0;
    const next = [];
    for (let at = 0; at < out.length; at += 1) {
      const here = out[at];
      const there = out[(at + 1) % out.length];
      const hereIn = inside(here);
      const thereIn = inside(there);
      if (hereIn) next.push(here);
      if (hereIn !== thereIn) {
        const from = side(here);
        const to = side(there);
        const share = from / (from - to);
        next.push({ x: here.x + (there.x - here.x) * share, y: here.y + (there.y - here.y) * share });
      }
    }
    out = next;
    if (out.length < 3) return [];
  }
  return out;
}

/**
 * **Сколько шагов делает свет** — два (G332). Слова заказчика: «он должен
 * проходить через окна с открытыми шторами и через проёмы в другие комнаты».
 *
 * Шаг первый — снаружи в комнату через её собственный проём (таск 196). Шаг
 * второй — из этой комнаты в соседнюю через проём, на который легло её пятно:
 * **проём со светом сам становится источником**. Рекурсии нет нарочно, и это
 * не лень: каждый шаг множит число пятен на число проёмов комнаты, а польза
 * падает — свет, дошедший до третьей комнаты, не отличить от общего полумрака.
 * Два шага — это «вижу, что соседняя комната подсвечена оттого, что солнце
 * бьёт в эту», то есть ровно то, о чём просил заказчик.
 *
 * Число названо константой, а не вписано в обход: вырасти ему придётся вместе
 * с глубиной `volumeRoomLight`, и оба места читают одно и то же.
 */
export const VOLUME_SUN_STEPS = 2;

/**
 * **Закрытое глухое полотно света не пропускает** (дефект D69).
 *
 * Один вопрос на два места: сам проём, в который светит солнце, и проём на пути
 * второго шага (G332). Три правила в одной строке, и каждое — чужое, уже
 * существующее:
 *
 *   `openingOpens`  — есть ли полотно вообще (таск 219). У окна, арки и пустого
 *                     проёма его нет, и гасить нечему; у ворот есть, хотя
 *                     `openingHasLeaf` отвечает про них «нет» — поэтому
 *                     спрашивается именно `openingOpens`, тот же вопрос, по
 *                     которому собран список дверей сцены;
 *   `openingGlazed` — **отметка**, а не вид (таск 215): у стеклянной двери
 *                     вместо глухого полотна рама и стекло, и закрытой она
 *                     светит, как окно. Сравнивать вид с `glassDoor` нельзя —
 *                     новая разметка пишет породу плюс отметку;
 *   `volumeDoorOpen`— **состояние**, живущее в сеансе окна (G207, G68): открыл
 *                     дверь — пятно вернулось, и в объект не записано ничего.
 */
export function volumeOpeningShut(opening, openDoorIds) {
  if (!opening || !openingOpens(opening.kind)) return false;
  if (openingGlazed(opening)) return false;
  return !volumeDoorOpen(openDoorIds, opening.id);
}

/**
 * **Помещение глазами света**: контур плюс то, что стоит по его рёбрам.
 *
 * Зачем это понадобилось: до таска свет знал о комнате только контур и клал
 * пятно на пол (таск 196). Пятну, уехавшему за дальнюю стену, нужна **сама
 * стена** (дефект D70), а второму шагу (G332) — **проём** в ней и комната за
 * ним. И то и другое от часа не зависит, поэтому считается здесь, вместе со
 * сценой, а не в пересчёте часа.
 *
 * На каждое ребро контура — `null` или запись:
 *
 *   `offMm`  — на сколько грань стены отстоит от прямой ребра наружу. Контур
 *              обводят рукой, и совпадать с гранью стены он не обязан: пятно
 *              ложится на **настоящую** грань, иначе оно висело бы в воздухе
 *              или уходило внутрь стены — порядок граней решают плоскости
 *              (таск 211), и промах в сантиметр спрятал бы пятно целиком;
 *   `tiles`  — сплошные куски лица стены, выпуклыми многоугольниками в
 *              координатах ребра (`volumeWallTiles`, те же, которыми стена
 *              нарисована): пятно живёт только на них, и потому не ложится ни
 *              на окно напротив, ни в дверной проём;
 *   `holes`  — проёмы этой стены: через них свет идёт дальше (`beyond` —
 *              помещение за стеной, `shut` — полотно или штора на пути).
 *
 * **Стена вдоль ребра ищется, а не берётся по привязке**: у помещения стены нет
 * вовсе (ADR 008, `volumeRooms` берёт контуры). Условие — ось стены
 * сонаправлена ребру с точностью `VOLUME_WALL_SAME_DEG` (та же мерка, которой
 * таск 214 решает «та же стена») и её ближняя грань отстоит от ребра не дальше
 * `VOLUME_FLOOR_LAP` — того самого напуска, которым пол подкладывают под стену
 * ради той же ручной обводки. Из двух граней берётся ближняя: контур, обведённый
 * чуть внутри стены, и контур, обведённый чуть внутри комнаты, — одна и та же
 * ошибка руки с разным знаком.
 *
 * Цена названа прямо: ребро, вдоль которого стены нет (широкий проход между
 * комнатами, обведёнными порознь), света не держит — пятно там кончается, а не
 * повисает в воздухе простынёй. Длинное ребро, у которого стена стоит только
 * частью, держит свет на своей части: `tiles` считаются у той стены, которая
 * нашлась, и дальше её конца их нет.
 */
export function volumeRoomLight(room, options = {}) {
  const points = room && room.pointsMm ? room.pointsMm : null;
  if (!points || points.length < 3) return null;
  const { walls, heightOf, openingsOf, roomAt, shutOf, lightOf } = options;
  const steps = Math.max(0, Number(options.steps) || 0);
  const limit = Math.cos(VOLUME_WALL_SAME_DEG * DEG);
  const edges = [];
  for (let index = 0; index < points.length; index += 1) {
    const a = points[index];
    const b = points[(index + 1) % points.length];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy);
    if (!(len > 0)) {
      edges.push(null);
      continue;
    }
    const e = { x: dx / len, y: dy / len };
    // Наружная нормаль ребра — «левая»: обход контура приведён к часовому на
    // экране (`volumeClockwise`), и это то же соглашение, по которому смотрят
    // наружу боковые грани призмы.
    const m = { x: dy / len, y: -dx / len };
    let found = null;
    for (const wall of walls || []) {
      const vectors = wallVectors(wall);
      if (!vectors) continue;
      if (Math.abs(vectors.u.x * e.x + vectors.u.y * e.y) < limit) continue;
      const half = Number(wall.thicknessMm) / 2;
      const axis = (Number(wall.aMm.x) - a.x) * m.x + (Number(wall.aMm.y) - a.y) * m.y;
      // **Прямая ребра обязана идти по телу стены** (плюс напуск по краям). Это
      // мерка `volumeWallCovers` «та же стена», только про одну стену и ребро, и
      // она терпит ровно то, что человек делает рукой: обводит то по внутренней
      // грани, то по оси стены. На объекте заказчика по осям обведено 17 рёбер
      // из 80 — у стены 250 мм это промах в 125, и порог в один напуск пола их
      // всех отбрасывал.
      if (Math.abs(axis) > half + VOLUME_FLOOR_LAP) continue;
      // Стена должна стоять **вдоль этого ребра**, а не в другом конце дома:
      // отступы её концов, снесённые на ребро, обязаны его перекрывать.
      const from = (Number(wall.aMm.x) - a.x) * e.x + (Number(wall.aMm.y) - a.y) * e.y;
      const to = from + vectors.len * vectorsAlong(vectors.u, e);
      if (Math.min(Math.max(from, to), len) - Math.max(Math.min(from, to), 0) <= 1) continue;
      if (found && Math.abs(axis) >= Math.abs(found.axisMm)) continue;
      // Грань, которой стена смотрит **в это помещение**: она лежит со стороны
      // внутренней нормали ребра, а не та, что просто ближе. Контур, обведённый
      // по оси, и контур, обведённый по дальней грани, дают одну и ту же стену и
      // одну и ту же её поверхность — настоящую.
      found = { offMm: axis - half, axisMm: axis, wall, vectors, half };
    }
    if (!found) {
      edges.push(null);
      continue;
    }
    const wall = found.wall;
    const heightMm = Number(heightOf ? heightOf(wall) : 0) || 0;
    const openings = openingsOf ? openingsOf(wall) : [];
    // Перевод отступа вдоль **стены** в отступ вдоль **ребра**: стену могли
    // чертить в другую сторону, и тогда отступы идут навстречу.
    const base = (Number(wall.aMm.x) - a.x) * e.x + (Number(wall.aMm.y) - a.y) * e.y;
    const flip = vectorsAlong(found.vectors.u, e);
    const wAt = (alongWall) => base + alongWall * flip;
    const tiles = [];
    for (const tile of volumeWallTiles(found.vectors.len, heightMm, openings)) {
      const bottomFrom = tile.bottomFromMm == null ? tile.bottomMm : tile.bottomFromMm;
      const bottomTo = tile.bottomToMm == null ? tile.bottomMm : tile.bottomToMm;
      tiles.push([
        { wMm: wAt(tile.fromMm), hMm: bottomFrom },
        { wMm: wAt(tile.toMm), hMm: bottomTo },
        { wMm: wAt(tile.toMm), hMm: tile.topMm },
        { wMm: wAt(tile.fromMm), hMm: tile.topMm },
      ]);
    }
    const holes = [];
    if (steps > 0) {
      for (const opening of openings) {
        const fromMm = Math.max(0, Math.min(found.vectors.len, Number(opening.atMm)));
        const toMm = Math.max(fromMm, Math.min(found.vectors.len, fromMm + Number(opening.widthMm)));
        const bottomMm = Math.max(0, Number(opening.heightAboveFloorMm || 0));
        const topMm =
          heightMm > 0 ? Math.min(heightMm, bottomMm + Number(opening.heightMm)) : bottomMm + Number(opening.heightMm);
        if (!(toMm > fromMm) || !(topMm > bottomMm)) continue;
        // Комната **за стеной** — тем же щупом, которым солнце выясняет, с
        // какой стороны проёма улица (`VOLUME_SUN_PROBE_MM`): второго числа для
        // этого не заведено.
        const side = found.vectors.n.x * m.x + found.vectors.n.y * m.y >= 0 ? 1 : -1;
        const middle = (fromMm + toMm) / 2;
        const probe = {
          x: Number(wall.aMm.x) + found.vectors.u.x * middle + found.vectors.n.x * side * (found.half + VOLUME_SUN_PROBE_MM),
          y: Number(wall.aMm.y) + found.vectors.u.y * middle + found.vectors.n.y * side * (found.half + VOLUME_SUN_PROBE_MM),
        };
        const beyondRoom = roomAt ? roomAt(probe) : null;
        if (!beyondRoom || beyondRoom.pointsMm === points) continue;
        const beyond = lightOf ? lightOf(beyondRoom, steps - 1) : null;
        if (!beyond) continue;
        holes.push({
          openingId: opening.id || null,
          shut: shutOf ? Boolean(shutOf(wall, opening, fromMm, toMm)) : false,
          // Лицо проёма — то же, что у источника: у арки свет идёт сквозь дугу,
          // а не сквозь прямоугольник (дефект D71).
          faceMm: volumeOpeningFaceMm(opening, fromMm, toMm, bottomMm, topMm).map((point) => ({
            wMm: wAt(point.alongMm),
            hMm: point.zMm,
          })),
          beyond,
        });
      }
    }
    edges.push({ offMm: found.offMm, tiles, holes });
  }
  return { pointsMm: points, edges };
}

/**
 * Перенос помещения света на сдвиг привязки (таск 205): в стопке этажей чужой
 * этаж стоит в своих координатах, и свет обязан переехать вместе с ним.
 *
 * Переносится **только контур**: отступы кусков стены и просветов считаны вдоль
 * ребра, а смещение грани — поперёк, и от переноса ни одно из этих чисел не
 * меняется. Комната за проёмом переезжает тем же счётом — второй шаг света
 * (G332) живёт на том же этаже, что первый.
 */
export function volumeShiftRoomLight(light, shiftMm) {
  if (!light) return null;
  if (!shiftMm || (!shiftMm.x && !shiftMm.y)) return light;
  return {
    pointsMm: volumeShiftPoints(light.pointsMm, shiftMm),
    edges: (light.edges || []).map((edge) => {
      if (!edge) return null;
      if (edge.holes.length === 0) return edge;
      return {
        ...edge,
        holes: edge.holes.map((hole) => ({ ...hole, beyond: volumeShiftRoomLight(hole.beyond, shiftMm) })),
      };
    }),
  };
}

/** Навстречу ли идут два единичных направления: `1` или `−1`. */
function vectorsAlong(u, e) {
  return u.x * e.x + u.y * e.y >= 0 ? 1 : -1;
}

/**
 * Грани солнечных пятен в этот час (таск 196).
 *
 * `spots` — проёмы сцены (`scene.sunSpots`), `shadow` — где стоит солнце и
 * насколько свет виден (`mood.shadow`, та же тройка, которой гаснет наружная
 * тень). Хозяин у света и у тени один нарочно: разойдись они, пятно на полу
 * легло бы не в ту сторону, в которую уходит тень дома за окном.
 *
 * **Солнце зашло — пятен нет**: `fade` ноль, и счёт не начинается. В сумерках
 * пятно гаснет тем же `fade`, что тень. Ночью его не даёт и луна: света у неё
 * для этого нет, и обещать его честнее не обещать.
 *
 * **Ярус у пятна свой** (`VOLUME_LAYER_SUN`): пятно лежит выше пола своей
 * комнаты и ниже всего, что в комнате стоит. Числа — те же, что стоили дефекта
 * D49: пятно и пол **коплоскостны** (оба на нулевой отметке, и у пятна нет даже
 * миллиметра подъёма, которым вещь стоит перед стеной), то есть дальность их
 * середин решала бы спор от часа к часу — пятно уходит от стены в комнату и
 * оказывается то ближе пола, то дальше. Ярусом же порядок задан правилом:
 *
 *   пол (2) → пятно (3) → тела (4) → указатель (5),
 *
 * и из этого прямо следуют два ответа, которых пришлось бы искать отдельно:
 * **метка на полу** (тело яруса 4, поднятое на `VOLUME_MARK_LIFT_MM`) рисуется
 * поверх пятна и остаётся видна; **вещь чертежа** (диван, шкаф) тоже, то есть
 * пятно под ней не просвечивает — свет кончается у того, что стоит на полу.
 * Полупрозрачная вещь (таск 169) смешивается с пятном, как смешивалась с полом.
 *
 * **Пятно обрезано контуром своей комнаты** (`volumeClipPolygon`). Без обрезки
 * закатное пятно уезжает сквозь стены на десятки метров: при высоте солнца 5°
 * окно с верхом 2,2 м даёт вынос 25 м, то есть через всю квартиру и наружу.
 *
 * **Пятно ложится и на стену** (дефект D70). Обрезка от этого не ослабла, а
 * наоборот: уехавшая за контур часть пятна не выбрасывается, а поднимается по
 * той стене, на которую свет и попадает. Разбор — у `volumeSunBeam`.
 */
export function volumeSunSpotFaces(spots, shadow, out = []) {
  const fade = shadow ? Math.max(0, Math.min(1, Number(shadow.fade))) : 0;
  if (!spots || spots.length === 0 || !(fade > 0)) return out;
  const rise = Number(shadow.rise);
  if (!Number.isFinite(rise) || !(rise > 0)) return out;
  // Вынос на миллиметр высоты: `1 / tg(высота солнца)`. Высота снизу не
  // подпирается (в отличие от тени дома, которой нужна земляная плита под ней):
  // пятно обрезано комнатой, и длина ему не страшна — у `fade` ноль наступает
  // раньше, чем `tg` уходит в ноль.
  const reach = 1 / Math.tan(rise * DEG);
  const away = ((Number(shadow.az) || 0) + 180) * DEG;
  // Куда идёт свет: ровно прочь от солнца, той же мерой, которой уходит тень
  // (`volumeShadowShift`). Сторона света чертежа здесь уже учтена — `az`
  // приходит повёрнутым на `topAzimuthDeg` (G288, `volumeSunAt`).
  const dir = { x: Math.cos(away), y: Math.sin(away) };
  for (const spot of spots) {
    // Закрытая штора гасит пятно своего проёма целиком (G301), закрытое глухое
    // полотно — тоже (дефект D69). Оба ответа посчитаны вместе со сценой: от
    // часа они не зависят, а спрашиваются на каждом его пересчёте.
    if (spot.sheerMarkId || spot.shut) continue;
    const into = spot.n.x * dir.x + spot.n.y * dir.y;
    // Свет идёт вдоль стены: пятну негде лежать, и считать нечего.
    if (!(Math.abs(into) > 1e-6)) continue;
    const sign = into > 0 ? 1 : -1;
    const room = sign > 0 ? spot.left : spot.right;
    const sunny = sign > 0 ? spot.right : spot.left;
    // Принимающая сторона — комната, солнечная — улица. Разбор — выше.
    if (!room || sunny) continue;
    // Луч считается от **внутренней грани** стены (`halfMm` в сторону комнаты):
    // пятно начинается там, где свет входит в комнату, а не в середине стены.
    volumeSunBeam(
      spot.faceMm,
      room,
      {
        origin: {
          x: spot.aMm.x + spot.n.x * spot.halfMm * sign,
          y: spot.aMm.y + spot.n.y * spot.halfMm * sign,
        },
        u: spot.u,
        dir,
        reach,
        fade,
        // `spot.baseMm` — пол **своего этажа** (таск 202). У одной схемы это
        // ноль; в стопке пятно обязано лежать на том полу, через чьё окно
        // вошло, и рисоваться раньше перекрытия этажа выше — иначе оно легло бы
        // светлым пятном на крышу.
        baseMm: Number(spot.baseMm) || 0,
      },
      // Вход первого шага — сама плоскость проёма: дальше луча считать от неё.
      { t0: 0, t1: 0 },
      VOLUME_SUN_STEPS - 1,
      out,
    );
  }
  return out;
}

/** Режет луч-многоугольник полуплоскостью: `f` ≥ 0 — оставить. `f` обязана быть линейной. */
function volumeSunClipHalf(points, f) {
  const out = [];
  for (let index = 0; index < points.length; index += 1) {
    const here = points[index];
    const there = points[(index + 1) % points.length];
    const a = f(here);
    const b = f(there);
    if (a >= 0) out.push(here);
    if (a < 0 !== b < 0) {
      const share = a / (a - b);
      out.push({
        alongMm: here.alongMm + (there.alongMm - here.alongMm) * share,
        zMm: here.zMm + (there.zMm - here.zMm) * share,
      });
    }
  }
  return out.length >= 3 ? out : [];
}

/**
 * Режет луч-многоугольник выпуклым куском **лица стены** (`shape` в
 * `{wMm, hMm}`), переводя каждую точку луча в лицо данным `faceAt`.
 *
 * Сторона «внутри» берётся у середины куска — тот же приём, что в
 * `volumeClipPolygon`: обход куска по часовой или против перестаёт значить
 * что-либо. Перевод луча в лицо **линеен** (см. `volumeSunBeam`), поэтому
 * прямая режется прямой и доля считается по одному отношению.
 */
function volumeSunFaceClip(points, shape, faceAt) {
  if (points.length < 3 || !shape || shape.length < 3) return [];
  let cw = 0;
  let ch = 0;
  for (const point of shape) {
    cw += point.wMm;
    ch += point.hMm;
  }
  cw /= shape.length;
  ch /= shape.length;
  let out = points;
  for (let index = 0; index < shape.length; index += 1) {
    const a = shape[index];
    const b = shape[(index + 1) % shape.length];
    const side = (wMm, hMm) => (b.wMm - a.wMm) * (hMm - a.hMm) - (b.hMm - a.hMm) * (wMm - a.wMm);
    const want = side(cw, ch) >= 0 ? 1 : -1;
    out = volumeSunClipHalf(out, (point) => {
      const face = faceAt(point);
      return side(face.wMm, face.hMm) * want;
    });
    if (out.length < 3) return [];
  }
  return out;
}

/** Площадь луч-многоугольника в мм² просвета: ею отсекаются вырожденные куски. */
function volumeSunArea(points) {
  let sum = 0;
  for (let i = 0, j = points.length - 1; i < points.length; j = i, i += 1) {
    sum += points[j].alongMm * points[i].zMm - points[i].alongMm * points[j].zMm;
  }
  return Math.abs(sum) / 2;
}

/** Чем пятно меньше, тем меньше смысла в грани: половина квадратного сантиметра. */
const VOLUME_SUN_MIN_MM2 = 50;

/**
 * **Пучок света, прошедший через проём, — один шаг.**
 *
 * Считается он не в плане и не в трёх осях, а **в самом просвете**: точка пучка
 * — это `{alongMm, zMm}`, то есть «через какое место проёма прошёл луч». Все
 * лучи пучка идут в одну сторону, поэтому место попадания — линейная функция
 * этой пары, и из одного этого факта выходит весь обход:
 *
 *   — **на полу** луч `(a, z)` лежит в `origin + u·a + dir·z·reach`: падение
 *     `1/reach` на миллиметр хода, значит высоты `z` хватает ровно на `z·reach`
 *     хода. Это та же формула, которой пятно считалось с таска 196, — в
 *     прежнем виде она и осталась, только лицо проёма теперь ломаная
 *     (`volumeOpeningFaceMm`), а не четыре угла: у арки свет идёт сквозь дугу;
 *   — **ребро контура** `k` луч пересекает на ходу `τ_k(a) = t0 + t1·a` —
 *     линейно по `a`, потому что ребро прямое, а ход у всех лучей один;
 *   — **высота попадания** в стену — `z − τ_k(a)/reach`, тоже линейная. Больше
 *     нуля — луч встретил стену раньше пола; меньше — успел лечь на пол.
 *
 * Отсюда **дефект D70 лечится без второго правила**: пятно, уехавшее за дальнюю
 * стену, не выбрасывается, а поднимается по ней на ту самую высоту. Окно 800 мм
 * при 6° даёт вынос 7,6 м — в комнате 2,8 м на пол не попадает **ничего**, и до
 * этого таска пятна не было вовсе; теперь оно стоит на дальней стене от 506 до
 * 1806 мм. Обрезка комнатой при этом не ослабла: пол режется её контуром, как
 * резался, а стена — только сплошными кусками своего лица (`tiles`), поэтому
 * пятно не ложится ни на окно напротив, ни в проём.
 *
 * **Через какое ребро луч выходит, решает только `a`** — и это не упрощение, а
 * свойство: в плане все лучи с одним `a` идут по одной и той же прямой, и
 * различаются лишь тем, когда кончится высота. Поэтому просвет делится по `a`
 * на участки с общим ребром выхода: границы участков — те `a`, где два ребра
 * меняются местами или где точка выхода доходит до конца ребра (всё это корни
 * линейных уравнений, считать нечего). Внутри участка ребро спрашивается один
 * раз — настоящим обходом по контуру.
 *
 * **Второй шаг** (G332): луч, попавший не в сплошной кусок стены, а в её проём,
 * идёт дальше — тем же пучком, с тем же `origin` и той же `dir`, только
 * просветом ему становится лицо того проёма, а комнатой — комната за ним.
 * Рекурсии нет: `steps` убывает, и у второго шага проёмов в описании комнаты
 * уже нет вовсе (`volumeRoomLight` строит их на один шаг). Дверь на пути
 * подчиняется тому же правилу, что дверь-источник (`volumeOpeningShut`): глухая
 * закрытая не пропускает, открытая и стеклянная пропускают.
 *
 * **Дыра двусвета (снятый пол) светом не работает, и это не недоделка.** Второй
 * шаг идёт через проём в **стене своей схемы**, а дыра в перекрытии ведёт на
 * чужой этаж: этажи собираются порознь (`volumeStackScene`, таск 202), у каждого
 * свои контуры и свой `baseMm`, и ни один не видит помещений соседа. Пучок
 * пришлось бы передавать из сцены в сцену — это уже не «ещё один проём», а
 * новый хозяин у геометрии этажей.
 */
function volumeSunBeam(faceMm, room, ctx, entry, steps, out) {
  if (!faceMm || faceMm.length < 3 || !room || !room.pointsMm) return out;
  const { origin, u, dir, reach, fade, baseMm } = ctx;
  const points = room.pointsMm;
  // ——— пол: та же обрезка контуром, что с таска 196 ———
  const floor = volumeClipPolygon(
    points,
    faceMm.map((point) => ({
      x: origin.x + u.x * point.alongMm + dir.x * point.zMm * reach,
      y: origin.y + u.y * point.alongMm + dir.y * point.zMm * reach,
    })),
  );
  if (floor.length >= 3) {
    out.push(
      // **Ярус у пятна телесный** (таск 211): оно лежит на полу, а пол с того
      // таска выкладывает дерево. Оставь пятну прежний ярус — и пол, рисуясь
      // после него, закрасил бы его целиком. Место в очереди пятну считает то
      // же дерево (`volumeOrderRank`): грань пятна коплоскостна полу, и обход
      // ставит её сразу за ним, а тело, стоящее на этом полу, — после неё.
      volumeFace(floor.map((point) => volumeAt(point, baseMm)), volumeSunSpotRgb(fade), {
        normal: { x: 0, y: 0, z: 1 },
        flat: true,
      }),
    );
  }
  if (!room.edges) return out;
  // ——— рёбра, через которые пучок может выйти ———
  const edges = [];
  for (let index = 0; index < points.length; index += 1) {
    const a = points[index];
    const b = points[(index + 1) % points.length];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy);
    if (!(len > 0)) continue;
    const e = { x: dx / len, y: dy / len };
    const m = { x: dy / len, y: -dx / len };
    const dot = dir.x * m.x + dir.y * m.y;
    // Наружу луч через это ребро не идёт: выйти через него нельзя.
    if (!(dot > 1e-9)) continue;
    const t0 = ((a.x - origin.x) * m.x + (a.y - origin.y) * m.y) / dot;
    const t1 = -(u.x * m.x + u.y * m.y) / dot;
    const dirE = dir.x * e.x + dir.y * e.y;
    edges.push({
      index,
      a,
      e,
      m,
      len,
      t0,
      t1,
      // Куда вдоль ребра попадает луч — тоже линейно по `a`.
      w0: (origin.x - a.x) * e.x + (origin.y - a.y) * e.y + t0 * dirE,
      w1: u.x * e.x + u.y * e.y + t1 * dirE,
      wall: room.edges[index] || null,
    });
  }
  if (edges.length === 0) return out;
  let minA = Infinity;
  let maxA = -Infinity;
  for (const point of faceMm) {
    minA = Math.min(minA, point.alongMm);
    maxA = Math.max(maxA, point.alongMm);
  }
  // ——— границы участков: корни линейных уравнений, и ничего больше ———
  const cuts = [minA, maxA];
  const edge = 1e-6;
  const addCut = (value) => {
    if (Number.isFinite(value) && value > minA + edge && value < maxA - edge) cuts.push(value);
  };
  for (let i = 0; i < edges.length; i += 1) {
    const one = edges[i];
    if (one.t1 !== 0) addCut(-one.t0 / one.t1);
    if (one.w1 !== 0) {
      addCut(-one.w0 / one.w1);
      addCut((one.len - one.w0) / one.w1);
    }
    if (one.t1 !== entry.t1) addCut((entry.t0 - one.t0) / (one.t1 - entry.t1));
    for (let j = i + 1; j < edges.length; j += 1) {
      const two = edges[j];
      if (one.t1 !== two.t1) addCut((two.t0 - one.t0) / (one.t1 - two.t1));
    }
  }
  cuts.sort((one, two) => one - two);
  /** Через какое ребро выходит луч `a`: первое по ходу, считая от входа. */
  const exitAt = (alongMm) => {
    let best = null;
    for (const one of edges) {
      const t = one.t0 + one.t1 * alongMm;
      if (!(t > entry.t0 + entry.t1 * alongMm)) continue;
      const w = one.w0 + one.w1 * alongMm;
      if (w < 0 || w > one.len) continue;
      if (!best || t < best.t) best = { one, t };
    }
    return best ? best.one : null;
  };
  // ——— участки: соседние с одним ребром выхода сливаются ———
  const runs = [];
  for (let index = 0; index < cuts.length - 1; index += 1) {
    const from = cuts[index];
    const to = cuts[index + 1];
    if (!(to - from > edge)) continue;
    const found = exitAt((from + to) / 2);
    if (!found) continue;
    const last = runs[runs.length - 1];
    if (last && last.edge === found && Math.abs(last.toMm - from) < edge) {
      last.toMm = to;
      continue;
    }
    runs.push({ edge: found, fromMm: from, toMm: to });
  }
  for (const run of runs) {
    const one = run.edge;
    if (!one.wall) continue;
    // Перевод точки пучка в лицо стены: вдоль ребра и по высоте. Обе линейны.
    const faceAt = (point) => {
      const t = one.t0 + one.t1 * point.alongMm;
      return { wMm: one.w0 + one.w1 * point.alongMm, hMm: point.zMm - t / reach };
    };
    let beam = faceMm.map((point) => ({ alongMm: point.alongMm, zMm: point.zMm }));
    beam = volumeSunClipHalf(beam, (point) => point.alongMm - run.fromMm);
    beam = volumeSunClipHalf(beam, (point) => run.toMm - point.alongMm);
    // Луч дошёл до стены раньше пола: высота попадания больше нуля.
    beam = volumeSunClipHalf(beam, (point) => faceAt(point).hMm);
    if (beam.length < 3) continue;
    const inside = { x: -one.m.x, y: -one.m.y, z: 0 };
    // Грань стены стоит там, где она **стоит**, а не где её обвели рукой.
    const offX = one.m.x * one.wall.offMm;
    const offY = one.m.y * one.wall.offMm;
    const spotAt = (point) => {
      const t = one.t0 + one.t1 * point.alongMm;
      return {
        x: origin.x + u.x * point.alongMm + dir.x * t + offX,
        y: origin.y + u.y * point.alongMm + dir.y * t + offY,
        z: baseMm + point.zMm - t / reach,
      };
    };
    // Пятно на сплошных куках лица — цвет и мера те же, что у напольного:
    // своя краска грани при светлоте 1 (`volumeSunSpotRgb`).
    const rgb = volumeSunSpotRgb(fade, VOLUME_WALL_RGB, volumeShade(inside));
    for (const tile of one.wall.tiles) {
      const patch = volumeSunFaceClip(beam, tile, faceAt);
      if (patch.length < 3 || volumeSunArea(patch) < VOLUME_SUN_MIN_MM2) continue;
      out.push(volumeFace(patch.map(spotAt), rgb, { normal: inside, flat: true }));
    }
    if (steps <= 0) continue;
    // Второй шаг: что попало в проём, идёт дальше тем же пучком.
    for (const hole of one.wall.holes) {
      if (hole.shut || !hole.beyond) continue;
      const through = volumeSunFaceClip(beam, hole.faceMm, faceAt);
      if (through.length < 3 || volumeSunArea(through) < VOLUME_SUN_MIN_MM2) continue;
      volumeSunBeam(through, hole.beyond, ctx, { t0: one.t0, t1: one.t1 }, steps - 1, out);
    }
  }
  return out;
}

/** Выпуклая оболочка (обход Эндрю). Точек мало — восемь на стену. */
export function volumeHull(points) {
  const list = [...points].sort((a, b) => (a.x === b.x ? a.y - b.y : a.x - b.x));
  if (list.length < 3) return list;
  const cross = (o, a, b) => (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  const half = (source) => {
    const out = [];
    for (const point of source) {
      while (out.length >= 2 && cross(out[out.length - 2], out[out.length - 1], point) <= 0) out.pop();
      out.push(point);
    }
    out.pop();
    return out;
  };
  return [...half(list), ...half([...list].reverse())];
}

/**
 * Прямая призма по плановому многоугольнику: боковые грани, верх и — если вещь
 * висит над полом — низ. Низ лежащей на полу вещи не рисуется вовсе: его
 * никогда не видно, а грань стоит кадра.
 */
function volumePrismFaces(corners, bottomMm, topMm, rgb, out, options = {}) {
  if (corners.length < 3 || !(topMm > bottomMm)) return out;
  const markId = options.markId || null;
  const doorId = options.doorId || null;
  // Не `Boolean`: признак несёт **плотность** (`true` — вещь чертежа, имя —
  // тело модели, таск 189), и свести его к «да» значило бы покрасить тюль
  // прозрачностью шкафа.
  const clear = options.clear || false;
  const channel = options.channel === undefined ? null : options.channel;
  for (let index = 0; index < corners.length; index += 1) {
    const a = corners[index];
    const b = corners[(index + 1) % corners.length];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    if (dx === 0 && dy === 0) continue;
    const length = Math.hypot(dx, dy);
    out.push(
      volumeFace([volumeAt(a, bottomMm), volumeAt(b, bottomMm), volumeAt(b, topMm), volumeAt(a, topMm)], rgb, {
        normal: { x: dy / length, y: -dx / length, z: 0 },
        markId,
        doorId,
        clear,
        channel,
      }),
    );
  }
  out.push(
    volumeFace(
      corners.map((point) => volumeAt(point, topMm)),
      rgb,
      { normal: { x: 0, y: 0, z: 1 }, markId, doorId, clear, channel },
    ),
  );
  // Низ лежащей на полу вещи не нужен никому, а низ висящей — нужен: на
  // потолочный светильник смотрят снизу, и без этой грани он был бы дырой.
  if (bottomMm > 0 || markId || doorId) {
    out.push(
      volumeFace(
        corners.map((point) => volumeAt(point, bottomMm)),
        rgb,
        { normal: { x: 0, y: 0, z: -1 }, markId, doorId, clear, channel },
      ),
    );
  }
  return out;
}

// ——— стена ———————————————————————————————————————————————————————————————

/**
 * Проём, через который проходят. Решает **геометрия, а не вид**: низ не выше
 * порога — переступили. Окно исключено отдельно и нарочно: оно застеклено, и
 * панорамное окно до пола держит так же, как стена под обычным.
 */
export function volumeOpeningWalkable(opening) {
  // Сквозь что ходят, решает модель (`openingWalkThrough`): сквозь окно любого
  // вида — нет, сквозь дверь, проём, арку и ворота — да. Сравнения с `"window"`
  // здесь больше нет нарочно: витраж в пол и балконное остекление (таск 215)
  // стоят от пола, и забытое сравнение пустило бы человека сквозь стекло.
  if (!opening || !openingWalkThrough(opening.kind)) return false;
  return Number(opening.heightAboveFloorMm || 0) <= VOLUME_STEP_MM;
}

/**
 * Сплошные участки стены — то, что держит человека. Проёмы, через которые
 * проходят, оставляют дыру; окно дыры не оставляет.
 */
export function volumeWallSolids(wall, openings) {
  const length = Math.hypot(Number(wall.bMm.x) - Number(wall.aMm.x), Number(wall.bMm.y) - Number(wall.aMm.y));
  const holes = (openings || [])
    .filter((opening) => volumeOpeningWalkable(opening))
    .map((opening) => ({ from: Number(opening.atMm), to: Number(opening.atMm) + Number(opening.widthMm) }))
    .sort((left, right) => left.from - right.from);
  const spans = [];
  let cursor = 0;
  for (const hole of holes) {
    if (hole.from > cursor) spans.push({ fromMm: cursor, toMm: Math.min(hole.from, length) });
    cursor = Math.max(cursor, hole.to);
  }
  if (cursor < length) spans.push({ fromMm: cursor, toMm: length });
  return spans.filter((span) => span.toMm - span.fromMm > 0);
}

/**
 * Низкие перемычки над проёмами (G234): препятствие **над** дырой, которое
 * держит стоящего и пропускает присевшего.
 *
 * Зачем оно вообще: проём, через который проходят, вырезан из препятствий
 * целиком (`volumeWallSolids`) — то есть лаз высотой в метр до таска 159
 * пропускал человека в полный рост. Заказчик назвал проём среди низких мест,
 * где «встать нельзя», и перемычка — это он же, только посчитанный.
 *
 * Порог отбора — `VOLUME_LINTEL_MM`, и он нарочно много ниже макушки: см. там.
 */
export function volumeWallLintels(openings, wallHeightMm) {
  const out = [];
  for (const opening of openings || []) {
    if (!volumeOpeningWalkable(opening)) continue;
    const bottom = Math.max(0, Number(opening.heightAboveFloorMm) || 0);
    const top = bottom + (Number(opening.heightMm) || 0);
    if (!(top > 0)) continue;
    const fromMm = Number(opening.atMm) || 0;
    const toMm = fromMm + (Number(opening.widthMm) || 0);
    if (!(toMm > fromMm)) continue;
    const ceiling = Math.max(top, Number(wallHeightMm) || top);
    // **У арки просвет считается по дуге** (дефект D71). Прежде перемычка
    // спрашивала один верх проёма на всю ширину, и у арки 1200 × 2100 выходило,
    // что препятствия нет вовсе: 2100 выше порога. А у косяков просвет там
    // 1500 — ниже порога, то есть пройти под пятой в полный рост нельзя, и
    // голова должна её задевать. Дуга берётся **та же**, которой стена садится
    // на свод (`volumeArchSpan` → `openingArchDropMm`), второго счёта у арки
    // нет.
    //
    // Препятствие остаётся прямой призмой — иначе его пришлось бы учить кривым,
    // — поэтому дуга режется на те же `VOLUME_ARCH_SEGMENTS` кусков, и у каждого
    // берётся **низшая** из его двух высот: лучше пригнуться на вершок раньше,
    // чем пройти головой сквозь кладку. Куски, под которыми и так проходят в
    // рост, не заводятся вовсе — у арки 1200 × 2100 это восемь средних из
    // двенадцати.
    const span = volumeArchSpan(opening, fromMm, toMm, top, bottom);
    if (span) {
      for (let index = 0; index < span.length - 1; index += 1) {
        const left = span[index];
        const right = span[index + 1];
        const low = Math.min(left.zMm, right.zMm);
        if (low >= VOLUME_LINTEL_MM) continue;
        out.push({
          fromMm: left.alongMm,
          toMm: right.alongMm,
          bottomMm: low,
          topMm: Math.max(low, ceiling),
        });
      }
      continue;
    }
    if (top >= VOLUME_LINTEL_MM) continue;
    out.push({ fromMm, toMm, bottomMm: top, topMm: ceiling });
  }
  return out;
}

/**
 * Разбивка грани стены на прямоугольники вокруг проёмов.
 *
 * Проёмы уже отсортированы вдоль стены (`openingsInWall`), и накладываться им
 * модель не даёт (`openingsOverlap`) — значит разбивка однозначна: промежуток
 * между проёмами во всю высоту, под проёмом и над ним. Вырожденные куски
 * (проём от пола, проём до потолка) выпадают сами.
 */
export function volumeWallTiles(lengthMm, heightMm, openings) {
  const tiles = [];
  let cursor = 0;
  for (const opening of openings || []) {
    const from = Math.max(0, Math.min(lengthMm, Number(opening.atMm)));
    const to = Math.max(from, Math.min(lengthMm, from + Number(opening.widthMm)));
    const bottom = Math.max(0, Number(opening.heightAboveFloorMm || 0));
    const top = Math.min(heightMm, bottom + Number(opening.heightMm));
    if (from > cursor) tiles.push({ fromMm: cursor, toMm: from, bottomMm: 0, topMm: heightMm });
    if (to > from) {
      if (bottom > 0) tiles.push({ fromMm: from, toMm: to, bottomMm: 0, topMm: bottom });
      // **Пазухи арки** (таск 219, G329): над дугой стена не кончается по
      // прямой — у косяков она спускается до пяты, и эти два серпа и есть то,
      // чем арка отличается от проёма. Нарезаются они трапециями по дуге, а не
      // одним вогнутым многоугольником: дерево порядка (таск 151) режет грани
      // плоскостями соседей и выпуклости от них не требует, но вогнутая грань
      // ему досталась бы одной штукой на весь серп — и легла бы поверх того,
      // что видно сквозь саму арку.
      const span = volumeArchSpan(opening, from, to, top, bottom);
      if (span) {
        for (let index = 0; index < span.length - 1; index += 1) {
          const left = span[index];
          const right = span[index + 1];
          const low = Math.min(left.zMm, right.zMm);
          if (!(heightMm > low)) continue;
          tiles.push({
            fromMm: left.alongMm,
            toMm: right.alongMm,
            bottomMm: low,
            topMm: heightMm,
            bottomFromMm: left.zMm,
            bottomToMm: right.zMm,
          });
        }
      } else if (heightMm > top) {
        tiles.push({ fromMm: from, toMm: to, bottomMm: top, topMm: heightMm });
      }
    }
    cursor = Math.max(cursor, to);
  }
  if (lengthMm > cursor) tiles.push({ fromMm: cursor, toMm: lengthMm, bottomMm: 0, topMm: heightMm });
  return tiles.filter((tile) => tile.toMm > tile.fromMm && tile.topMm > tile.bottomMm);
}

/** Во сколько отрезков режется дуга арки: и свод, и пазухи, и ничего больше. */
export const VOLUME_ARCH_SEGMENTS = 12;

/**
 * Дуга арки ломаной вдоль стены: `{alongMm, zMm}` от косяка до косяка.
 *
 * `null` — у вида прямой верх или дуге негде встать (просвет ниже её подъёма).
 * Числа берутся у модели (`openingArchGeometry` и `openingArchDropMm`) — теми
 * же, какими дугу рисует лист развёртки: второй формы у арки быть не должно.
 */
function volumeArchSpan(opening, from, to, top, bottom) {
  const arch = openingArchGeometry(opening);
  if (!arch) return null;
  if (!(top - bottom > arch.riseMm)) return null;
  const points = [];
  for (let index = 0; index <= VOLUME_ARCH_SEGMENTS; index += 1) {
    const part = index / VOLUME_ARCH_SEGMENTS;
    points.push({ alongMm: from + (to - from) * part, zMm: top - openingArchDropMm(opening, part) });
  }
  return points;
}

/**
 * **Просвет проёма ломаной** — `{alongMm, zMm}` по кругу, от левого косяка.
 *
 * Один ответ на вопрос «через что именно проходит свет» (дефект D71): у вида с
 * прямым верхом четыре точки, у арки — откосы и дуга той же `volumeArchSpan`,
 * которой стена садится на свод. До этого таска солнце считало арку
 * прямоугольником, и пятно выходило шире настоящего на две пазухи.
 *
 * Выпуклый и у того и у другой: дуга идёт наружу, и прямая низа её замыкает.
 * На это опирается обрезка комнатой (`volumeClipPolygon` требует выпуклости
 * отсекающего) — заведись здесь вогнутое лицо, обрезку пришлось бы менять.
 */
export function volumeOpeningFaceMm(opening, fromMm, toMm, bottomMm, topMm) {
  const face = [
    { alongMm: fromMm, zMm: bottomMm },
    { alongMm: toMm, zMm: bottomMm },
  ];
  const span = volumeArchSpan(opening, fromMm, toMm, topMm, bottomMm);
  if (span) {
    for (let index = span.length - 1; index >= 0; index -= 1) face.push(span[index]);
    return face;
  }
  face.push({ alongMm: toMm, zMm: topMm }, { alongMm: fromMm, zMm: topMm });
  return face;
}

// ——— ус на углу стен (G265, таск 178) ————————————————————————————————————
//
// Слова заказчика: «Внешние углы под 90 градусов в стенах сделай так же как
// пофиксил столешницу». Столешница — полоса вещи чертежа, починенная усом по
// биссектрисе в таске 169 (дефект D38), и беда у стен ровно та же.
//
// **Что было видно.** Стена рисуется коробкой с поперечными торцами по своей
// оси. Две стены, сошедшиеся в вершине под 90°, кладут эти коробки крест-накрест:
// квадрат со стороной в полтолщины с **внутренней** стороны угла покрыт дважды,
// а такой же квадрат с **внешней** — не покрыт вовсе. На стене 100 мм это
// квадрат 50 × 50 мм: снаружи дома в углу зияет вырез, сквозь который видно
// землю и нутро стены, а внутри комнаты по углу идёт шов.
//
// **Чем стены отличаются от полосы.** У полосы вершины идут цепочкой: у звена
// всегда ровно один сосед с каждой стороны, и ширина у всей полосы одна. Стены
// — отдельные сущности: в вершине может сойтись три стены и больше, у соседок
// бывает разная толщина и разная высота, а конец стены может упираться в
// середину чужой. Поэтому ус ставится только там, где стык **однозначен**:
//
//   1. в вершине ровно **два** конца стен — тройник и крест пропускаются: у
//      них нет одной биссектрисы, и какую пару сводить, сказать нечем;
//   2. **высоты соседок равны** — иначе ус срезал бы торец, а над соседкой
//      осталась бы дыра во всю разницу высот;
//   3. стены **не вдоль одной прямой** — у развёрнутых на 180° кромки
//      параллельны и не пересекаются вовсе (стык и так чистый);
//   4. ус не длиннее `VOLUME_MITER_MAX` полутолщин — то же число и та же
//      причина, что у полосы (D38): на острых углах ус уходит в бесконечность;
//   5. ус короче самой стены — у стены в ладонь длиной оба уса съели бы её
//      целиком и вывернули бы грани наизнанку.
//
// Толщины при этом могут быть **разными**: кромка каждой стены кончается там,
// где встречает соответствующую кромку соседки, и обе стены считают эту точку
// одинаково — стык выходит общим и без уговора между ними.
//
// **Препятствие не меняется** — ровно как в D38: `volumeWallSolids` остаётся
// прямоугольником по оси. Цена названа прямо: внешний клин угла теперь
// нарисован, но не держит; на стене 100 мм это треугольник с катетами 50 мм,
// вдвое меньше радиуса тела, и дотянуться до него человек всё равно не может —
// его держит сама стена.

/** Какая кромка соседки отвечает кромке `side` этой стены. Ноль — вдоль одной прямой. */
function volumeMiterSide(side, hereN, hereAway, thereN, thereAway) {
  const here = hereN.x * thereAway.x + hereN.y * thereAway.y;
  const there = thereN.x * hereAway.x + thereN.y * hereAway.y;
  if (Math.abs(here) < VOLUME_MITER_EPS || Math.abs(there) < VOLUME_MITER_EPS) return 0;
  return side * Math.sign(here) * Math.sign(there);
}

/**
 * Где кончается кромка `side` стены, сходящейся с соседкой: отступ вдоль оси от
 * общей вершины, в её сторону. Отрицательный — кромка уходит **за** вершину,
 * то есть наружу угла. `null` — ус неприменим.
 */
function volumeMiterReach(side, here, there) {
  const sideThere = volumeMiterSide(side, here.n, here.away, there.n, there.away);
  if (sideThere === 0) return null;
  const turn = here.away.x * there.away.y - here.away.y * there.away.x;
  if (Math.abs(turn) < VOLUME_MITER_EPS) return null;
  const from = { x: here.n.x * side * here.half, y: here.n.y * side * here.half };
  const to = { x: there.n.x * sideThere * there.half, y: there.n.y * sideThere * there.half };
  const gap = { x: to.x - from.x, y: to.y - from.y };
  const reach = (gap.x * there.away.y - gap.y * there.away.x) / turn;
  const limit = VOLUME_MITER_MAX * here.half;
  return Math.max(-limit, Math.min(limit, reach));
}

/**
 * Усы на концах стен: `Map` по идентификатору стены →
 * `{start: {left, right} | null, end: {left, right} | null}`, где числа —
 * координаты вдоль оси стены, на которых кончаются её левая и правая кромки.
 * Без уса это 0 и длина.
 *
 * `heightOf(wall)` — высота стены в сцене: ус ставится только между стенами
 * одной высоты (см. разбор выше).
 */
export function volumeWallMiters(walls, heightOf = () => 0) {
  const list = [];
  for (const wall of walls || []) {
    const vectors = wallVectors(wall);
    if (!vectors) continue;
    list.push({ wall, vectors, half: Math.abs(Number(wall.thicknessMm) || 0) / 2 });
  }
  const atCorner = new Map();
  const keyOf = (point) => Math.round(Number(point.x)) + "," + Math.round(Number(point.y));
  list.forEach((item, index) => {
    for (const end of ["a", "b"]) {
      const key = keyOf(end === "a" ? item.wall.aMm : item.wall.bMm);
      if (!atCorner.has(key)) atCorner.set(key, []);
      atCorner.get(key).push({ index, end });
    }
  });
  const miters = new Map();
  const seatOf = (index) => {
    const id = list[index].wall.id;
    if (!miters.has(id)) miters.set(id, { start: null, end: null });
    return miters.get(id);
  };
  const faceOf = (item, end) => ({
    n: item.vectors.n,
    half: item.half,
    // Куда стена уходит от общей вершины.
    away: end === "a" ? item.vectors.u : { x: -item.vectors.u.x, y: -item.vectors.u.y },
  });
  for (const ends of atCorner.values()) {
    if (ends.length !== 2) continue;
    const [one, two] = ends;
    if (one.index === two.index) continue;
    const here = list[one.index];
    const there = list[two.index];
    if (!(here.half > 0) || !(there.half > 0)) continue;
    if (Math.abs(Number(heightOf(here.wall)) - Number(heightOf(there.wall))) > 1) continue;
    const hereFace = faceOf(here, one.end);
    const thereFace = faceOf(there, two.end);
    const cut = (item, face, other, end) => {
      const left = volumeMiterReach(1, face, other);
      const right = volumeMiterReach(-1, face, other);
      if (left === null || right === null) return null;
      // Ус длиннее стены: вывернул бы её грани наизнанку — оставляем торец.
      if (Math.max(Math.abs(left), Math.abs(right)) >= item.vectors.len) return null;
      return end === "a"
        ? { left, right }
        : { left: item.vectors.len - left, right: item.vectors.len - right };
    };
    const first = cut(here, hereFace, thereFace, one.end);
    const second = cut(there, thereFace, hereFace, two.end);
    if (!first || !second) continue;
    seatOf(one.index)[one.end === "a" ? "start" : "end"] = first;
    seatOf(two.index)[two.end === "a" ? "start" : "end"] = second;
  }
  return miters;
}

/**
 * Грани стены: две стороны, разбитые проёмами, два торца, верх; на каждый
 * проём — четыре грани его откосов, рама окну и полотно двери.
 *
 * Низ стены не рисуется: он под полом. Полотно двери стоит **закрытым** (G207,
 * решение заказчика, которое отменило решение таска 146): «По умолчанию пусть
 * все двери будут закрыты». Раскрывается оно поимённо — `openDoorIds` — и живёт
 * это только в сеансе окна: в объект состояние двери не пишется (G68).
 */
export function volumeWallFaces(wall, openings, heightMm, out = [], openDoorIds = null, miter = null, rooms = null) {
  const vectors = wallVectors(wall);
  if (!vectors || !(heightMm > 0)) return out;
  const half = Number(wall.thicknessMm) / 2;
  const { u, n, len } = vectors;
  const at = (along, across) => ({
    x: Number(wall.aMm.x) + u.x * along + n.x * across,
    y: Number(wall.aMm.y) + u.y * along + n.y * across,
  });
  // Ус на углу (G265): кромка кончается не поперёк оси, а там, где встречает
  // кромку соседки. Без соседки числа те же, что были, — 0 и длина.
  const startOf = (side) => (miter && miter.start ? (side > 0 ? miter.start.left : miter.start.right) : 0);
  const endOf = (side) => (miter && miter.end ? (side > 0 ? miter.end.left : miter.end.right) : len);
  for (const side of [1, -1]) {
    const normal = { x: n.x * side, y: n.y * side, z: 0 };
    const sideName = side > 0 ? "left" : "right";
    // Сторона стены — **один** многоугольник на кусок между проёмами. Метровой
    // сетки, которой она резалась в тасках 148–150 ради порядка рисования,
    // больше нет: порядок выкладывает дерево (`volumeOrderTree`), а вещь стоит
    // перед плоскостью стены на два миллиметра — этого дереву довольно.
    for (const tile of volumeWallTiles(len, heightMm, openings)) {
      // Крайние куски стороны дотягиваются до уса: внутренняя кромка угла
      // отступает, внешняя выходит за вершину — и обе кончаются там же, где
      // кромки соседки.
      const from = at(tile.fromMm === 0 ? startOf(side) : tile.fromMm, half * side);
      const to = at(tile.toMm === len ? endOf(side) : tile.toMm, half * side);
      // Нижняя кромка куска бывает наклонной — так стена садится на дугу арки
      // (таск 219). У прямого куска оба угла на одной высоте, и кадр прежних
      // стен от этого не меняется ни на грань.
      const bottomFrom = tile.bottomFromMm == null ? tile.bottomMm : tile.bottomFromMm;
      const bottomTo = tile.bottomToMm == null ? tile.bottomMm : tile.bottomToMm;
      // Обход берётся так, чтобы нормаль смотрела на свою сторону: на правой
      // стороне концы меняются местами.
      const first = side > 0 ? to : from;
      const second = side > 0 ? from : to;
      const firstBottom = side > 0 ? bottomTo : bottomFrom;
      const secondBottom = side > 0 ? bottomFrom : bottomTo;
      out.push(
        volumeFace(
          [
            volumeAt(first, firstBottom),
            volumeAt(second, secondBottom),
            volumeAt(second, tile.topMm),
            volumeAt(first, tile.topMm),
          ],
          VOLUME_WALL_RGB,
          { normal },
        ),
      );
    }
  }
  for (const end of [0, 1]) {
    // Сведённый ус торца не имеет вовсе: там стена переходит в соседку, и
    // поперечная грань встала бы внутри угла, споря с её же кромками.
    if (end === 0 ? miter && miter.start : miter && miter.end) continue;
    const along = end === 0 ? 0 : len;
    const normal = { x: u.x * (end === 0 ? -1 : 1), y: u.y * (end === 0 ? -1 : 1), z: 0 };
    const left = at(along, half);
    const right = at(along, -half);
    const first = end === 0 ? left : right;
    const second = end === 0 ? right : left;
    out.push(
      volumeFace([volumeAt(first, 0), volumeAt(second, 0), volumeAt(second, heightMm), volumeAt(first, heightMm)], VOLUME_WALL_RGB, {
        normal,
      }),
    );
  }
  out.push(
    volumeFace(
      [at(startOf(1), half), at(endOf(1), half), at(endOf(-1), -half), at(startOf(-1), -half)].map((point) =>
        volumeAt(point, heightMm),
      ),
      VOLUME_WALL_RGB,
      { normal: { x: 0, y: 0, z: 1 } },
    ),
  );
  for (const opening of openings || []) {
    volumeOpeningFaces(wall, opening, heightMm, out, openDoorIds, rooms);
  }
  return out;
}

/**
 * **С какой стороны стены комната** — `1`, `-1` или `0`, если ответа нет.
 *
 * Спрашивается у контуров помещений тем же щупом, которым солнце выясняет,
 * куда ему светить (`VOLUME_SUN_PROBE_MM`): точка в полутора сантиметрах от
 * грани стены — уже комната, если контур обведён. Второго числа для этого не
 * заведено, и обводят контур один раз на обе задачи.
 *
 * `0` — обе стороны одинаковы (две комнаты или улица с обеих): тогда выбор
 * делает тот, кто спрашивал, и своё умолчание он называет сам.
 */
export function volumeInnerSide(wall, rooms, alongMm) {
  if (!Array.isArray(rooms) || rooms.length === 0) return 0;
  const vectors = wallVectors(wall);
  if (!vectors) return 0;
  const half = Number(wall.thicknessMm) / 2;
  const probe = (side) => ({
    x: Number(wall.aMm.x) + vectors.u.x * alongMm + vectors.n.x * side * (half + VOLUME_SUN_PROBE_MM),
    y: Number(wall.aMm.y) + vectors.u.y * alongMm + vectors.n.y * side * (half + VOLUME_SUN_PROBE_MM),
  });
  const inside = (side) => rooms.some((room) => volumePointInside(probe(side), room.pointsMm));
  const left = inside(1);
  const right = inside(-1);
  if (left === right) return 0;
  return left ? 1 : -1;
}

/** Откосы проёма, рама окна и полотно двери — закрытое или раскрытое. */
function volumeOpeningFaces(wall, opening, heightMm, out, openDoorIds, rooms = null) {
  const vectors = wallVectors(wall);
  if (!vectors) return out;
  const half = Number(wall.thicknessMm) / 2;
  const { u, n, len } = vectors;
  const from = Math.max(0, Math.min(len, Number(opening.atMm)));
  const to = Math.max(from, Math.min(len, from + Number(opening.widthMm)));
  const bottom = Math.max(0, Number(opening.heightAboveFloorMm || 0));
  const top = Math.min(heightMm, bottom + Number(opening.heightMm));
  if (!(to > from) || !(top > bottom)) return out;
  const at = (along, across) => ({
    x: Number(wall.aMm.x) + u.x * along + n.x * across,
    y: Number(wall.aMm.y) + u.y * along + n.y * across,
  });
  // Низ проёма смотрит вверх, верх — вниз: подоконник виден снизу, перемычка
  // сверху, и затенение разводит их само.
  if (bottom > 0) {
    out.push(
      volumeFace(
        [at(from, half), at(to, half), at(to, -half), at(from, -half)].map((point) => volumeAt(point, bottom)),
        VOLUME_WALL_RGB,
        { normal: { x: 0, y: 0, z: 1 } },
      ),
    );
  }
  // **Свод арки** (таск 219, G329): у неё верх не перемычкой, а дугой, и
  // откосы кончаются на пяте. Свод нарезан теми же отрезками, что пазухи, —
  // одной ломаной на обе поверхности.
  const span = volumeArchSpan(opening, from, to, top, bottom);
  const springMm = span ? span[0].zMm : top;
  if (span) {
    const middle = (from + to) / 2;
    const arch = openingArchGeometry(opening);
    for (let index = 0; index < span.length - 1; index += 1) {
      const left = span[index];
      const right = span[index + 1];
      // Нормаль свода смотрит **внутрь проёма** — к центру той окружности, по
      // которой он идёт: лампа сцены тогда гасит дугу к косякам, и свод виден
      // сводом, а не плоской полосой.
      const atMm = (left.alongMm + right.alongMm) / 2;
      const zMm = (left.zMm + right.zMm) / 2;
      const toCentre = { along: middle - atMm, z: top - arch.radiusMm - zMm };
      const length = Math.hypot(toCentre.along, toCentre.z) || 1;
      const normal = {
        x: (u.x * toCentre.along) / length,
        y: (u.y * toCentre.along) / length,
        z: toCentre.z / length,
      };
      out.push(
        volumeFace(
          [
            volumeAt(at(left.alongMm, -half), left.zMm),
            volumeAt(at(right.alongMm, -half), right.zMm),
            volumeAt(at(right.alongMm, half), right.zMm),
            volumeAt(at(left.alongMm, half), left.zMm),
          ],
          VOLUME_WALL_RGB,
          { normal },
        ),
      );
    }
  } else if (top < heightMm) {
    out.push(
      volumeFace(
        [at(from, -half), at(to, -half), at(to, half), at(from, half)].map((point) => volumeAt(point, top)),
        VOLUME_WALL_RGB,
        { normal: { x: 0, y: 0, z: -1 } },
      ),
    );
  }
  for (const end of [from, to]) {
    const sign = end === from ? 1 : -1;
    const normal = { x: u.x * sign, y: u.y * sign, z: 0 };
    const left = at(end, half);
    const right = at(end, -half);
    const first = sign > 0 ? right : left;
    const second = sign > 0 ? left : right;
    out.push(
      volumeFace([volumeAt(first, bottom), volumeAt(second, bottom), volumeAt(second, springMm), volumeAt(first, springMm)], VOLUME_WALL_RGB, {
        normal,
      }),
    );
  }
  if (openingFamilyOf(opening.kind) === "window") {
    volumeWindowFrame(at, from, to, bottom, top, out, openingFaceGrid(opening));
    return out;
  }
  if (openingHasLeaf(opening.kind)) {
    const open = volumeDoorOpen(openDoorIds, opening.id);
    volumeDoorLeaf(wall, opening, { from, to, bottom, top }, out, open);
    return out;
  }
  // **Роллетные и подъёмно-секционные ворота.** Закрытые стоят полотном в
  // проёме, в середине толщины стены — там же, где бруски рамы у окна.
  // Открытые уходят **вверх** (таск 219, G328): в таске 215 открытого
  // положения у них не было вовсе, и довод был — «показывать это пришлось бы
  // горизонтальным листом в комнате». Заказчик довод прочёл и лист принял:
  // «да, пусть лист будет».
  if (openingMotionOf(opening.kind) === "lift") {
    const open = volumeDoorOpen(openDoorIds, opening.id);
    const inner = open ? volumeInnerSide(wall, rooms, (from + to) / 2) : 0;
    if (open) volumeLiftOpen(wall, opening, { at, from, to, bottom, top, half, heightMm, inner }, out);
    else volumeLiftLeaf(at, from, to, bottom, top, out, openingFaceGrid(opening), opening.id || null);
  }
  return out;
}

/** Толщина свёрнутого полотна: вал роллеты и пакет панелей секционных. */
export const VOLUME_ROLL_MM = 300;

/**
 * **Открытые поднимающиеся ворота** (таск 219, G328).
 *
 * Разница между рулоном и пакетом дешева, и поэтому она видна — это два разных
 * механизма, и человек, выбравший один из них, должен увидеть именно его:
 *
 *   **роллетные** — полотно свёрнуто в **вал над проёмом**: короб поперёк
 *     стены, во всю ширину проёма, прямо под перемычкой. Так его и ставят —
 *     накладным коробом либо в нишу; места он занимает ровно `VOLUME_ROLL_MM`,
 *     и в комнату не выступает ничем;
 *   **подъёмно-секционные** — панели ушли по направляющим под потолок и лежат
 *     **горизонтальным листом в комнате**: лист той же ширины, что проём, и
 *     той же длины, какой была высота полотна. Это и есть «пусть лист будет».
 *
 * Куда уводить лист, спрашивается у помещений (`inner`): панели уезжают
 * **внутрь**, в гараж, а не на улицу. Помещения не обведены — сторона взята
 * по нормали стены и названа здесь же: промах стоит картинки, а не разметки.
 *
 * Полотна в проёме при этом нет вовсе — ворота открыты, сквозь них видно.
 */
function volumeLiftOpen(wall, opening, span, out) {
  const { at, from, to, top, bottom, half, heightMm, inner } = span;
  const doorId = opening.id || null;
  const leaf = Math.max(0, top - bottom);
  const roll = Math.min(VOLUME_ROLL_MM, Math.max(60, leaf));
  if (openingSlatted(opening.kind)) {
    // Рулон: короб под перемычкой, поперёк стены, во всю ширину проёма. Если
    // над проёмом места не осталось (проём до самого потолка), вал опускается
    // в сам проём — вверху, где ему и быть.
    const room = Math.max(0, heightMm - top);
    const low = room >= roll ? top : Math.max(bottom, top - roll);
    const high = low + roll;
    const vectors = wallVectors(wall);
    volumePrismFaces(
      volumeBoxCorners(at((from + to) / 2, 0), vectors.u, to - from, Math.min(roll, half * 2)),
      low,
      high,
      VOLUME_DOOR_RGB,
      out,
      { doorId },
    );
    return out;
  }
  // Пакет панелей: горизонтальный лист под перемычкой, уходящий в комнату.
  const side = inner || 1;
  const deep = Math.max(half, leaf);
  const near = { from: at(from, half * side), to: at(to, half * side) };
  const far = { from: at(from, (half + deep) * side), to: at(to, (half + deep) * side) };
  out.push(
    volumeFace(
      [volumeAt(near.from, top), volumeAt(near.to, top), volumeAt(far.to, top), volumeAt(far.from, top)],
      VOLUME_DOOR_RGB,
      { both: true, doorId },
    ),
  );
  return out;
}

/**
 * Полотно поднимающихся ворот: панели по горизонталям его лица.
 *
 * Панель на панель не налезает и все они коплоскостны — то же условие, по
 * которому не спорят за порядок рама и стекло двери (таск 180): грани в одной
 * плоскости, которые друг друга не закрывают, в сортировке по дальности
 * безразличны.
 */
function volumeLiftLeaf(at, from, to, bottom, top, out, grid, doorId = null) {
  const height = top - bottom;
  const edges = [0, ...(grid && Array.isArray(grid.ys) ? grid.ys : []), 1];
  for (let index = 1; index < edges.length; index += 1) {
    const low = bottom + height * edges[index - 1];
    const high = bottom + height * edges[index];
    if (!(high > low)) continue;
    const first = at(from, 0);
    const second = at(to, 0);
    out.push(
      volumeFace([volumeAt(first, low), volumeAt(second, low), volumeAt(second, high), volumeAt(first, high)], VOLUME_DOOR_RGB, {
        both: true,
        doorId,
      }),
    );
  }
  return out;
}

/** Открыта ли эта дверь. Список пустой или не дан — закрыты все (G207). */
export function volumeDoorOpen(openDoorIds, doorId) {
  if (!openDoorIds || !doorId) return false;
  if (typeof openDoorIds.has === "function") return openDoorIds.has(doorId);
  return Array.isArray(openDoorIds) && openDoorIds.includes(doorId);
}

/** Толщина брусков рамы окна. */
const VOLUME_FRAME_MM = 60;

// Ручка двери (G207). Числа — обычная дверная фурнитура: ручка на 1050 мм от
// пола, длиной 130 мм, выступает на 35 мм в каждую сторону полотна, высотой
// 90 мм. Отступ от свободного края — 70 мм, как у настоящего замка.
const VOLUME_HANDLE_MM = 1050;
const VOLUME_HANDLE_LONG_MM = 130;
const VOLUME_HANDLE_OUT_MM = 35;
const VOLUME_HANDLE_TALL_MM = 90;
const VOLUME_HANDLE_EDGE_MM = 70;

/**
 * **Сложенная гармошка** (таск 226, требование G338): два числа, из которых
 * выходит толщина пакета.
 *
 * `VOLUME_FOLD_LEAF_MM` — толщина звена. Сорок миллиметров: межкомнатное
 *   полотно 35–40 мм, у складных створок берут самое тонкое из этого ряда.
 * `VOLUME_FOLD_GAP_MM` — зазор между сложенными звеньями: петля-карта с
 *   осью снаружи полотна, десять миллиметров. Без зазора звенья легли бы
 *   плоскость в плоскость, а коплоскостные грани в сортировке по дальности
 *   решаются случаем (правило таска 180) — пакет мигал бы на облёте.
 *
 * Толщина пакета считается, а не пишется: `звеньев × 40 + промежутков × 10`.
 * У гармошки каталога (четыре звена) это **190 мм** — ровно то, на сколько
 * сложенное полотно вылезает из плоскости косяка в настоящей двери.
 */
export const VOLUME_FOLD_LEAF_MM = 40;
export const VOLUME_FOLD_GAP_MM = 10;

// Рама — четыре бруска по краю проёма, в середине толщины стены. Стекла нет:
// сквозь окно видно фон, и это ровно то, чего просил заказчик.
//
// **Импосты** (таск 215) — те же бруски по долям `openingFaceGrid`: двойное
// окно получает стойку посередине, тройное две, балконное две стойки и
// перекладину пояса. Своей сетки объём не считает: разойдись она с листом —
// окно на развёртке делилось бы на три, а в объёме на две.
function volumeWindowFrame(at, from, to, bottom, top, out, grid) {
  const half = VOLUME_FRAME_MM / 2;
  const span = to - from;
  const height = top - bottom;
  const bars = [
    { from, to, bottom, top: Math.min(top, bottom + VOLUME_FRAME_MM) },
    { from, to, bottom: Math.max(bottom, top - VOLUME_FRAME_MM), top },
    { from, to: Math.min(to, from + VOLUME_FRAME_MM), bottom, top },
    { from: Math.max(from, to - VOLUME_FRAME_MM), to, bottom, top },
  ];
  // Импосты встают **внутрь** рамы, а перекладина — отрезками между стойками:
  // наложенных коплоскостных граней в сцене быть не должно (правило таска 180),
  // а сошлись бы они здесь трижды — стойка с низом, с верхом и с поясом.
  const xs = grid && Array.isArray(grid.xs) ? grid.xs : [];
  const ys = grid && Array.isArray(grid.ys) ? grid.ys : [];
  const inner = {
    from: from + VOLUME_FRAME_MM,
    to: to - VOLUME_FRAME_MM,
    bottom: bottom + VOLUME_FRAME_MM,
    top: top - VOLUME_FRAME_MM,
  };
  const posts = xs.map((part) => from + span * part);
  for (const middle of posts) {
    bars.push({ from: middle - half, to: middle + half, bottom: inner.bottom, top: inner.top });
  }
  const gaps = [inner.from, ...posts.flatMap((middle) => [middle - half, middle + half]), inner.to];
  for (const part of ys) {
    const middle = bottom + height * part;
    for (let index = 0; index + 1 < gaps.length; index += 2) {
      bars.push({ from: gaps[index], to: gaps[index + 1], bottom: middle - half, top: middle + half });
    }
  }
  for (const bar of bars) {
    if (!(bar.to > bar.from) || !(bar.top > bar.bottom)) continue;
    const first = at(bar.from, 0);
    const second = at(bar.to, 0);
    out.push(
      volumeFace(
        [volumeAt(first, bar.bottom), volumeAt(second, bar.bottom), volumeAt(second, bar.top), volumeAt(first, bar.top)],
        VOLUME_FRAME_RGB,
        { both: true },
      ),
    );
  }
}

/**
 * **Звенья сложенной гармошки** (таск 226, G338): где встаёт каждое полотнище,
 * когда дверь раскрыта.
 *
 * Долг таска 215 звучал так: «гармошка в объёме складывается в половину своей
 * ширины — приближение, а не пакет звеньев». Приближение врало дважды: полотно
 * съезжало за косяк, как сдвижное (а гармошка никуда не съезжает), и оставалось
 * одной полосой вдвое короче себя (а она собирается звеньями).
 *
 * Теперь честно: **звенья встают поперёк стены пакетом у того косяка, где
 * петли**. Каждое звено — та же секция лица, которой полотно нарисовано на
 * плане и на развёртке (`openingFoldLinks`), то есть у гармошки каталога
 * 900 / 4 = 225 мм; в комнату пакет выступает ровно на эту ширину. Вдоль стены
 * он занимает свою толщину (`VOLUME_FOLD_LEAF_MM`, `VOLUME_FOLD_GAP_MM`) и
 * **из проёма не вылезает**: у двери у́же пакета (меньше 190 мм — такого не
 * бывает, но ширину задаёт человек) шаг жмётся по месту, а не рисует звенья
 * сквозь стену.
 */
function volumeFoldPack(root, into, across, width, links) {
  const link = width / links;
  const step = VOLUME_FOLD_LEAF_MM + VOLUME_FOLD_GAP_MM;
  const pack = links * VOLUME_FOLD_LEAF_MM + (links - 1) * VOLUME_FOLD_GAP_MM;
  const squeeze = pack > width ? width / pack : 1;
  const boards = [];
  for (let index = 0; index < links; index += 1) {
    // Грань звена стоит в середине его толщины: пакет начинается у самого
    // косяка и кончается ровно через свою толщину.
    const away = (VOLUME_FOLD_LEAF_MM / 2 + step * index) * squeeze;
    boards.push({
      at: { x: root.x + into.x * away, y: root.y + into.y * away },
      along: across,
      width: link,
    });
  }
  return boards;
}

/**
 * Полотно двери — одна двусторонняя грань от петли и ручка на ней.
 *
 * **Закрытое** стоит в самом проёме, в середине толщины стены: там же, где
 * бруски рамы у окна, и ровно поэтому не спорит с гранями стены за порядок —
 * совпавшие плоскости в сортировке по дальности решаются случаем, а полотно в
 * середине стены от её сторон отодвинуто на полтолщины.
 *
 * **Раскрытое** уходит от петли на четверть оборота — так дверь рисуют на плане
 * (`render.drawingDoorLeaf`), и так видно, какой кусок пола она занимает.
 *
 * Держать человека полотно не должно ни в том, ни в другом виде (слова
 * заказчика: «Проходим сквозь нарисованные двери») и в список препятствий не
 * попадает — см. `volumeWallSolids`. Закрытая дверь, сквозь которую проходят,
 * выглядит странно, и об этом сказано вслух в отчёте: поведение заказчик не
 * отменял, а менять его без его слова нельзя.
 */
function volumeDoorLeaf(wall, opening, span, out, open) {
  const vectors = wallVectors(wall);
  const whole = span.to - span.from;
  if (!vectors || !(whole > 0)) return out;
  const { u, n } = vectors;
  const motion = openingMotionOf(opening.kind);
  const atStart = opening.hinge !== "end";
  const side = opening.swing === "right" ? -1 : 1;
  const doorId = opening.id || null;
  const point = (along, across = 0) => ({
    x: Number(wall.aMm.x) + u.x * along + n.x * side * across,
    y: Number(wall.aMm.y) + u.y * along + n.y * side * across,
  });
  // Створки: у двупольной две по половине проёма от своих косяков, у остальных
  // одна. Стороны открывания у двух створок общие — ровно как на плане.
  const twin = motion === "swing" && openingLeavesOf(opening.kind) > 1;
  const width = twin ? whole / 2 : whole;
  const leaves = twin
    ? [
        { along: span.from, out: 1 },
        { along: span.to, out: -1 },
      ]
    : [{ along: atStart ? span.from : span.to, out: atStart ? 1 : -1 }];
  for (const plan of leaves) {
    const root = point(plan.along);
    // Куда смотрит полотно.
    //
    //   распашное раскрытое — прочь от стены на четверть оборота;
    //   сдвижное раскрытое — вдоль стены **за** косяк, то есть полотно
    //     съезжает туда, куда показывала стрелка на плане;
    //   гармошка раскрытая — пакетом звеньев поперёк стены у косяка с петлями
    //     (таск 226, `volumeFoldPack`): она никуда не съезжает, она
    //     складывается;
    //   портальное раскрытое — не рисуется вовсе: оно внутри стены, и это
    //     самый честный вид «открыто», какой у него бывает;
    //   закрытое любое — вдоль стены, в самом проёме.
    if (open && motion === "pocket") continue;
    const packed = open && motion === "fold";
    const slid = open && motion === "slide";
    const leaf = open && motion === "swing" ? { x: n.x * side, y: n.y * side } : { x: u.x * plan.out, y: u.y * plan.out };
    const boards = packed
      ? volumeFoldPack(root, leaf, { x: n.x * side, y: n.y * side }, width, openingFoldLinks(opening))
      : [
          {
            at: slid ? { x: root.x - leaf.x * width, y: root.y - leaf.y * width } : root,
            along: leaf,
            width,
          },
        ];
    for (const board of boards) {
      const tip = { x: board.at.x + board.along.x * board.width, y: board.at.y + board.along.y * board.width };
      if (openingGlazed(opening)) {
        volumeGlassLeaf(board.at, board.along, board.width, span, out, doorId);
      } else {
        out.push(
          volumeFace(
            [
              volumeAt(board.at, span.bottom),
              volumeAt(tip, span.bottom),
              volumeAt(tip, span.top),
              volumeAt(board.at, span.top),
            ],
            VOLUME_DOOR_RGB,
            { both: true, doorId },
          ),
        );
      }
    }
    // Ручка у свободного края полотна, на высоте, на которой её берут рукой
    // (G207: «ну и на дверях ручки нарисуй»). Выступает на обе стороны: дверь
    // открывают с той стороны, с которой подошли. У сложенной гармошки свободный
    // край — у **последнего** звена пакета: ручка едет вместе с ним и в воздухе
    // не остаётся.
    const edge = boards[boards.length - 1];
    const handleAt = {
      x: edge.at.x + edge.along.x * (edge.width - VOLUME_HANDLE_EDGE_MM),
      y: edge.at.y + edge.along.y * (edge.width - VOLUME_HANDLE_EDGE_MM),
    };
    const bottom = Math.max(span.bottom, VOLUME_HANDLE_MM - VOLUME_HANDLE_TALL_MM / 2);
    const top = Math.min(span.top, bottom + VOLUME_HANDLE_TALL_MM);
    if (top > bottom) {
      volumePrismFaces(
        volumeBoxCorners(handleAt, edge.along, VOLUME_HANDLE_LONG_MM, VOLUME_HANDLE_OUT_MM * 2),
        bottom,
        top,
        VOLUME_HANDLE_RGB,
        out,
        { doorId },
      );
    }
  }
  return out;
}

/**
 * **Полотно стеклянной двери** (таск 180, G269): рама по контуру и стекло в
 * середине. Слова заказчика — «как на французский балкон — с рамой, но не
 * глухая, а по центру стекло, ну и тоже ручки».
 *
 * Четыре бруска рамы непрозрачны, пятая грань — стекло, и у неё тот же
 * признак `clear`, которым просвечивает вещь чертежа (таск 169) и тюль шторы
 * (таск 189). Доля **названа** — `"glass"` в `VOLUME_CLEAR_ALPHAS`, — а не
 * записана числом здесь: иначе стекло двери и стекло шкафа смешивались бы
 * по-разному в одном кадре, и расхождение заметил бы только глаз.
 *
 * ——— порядок граней ——————————————————————————————————————————————————————
 *
 * Рама и стекло **коплоскостны**: все пять граней лежат в одной плоскости
 * полотна. Дерево порядка (таск 151) порядок внутри плоскости не обещает — и
 * здесь он не нужен ни на что: бруски стоят вокруг стекла, а не поверх него, и
 * коплоскостные грани, которые друг друга не закрывают, смешиваться между
 * собой не могут. Ровно это условие и записано у `volumeOrderTree`.
 *
 * А вот то, что **за** полотном, дерево разводит как надо: плоскость полотна
 * сама становится секущей, и всё, что за ней, рисуется раньше — то есть
 * прозрачному стеклу достаётся уже готовый задник, как того и требует
 * смешивание. Второго прохода «прозрачные после непрозрачных» не понадобилось
 * и здесь.
 *
 * Полотно уже рамы вдвое — рама съедает ширину с двух сторон; на узкой или
 * низкой двери (меньше трёх рам) стекла не остаётся, и полотно рисуется глухим
 * одной гранью рамы: врать про стекло там, где его негде нарисовать, незачем.
 */
function volumeGlassLeaf(hinge, leaf, width, span, out, doorId) {
  const at = (along, z) => volumeAt({ x: hinge.x + leaf.x * along, y: hinge.y + leaf.y * along }, z);
  const quad = (fromAlong, toAlong, bottom, top, rgb, clear) => {
    if (!(toAlong > fromAlong) || !(top > bottom)) return;
    out.push(volumeFace([at(fromAlong, bottom), at(toAlong, bottom), at(toAlong, top), at(fromAlong, top)], rgb, {
      both: true,
      doorId,
      clear,
    }));
  };
  const frame = OPENING_GLASS_FRAME_MM;
  const height = span.top - span.bottom;
  if (!(width > frame * 3) || !(height > frame * 3)) {
    quad(0, width, span.bottom, span.top, VOLUME_FRAME_RGB, false);
    return out;
  }
  const inner = { from: frame, to: width - frame, bottom: span.bottom + frame, top: span.top - frame };
  // Низ, верх и две стойки — рама; стойки встают между низом и верхом, чтобы
  // бруски не легли друг на друга: наложенных коплоскостных граней в сцене
  // быть не должно.
  quad(0, width, span.bottom, inner.bottom, VOLUME_FRAME_RGB, false);
  quad(0, width, inner.top, span.top, VOLUME_FRAME_RGB, false);
  quad(0, inner.from, inner.bottom, inner.top, VOLUME_FRAME_RGB, false);
  quad(inner.to, width, inner.bottom, inner.top, VOLUME_FRAME_RGB, false);
  // Плотность стекла названа, а не задана числом (таск 189): `volumeClearAlpha`
  // переводит имя в долю, и второго числа у двери нет.
  quad(inner.from, inner.to, inner.bottom, inner.top, VOLUME_GLASS_RGB, "glass");
  return out;
}

// ——— пол, потолок, объекты ———————————————————————————————————————————————

/**
 * Высота помещения: переопределение комнаты, высота схемы, а если ни того ни
 * другого — `WALL_HEIGHT_FALLBACK_MM` и честный `known: false`.
 *
 * Умолчание живёт в модели (таск 173) и **одно** на объём и развёртку: своей
 * константы здесь больше нет. Окно говорит о нём строкой `volume.noHeight`, и
 * в строке стоит то же число, что на полосе развёртки, — прежде окно обещало
 * это согласие комментарием, а числа были разные (2700 против «не ниже 2000»).
 */
export function volumeHeightMm(project, schemeId, roomId) {
  const given = wallHeightOf(project, { schemeId, roomId });
  if (given > 0) return { mm: given, known: true };
  return { mm: WALL_HEIGHT_FALLBACK_MM, known: false };
}

/** Внутри ли точка в плановом многоугольнике. Тот же счёт, что `pointInOutline`. */
export function volumePointInside(point, corners) {
  let inside = false;
  for (let i = 0, j = corners.length - 1; i < corners.length; j = i, i += 1) {
    const a = corners[i];
    const b = corners[j];
    const crosses = a.y > point.y !== b.y > point.y;
    if (crosses && point.x < ((b.x - a.x) * (point.y - a.y)) / (b.y - a.y) + a.x) inside = !inside;
  }
  return inside;
}

/** Площадь планового многоугольника в мм². */
export function volumeArea(corners) {
  let sum = 0;
  for (let i = 0, j = corners.length - 1; i < corners.length; j = i, i += 1) {
    sum += corners[j].x * corners[i].y - corners[i].x * corners[j].y;
  }
  return Math.abs(sum) / 2;
}

/**
 * Обход приводится к часовому на экране — тому единственному, при котором
 * «левая» нормаль ребра смотрит **наружу** (соглашение `volumeFaceNormal` и
 * `wallVectors`, второго в сборке нет). Зависеть это от того, в какую сторону
 * человек обводил комнату или ставил вещь, не должно.
 *
 * **Знак здесь был обратный, и это дефект, найденный замером D32** (таск 150):
 * функция возвращала обход против часовой, то есть у каждой призмы — у вещи
 * чертежа, у тела метки — боковые нормали смотрели **внутрь**. Следствие
 * видно глазами: ближняя сторона шкафа отсекалась как отвёрнутая, и вместо неё
 * рисовалась дальняя — сквозь переднюю стенку шкафа был виден его задник. У
 * плит пола и потолка нормаль задана прямо, поэтому их это не касалось, и
 * тестами не ловилось: они считали грани, а не их направление.
 *
 * Ось `y` смотрит вниз, и при этой формуле у часового на экране обхода сумма
 * **положительная**: проверено на квадрате, у которого наружу смотрят все
 * четыре нормали.
 */
function volumeClockwise(corners) {
  let sum = 0;
  for (let i = 0, j = corners.length - 1; i < corners.length; j = i, i += 1) {
    sum += corners[j].x * corners[i].y - corners[i].x * corners[j].y;
  }
  return sum >= 0 ? corners : [...corners].reverse();
}

/**
 * Помещения объёма: контур в миллиметрах и высота.
 *
 * Берутся **контуры** (`outlines`), а не стены: помещения в этой сборке
 * выводятся из контуров (ADR 008), и у стены помещения нет. Перевод в
 * миллиметры — только через мост `planFractionToMm`; нет калибровки или
 * привязки — помещений нет, и это не поломка, а честный ответ: чертежу без
 * моста не от чего считать доли.
 */
export function volumeRooms(project, schemeId) {
  const rooms = [];
  for (const outline of outlinesInOrder(project, schemeId)) {
    const points = [];
    let ok = true;
    for (const point of outline.points || []) {
      const mm = planFractionToMm(project, schemeId, point);
      if (!mm) {
        ok = false;
        break;
      }
      points.push(mm);
    }
    if (!ok || points.length < 3) continue;
    const height = volumeHeightMm(project, schemeId, outline.roomId);
    rooms.push({
      outlineId: outline.id,
      roomId: outline.roomId || null,
      pointsMm: volumeClockwise(points),
      heightMm: height.mm,
      heightKnown: height.known,
      // Пол помещения (таск 209, G317): нет ключа — есть пол, и прежний объект
      // показывается как показывался. Контур без помещения (такое бывает у
      // объекта, где комнату удалили, а обводку оставили) считается с полом:
      // снимать его было некому.
      hasFloor: roomHasFloor(project, outline.roomId),
    });
  }
  return rooms;
}

/** Высота в точке: по накрывающему её контуру, иначе по схеме. */
function volumeHeightAt(project, schemeId, pointMm, fallbackMm) {
  const fraction = planMmToFraction(project, schemeId, pointMm);
  const roomId = fraction ? roomAtPoint(project, schemeId, fraction) : null;
  if (!roomId) return fallbackMm;
  return volumeHeightMm(project, schemeId, roomId).mm;
}

/**
 * **Ус на изломе полосы** (дефект D38, таск 169).
 *
 * Слова заказчика по снимку объёма: «не должно быть такого, ни двойного на
 * углу, ни пустоты в другом углу».
 *
 * Полоса (кухонный фронт, короб, марш) — цепочка призм по звеньям, и звенья,
 * обрубленные **поперёк своей оси**, на изломе не стыкуются: с внутренней
 * стороны угла они залезают друг на друга, с внешней между ними остаётся клин
 * пустоты. Непрозрачные звенья это прятали — лишний слой неотличим от одного,
 * — а прозрачные показали оба изъяна разом.
 *
 * Лечится тем же, чем в черчении: звено кончается не поперёк оси, а **по
 * биссектрисе угла**. Две кромки сходятся ровно, нахлёст пропадает вместе с
 * клином, и граней от этого не прибавляется ни одной — меняются координаты
 * четырёх точек звена.
 *
 * Смещение считается по сумме единичных нормалей: `(n₁ + n₂) / (1 + n₁·n₂)`.
 * На прямой она даёт ровно нормаль, на прямом угле — её же, удлинённую в
 * `√2`, то есть точку встречи двух кромок.
 */
function volumeMiterOffset(prev, next, halfWidth) {
  if (!prev) return { x: next.x * halfWidth, y: next.y * halfWidth };
  if (!next) return { x: prev.x * halfWidth, y: prev.y * halfWidth };
  const dot = prev.x * next.x + prev.y * next.y;
  const denominator = 1 + dot;
  // Полный разворот: ус уходит в бесконечность, а стыковать нечего — полоса
  // легла сама на себя. Кромка остаётся поперечной, как была.
  if (!(denominator > VOLUME_MITER_EPS)) return { x: next.x * halfWidth, y: next.y * halfWidth };
  const x = ((prev.x + next.x) / denominator) * halfWidth;
  const y = ((prev.y + next.y) / denominator) * halfWidth;
  const reach = Math.hypot(x, y);
  const limit = VOLUME_MITER_MAX * Math.abs(halfWidth);
  // Острый излом: ус длиннее предела — срезаем его по пределу («заглушка»).
  // Полоса в этом месте кончается тупым носом, и между звеньями остаётся
  // щель — но лежит она **внутри** острого угла, который сам себя закрывает.
  if (reach > limit && reach > 0) return { x: (x / reach) * limit, y: (y / reach) * limit };
  return { x, y };
}

/**
 * Объект схемы, разложенный на прямые призмы.
 *
 * Прямоугольник — одна призма по четырём углам, ломаная — цепочка призм по
 * звеньям, сходящихся на изломе **усом** (`volumeMiterOffset`, дефект D38).
 *
 * Высота `null` значит «во всю высоту помещения» (колонна, ниша, короб) — она
 * берётся по тому помещению, в котором вещь стоит.
 *
 * Одно место на обе надобности: по этим призмам вещь и рисуется, и держит
 * человека. Посчитай их врозь — и однажды нарисованный шкаф окажется не там,
 * где он не пускает.
 *
 * Ус — единственное, в чём эти две надобности расходятся, и расходятся
 * **названно**: `corners` — то, что рисуется (звено с косыми кромками),
 * `solidCorners` — прежний прямоугольник звена, которым вещь держит человека.
 * Препятствие осталось прямоугольником не из лени: `volumePrismSolid` выводит
 * ось и толщину из трёх первых углов, и косая кромка превратила бы трапецию в
 * препятствие, стоящее не там, где вещь. Цена решения названа: внешний клин
 * излома теперь **нарисован, но не держит** — на прямом угле это треугольник
 * с катетами в половину ширины полосы.
 */
export function volumeObjectPrisms(project, schemeId, object, fallbackHeightMm) {
  const corners = schemeObjectCorners(object);
  if (corners.length === 0) return [];
  const bottom = Math.max(0, Number(object.heightAboveFloorMm || 0));
  const own = typeof object.heightMm === "number" ? Number(object.heightMm) : null;
  const topAt = (middle) => (own === null ? volumeHeightAt(project, schemeId, middle, fallbackHeightMm) : bottom + own);
  if (object.shape !== "polyline") {
    return [{ corners: volumeClockwise(corners), bottomMm: bottom, topMm: topAt(object.atMm || corners[0]) }];
  }
  const halfWidth = Number(object.depthMm) / 2;
  // Звенья собираются списком **до** призм: усу нужен сосед, а вырожденное
  // звено (две точки в одном месте) соседом быть не может — оно выпадает, и
  // ус считается через него.
  const links = [];
  for (let index = 0; index + 1 < corners.length; index += 1) {
    const a = corners[index];
    const b = corners[index + 1];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const length = Math.hypot(dx, dy);
    if (!(length > 0)) continue;
    links.push({ a, b, n: { x: dy / length, y: -dx / length } });
  }
  const prisms = [];
  for (let index = 0; index < links.length; index += 1) {
    const link = links[index];
    const head = volumeMiterOffset(links[index - 1] ? links[index - 1].n : null, link.n, halfWidth);
    const tail = volumeMiterOffset(link.n, links[index + 1] ? links[index + 1].n : null, halfWidth);
    const a = link.a;
    const b = link.b;
    const nx = link.n.x * halfWidth;
    const ny = link.n.y * halfWidth;
    prisms.push({
      corners: volumeClockwise([
        { x: a.x + head.x, y: a.y + head.y },
        { x: b.x + tail.x, y: b.y + tail.y },
        { x: b.x - tail.x, y: b.y - tail.y },
        { x: a.x - head.x, y: a.y - head.y },
      ]),
      // Препятствие — прежний прямоугольник звена (см. выше про расхождение).
      solidCorners: volumeClockwise([
        { x: a.x + nx, y: a.y + ny },
        { x: b.x + nx, y: b.y + ny },
        { x: b.x - nx, y: b.y - ny },
        { x: a.x - nx, y: a.y - ny },
      ]),
      bottomMm: bottom,
      topMm: topAt({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }),
    });
  }
  return prisms;
}

/**
 * Модель вещи чертежа (таск 155). Ключ каталога старше имени вида, и оба пути
 * нужны: ключ — то, чем вещь названа с таска 154, имя — то, чем живут уже
 * размеченные объекты (G68). Оба пути сведены в `schemeObjectKeyOf`, и
 * второго места, где ключ вещи вычисляют, в сборке нет.
 *
 * У ломаной модели нет: ломаной задают кухонный фронт, короб и марш, то есть
 * **полосу**, а не вещь, — повторять по модели на каждом звене значило бы
 * поставить в ряд пять холодильников там, где человек провёл линию.
 */
export function volumeObjectModel(project, object) {
  if (!object || object.shape === "polyline") return null;
  return objectModelByKey(schemeObjectKeyOf(project, object));
}

/**
 * Габарит вещи чертежа для модели.
 *
 * **Перёд берётся из поворота на чертеже**, и больше ниоткуда: человек
 * поворачивает вещь мышью или числом, и это единственное место, где он
 * говорит, куда она смотрит. Угадывать по ближней стене было бы умнее на
 * словах и непредсказуемо на деле: шкаф, поставленный в середине комнаты,
 * разворачивался бы сам, стоило подвинуть его на сантиметр.
 *
 * При нулевом повороте вещь смотрит вниз по листу — туда, куда смотрит вещь,
 * приставленная к верхней стене комнаты. Так ставят шкаф, кровать и машинку:
 * габарит задают «ширина по стене × глубина от стены», и глубина уходит от
 * стены в комнату.
 */
export function volumeObjectFrame(project, schemeId, object, fallbackHeightMm) {
  if (!object || object.shape === "polyline" || !object.atMm) return null;
  const prisms = volumeObjectPrisms(project, schemeId, object, fallbackHeightMm);
  if (prisms.length !== 1) return null;
  const prism = prisms[0];
  const angle = ((Number(object.turnDeg) || 0) * Math.PI) / 180;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  return {
    at: { x: Number(object.atMm.x), y: Number(object.atMm.y) },
    bottomMm: prism.bottomMm,
    u: { x: cos, y: sin },
    f: { x: sin, y: -cos },
    widthMm: Number(object.widthMm),
    depthMm: Number(object.depthMm),
    heightMm: prism.topMm - prism.bottomMm,
  };
}

/**
 * Грани объекта схемы: модель, а без неё — прежняя призма по габариту.
 *
 * **Все они просвечивают** (таск 169, G251): и модель, и запасной габарит, и
 * звено ломаной — вещь чертежа прозрачна целиком, какой бы породы она ни была.
 * Это одно место на весь объём: других хозяев `clear` в сборке нет, и вещь не
 * может оказаться прозрачной в кадре и непрозрачной для взгляда.
 *
 * Прозрачность — **вид, а не свойство вещи**: в объект не пишется ничего
 * (G68), и ни столкновения (`volumeObjectPrisms` → `volumePrismSolid`), ни
 * чертёж, ни выгрузки о ней не знают. Сквозь прозрачный шкаф по-прежнему не
 * пройти.
 */
export function volumeObjectFaces(project, schemeId, object, fallbackHeightMm, out = []) {
  const model = volumeObjectModel(project, object);
  const frame = model ? volumeObjectFrame(project, schemeId, object, fallbackHeightMm) : null;
  if (frame) return volumeModelFaces(frame, model, VOLUME_OBJECT_RGB, out, { clear: true });
  for (const prism of volumeObjectPrisms(project, schemeId, object, fallbackHeightMm)) {
    volumePrismFaces(prism.corners, prism.bottomMm, prism.topMm, VOLUME_OBJECT_RGB, out, { clear: true });
  }
  return out;
}

/**
 * Держит ли вещь человека. Решает, как и у проёма, геометрия: через низкое
 * переступают, под высоким проходят.
 *
 * Колонна, шкаф и столешница не пускают — пройти сквозь шкаф так же неверно,
 * как сквозь стену, и заказчик разрешил проходить ровно сквозь **дверные
 * полотна**, а не сквозь вещи. Короб под потолком, наоборот, над головой, и
 * останавливать им человека было бы странно.
 *
 * Спрашивается это **в полный рост** и один раз, при сборке сцены: присед
 * макушку только опускает, то есть отсеять он может лишь то, что уже отсеяно
 * здесь. Что держит присевшего, решается на шаге — `volumeSolidBlocks`, и
 * высоты вещи для этого едут в препятствие (`volumePrismSolid`).
 */
export function volumePrismBlocks(prism) {
  return prism.bottomMm < VOLUME_HEAD_MM && prism.topMm > VOLUME_STEP_MM;
}

/** Препятствие из призмы: повёрнутый прямоугольник по её габариту. */
export function volumePrismSolid(prism) {
  // Звено полосы держит человека прежним прямоугольником, а не косым усом
  // (D38): ось и толщину препятствия выводят три первых угла, и трапеция
  // поставила бы их криво. У всего остального `solidCorners` нет вовсе.
  const corners = prism.solidCorners || prism.corners;
  if (corners.length < 4) return null;
  const a = corners[0];
  const b = corners[1];
  const c = corners[2];
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const length = Math.hypot(dx, dy);
  if (!(length > 0)) return null;
  const ux = dx / length;
  const uy = dy / length;
  const nx = uy;
  const ny = -ux;
  const depth = Math.abs((c.x - b.x) * nx + (c.y - b.y) * ny);
  return {
    cx: (a.x + c.x) / 2,
    cy: (a.y + c.y) / 2,
    ux,
    uy,
    nx,
    ny,
    half: length / 2,
    halfT: depth / 2,
    // Высоты вещи едут в препятствие вместе с её габаритом (G234): под
    // навесным шкафом присевший проходит, сквозь колонну до потолка — нет.
    bottomMm: Number(prism.bottomMm) || 0,
    topMm: Number(prism.topMm) || 0,
  };
}

// ——— лестница и этажи ————————————————————————————————————————————————————
//
// Таск 149. Слова заказчика: «У схем можно задавать этаж, а при подходе к любой
// лестнице спрашивать нужный этаж. Если 2 этажа, то просто с подтверждением
// переходить».
//
// Лестница — не новая сущность: она **уже** есть в справочнике видов объектов
// чертежа («Лестница» в стартовом наборе, таск 122), её рисуют прямоугольником
// или ломаной марша, и в объёме она стоит призмой во всю высоту помещения.
// Объём только узнаёт её среди прочих вещей.
//
// **Узнаёт по ключу каталога — `stairs`** (таск 154). Прежде узнавала по
// имени вида, и это было единственным, что у вида есть: ни кода, ни ключа, а
// `id` у каждого объекта свой. Имя человек правит руками — переименовал «Марш»,
// и перехода по этажам нет. Со встроенным каталогом у лестницы появился ключ,
// один на все объекты и на все машины, и узнавание перестало зависеть от слов.
//
// Имя осталось **запасным путём** и нигде здесь не упоминается: вещь прежней
// разметки получает ключ выводом из имени в `schemeObjectKeyOf`, тем же
// терпимым сравнением («Лестница», «лестничный марш», «Лестница на 2 этаж»,
// `stairs`). Два места, где лестницу узнают, развелись бы при первой правке —
// поэтому место одно.

/** Расстояние от точки до многоугольника: ноль — точка внутри. */
function volumePolygonGap(point, corners) {
  if (corners.length < 3) return Infinity;
  if (volumePointInside(point, corners)) return 0;
  let gap = Infinity;
  for (let i = 0, j = corners.length - 1; i < corners.length; j = i, i += 1) {
    gap = Math.min(gap, segmentDistanceMm(point, corners[i], corners[j]));
  }
  return gap;
}

/**
 * Лестницы схемы: `{objectId, polygons, atMm}` в миллиметрах чертежа.
 *
 * `polygons` — те же габариты, которыми лестница рисуется и которыми не
 * пускает (`volumeObjectPrisms`): у ломаной марша их столько, сколько звеньев.
 * Второй геометрии у лестницы нет — иначе спрашивать про этаж начали бы не там,
 * где она нарисована.
 */
export function volumeStairs(project, schemeId) {
  const stairs = [];
  for (const object of schemeObjectsOnScheme(project, schemeId)) {
    const key = schemeObjectKeyOf(project, object);
    // **Марш и выход — одна и та же дверь между этажами** (таск 204): к маршу
    // подходят снизу, к выходу — сверху, вопрос «на какой этаж?» у них общий.
    // Список ключей один на сборку и живёт в модели: по нему же ставится точка
    // привязки (`SCHEME_ANCHOR_OBJECT_KEYS`, таск 205), и это не совпадение —
    // привязку берут ровно у лестничной клетки.
    if (!SCHEME_ANCHOR_OBJECT_KEYS.includes(key)) continue;
    const polygons = volumeObjectPrisms(project, schemeId, object, WALL_HEIGHT_FALLBACK_MM).map(
      (prism) => prism.corners,
    );
    if (polygons.length === 0) continue;
    let sx = 0;
    let sy = 0;
    let count = 0;
    for (const polygon of polygons) {
      for (const point of polygon) {
        sx += point.x;
        sy += point.y;
        count += 1;
      }
    }
    // `key` — марш это или выход: по нему прибытие ищет **парную** вещь (D58).
    stairs.push({ objectId: object.id, key, polygons, atMm: { x: sx / count, y: sy / count } });
  }
  return stairs;
}

// ——— куда человек попадает, поднявшись по лестнице (дефект D58) ——————————
//
// Слова заказчика: «почему при переходе между схемами по лестнице я оказываюсь
// в середине объекта, а не возле лестницы? Надо доделать».
//
// **Что было.** Таск 149 ставил человека в **то же место плана**: мол,
// лестничная клетка у этажей одного дома в одном месте, значит те же
// координаты и есть «у лестницы». Довод верен ровно до тех пор, пока у двух
// схем один ноль — а ноль у каждой свой, и берётся он с подложки: планы
// сканируют по отдельности, обрезают по-разному и обводят с разных углов.
// Поэтому «те же координаты» и выносили человека на середину квартиры.
//
// **Что теперь.** Прибытие считается от самой лестницы, а место ухода нужно
// только затем, чтобы выбрать нужную лестничную клетку, когда их несколько:
//
//   1. **Выход с лестницы** (`stairsExit`, вещь таска 204) — если он на этаже
//      нарисован, человек встаёт у него: это и есть то место, где лестница
//      выходит на этаж, и гадать там не о чем;
//   2. **сама лестница** — если выхода нет. Встать **на** неё нельзя: марш
//      занимает место, и человек, поставленный в его середину, смотрел бы в
//      ступени. Поэтому место ищется **рядом с габаритом**: шестнадцать проб
//      вокруг, и берётся та, где человек стоит в помещении и где вокруг него
//      больше всего пусто;
//   3. **ни того, ни другого** — только тогда работает прежнее правило «то же
//      место плана», и окно по-прежнему говорит об этом вслух. Теперь оно
//      честнее: место пересчитано **через привязку** (таск 205), то есть это
//      та же точка дома, а не та же точка чужого чертежа.
//
// **Куда смотреть.** Прочь от лестницы — в ту сторону, в которую с неё сошли.
// Это и есть «лицом в комнату, а не в стену»: место выбрано там, где пусто,
// значит и взгляд в него смотрит в комнату. Своего счёта «где тут стена» для
// взгляда не заводится.

/** Насколько отойти от габарита лестницы: тело плюс запас на ступень. */
export const VOLUME_LANDING_GAP_MM = 250;

/** Сколько проб по кругу: тот же шаг, что у поиска свободного места. */
const VOLUME_LANDING_TRIES = 16;

/** Дальше этого свободное место не ценится: трёх метров хватает любому. */
const VOLUME_LANDING_ROOM_MM = 3000;

/**
 * Куда встать, придя по лестнице на этот этаж (D58). `null` — лестничной
 * клетки на нём не нарисовано, и решает это вызывающий.
 *
 * `atMm` — место ухода, пересчитанное в координаты **этой** схемы: им
 * выбирается лестница, когда их несколько.
 */
export function volumeStairLanding(scene, atMm = null, headMm = VOLUME_HEAD_MM, fromKey = null) {
  const all = (scene && scene.stairs) || [];
  if (all.length === 0) return null;
  // **Приходят в парную вещь** (таск 204): поднялись по маршу — вышли у выхода,
  // спустились от выхода — сошли у марша. Парной нет — годится любая вещь
  // лестничной клетки: другого места, где лестница выходит на этаж, всё равно
  // не нарисовано.
  //
  // Кого считать парой — **одно правило на всю клетку** и лежит оно в модели
  // (`schemeStairArrivalKeys`): маршем ушли — в выход, выходом — в марш,
  // лифтом — в лифт (таск 224). Своей сверки ключей здесь больше нет нарочно:
  // маршей четыре вида, лифт приходит сам в себя, и перечисляй я это на месте,
  // третья порода клетки тихо разъехалась бы с первыми двумя.
  const want = schemeStairArrivalKeys(fromKey);
  const paired = all.filter((place) => want.includes(place.key));
  const places = paired.length > 0 ? paired : all;
  let best = places[0];
  if (places.length > 1 && atMm) {
    let gap = Infinity;
    for (const place of places) {
      const length = Math.hypot(place.atMm.x - atMm.x, place.atMm.y - atMm.y);
      if (length < gap) {
        gap = length;
        best = place;
      }
    }
  }
  const centre = best.atMm;
  let reach = 0;
  for (const polygon of best.polygons || []) {
    for (const point of polygon) reach = Math.max(reach, Math.hypot(point.x - centre.x, point.y - centre.y));
  }
  const step = reach + VOLUME_BODY_MM + VOLUME_LANDING_GAP_MM;
  const solids = scene.solids || [];
  // Просторным считается место, где нет ни стены, ни мебели, — та же мерка, по
  // которой выбирается место старта (`volumeStart`).
  const roomy = [...solids, ...(scene.objectBoxes || [])];
  const rooms = (scene.rooms || []).length > 0;
  let spot = null;
  let score = -Infinity;
  for (let turn = 0; turn < VOLUME_LANDING_TRIES; turn += 1) {
    const angle = (turn * 2 * Math.PI) / VOLUME_LANDING_TRIES;
    const probe = { x: centre.x + Math.cos(angle) * step, y: centre.y + Math.sin(angle) * step };
    const pushed = volumePush(solids, probe, VOLUME_BODY_MM, headMm);
    // Вытолкнуть не удалось — место теснее тела, и это не площадка.
    if (volumeDepthMm(solids, pushed.x, pushed.y, VOLUME_BODY_MM, headMm) > 0) continue;
    const found = volumeRoomAt(scene, pushed);
    // Площадка у лестницы обязана быть **с полом**: сойти с марша в дыру
    // двусветного пространства — не прибытие, а падение (таск 209).
    const inside = !rooms || (found !== null && found.hasFloor !== false);
    const free = Math.min(volumeFreeMm(roomy, pushed.x, pushed.y, headMm), VOLUME_LANDING_ROOM_MM);
    // В помещении — главное, простор — второе. Вне контуров человек стоял бы
    // на улице, а по лестнице выходят в дом.
    const value = (inside ? VOLUME_LANDING_ROOM_MM * 2 : 0) + free;
    if (value > score) {
      score = value;
      spot = pushed;
    }
  }
  // Вокруг лестницы одни стены — встаём там, где свободно хоть где-нибудь.
  if (!spot) spot = volumeFreeSpotNear(solids, centre, headMm) || { x: centre.x, y: centre.y };
  return {
    x: spot.x,
    y: spot.y,
    yaw: Math.atan2(spot.y - centre.y, spot.x - centre.x),
    objectId: best.objectId,
    key: best.key || SCHEME_STAIR_OBJECT_KEYS[0],
    // Встали ли у парной вещи: `false` — её на этаже не нарисовано, и площадка
    // взята у того, что нашлось.
    paired: paired.length > 0,
  };
}

/**
 * Лестница, к которой подошли, или `null`. Ближайшая, если их рядом несколько:
 * спрашивают про ту, у которой стоят.
 */
export function volumeStairNear(stairs, at, reach = VOLUME_STAIR_REACH_MM) {
  let near = null;
  let gap = reach;
  for (const stair of stairs || []) {
    let own = Infinity;
    for (const polygon of stair.polygons) own = Math.min(own, volumePolygonGap(at, polygon));
    if (own > gap) continue;
    gap = own;
    near = stair;
  }
  return near ? { stair: near, distanceMm: gap } : null;
}

/**
 * Куда ведёт лестница: `{floor, options}` — этаж этой схемы и этажи, на которые
 * можно перейти.
 *
 * В список идёт не всякая схема, а та, у которой **задан этаж и есть чертёж**.
 * Этаж — потому что схема без номера не этаж, а просто второй план (развёртка,
 * фрагмент, чужая квартира), и предлагать «перейти» на него значило бы гадать.
 * Чертёж — потому что переход на схему, где показывать нечего, это тупик: окно
 * открылось бы пустым полем и человеку пришлось бы возвращаться.
 *
 * Порядок — по номеру этажа, снизу вверх: так его читают на табличке лифта.
 * Два плана с одним номером (бывает: план этажа и его зеркальная копия)
 * остаются оба и различаются именем схемы — выбрасывать чужую работу по
 * догадке нельзя.
 */
export function volumeFloors(project, schemeId) {
  const options = [];
  for (const scheme of schemesInOrder(project)) {
    if (scheme.id === schemeId) continue;
    const floor = schemeFloorOf(project, scheme.id);
    if (floor === null) continue;
    if (!volumeDrawn(project, scheme.id)) continue;
    options.push({
      schemeId: scheme.id,
      name: scheme.name,
      floor,
      stairs: volumeStairs(project, scheme.id).length > 0,
    });
  }
  options.sort((a, b) => a.floor - b.floor);
  return { floor: schemeFloorOf(project, schemeId), options };
}

/** Есть ли в схеме чертёж: без стен и объектов объёму показывать нечего. */
export function volumeDrawn(project, schemeId) {
  if (!project || !schemeId) return false;
  return wallsOnScheme(project, schemeId).length > 0 || schemeObjectsOnScheme(project, schemeId).length > 0;
}

// ——— стопка этажей (таск 202, G307) ——————————————————————————————————————
//
// Слова заказчика: «давай сделаем новую фичу — отображение сразу всех этажей.
// Но в опциях просмотра пусть будет пункт что показывать. Все этажи (если
// указаны этажи у схем) или какой-то именно этаж».
//
// ——— высота этажа ————————————————————————————————————————————————————————
//
// **Этаж кончается там, где кончается его самая высокая стена**, и это не то
// же, что высота схемы: у комнаты бывает своё число (таск 173), и этаж с
// трёхметровой гостиной при схеме 2700 обязан подняться на три метра — иначе
// перекрытие верхнего этажа срезало бы ей потолок. Отсюда `volumeFloorTopMm`:
// потолок этажа — максимум из высоты схемы и всех её стен. Хозяин мерки один,
// её же спрашивает сам `volumeScene` под вынос земли.
//
// **Высоты складываются по очереди, а не умножаются.** У каждой схемы своя
// высота, и база следующего этажа — база этого плюс его потолок плюс
// перекрытие. Умножить одну высоту на число этажей значило бы поставить
// трёхметровый этаж в 2700 или наоборот.
//
// ——— перекрытие ——————————————————————————————————————————————————————————
//
// `VOLUME_SLAB_MM` = 200 мм — монолитная плита перекрытия жилого дома (сборная
// ПК — 220). Больше в это число ничего не вложено **нарочно**: стяжка с
// покрытием лежит уже внутри высоты этажа, потому что высота стен схемы
// отмерена от того пола, по которому ходят, а не от плиты. Числа этого в
// объекте нет и не будет — у схемы задаётся этаж и высота стен, а не толщина
// пола под ней (G68); понадобится своя — это новое поле схемы и отдельный
// разговор.
//
// ——— дыра в нумерации и два плана на одном номере ————————————————————————
//
// **Дыра не оставляет пустого места.** Есть 1 и 3, нет 2 — третий встаёт на
// первый. Выдумать пропущенному этажу высоту нечем: своей у него нет, а взять
// среднюю или соседнюю — это догадка, которую правило сборки запрещает
// применять молча. Номера в окне стоят как есть (1 и 3), и видно, что между
// ними ничего не нарисовано.
//
// **Два плана на одном номере — в стопке один.** Довод таска 149 («план этажа
// и его зеркальная копия») в силе и ничего не выбрасывает: оба остаются в
// списке лестницы, оба открываются по отдельности, ни одна схема не тронута.
// Но поставить их в стопку обоих нельзя — они встанут друг в друга и дадут
// кашу вместо этажа. Поэтому на номер берётся один план: открытый, если открыт
// один из них, иначе первый по порядку схем; остальные окно называет вслух.

/** Толщина перекрытия между этажами. Разбор — абзацем выше. */
export const VOLUME_SLAB_MM = 200;

/**
 * **Где начало этой схемы в общем плане дома** — единственный шов совмещения
 * этажей (таск 205, требование G309).
 *
 * Слова заказчика: «надо синхронизировать схемы для наложения одной на другую.
 * Можно точку привязки указать например. Кстати лестница как раз таки может
 * стать такой. Указываем в 1 месте лестницу и над ней выход с лестницы».
 *
 * Точку привязки завёл таск 205, и считает смещение **модель**
 * (`schemeAnchorOriginMm`): у схемы с привязкой `a` начало координат лежит в
 * общем плане в `−a`, у схемы без привязки — в нуле, то есть всё стоит как
 * стояло до стопки (G68). Здесь — дверь, через которую об этом спрашивает
 * объём, и больше нигде: `volumeFloorPlan` кладёт каждому этажу `shiftMm`
 * (разницу начал, как разницу баз по высоте), а грани двигает
 * `volumeFloorFaces`.
 *
 * Дверь не убрана за ненадобностью нарочно: совмещение спрашивается из одного
 * места, и когда у привязки появится второй ключ (поворот — разбор в модели),
 * править придётся здесь, а не в трёх местах сборки сцены.
 */
export function volumeSchemeOriginMm(project, schemeId) {
  return schemeAnchorOriginMm(project, schemeId);
}

/** Плановые точки, сдвинутые на смещение схемы. Пустой сдвиг отдаёт их же. */
export function volumeShiftPoints(points, shiftMm) {
  if (!shiftMm || (!shiftMm.x && !shiftMm.y)) return points;
  return (points || []).map((point) => ({ ...point, x: point.x + shiftMm.x, y: point.y + shiftMm.y }));
}

/**
 * Высота каждой стены схемы: переопределение комнаты с той стороны, где оно
 * есть, иначе высота схемы.
 *
 * Хозяин мерки один на сборку: её спрашивает сцена (вынос земли и грани стен)
 * и стопка этажей (потолок этажа). Разойдись они — перекрытие срезало бы
 * стену, которую сцена нарисовала выше.
 */
export function volumeWallHeights(project, schemeId, fallbackMm) {
  const heights = new Map();
  for (const wall of wallsOnScheme(project, schemeId)) {
    const left = wallHeightOnSide(project, wall.id, "left");
    const right = wallHeightOnSide(project, wall.id, "right");
    heights.set(wall.id, Math.max(left > 0 ? left : 0, right > 0 ? right : 0) || fallbackMm);
  }
  return heights;
}

/**
 * Высота этажа в стопке — **высота схемы**, а не самой высокой её комнаты
 * (таск 209 уточняет таск 202).
 *
 * Сперва здесь стоял максимум по стенам: «иначе перекрытие срежет комнату, у
 * которой своя высота». Двусветное пространство (G317) перевернуло довод.
 * Высокая комната — это и есть помещение на два этажа, и поднимать из-за неё
 * **весь** верхний этаж значит разносить дом: задали гостиной 5800 — и спальни
 * над ней уехали бы на три метра вверх от лестницы.
 *
 * Поэтому правило простое и предсказуемое: этаж ровно такой высоты, какая
 * задана схеме, а комната, которой задали больше, проходит сквозь перекрытие —
 * **через ту дыру, которую оставляет снятый пол помещения над ней**. Цена
 * названа прямо: комната выше схемы, под которой пол не снимали, упрётся в
 * перекрытие и будет срезана им — и это видно сразу, с первого взгляда на
 * стопку.
 *
 * Самую высокую стену спрашивает `volumeWallsTopMm` — она нужна земле под
 * тень, и это другая мерка.
 */
export function volumeFloorTopMm(project, schemeId) {
  return volumeHeightMm(project, schemeId, null).mm;
}

/** Самая высокая стена схемы: по ней считается вынос земли под тень (D43). */
export function volumeWallsTopMm(project, schemeId, heights = null) {
  const schemeMm = volumeHeightMm(project, schemeId, null).mm;
  const map = heights || volumeWallHeights(project, schemeId, schemeMm);
  let top = schemeMm || 0;
  for (const height of map.values()) top = Math.max(top, Number(height) || 0);
  return top;
}

/**
 * Что стопка этажей показывает и чего ей не хватает (таск 202).
 *
 * Отдаёт `{floor, floors, doubles, can, why}`:
 *
 *   - `floors` — этажи снизу вверх, по одному плану на номер, с базой
 *     `baseMm` **относительно того этажа, на котором стоит человек**: у него
 *     самого ноль, у нижнего — минус. Отсчёт именно такой, потому что всё
 *     остальное в объёме считается от пола открытой схемы — камера, ходьба,
 *     выделение, миникарта, — и смена системы координат под ними стоила бы
 *     переписывания ходьбы ради картинки;
 *   - `doubles` — планы, которые на свой номер не попали (два плана на одном
 *     этаже): окно называет их вслух;
 *   - `can` — доступны ли «все этажи» вообще, `why` — почему нет.
 *
 * Схема без номера этажа этажом не считается (правило таска 149), схема без
 * чертежа — тоже: в стопке от неё была бы пустота.
 */
export function volumeFloorPlan(project, schemeId) {
  const floor = schemeFloorOf(project, schemeId);
  const found = [];
  for (const scheme of schemesInOrder(project)) {
    const own = schemeFloorOf(project, scheme.id);
    if (own === null) continue;
    if (!volumeDrawn(project, scheme.id)) continue;
    found.push({ schemeId: scheme.id, name: scheme.name, floor: own });
  }
  // Снизу вверх, а внутри номера — порядком схем: сортировка устойчива
  // (ES2019), и первым на номере остаётся план, заведённый раньше.
  found.sort((a, b) => a.floor - b.floor);
  const floors = [];
  const doubles = [];
  for (const item of found) {
    const already = floors.findIndex((taken) => taken.floor === item.floor);
    if (already < 0) {
      floors.push({ ...item });
      continue;
    }
    // Открытая схема на номере главнее: человек смотрит на неё, и подменять её
    // однофамильцем значило бы подменить то, по чему он ходит.
    if (item.schemeId === schemeId) {
      doubles.push(floors[already]);
      floors[already] = { ...item };
      continue;
    }
    doubles.push({ ...item });
  }
  let base = 0;
  for (const item of floors) {
    item.heightMm = volumeFloorTopMm(project, item.schemeId);
    item.baseMm = base;
    item.originMm = volumeSchemeOriginMm(project, item.schemeId);
    item.current = item.schemeId === schemeId;
    base += item.heightMm + VOLUME_SLAB_MM;
  }
  const mine = floors.find((item) => item.current) || null;
  const zero = mine ? mine.baseMm : 0;
  // Этаж стоит относительно того, на котором человек: по высоте — разница баз,
  // в плане — разница начал (шов таска 205, `volumeSchemeOriginMm`). У своего
  // этажа и то и другое ноль, и это не совпадение, а правило отсчёта.
  const here = mine ? mine.originMm : { x: 0, y: 0 };
  for (const item of floors) {
    item.baseMm -= zero;
    item.shiftMm = { x: item.originMm.x - here.x, y: item.originMm.y - here.y };
  }
  // Причина недоступности — та, которую человек может **исправить**: нет
  // номеров вовсе, их меньше двух, или они есть, но не у открытой схемы.
  // Порядок именно такой: сказать «у этой схемы нет этажа» там, где этажей нет
  // ни у кого, значило бы послать править не ту схему.
  const why = floors.length > 1 ? (mine ? null : "noFloor") : found.length > 0 ? "one" : "none";
  return { floor, floors, doubles, can: why === null, why };
}

/**
 * **Ярусов по этажам больше нет** (таск 211 снял их вместе с ярусом полов).
 *
 * В таске 202 каждому этажу стопки отводился свой отрезок ярусов между полами
 * и телами: иначе солнечное пятно первого этажа (ярус 3) рисовалось бы поверх
 * перекрытия второго (ярус 2). Лечило это следствие, а не причину — причиной
 * был сам ярус полов, из-за которого горизонтали не закрывали ни одного тела
 * (D62, D63). Теперь полы, потолки, плита и пятна лежат в ярусе тел, и порядок
 * им всем — на всех этажах разом — считает дерево, сшитое по этажам
 * плоскостями (`volumeOrderStack`). Делить ярусы стало нечего.
 */

/**
 * Этаж стопки: грани встают на свою базу и на своё место в плане, плоское
 * уходит в ярус этажа, а у чужого этажа снимаются хозяева.
 *
 * `shiftMm` — смещение схемы в общем плане (шов таска 205): сегодня ноль, и
 * этажи совмещаются по началу координат.
 *
 * Правятся грани **на месте**: они только что собраны `volumeScene` и больше ни
 * у кого на руках, а копия стопки из трёх этажей — это десятки тысяч лишних
 * точек на каждую сборку сцены.
 *
 * **У этажа, на котором не стоишь, хозяев нет.** Снимаются `markId`, `channel`
 * и `doorId`: выделение, прицел, клавиши выключателя и двери остаются на своём
 * этаже. Иначе щелчок по розетке чужого этажа выделил бы метку чужой схемы —
 * карточка, список меток и подсветка на плане говорили бы о том, чего в кадре
 * нет, — а «все двери» открывало бы двери двух этажей через одну.
 */
export function volumeFloorFaces(faces, { baseMm = 0, shiftMm = null, own = true } = {}) {
  const lift = Number(baseMm) || 0;
  const dx = Number(shiftMm && shiftMm.x) || 0;
  const dy = Number(shiftMm && shiftMm.y) || 0;
  for (const face of faces || []) {
    if (lift !== 0 || dx !== 0 || dy !== 0) {
      for (const point of face.p) {
        point.x += dx;
        point.y += dy;
        point.z += lift;
      }
    }
    if (own) continue;
    face.markId = null;
    if (face.channel !== undefined) face.channel = null;
    if (face.doorId !== undefined) face.doorId = null;
  }
  return faces;
}

/**
 * Тело перекрытия под полом: кромка по контуру и низ (таск 209, дефект D60).
 *
 * **Почему это понадобилось.** Пол был одной плоскостью без толщины, и между
 * этажами стопки зияла щель в `VOLUME_SLAB_MM`: верх стен нижнего этажа на
 * 2800, пол верхнего на 3000, а между ними **не было ни одной грани** — замер
 * на стенде из трёх этажей дал ноль граней, пересекающих эту полосу. Снаружи
 * сквозь неё было видно внутрь дома, и ровно это заказчик назвал словами
 * «говоришь рисуются, а я их не вижу».
 *
 * Теперь у пола есть тело: бок красится бетоном (`VOLUME_SLAB_RGB`) и идёт в
 * дерево порядка наравне со стенами, низ — потолком, и он же закрывает вид
 * снизу там, где у нижнего этажа комнаты не обведены.
 *
 * Эта же кромка — **края дыры** двусветного пространства (G317): пол снят у
 * помещения, перекрытия там нет, а у соседних оно кончается своим торцом.
 * Второго механизма «нарисовать край дыры» не нужно и заводить нельзя.
 */
export function volumeSlabFaces(points, topMm, out = []) {
  if (!points || points.length < 3) return out;
  const bottomMm = topMm - VOLUME_SLAB_MM;
  for (let index = 0; index < points.length; index += 1) {
    const a = points[index];
    const b = points[(index + 1) % points.length];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    if (dx === 0 && dy === 0) continue;
    const length = Math.hypot(dx, dy);
    out.push(
      volumeFace(
        [volumeAt(a, bottomMm), volumeAt(b, bottomMm), volumeAt(b, topMm), volumeAt(a, topMm)],
        VOLUME_SLAB_RGB,
        // Ярус у кромки **телесный**: она стоит вертикально, как стена, и
        // спорит с соседями порядком, а не правилом.
        { normal: { x: dy / length, y: -dx / length, z: 0 } },
      ),
    );
  }
  out.push(
    volumeFace(points.map((point) => volumeAt(point, bottomMm)), VOLUME_CEILING_RGB, {
      normal: { x: 0, y: 0, z: -1 },
    }),
  );
  return out;
}

// ——— чья стена в полосе двусвета (таск 214, дефект D65) ————————————————
//
// Слова заказчика: «если на двусветном помещении на 2 этаже отрисовать проёмы
// в стенах (проход, дверь, окна), то их перекрывает стена первого этажа и
// становятся глухими».
//
// **Откуда берутся две стены.** Двусвет собирается двумя ручками (таск 209):
// комнате снизу задают высоту в два этажа, у помещения сверху снимают пол.
// Высота комнаты поднимает её стены (`wallHeightOnSide`), и в полосе второго
// этажа оказываются **две стены разом**: высокая нижняя, глухая наверху, и
// своя стена второго этажа — та, в которой человек чертит проёмы. Толщина,
// место и плоскость у них те же, и порядок между совпавшими плоскостями
// решать нечем: чья грань нарисуется последней, ту и видно. На объекте
// заказчика так закрыты **7 проёмов из 17** на втором этаже — шесть окон
// (4000…5400 мм) и проход (3200…5300).
//
// **Главная — стена того этажа, в чьей полосе она стоит.** Это не «спрятать
// лишнее», а прочтение данных: один и тот же кусок дома человек чертит на
// каждом плане своего этажа, и проёмы верхней полосы он рисует на верхнем
// плане. Нижняя стена поднимается выше своего этажа только там, где **у
// верхнего этажа своей стены нет** — тогда уступать некому, и простенок
// двусветной стены честно стоит на всю высоту. Оба случая встречаются в одной
// комнате: на объекте заказчика пять высоких стен накрыты верхними целиком, а
// шестая — на 5 % длины, и остальные её 95 % остаются высокими.
//
// Уступает стена **кусками, а не целиком**: накрытый кусок становится проёмом
// от перекрытия до её верха. Поэтому в сцене не заводится ни одного нового
// вида грани — работают те же откосы, те же куски стены между проёмами и те же
// препятствия, которыми живут настоящие проёмы.

/** Насколько стены считаются «той же самой»: угол между их осями. */
export const VOLUME_WALL_SAME_DEG = 20;

/**
 * Куски стены, которые на этаже выше накрыты его собственной стеной.
 *
 * `uppers` — стены верхнего этажа, **уже переведённые в координаты этой
 * схемы** (разницу привязок знает стопка). Считается «та же стена»: оси
 * сонаправлены с точностью до `VOLUME_WALL_SAME_DEG` и отстоят не дальше, чем
 * сумма полутолщин. Стена, которая просто упирается в эту (перегородка под
 * прямым углом), накрытием не считается — иначе она пробивала бы в двусветной
 * стене дыру шириной в себя.
 */
export function volumeWallCovers(wall, uppers) {
  const vectors = wallVectors(wall);
  if (!vectors) return [];
  const half = Number(wall.thicknessMm) / 2;
  const limit = Math.cos(VOLUME_WALL_SAME_DEG * DEG);
  const spans = [];
  for (const up of uppers || []) {
    const other = wallVectors(up);
    if (!other) continue;
    if (Math.abs(vectors.u.x * other.u.x + vectors.u.y * other.u.y) < limit) continue;
    const reach = half + Number(up.thicknessMm) / 2;
    const ends = [up.aMm, up.bMm].map((point) => {
      const dx = Number(point.x) - Number(wall.aMm.x);
      const dy = Number(point.y) - Number(wall.aMm.y);
      return {
        along: dx * vectors.u.x + dy * vectors.u.y,
        across: dx * vectors.n.x + dy * vectors.n.y,
      };
    });
    if (Math.abs(ends[0].across) > reach && Math.abs(ends[1].across) > reach) continue;
    const from = Math.max(0, Math.min(ends[0].along, ends[1].along));
    const to = Math.min(vectors.len, Math.max(ends[0].along, ends[1].along));
    if (!(to - from > 1)) continue;
    spans.push({ fromMm: from, toMm: to });
  }
  spans.sort((a, b) => a.fromMm - b.fromMm);
  const merged = [];
  for (const span of spans) {
    const last = merged[merged.length - 1];
    if (last && span.fromMm <= last.toMm + 1) {
      last.toMm = Math.max(last.toMm, span.toMm);
      continue;
    }
    merged.push({ ...span });
  }
  return merged;
}

/** Куски стены, которые **не** накрыты: дополнение к `volumeWallCovers`. */
export function volumeWallFree(lengthMm, covers) {
  const free = [];
  let cursor = 0;
  for (const span of covers || []) {
    if (span.fromMm > cursor) free.push({ fromMm: cursor, toMm: Math.min(lengthMm, span.fromMm) });
    cursor = Math.max(cursor, span.toMm);
  }
  if (cursor < lengthMm) free.push({ fromMm: cursor, toMm: lengthMm });
  return free.filter((span) => span.toMm - span.fromMm > 1);
}

// ——— потолок под дырой двусвета (таск 229, требование G343) ——————————————
//
// Вопрос заказчика: «можно ли поправить?» — о потолке нижней комнаты, который
// остаётся на месте под двусветом, **если высоту комнате не задали**.
//
// **Откуда он там.** Двусвет собирают двумя ручками (таск 209): у помещения
// сверху снимают пол, комнате снизу задают высоту в два этажа. Сними один
// пол — дыра в перекрытии появится, а потолок комнаты под ней останется стоять
// на своей высоте и затянет её снизу: сверху сквозь дыру видно серую плоскость
// потолка, а не комнату, и двусвета не получается.
//
// **Что снимается.** Потолок, который стоит **в плоскости перекрытия** — тот
// самый, что и есть низ плиты этажа выше. Это и есть случай «высоту комнате не
// задали»: её потолок равен высоте этажа. Задали больше (двусвет как он есть,
// 6000 мм на объекте заказчика) — потолок стоит выше дыры, и снимать нечего;
// задали меньше (подшивной потолок) — он не низ перекрытия, а своя плоскость
// комнаты, и дыра до неё не доходит. Поэтому мерка одна: `capMm` без
// перекрытия против высоты комнаты, с той же точностью «одна плоскость»
// (`VOLUME_PLANE_EPS_MM`), которой сшиваются этажи.
//
// **Резать потолок по контуру дыры не стали, и цена названа числами.** Случай
// «дыра накрывает комнату целиком», на который рассчитывал тикет, на объекте
// заказчика не встретился ни разу: накрытие там **68,8 % и 89,8 %** площади.
// Поэтому потолок снимается целиком при любом накрытии, а ненакрытую часть
// держит **низ плиты этажа выше** — он лежит ровно в той же плоскости и того же
// цвета (`VOLUME_CEILING_RGB`), потому что это и есть потолок этой комнаты.
// Замер по объекту заказчика (сетка 25 мм, с полосами под стенами верхнего
// этажа): у комнаты 74,2 м² ненакрытое — 30,9 % низом плиты и **0,2 %** ничем,
// у комнаты 16,8 м² — 9,3 % и **1,0 %**. Эти доли процента — полоски у стен,
// где второй этаж не обведён; цена их закрытия — счёт вычитания многоугольников
// (в сборке есть только отсечка выпуклым, `volumeClipPolygon`), то есть новый
// кусок геометрии ради 0,2 % площади двух комнат. Не стали.

/**
 * Накладываются ли два плановых многоугольника. Спрашивается вершинами и
 * серединами: вершина одного внутри другого (или середина внутри) — значит
 * накладываются.
 *
 * Точного пересечения здесь не нужно, и заводить его нельзя: вопрос, на
 * который отвечает мерка, — «стоит ли эта комната под дырой», а не «на сколько
 * квадратных метров». Чего она не ловит: накрест положенных многоугольников,
 * у которых ни одна вершина не внутри (крест из двух прямоугольников). Контур
 * комнаты и контур помещения этажом выше так не лежат — они обведены по тем же
 * стенам, — а середины добирают случай «дыра целиком внутри комнаты», где
 * вершин внутри нет ни у той, ни у другой.
 */
export function volumePolysOverlap(a, b) {
  if (!a || a.length < 3 || !b || b.length < 3) return false;
  if (a.some((point) => volumePointInside(point, b))) return true;
  if (b.some((point) => volumePointInside(point, a))) return true;
  const middle = (points) => {
    let x = 0;
    let y = 0;
    for (const point of points) {
      x += point.x;
      y += point.y;
    }
    return { x: x / points.length, y: y / points.length };
  };
  return volumePointInside(middle(a), b) || volumePointInside(middle(b), a);
}

/**
 * Снят ли у помещения потолок дырой двусвета (таск 229, G343). Разбор —
 * абзацем выше.
 *
 * `voids` — контуры помещений **без пола** с этажа выше, уже переведённые в
 * координаты этой схемы (разницу привязок знает стопка, шов таска 205);
 * `capMm` — потолок полосы этажа, тот же довод, которым уступают стены в
 * двусвете (таск 214). Без стопки ни того, ни другого нет вовсе — и тогда всё
 * как было: одна схема про соседние этажи не знает ничего (G68).
 */
export function volumeCeilingUnderVoid(room, voids, capMm) {
  if (!voids || voids.length === 0) return false;
  const slabMm = (Number(capMm) || 0) - VOLUME_SLAB_MM;
  if (!(slabMm > 0)) return false;
  // Потолок в плоскости перекрытия — и только он: выше дыры или ниже её стоит
  // своя плоскость комнаты, и снимать её нечем.
  if (Math.abs((Number(room.heightMm) || 0) - slabMm) > VOLUME_PLANE_EPS_MM) return false;
  return voids.some((hole) => volumePolysOverlap(room.pointsMm, hole));
}

/** Снизу и сверху: насколько грани уходят по вертикали. `null` — граней нет. */
export function volumeFacesSpan(faces) {
  let minZ = Infinity;
  let maxZ = -Infinity;
  for (const face of faces || []) {
    for (const point of face.p) {
      if (point.z < minZ) minZ = point.z;
      if (point.z > maxZ) maxZ = point.z;
    }
  }
  return minZ > maxZ ? null : { minZ, maxZ };
}

/**
 * Дерево порядка стопки: по дереву на этаж, сшитые горизонтальной плоскостью.
 *
 * **Почему не одно дерево на всё.** Дерево строится при сборке сцены и стоит
 * девять миллисекунд на 2458 гранях одной схемы; растёт оно хуже, чем линейно —
 * резы множатся. А этажи **не проникают друг в друга**: каждый лежит в своём
 * слое между перекрытиями, и горизонтальная плоскость между ними — это точный
 * узел дерева, а не приближение. Поэтому стопка платит ровно столько, сколько
 * платят этажи по отдельности, и ни одного лишнего реза.
 *
 * `groups` — этажи снизу вверх, у каждого свои грани. Если чьи-то тела всё же
 * перекрылись по вертикали (метка, посаженная выше стен своего этажа), сшивать
 * нечем — такие этажи сливаются в одно дерево. Это дороже, зато верно: порядок
 * в объёме обязан быть точным в каждом пикселе.
 */
export function volumeOrderStack(groups) {
  const parts = [];
  for (const faces of groups || []) {
    const inTree = (faces || []).filter((face) => !face.line && face.layer === VOLUME_LAYER_BODY);
    const span = volumeFacesSpan(inTree);
    if (!span) continue;
    const last = parts[parts.length - 1];
    // Перекрылись по вертикали — плоскости между ними нет, и этажи считаются
    // одним куском. **Касание не перекрытие**: с таска 209 плита верхнего
    // этажа начинается ровно там, где кончаются стены нижнего, и шов проходит
    // по этой самой плоскости — ни одна грань её не пересекает.
    if (last && span.minZ < last.span.maxZ - VOLUME_PLANE_EPS_MM) {
      last.faces = [...last.faces, ...inTree];
      last.span = { minZ: Math.min(last.span.minZ, span.minZ), maxZ: Math.max(last.span.maxZ, span.maxZ) };
      continue;
    }
    parts.push({ faces: inTree, span });
  }
  if (parts.length === 0) return null;
  let tree = volumeOrderTree(parts[0].faces);
  for (let at = 1; at < parts.length; at += 1) {
    const upper = volumeOrderTree(parts[at].faces);
    if (!upper) continue;
    if (!tree) {
      tree = upper;
      continue;
    }
    // Шов — ровно между этажами: верх нижнего и низ верхнего.
    const zMm = (parts[at - 1].span.maxZ + parts[at].span.minZ) / 2;
    tree = {
      plane: { x: 0, y: 0, z: 1, d: zMm },
      same: [],
      front: upper,
      back: tree,
      count: tree.count + upper.count,
    };
  }
  return tree;
}

/**
 * Сцена из нескольких этажей (таск 202).
 *
 * **Чем она остаётся** — сценой того этажа, на котором стоит человек: все её
 * поля, кроме граней, дерева, тени и пятен, принадлежат открытой схеме. Ходьба,
 * препятствия, метки, выделение, лестница, миникарта и сводка спрашивают её,
 * а соседние этажи добавляют к кадру только то, что видно. Это и есть ответ на
 * «что значит ходьба при всех этажах»: ходим по своему этажу и переходим
 * лестницей, как с таска 149, — ни провалов между этажами, ни второго правила
 * столкновений.
 *
 * `optionsOf(schemeId)` — доводы сборки для каждой схемы (видимые метки,
 * открытые двери, спрятанные вещи): фильтр и отметки обязаны значить на всех
 * этажах одно и то же.
 */
export function volumeStackScene(project, plan, optionsOf) {
  const floors = (plan && plan.floors) || [];
  const mineAt = floors.findIndex((item) => item.current);
  if (mineAt < 0 || floors.length < 2) return null;
  const mine = floors[mineAt];
  const take = (schemeId) => (typeof optionsOf === "function" ? optionsOf(schemeId) || {} : {});
  // **У этажа выше нижнего плиты нет вовсе**: земля у дома одна и лежит под
  // нижним этажом, а перекрытие собирается из полов помещений (таск 209).
  // Зелёный прямоугольник с выносом под тень, повторённый на каждом этаже,
  // закрыл бы дом сверху травой, а сплошная плита по габариту — затянула бы
  // дыру двусветного пространства. Правило одно и для той схемы, которая
  // открыта: второй этаж не становится землёй от того, что человек на нём
  // стоит.
  const upperOf = (at) => at > 0;

  /**
   * Чем этаж накрыт сверху (таск 214): потолок его полосы и куски стен, у
   * которых этаж выше поставил свою стену на то же место. Стены соседа
   * переводятся в координаты этого этажа — разницу привязок знает план стопки.
   */
  const coverOf = (at) => {
    const here = floors[at];
    const above = floors[at + 1];
    if (!above) return {};
    const dx = above.shiftMm.x - here.shiftMm.x;
    const dy = above.shiftMm.y - here.shiftMm.y;
    const uppers = wallsOnScheme(project, above.schemeId).map((wall) => ({
      aMm: { x: Number(wall.aMm.x) + dx, y: Number(wall.aMm.y) + dy },
      bMm: { x: Number(wall.bMm.x) + dx, y: Number(wall.bMm.y) + dy },
      thicknessMm: wall.thicknessMm,
    }));
    const covers = new Map();
    for (const wall of wallsOnScheme(project, here.schemeId)) {
      const spans = volumeWallCovers(wall, uppers);
      if (spans.length > 0) covers.set(wall.id, spans);
    }
    // Дыры двусвета (таск 229, G343): контуры помещений **без пола** этажом
    // выше, переведённые в координаты этого этажа. Перекрытия там нет, и
    // комнате под дырой низ плиты потолком уже не работает — своего потолка она
    // не рисует.
    const voids = volumeRooms(project, above.schemeId)
      .filter((room) => room.hasFloor === false)
      .map((room) => volumeShiftPoints(room.pointsMm, { x: dx, y: dy }));
    // Потолок полосы этажа в его собственных миллиметрах: база соседа минус
    // своя, то есть высота этажа вместе с перекрытием.
    return { capMm: above.baseMm - here.baseMm, covers, voids };
  };
  const base = volumeScene(project, mine.schemeId, {
    ...take(mine.schemeId),
    ...coverOf(mineAt),
    order: false,
    upper: upperOf(mineAt),
  });
  if (!base || base.empty) return base;
  const groups = [];
  const faces = [];
  const shadowBoxes = [];
  const sunSpots = [];
  const groundMm = floors[0].baseMm;
  let landMm = null;
  let stackBox = null;
  let bottomMm = 0;
  let topMm = 0;
  for (let at = 0; at < floors.length; at += 1) {
    const item = floors[at];
    const own = at === mineAt;
    const sub = own
      ? base
      : volumeScene(project, item.schemeId, {
          ...take(item.schemeId),
          ...coverOf(at),
          order: false,
          upper: upperOf(at),
        });
    if (!sub || sub.empty) continue;
    if (at === 0) landMm = sub.landMm;
    volumeFloorFaces(sub.faces, { baseMm: item.baseMm, shiftMm: item.shiftMm, own });
    groups.push(sub.faces);
    faces.push(...sub.faces);
    if (sub.boundsMm) {
      const box = {
        minX: sub.boundsMm.minX + item.shiftMm.x,
        minY: sub.boundsMm.minY + item.shiftMm.y,
        maxX: sub.boundsMm.maxX + item.shiftMm.x,
        maxY: sub.boundsMm.maxY + item.shiftMm.y,
      };
      stackBox = stackBox
        ? {
            minX: Math.min(stackBox.minX, box.minX),
            minY: Math.min(stackBox.minY, box.minY),
            maxX: Math.max(stackBox.maxX, box.maxX),
            maxY: Math.max(stackBox.maxY, box.maxY),
          }
        : box;
    }
    // Тень на земле кладут **все этажи разом**: дом отбрасывает одно пятно, а
    // стена второго этажа даёт тень длиннее — она выше над землёй. Поэтому у
    // габарита появляется `baseMm` (где лежит земля) и высота от неё.
    for (const box of sub.shadowBoxes || []) {
      shadowBoxes.push({
        ...box,
        corners: volumeShiftPoints(box.corners, item.shiftMm),
        baseMm: groundMm,
        heightMm: item.baseMm - groundMm + box.heightMm,
      });
    }
    // Солнечное пятно лежит на полу **своего** этажа и в его ярусе: иначе
    // пятно первого этажа легло бы на перекрытие второго.
    for (const spot of sub.sunSpots || []) {
      sunSpots.push({
        ...spot,
        aMm: { x: spot.aMm.x + item.shiftMm.x, y: spot.aMm.y + item.shiftMm.y },
        left: volumeShiftRoomLight(spot.left, item.shiftMm),
        right: volumeShiftRoomLight(spot.right, item.shiftMm),
        baseMm: item.baseMm,
      });
    }
    bottomMm = Math.min(bottomMm, item.baseMm);
    topMm = Math.max(topMm, item.baseMm + item.heightMm);
  }
  return {
    ...base,
    faces,
    order: volumeOrderStack(groups),
    shadowBoxes,
    sunSpots,
    // Земля — у нижнего этажа: у него плита работает землёй, у остальных она
    // стала перекрытием. Нет её и там (помещения не обведены) — нет её и у
    // стопки: это правило сцены, а не стопки.
    landMm,
    // Габарит стопки: по вертикали — от пола нижнего этажа до потолка верхнего,
    // в плане — объединение габаритов этажей (сойтись в плане они могут не
    // точно, когда появится привязка, — шов таска 205). Им «Вся схема» вмещает
    // дом целиком, а обзор держит камеру над его крышей, а не над потолком
    // своего этажа.
    stackMm: {
      bottomMm,
      topMm,
      count: floors.length,
      boundsMm: stackBox
        ? { ...stackBox, widthMm: stackBox.maxX - stackBox.minX, heightMm: stackBox.maxY - stackBox.minY }
        : null,
    },
  };
}

// ——— метки ———————————————————————————————————————————————————————————————
//
// Таск 148, второй шаг G205. Где стоит вещь — правила заказчика, записанные
// словами и сведённые в одно решение:
//
//   **Высота решает вертикаль, стена — сторону и место.**
//
//   1. Высота задана и метка привязана к стене → вещь стоит **на своей стене**:
//      отступ вдоль из привязки, высота над полом — середина вещи, сторона — та,
//      на которой метка лежит по плану. Выступ от стены (G197) гонит её наружу.
//   2. Высота задана, стены нет → вещь висит **в своём месте по плану** на
//      заданной высоте.
//   2a. Высота задана **нулём** → вещь не висит, а **стоит на полу**: на нуле
//      её низ, а не середина (дефект D34, `volumeMarkOnFloor`). Правило
//      действует в обеих ветках: осушитель у стены стоит на полу так же, как
//      робот-пылесос посреди комнаты.
//   3. Высоты нет → вещь **потолочная**: встаёт под потолок того помещения, в
//      котором стоит, в своём месте по плану. Это не догадка сборки, а то, как
//      заполнен справочник: высота пуста ровно у потолочного света — точечный
//      светильник, светильник, подсветка, лента, трек, люстра, подсветка
//      кровати и шкафа, — и заполнена у всего, что висит на стене.
//   4. Высоты нет и потолка над меткой нет (помещение не обведено или метка
//      лежит вне контуров) → вешать не на что, и вещь **не размещается**:
//      уходит списком «не размещённые». Слова заказчика прямые: выдумывать им
//      место нельзя, но и молча терять нельзя.
//   5. Размера нет → недостающая сторона берётся **у изображения объекта**, а
//      без изображения — у общей рамки (G215 и G226, `markBox.js`), и вещь
//      попадает в сцену, а не в список. Такое бывает у типа, заведённого
//      руками: в стартовом справочнике размеры есть у всех (G192), а
//      «Мастер-выключатель» из объекта заказчика — его собственный тип, и
//      размеров у него нет ни одного. Габарит при этом догадка, и окно говорит
//      об этом списком `spare`: потерять вещь нельзя, но и выдать догадку за
//      чертёж тоже.
//
//      Правило здесь **не своё**: его же спрашивает развёртка, и оттуда оно и
//      взято — каждая сторона подтягивается отдельно. Вещь, у которой названы
//      обе стороны, рисуется ровно как прежде.
//
// **Плашка комментария в объёме не участвует вовсе** — ни вещью, ни строкой
// списка: это надпись на чертеже, а не изделие (то же правило, что у развёртки,
// `markWallBindable`).
//
// Три измерения вещи читаются по той поверхности, на которой она висит, и это
// одно правило на все случаи: **длина — вдоль поверхности, ширина — вторая
// сторона лица, выступ — прочь от поверхности**. На стене лицо стоит
// вертикально (длина вдоль стены, ширина вверх, выступ наружу), на потолке —
// горизонтально (длина и ширина по полу, выступ вниз). Поэтому точечная лента
// ЛВ (40 × 600) на стене сама собой встаёт **вертикальной лентой**, а люстра
// (500 × 400, выступ 300) свисает с потолка своим габаритом: ни одной отдельной
// ветки на эти два случая нет.
//
// **Метки не держат человека.** Сквозь шкаф ходить нельзя — это вещь чертежа, —
// а сквозь розетку можно: препятствием её никто не называл.

/**
 * На сколько лицо вещи выступает перед гранью стены, прежде чем начнётся её
 * выступ. Два миллиметра — не зазор «на всякий случай», а лекарство от
 * совпавших плоскостей: встроенный щит (выступ −30) и плоская панель лежат
 * ровно в грани стены, и без этого сдвига порядок граней между ними решался бы
 * случайно.
 */
export const VOLUME_MARK_LIFT_MM = 2;
/**
 * Самая мелкая сторона вещи. Лента 10 × 10 мм в объёме вырождается в волос, в
 * который не попасть кликом, — и дело не в красоте, а в том, что вещь обязана
 * остаться выделяемой. Двадцать миллиметров на расстоянии вытянутой руки — те
 * же пара точек экрана, что и десять, но грань у них настоящая.
 */
export const VOLUME_MARK_MIN_MM = 20;

/**
 * Напуск пола под стеной (дефект D37): на сколько полоса пола выходит за грань
 * стены по обе стороны. Пять сантиметров прячутся под самой стеной и в углах, а
 * больше — и пол полез бы кантом наружу, из-под стены на землю.
 */
export const VOLUME_FLOOR_LAP = 50;

/**
 * Вещь **стоит на полу**, а не висит на своей высоте (дефект D34).
 *
 * Высота над полом — это **середина** вещи: розетка на 300 занимает от 260 до
 * 340, и иначе её не поставить — ни верх, ни низ у висящей вещи не главнее
 * другого. Но ровно на этом правиле вещь с высотой **нуль** — осушитель, робот‑
 * пылесос, датчик протечки — вставала серединой на нуле, то есть нижней
 * половиной под полом.
 *
 * Признак — **сама нулевая высота, и больше ничего**. Проверять «есть ли под
 * ней пол» незачем: пол в объёме есть всегда (обведённое помещение или плита
 * под всем чертежом, `volumeScene`), так что проверка была бы истинной везде и
 * не различала бы ничего. Поля «где стоит» у метки нет (у вещей чертежа оно
 * появилось в таске 154), и заводить его ради этого не нужно: вещи, у которой
 * середина **на уровне пола**, не бывает. Записанный ноль у висящей вещи
 * означал бы, что её половина замурована в стяжку, — такого не размечают, и
 * читать ноль как «низ на полу» значит понять человека, а не догадаться за
 * него.
 *
 * Поэтому правило узкое: **двигается только нулевая высота**. Вещь на 50 мм
 * останется серединой на пятидесяти, даже если её низ при этом уйдёт ниже нуля:
 * пятьдесят человек написал сам, и перетолковывать его число нельзя (G68 —
 * готовый объект не должен меняться сверх того, что прямо исправляют).
 */
export function volumeMarkOnFloor(heightMm) {
  return heightMm === 0;
}

/**
 * **Запасной габарит** спрашивается у общего правила — `markBoxMm`
 * (`markBox.js`, G226), и своего у объёма больше нет.
 *
 * Дыра, с которой запас начинался (G215), была такая: `fillTypeSizes` (G192)
 * подтягивает умолчания по коду и по форме знака, но у типа, заведённого рукой
 * с незнакомой формой, донора нет вовсе — и вещь уходила списком «не
 * размещены». То есть выпадала из объёма не из-за данных, а из-за правила.
 *
 * Запас тогда включался только там, где нет **ни одной** стороны, — а
 * развёртка уже подтягивала стороны **врозь**, и вещь с длиной 600 и пустой
 * шириной выходила 600 × 90 на листе и 600 × 20 здесь. Теперь правило одно и
 * развёрточное: каждая сторона берётся у изображения объекта, а без
 * изображения — у общей рамки. Частный случай «не задано ни одной» никуда не
 * делся, просто перестал быть вторым правилом рядом.
 *
 * **Выступ остаётся за объёмом**: у плоского изображения его взять негде —
 * записи реестра двумерные, — а на листе развёртки его нет вовсе. Рамка
 * отвечает за него теми же 10 мм (`MARK_BOX_FRAME_DEPTH_MM`), и только у вещи,
 * о размерах которой не сказано ничего: записанный ноль — это ноль
 * («встроенный»), а не пустота, и двух миллиметров (`VOLUME_MARK_LIFT_MM`)
 * вещи с запасными размерами под потолком мало — она стала бы плёнкой.
 *
 * **В справочник не пишется ничего** (G68): запас живёт в сцене, на время
 * рисования. Иначе человек увидел бы у своего типа чужие числа и решил, что
 * сам их задал, — а они догадка сборки, и сказать о ней надо словом
 * (`spare` в `volumeMarks`), а не записью в объект.
 */

/** Как вещь поставлена: на стене, в воздухе на своей высоте, под потолком. */
export const VOLUME_MARK_WALL = "wall";
export const VOLUME_MARK_ROOM = "room";
export const VOLUME_MARK_CEILING = "ceiling";

/** Почему вещь не размещена. Строки к этим кодам — в окне, не здесь. */
export const VOLUME_MARK_NO_POINT = "noPoint";
export const VOLUME_MARK_NO_SIZE = "noSize";
export const VOLUME_MARK_NO_PLACE = "noPlace";

/** Толщина контура изображения — в экранных точках (см. `volumeLine`). */
const VOLUME_VIEW_LINE_PX = 1.4;
/** На сколько контур отодвинут от лица вещи, чтобы не спорить с ним за порядок. */
const VOLUME_VIEW_LIFT_MM = 1;
/** Во сколько отрезков разбирается полная окружность изображения. */
const VOLUME_VIEW_STEPS = 16;

// Светлота тела вещи: цвет категории, разбавленный белым, и контур поверх него
// — тем же цветом в полную силу. Так вещь читается и издали (пятно цвета
// категории видно, когда контур уже слился), и вблизи (контур насыщеннее
// своего тела, как тушь по бумаге на развёртке).
//
// Доля подобрана живым прогоном, и оба края пробовались на нём же: при 0,7 тело
// почти догоняет контур по насыщенности, и решётка бризера на нём пропадает; при
// 0,3 бледное пятно теряется на светлой стене. Замечание таска 139 («цвет на
// всей поверхности читается хуже контура») верно и здесь — поэтому цвет и
// разбавлен, а не взят в полную силу.
const VOLUME_MARK_TINT = 0.45;
const VOLUME_MARK_BASE = [226, 224, 220];

function volumeTint(rgb) {
  return [0, 1, 2].map((index) =>
    Math.round(rgb[index] * VOLUME_MARK_TINT + VOLUME_MARK_BASE[index] * (1 - VOLUME_MARK_TINT)),
  );
}

/** Цвет метки тройкой каналов; незнакомый — серый, как и в `styleOf`. */
function volumeRgbOf(color) {
  const rgb = hexToRgb(color);
  return rgb ? [rgb.r, rgb.g, rgb.b] : [120, 120, 120];
}

// Точки метки в миллиметрах чертежа. Пусто — моста к подложке нет (ADR 008) или
// точек у метки не осталось: место неизвестно, и выдумывать его нельзя.
function volumeMarkPathMm(project, mark) {
  const out = [];
  for (const point of mark.points || []) {
    const at = planFractionToMm(project, mark.schemeId, point);
    if (!at) return [];
    out.push(at);
  }
  return out;
}

function volumePathMiddle(path) {
  const xs = path.map((point) => point.x);
  const ys = path.map((point) => point.y);
  return { x: (Math.min(...xs) + Math.max(...xs)) / 2, y: (Math.min(...ys) + Math.max(...ys)) / 2 };
}

/** Изображение объекта у метки: имя у типа старше формы знака (ADR 005). */
export function volumeMarkView(project, mark) {
  const type = findType(project, mark.typeId);
  const style = styleOf(project, mark.typeId);
  return objectViewByName(typeObjectView(type)) || objectViewForShape(style.shape);
}

// Прямоугольник в плане вокруг точки: `along` вдоль направления `u`, `across`
// поперёк него. Из него выходит и тело точечной вещи, и звено ленты.
function volumeBoxCorners(at, u, alongMm, acrossMm) {
  const n = { x: u.y, y: -u.x };
  const ha = alongMm / 2;
  const hc = acrossMm / 2;
  return volumeClockwise([
    { x: at.x - u.x * ha - n.x * hc, y: at.y - u.y * ha - n.y * hc },
    { x: at.x + u.x * ha - n.x * hc, y: at.y + u.y * ha - n.y * hc },
    { x: at.x + u.x * ha + n.x * hc, y: at.y + u.y * ha + n.y * hc },
    { x: at.x - u.x * ha + n.x * hc, y: at.y - u.y * ha + n.y * hc },
  ]);
}

// Звенья ленты: по призме на отрезок пути, поперечник у всех один. То же, что у
// ломаного объекта чертежа (`volumeObjectPrisms`), и по той же причине —
// соседние звенья заходят друг в друга на изломе, как две стены в углу.
function volumePathPrisms(path, acrossMm, bottomMm, topMm) {
  const prisms = [];
  for (let index = 0; index + 1 < path.length; index += 1) {
    const a = path[index];
    const b = path[index + 1];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const length = Math.hypot(dx, dy);
    if (!(length > 0)) continue;
    const u = { x: dx / length, y: dy / length };
    const middle = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
    prisms.push({ corners: volumeBoxCorners(middle, u, length, acrossMm), bottomMm, topMm });
  }
  return prisms;
}

/**
 * **Точки повтора вдоль пути** (таск 177, G275): куда сядут светильники трека.
 *
 * Правило одно на любую длину и любой излом: считается **число** элементов —
 * `round(длина / шаг)`, не меньше одного и не больше потолка, — и они
 * расставляются равномерно с отступом полушага от концов. Поэтому у трека в
 * 1,7 м выходит три светильника через 567 мм, а не два через 600 и обрубок, а у
 * трека в 40 см — ровно один посередине.
 *
 * Отдаёт точку и направление пути в ней: по направлению встаёт габарит
 * элемента, и на изломе он честно повернётся вместе с полосой.
 */
export function volumeLineSpots(path, stepMm, max) {
  const legs = [];
  let total = 0;
  for (let index = 0; index + 1 < path.length; index += 1) {
    const a = path[index];
    const b = path[index + 1];
    const length = Math.hypot(b.x - a.x, b.y - a.y);
    if (!(length > 0)) continue;
    legs.push({ a, u: { x: (b.x - a.x) / length, y: (b.y - a.y) / length }, length, from: total });
    total += length;
  }
  if (legs.length === 0 || !(stepMm > 0)) return [];
  const count = Math.max(1, Math.min(Math.round(total / stepMm) || 1, Math.max(1, max)));
  const spots = [];
  for (let index = 0; index < count; index += 1) {
    const along = (total * (index + 0.5)) / count;
    // Нога, на которую попала мера. Последняя — для меры, упёршейся в конец.
    const leg = legs.find((item) => along <= item.from + item.length) || legs[legs.length - 1];
    const inside = along - leg.from;
    spots.push({
      at: { x: leg.a.x + leg.u.x * inside, y: leg.a.y + leg.u.y * inside },
      u: leg.u,
      // **Настоящий** шаг, а не заказанный: на коротком пути он сжался, на
      // длинном растянулся потолком. Им меряется элемент, который должен
      // встать вплотную к соседнему — полотнище шторы.
      stepMm: total / count,
    });
  }
  return spots;
}

/**
 * Габариты повторяющихся элементов по пути полосы (таск 177).
 *
 * Полоса остаётся полосой: её рисуют звенья. Элемент встаёт **в её
 * поперечнике**, свисает ниже и заходит внутрь — почему именно так, разобрано
 * у `MODELS_LINES` в `objectModels/lines.js`.
 */
function volumeLineFrames(repeat, path, acrossMm, bottomMm, topMm) {
  const thickMm = Math.max(VOLUME_MARK_LIFT_MM, topMm - bottomMm);
  const thinMm = Math.max(VOLUME_MARK_LIFT_MM, acrossMm * repeat.acrossShare);
  return volumeLineSpots(path, repeat.stepMm, repeat.max).map((spot, index) => {
    const f = { x: spot.u.y, y: -spot.u.x };
    // Вдоль пути элемент мерится либо своим поперечником (светильник трека —
    // кругляш), либо **шагом** (полотнище шторы — почти вплотную к соседнему,
    // иначе вместо ткани выйдут жалюзи).
    const alongMm = repeat.alongShare
      ? Math.max(VOLUME_MARK_LIFT_MM, spot.stepMm * repeat.alongShare)
      : thinMm;
    // Волна: соседние элементы разведены по глубине. Складка тем и видна —
    // грани полотнищ отвёрнуты друг от друга, и между ними встаёт тёмный стык.
    const wave = repeat.waveShare ? (index % 2 === 0 ? -1 : 1) * repeat.waveShare * thinMm : 0;
    return {
      at: { x: spot.at.x + f.x * wave, y: spot.at.y + f.y * wave },
      // Полотно висит **до пола**: низ — ноль, верх заходит в полосу карниза.
      // Светильник трека, наоборот, свисает из полосы на долю её толщины.
      bottomMm: repeat.toFloor ? 0 : bottomMm - thickMm * repeat.dropShare,
      u: spot.u,
      f,
      widthMm: alongMm,
      depthMm: thinMm,
      heightMm: repeat.toFloor
        ? Math.max(VOLUME_MARK_LIFT_MM, bottomMm + thickMm * repeat.biteShare)
        : thickMm * (repeat.dropShare + repeat.biteShare),
    };
  });
}

/**
 * Где стоит одна метка — или почему не стоит нигде.
 *
 * `null` — того, чего в объёме нет вовсе (плашка комментария); `{markId, skip}`
 * — неразмещённая; полное описание места — размещённая. Чистая: ни холста, ни
 * строк, — правило места обязано проверяться без браузера.
 */
export function volumeMarkPlacement(project, mark, rooms = []) {
  if (!mark || markIsComment(mark)) return null;
  const path = volumeMarkPathMm(project, mark);
  if (path.length === 0) return { markId: mark.id, skip: VOLUME_MARK_NO_POINT };
  const sizes = markSizes(project, mark);
  const markView = volumeMarkView(project, mark);
  // Габарит лица — у общего правила (G226): каждая недостающая сторона берётся
  // у изображения объекта, а без изображения — у общей рамки. Строки
  // `VOLUME_MARK_NO_SIZE` в списке неразмещённых после G215 не бывает вовсе,
  // но код остаётся: окно знает его, и объект прежнего формата в середине
  // пересборки не должен спорить с новым правилом.
  const box = markBoxMm({ lengthMm: sizes.length, widthMm: sizes.width }, markView);
  const lengthMm = Math.max(VOLUME_MARK_MIN_MM, box.lengthMm);
  const widthMm = Math.max(VOLUME_MARK_MIN_MM, box.widthMm);
  // Выступ **не подтягивается до самой мелкой стороны**: это измерение, по
  // которому ничего не выделяют, и округли его до двадцати — плоская панель
  // стала бы вдвое толще себя. Хватает двух миллиметров: тело перестаёт быть
  // вырожденным, а у встроенного светильника выступ и правда нулевой.
  //
  // Запасной выступ берётся только у вещи, о размерах которой не сказано
  // **ничего**, и только там, где своего выступа нет: записанный ноль — это
  // ноль («встроенный»), а не пустота. Вещь, у которой человек назвал хоть
  // одну сторону лица, остаётся при своём выступе — догадываться о третьем
  // измерении по одной названной стороне нечем, да и готовый объект от этого
  // не должен толстеть.
  const nothingOwn = box.lengthFrom !== "own" && box.widthFrom !== "own";
  const depthOwn = nothingOwn && sizes.depth === null ? MARK_BOX_FRAME_DEPTH_MM : sizes.depth;
  const depthMm = Math.max(VOLUME_MARK_LIFT_MM, Math.abs(depthOwn || 0));
  const recessed = Number(sizes.depth) < 0;
  const line = mark.kind === "line" && path.length >= 2;
  const style = styleOf(project, mark.typeId);
  const rgb = volumeRgbOf(style.color);
  const view = line ? null : markView;
  // Повтор вдоль пути (таск 177, G275): у трека из полосы торчат светильники, у
  // ленты не торчит ничего. Ищется по коду типа — почему именно по коду,
  // разобрано в `objectModels/lines.js`.
  const lineType = line ? findType(project, mark.typeId) : null;
  const repeat = lineType ? objectLineModel(lineType.code) : null;
  const repeating = (spotPath, acrossMm, bottomMm, topMm) => {
    if (!repeat) return null;
    const frames = volumeLineFrames(repeat, spotPath, acrossMm, bottomMm, topMm);
    return frames.length === 0 ? null : { key: repeat.key, parts: repeat.parts, frames };
  };
  const common = {
    markId: mark.id,
    label: labelOf(project, mark.id),
    color: style.color,
    rgb,
    bodyRgb: volumeTint(rgb),
    kind: line ? "line" : "point",
    view,
    // Хоть одна сторона габарита — догадка сборки, а не чертёж: окно обязано
    // сказать об этом словом (`volumeMarks().spare`). Откуда именно взята
    // каждая сторона, здесь не хранится: это правило `markBoxMm`, и
    // спрашивают его у неё.
    spare: box.guessed,
    // Модель садится на последнюю ступень лестницы изображения (таск 155,
    // `objectModels/registry.js`): нашлось изображение — его имя и есть ключ
    // модели. У линейной метки модели нет и быть не может: она не вещь, а
    // цепочка звеньев, и у звена нет ни лица, ни верха. Зато у неё может быть
    // **повтор вдоль пути** (таск 177, поле `repeat`) — у трека из полосы
    // торчат светильники, у ленты не торчит ничего.
    //
    // С запасным габаритом (G215, G226) модель живёт мирно и по той же
    // причине: недостающая сторона взята у того же изображения, и получается,
    // что у вещи сходятся и габарит, и тело — а не кубик в габарите от
    // кондиционера.
    // Клавиш у выключателя столько, сколько каналов у типа (таск 177, G274):
    // описание приходит по имени изображения, а число клавиш — у справочника.
    // Неклавишной модели это ничего не меняет, и отдаётся она той же ссылкой.
    model: view ? objectModelChannels(objectModelByKey(view.name), typeChannels(project, mark.typeId)) : null,
  };
  const heightMm = sizes.heightAboveFloor;
  const binding = markWall(mark);
  const wall = binding ? findWall(project, binding.wallId) : null;
  const vectors = wall ? wallVectors(wall) : null;
  const side = wall && vectors ? markWallSideOn(project, mark, wall.id) : null;

  // ——— на своей стене ———
  if (heightMm !== null && wall && vectors && side) {
    const sign = side === "left" ? 1 : -1;
    const normal = { x: vectors.n.x * sign, y: vectors.n.y * sign, z: 0 };
    const faceMm = Number(wall.thicknessMm) / 2 + VOLUME_MARK_LIFT_MM;
    // Отступ берётся из привязки **как есть**: зеркалит отступы только лист
    // развёртки (таск 129), а объёму нужны обе стороны стены разом.
    const to = binding.toMm === null ? binding.atMm : binding.toMm;
    const fromMm = Math.min(binding.atMm, to);
    const toMm = Math.max(binding.atMm, to);
    const alongMm = line ? Math.max(VOLUME_MARK_MIN_MM, toMm - fromMm) : lengthMm;
    const middle = (fromMm + toMm) / 2;
    // Выступ идёт наружу от грани стены; утопленное (щит, выступ −30) уходит
    // внутрь, но лицом остаётся в плоскости стены — иначе его не было бы видно.
    const outer = recessed ? faceMm : faceMm + depthMm;
    const inner = recessed ? faceMm - depthMm : faceMm;
    // Высота над полом — середина вещи, кроме вещи, стоящей на полу
    // (`volumeMarkOnFloor`, D34): у неё на полу стоит низ. Вверх на стене идёт
    // **ширина** — вторая сторона лица, и другого имени у этой оси нет.
    const bottomMm = volumeMarkOnFloor(heightMm) ? 0 : heightMm - widthMm / 2;
    const topMm = bottomMm + widthMm;
    // Середина тела, а не записанное число: по ней стоит лицо, целится рамка
    // выделения и приходит стрелка связи. У всего, что висит, она и есть
    // записанная высота, — разойтись они могут только у стоящего на полу.
    const centreMm = (bottomMm + topMm) / 2;
    const at = (across, alongMm = middle) => ({
      x: Number(wall.aMm.x) + vectors.u.x * alongMm + normal.x * across,
      y: Number(wall.aMm.y) + vectors.u.y * alongMm + normal.y * across,
    });
    const faceAt = at(outer);
    const coreMm = (outer + inner) / 2;
    return {
      ...common,
      mode: VOLUME_MARK_WALL,
      wallId: wall.id,
      side,
      heightMm: centreMm,
      prisms: [
        {
          corners: volumeBoxCorners(at(coreMm), vectors.u, alongMm, Math.max(outer - inner, 1)),
          bottomMm,
          topMm,
        },
      ],
      // Повтор вдоль стены: путь — сама полоса от отступа до отступа. Поперечник
      // тут — выступ от стены, а толщина полосы — её высота: на стене полоса
      // лежит боком, и элемент всё равно свисает вниз.
      repeat: repeating(
        [at(coreMm, fromMm), at(coreMm, toMm)],
        Math.max(outer - inner, 1),
        bottomMm,
        topMm,
      ),
      anchor: { x: faceAt.x, y: faceAt.y, z: centreMm },
      // Габарит для модели (таск 155). Перёд берётся **оттуда же, откуда
      // лицо**: `u` — вдоль стены, как у изображения, `f` — от лица в стену,
      // то есть доля −0.5 по глубине всегда лежит на наружной грани, и у
      // утопленного щита тоже. Вверх идёт **высота вещи** — поле `width`,
      // которое с таска 158 так и подписано («Высота»): по стене мерят длину,
      // поперёк — ширину (выступ), вверх — высоту.
      frame: {
        at: at((outer + inner) / 2),
        bottomMm,
        u: { x: vectors.u.x, y: vectors.u.y },
        f: { x: -normal.x, y: -normal.y },
        widthMm: alongMm,
        depthMm: Math.max(outer - inner, 1),
        heightMm: widthMm,
      },
      // Лицо вещи — её наружная грань: по нему рисуется изображение объекта.
      face: {
        origin: { x: faceAt.x, y: faceAt.y, z: centreMm },
        u: { x: vectors.u.x, y: vectors.u.y, z: 0 },
        v: { x: 0, y: 0, z: 1 },
        normal,
        widthMm: alongMm,
        heightMm: widthMm,
      },
    };
  }

  // ——— в воздухе на своей высоте и под потолком ———
  const middle = volumePathMiddle(path);
  const room = heightMm === null ? volumeRoomAt({ rooms }, middle) : null;
  if (heightMm === null && !room) return { markId: mark.id, skip: VOLUME_MARK_NO_PLACE };
  // Вверх у вещи без стены идёт **выступ**: она лежит лицом к полу или к
  // потолку, а не стоит боком. Потолочная свисает выступом от потолка, висящая
  // в воздухе берёт свою высоту серединой, а стоящая на полу
  // (`volumeMarkOnFloor`, D34) — низом: робот-пылесос с выступом 90 занимает от
  // нуля до девяноста, а не от минус сорока пяти до сорока пяти.
  const onFloor = volumeMarkOnFloor(heightMm);
  // Потолочная вещь висит **на два миллиметра ниже потолка** — ту же щель
  // (`VOLUME_MARK_LIFT_MM`), которой вещь на стене отходит от стены. До таска
  // 211 её верх лежал ровно в плоскости потолка, и это сходило с рук: потолок
  // рисовался ярусом раньше тел и всегда оказывался под ними. Теперь порядок
  // им считает дерево, а у совпавших плоскостей порядок решать нечем — трек и
  // лента проступали сквозь крышу на виде сверху.
  const bottomMm =
    heightMm === null
      ? room.heightMm - depthMm - VOLUME_MARK_LIFT_MM
      : onFloor
        ? 0
        : heightMm - depthMm / 2;
  const topMm = bottomMm + depthMm;
  const centreMm = (topMm + bottomMm) / 2;
  const prisms = line
    ? volumePathPrisms(path, lengthMm, bottomMm, topMm)
    : [{ corners: volumeBoxCorners(middle, { x: 1, y: 0 }, lengthMm, widthMm), bottomMm, topMm }];
  if (prisms.length === 0) return { markId: mark.id, skip: VOLUME_MARK_NO_POINT };
  return {
    ...common,
    mode: heightMm === null ? VOLUME_MARK_CEILING : VOLUME_MARK_ROOM,
    roomId: room ? room.roomId : null,
    heightMm: centreMm,
    prisms,
    // Повтор вдоль пути (таск 177): трек под потолком и есть тот случай, для
    // которого он заведён. Поперечник полосы — её ширина в плане, толщина —
    // выступ: полоса лежит лицом к полу, и светильники свисают вниз.
    repeat: repeating(path, lengthMm, bottomMm, topMm),
    anchor: { x: middle.x, y: middle.y, z: centreMm },
    // Габарит для модели. Вещь в воздухе не повёрнута ничем — её коробка
    // лежит по осям плана, — значит и модель берёт их: `u` вдоль `x`, перёд
    // смотрит против `y`. Вверх здесь идёт **ширина (выступ)**: у потолочного
    // светильника вниз от потолка свисает именно она, а высота с длиной
    // ложатся в план — лицо вещи смотрит вниз.
    //
    // **Здесь имена осей и расходятся с картинкой** (дефект D36, таск 158): у
    // вещи под потолком «Ширина» рисуется вниз, а «Высота» — в плане. Имена
    // верны для вещи на стене, а таких у заказчика 79 из 86; под потолком
    // расходится люстра (500 × 400 при выступе 300). Честная правка — хранить
    // габарит в осях самой вещи и раскладывать его по посадке — двигает
    // готовые картинки, поэтому ждёт слова заказчика (G68).
    frame: line
      ? null
      : {
          at: middle,
          bottomMm,
          u: { x: 1, y: 0 },
          f: { x: 0, y: 1 },
          widthMm: lengthMm,
          depthMm: widthMm,
          heightMm: topMm - bottomMm,
        },
    // Лицо потолочной вещи смотрит вниз: на светильник смотрят снизу, и
    // изображение объекта рисуется на нижней грани. У стоящей на полу — ровно
    // наоборот (D34): на робота-пылесоса смотрят сверху, а лицо, оставленное
    // внизу, легло бы в самую плоскость пола и ушло бы под неё вместе с
    // контуром (`VOLUME_VIEW_LIFT_MM` поднимает контур **по нормали**), да ещё
    // и отсеклось бы отбором по нормали — то есть вещь осталась бы без
    // изображения вовсе.
    //
    // Переворачивается только нормаль и сторона, на которой лежит лицо: `u` и
    // `v` остаются своими. У горизонтального лица верхнего края нет вовсе —
    // человек ходит вокруг и смотрит на него с любой стороны, — и назначать его
    // значило бы выдумать то, чего в данных нет.
    face: line
      ? null
      : {
          origin: { x: middle.x, y: middle.y, z: onFloor ? topMm : bottomMm },
          u: { x: 1, y: 0, z: 0 },
          v: { x: 0, y: 1, z: 0 },
          normal: { x: 0, y: 0, z: onFloor ? 1 : -1 },
          widthMm: lengthMm,
          heightMm: widthMm,
        },
  };
}

/**
 * Все метки схемы: размещённые, список тех, кому места не нашлось, и список
 * нарисованных запасным габаритом (G215).
 *
 * `marks` — что считать: окно отдаёт сюда видимые на плане, чтобы фильтр значил
 * в двух видах одно и то же. Порядок сохраняется — списки читаются в том же
 * порядке, что таблица меток.
 *
 * Запасной габарит — не потеря, а догадка: вещь в сцене есть, но её размер
 * сборка выдумала. Поэтому `spare` отдельным списком, а не причиной в
 * `unplaced`: это разные новости, и смешивать их нельзя.
 */
export function volumeMarks(project, schemeId, { marks, rooms } = {}) {
  const list = marks || (project ? project.marks.filter((mark) => mark.schemeId === schemeId) : []);
  const placed = [];
  const unplaced = [];
  const spare = [];
  for (const mark of list) {
    const place = volumeMarkPlacement(project, mark, rooms || []);
    if (!place) continue;
    if (place.skip) {
      unplaced.push({ markId: mark.id, label: labelOf(project, mark.id), reason: place.skip });
      continue;
    }
    placed.push(place);
    if (place.spare) spare.push({ markId: place.markId, label: place.label });
  }
  return { placed, unplaced, spare };
}

/**
 * Грани тела вещи. Хозяин у каждой — сама метка: по ним и ловится клик.
 *
 * Есть модель — рисуется она, нет — прежняя коробка по габариту (таск 155).
 * Порядок именно такой, а не наоборот: пока модели писались, объём ни одной
 * минуты не был сломан, и тип, заведённый человеком руками, останется с
 * коробкой навсегда — у него нет изображения, а значит нет и модели.
 *
 * Выделение, прицел и `E` по взгляду от модели не зависят: `markId` стоит у
 * **каждой** грани модели, поэтому выделяется вещь целиком, а не одно тело.
 */
export function volumeMarkFaces(place, out = []) {
  if (place.model && place.frame) {
    return volumeModelFaces(place.frame, place.model, place.bodyRgb, out, { markId: place.markId });
  }
  for (const prism of place.prisms || []) {
    volumePrismFaces(prism.corners, prism.bottomMm, prism.topMm, place.bodyRgb, out, { markId: place.markId });
  }
  // Повтор вдоль пути (таск 177, G275): полоса уже нарисована звеньями, а
  // поверх неё садятся светильники трека. Хозяин у них тот же — сама метка,
  // поэтому щелчок по светильнику выделяет трек, а не ничего.
  for (const frame of (place.repeat && place.repeat.frames) || []) {
    volumeModelFaces(frame, place.repeat, place.bodyRgb, out, { markId: place.markId });
  }
  return out;
}

// ——— модели (таск 155, требование G221) ——————————————————————————————————
//
// Второй интерпретатор описаний — после плоского (`objectViews/registry.js`) и
// объёмного для изображений (`volumeViewPolylines`). Читает список тел
// (`objectModels/kit.js`) и выдаёт призмы: ни мешей, ни вершин руками.
//
// Тело — это **призма по многоугольнику в плане**, то есть ровно то, чем уже
// рисуются стены, вещи чертежа и коробки меток. Поэтому цилиндр здесь
// вертикальный, и другого быть не может: `volumePrismFaces` выдавливает
// многоугольник вверх. Лежачая труба — полотенцесушитель, ствол объектива,
// карниз — описывается коробкой, и в её тридцати миллиметрах разницы не видит
// никто. Это то же решение, что отказ от кривой Безье у изображений: не
// хватает примитива — упрощается вещь, а не растёт набор.

/** Нейтральные концы двух материалов. Чистых их не бывает — см. `volumeModelRgb`. */
const VOLUME_MODEL_METAL = [172, 176, 182];
const VOLUME_MODEL_GLASS = [205, 219, 230];
/** Насколько `light` светлее тела и насколько `dark` темнее его. */
const VOLUME_MODEL_LIGHT = 0.8;
const VOLUME_MODEL_DARK = 0.72;
/** Сколько своего цвета остаётся у металла и стекла. */
const VOLUME_MODEL_NEUTRAL = 0.86;

function volumeMix(rgb, to, share) {
  return [0, 1, 2].map((index) => Math.round(rgb[index] * (1 - share) + to[index] * share));
}

/**
 * Цвет тела: материал, посчитанный **от цвета самой вещи**.
 *
 * Так решается спор модели с ADR 005. Цвет принадлежит категории, и модель
 * своей краски не приносит ни одной: `body` — ровно тот цвет, которым вещь
 * рисовалась до моделей (у метки — разбавленный цвет её категории, у вещи
 * чертежа — её собственный), `light` и `dark` — он же светлее и темнее,
 * `metal` и `glass` — почти нейтральные, но оттенок вещи в них остаётся.
 * Перекрасил человек категорию — поехали все пять.
 *
 * Из этого следует проверяемое обещание: **у вещи, чья модель — одно тело во
 * весь габарит, в кадре не изменилось ничего** — ни цвета, ни числа граней.
 * Колонна тому свидетель.
 *
 * Выигрыш тоже проверяется глазами: на одной стене стоят розетка и
 * выключатель одного цвета, и до моделей они были двумя одинаковыми плашками.
 * Теперь у одной светлая сердцевина, у другого светлые клавиши — а красный
 * остался красным.
 */
export function volumeModelRgb(material, bodyRgb) {
  if (material === "light") return volumeMix(bodyRgb, VOLUME_MARK_BASE, VOLUME_MODEL_LIGHT);
  if (material === "dark") return bodyRgb.map((value) => Math.round(value * VOLUME_MODEL_DARK));
  if (material === "metal") return volumeMix(bodyRgb, VOLUME_MODEL_METAL, VOLUME_MODEL_NEUTRAL);
  if (material === "glass") return volumeMix(bodyRgb, VOLUME_MODEL_GLASS, VOLUME_MODEL_NEUTRAL);
  return bodyRgb;
}

/**
 * Тела модели, переведённые в призмы габарита.
 *
 * Габарит — `frame`: середина в плане, низ по высоте, направление лица и три
 * размера. Доли переводятся им, и только им: ни одно описание не знает ни
 * миллиметров, ни того, на стене вещь или на полу.
 */
export function volumeModelPrisms(frame, parts) {
  const out = [];
  if (!frame || !(frame.heightMm > 0)) return out;
  const at = (fx, fy) => ({
    x: frame.at.x + frame.u.x * fx * frame.widthMm + frame.f.x * fy * frame.depthMm,
    y: frame.at.y + frame.u.y * fx * frame.widthMm + frame.f.y * fy * frame.depthMm,
  });
  for (const part of parts || []) {
    // Лежачий цилиндр призмой не бывает вовсе (таск 177): призма выдавливается
    // вверх, а у него ось горизонтальна. Грани ему строит `volumeTubeFaces`, и
    // здесь он пропускается — иначе барабан стиральной машины молча стал бы
    // коробкой, то есть ровно тем, на что заказчик и указал.
    if (part.kind === "tube") continue;
    // Полотно шторы висит **до пола** (таск 177, G261): верх из долей, низ —
    // ноль. Это единственное тело, которое выходит из габарита, и выходит оно
    // по признаку в описании, а не по догадке интерпретатора.
    const bottomMm = part.toFloor ? 0 : frame.bottomMm + part.z * frame.heightMm;
    const topMm = frame.bottomMm + (part.z + part.height) * frame.heightMm;
    const corners = [];
    if (part.kind === "cyl") {
      // Эллипс вписан в прямоугольник тела, углы сдвинуты на полшага: при
      // восьми сторонах так получаются плоские грани вперёд, назад и по
      // бокам, а не рёбра — цилиндр у стены стоит к ней стороной.
      const cx = part.x + part.width / 2;
      const cy = part.y + part.depth / 2;
      for (let index = 0; index < MODEL_CYL_SIDES; index += 1) {
        const angle = ((index + 0.5) * Math.PI * 2) / MODEL_CYL_SIDES;
        corners.push(at(cx + (Math.cos(angle) * part.width) / 2, cy + (Math.sin(angle) * part.depth) / 2));
      }
    } else {
      corners.push(at(part.x, part.y));
      corners.push(at(part.x + part.width, part.y));
      corners.push(at(part.x + part.width, part.y + part.depth));
      corners.push(at(part.x, part.y + part.depth));
    }
    out.push({
      corners: volumeClockwise(corners),
      bottomMm,
      topMm,
      material: part.material,
      name: part.name,
      // Признак свечения доезжает до призмы и останавливается здесь: сегодня
      // он у всех выключен, а день, когда свет начнёт включаться, правит одну
      // строку ниже — и ни одной из пятидесяти моделей.
      lit: part.lit,
      // Номер канала клавиши (таск 177): у остальных тел его нет вовсе.
      channel: part.channel === undefined ? null : part.channel,
      // Чем тело просвечивает (таск 189): имя плотности или `null`. Доезжает
      // до грани и останавливается — в объект не пишется ничего (G68).
      clear: part.clear || null,
    });
  }
  return out;
}

/**
 * Грань **наружу тела**: обход разворачивается, если нормаль смотрит внутрь.
 *
 * Заведена для лежачего цилиндра (таск 177) и нужна ровно ему: у призмы
 * сторона наружу выходит сама — плановый многоугольник записан по часовой
 * (`volumeClockwise`), и «левая» нормаль ребра смотрит из тела. У лежачего
 * цилиндра плана нет вовсе: его бока стоят косо к обеим осям, и держать в
 * голове, куда повёрнут габарит, пришлось бы в каждой записи. Вместо этого
 * спрашивается сама геометрия: `inside` — точка на оси тела, и грань
 * обязана смотреть от неё.
 */
function volumeFaceOut(points, inside, rgb, options) {
  const normal = volumeFaceNormal(points);
  const middle = volumeMiddleOf(points);
  const away =
    normal.x * (middle.x - inside.x) + normal.y * (middle.y - inside.y) + normal.z * (middle.z - inside.z);
  return volumeFace(away >= 0 ? points : [...points].reverse(), rgb, options);
}

/**
 * Грани **лежачего цилиндра**: восемь боковых полос и два днища (таск 177,
 * G262 — «барабан, горизонтальный и внутри»).
 *
 * Круг вписан в те две стороны тела, что поперёк оси, а углы сдвинуты на
 * полшага — как у стоячего цилиндра: при восьми сторонах восьмиугольник стоит
 * к глазу стороной, а не ребром. Цена та же, что у стоячего, — десять граней,
 * и предел вещи от нового вида тела не поехал.
 */
export function volumeTubeFaces(frame, part, rgb, out = [], options = {}) {
  if (!frame || !(frame.heightMm > 0)) return out;
  const at = (fx, fy, fz) => ({
    x: frame.at.x + frame.u.x * fx * frame.widthMm + frame.f.x * fy * frame.depthMm,
    y: frame.at.y + frame.u.y * fx * frame.widthMm + frame.f.y * fy * frame.depthMm,
    z: frame.bottomMm + fz * frame.heightMm,
  });
  // Ось: `x` — поперёк лица, `y` — из лица в глубину. Вдоль неё тело тянется от
  // `from` до `to`, а круг лежит в двух оставшихся долях.
  const alongX = part.axis === "x";
  const from = alongX ? part.x : part.y;
  const to = from + (alongX ? part.width : part.depth);
  const across = alongX ? part.y + part.depth / 2 : part.x + part.width / 2;
  const acrossMm = alongX ? frame.depthMm : frame.widthMm;
  const middleZ = part.z + part.height / 2;
  // Доли круга поперёк оси. Обычно он вписан в само тело и в неквадратном
  // габарите выходит овальным — как овальна колонна 150 × 90. `round` берёт
  // диаметр по **большей** стороне тела в миллиметрах и переводит его в доли
  // каждой оси порознь: круг остаётся кругом, даже если для этого ему придётся
  // выйти из габарита (круглое зеркало при полосе подсветки, таск 177).
  let acrossShare = (alongX ? part.depth : part.width) / 2;
  let upShare = part.height / 2;
  if (part.round) {
    const radiusMm = Math.max(acrossShare * 2 * acrossMm, part.height * frame.heightMm) / 2;
    acrossShare = acrossMm > 0 ? radiusMm / acrossMm : acrossShare;
    upShare = frame.heightMm > 0 ? radiusMm / frame.heightMm : upShare;
  }
  const ring = [];
  for (let index = 0; index < MODEL_CYL_SIDES; index += 1) {
    const angle = ((index + 0.5) * Math.PI * 2) / MODEL_CYL_SIDES;
    ring.push({ across: across + Math.cos(angle) * acrossShare, z: middleZ + Math.sin(angle) * upShare });
  }
  const node = (item, along) => (alongX ? at(along, item.across, item.z) : at(item.across, along, item.z));
  const axisAt = (along) => (alongX ? at(along, across, middleZ) : at(across, along, middleZ));
  const middle = axisAt((from + to) / 2);
  for (let index = 0; index < ring.length; index += 1) {
    const a = ring[index];
    const b = ring[(index + 1) % ring.length];
    out.push(volumeFaceOut([node(a, from), node(b, from), node(b, to), node(a, to)], middle, rgb, options));
  }
  // Днища: наружу у каждого — прочь от другого конца оси.
  out.push(volumeFaceOut(ring.map((item) => node(item, from)), axisAt(to), rgb, options));
  out.push(volumeFaceOut(ring.map((item) => node(item, to)), axisAt(from), rgb, options));
  return out;
}

/**
 * Грани модели.
 *
 * `options.markId` — хозяин: у вещей чертежа его нет, у меток есть.
 * `options.clear` — модель просвечивает **целиком** (таск 169): так рисуются
 * вещи чертежа. У метки такого признака нет и не будет: просвечивает не метка,
 * а **тело** — полотнище тюля (таск 189), стекло в раме, — и говорит об этом
 * само описание (`clear` в `objectModels/kit.js`). Поэтому плотность тела
 * сильнее общей: прозрачное тело прозрачно и внутри прозрачной вещи, а труба
 * карниза остаётся плотной внутри шторы.
 *
 * Тела двух видов идут призмами, лежачий цилиндр — своими гранями (таск 177).
 * Разбор по виду тела здесь и только здесь: ни одна модель не знает, чем её
 * рисуют.
 */
export function volumeModelFaces(frame, model, rgb, out = [], options = {}) {
  const parts = (model && model.parts) || [];
  const own = (part) => ({
    markId: options.markId || null,
    // Плотность тела старше общей — см. заголовок.
    clear: (part && part.clear) || options.clear || false,
    // Номер канала доезжает до грани и останавливается там: что значит «канал
    // выделен», решает окно, а в объект не пишется ничего (G68, таск 177).
    channel: part && part.channel !== undefined ? part.channel : null,
  });
  for (const part of parts) {
    if (part.kind !== "tube") continue;
    volumeTubeFaces(frame, part, volumeModelRgb(part.material, rgb), out, own(part));
  }
  for (const prism of volumeModelPrisms(frame, parts)) {
    // Та самая одна строка: `prism.lit` пока всегда `false`.
    const fill = volumeModelRgb(prism.material, rgb);
    volumePrismFaces(prism.corners, prism.bottomMm, prism.topMm, fill, out, own(prism));
  }
  return out;
}

/**
 * **Второй интерпретатор изображений объектов** (таск 139, G198).
 *
 * Обещание того таска проверяется здесь: объёму хватило тех же пяти примитивов,
 * и ни одной записи переписывать не пришлось. Разница с плоским интерпретатором
 * (`objectViews/registry.js`, `drawPart`) одна, и она в природе вывода: тот
 * рисует по холсту и умеет дуги со скруглениями сам, а этому нужны **точки** —
 * окружность, дуга и скруглённый угол разбираются на отрезки здесь.
 *
 * Доли те же: −0.5…0.5 по сторонам своего прямоугольника.
 */
export function volumeViewPolylines(view) {
  const lines = [];
  for (const part of (view && view.parts) || []) {
    if (part.kind === "line") {
      lines.push({ points: [{ x: part.x1, y: part.y1 }, { x: part.x2, y: part.y2 }], closed: false });
      continue;
    }
    if (part.kind === "poly") {
      lines.push({ points: (part.points || []).map(([x, y]) => ({ x, y })), closed: Boolean(part.close) });
      continue;
    }
    if (part.kind === "rect") {
      lines.push({ points: volumeRectPoints(part), closed: true });
      continue;
    }
    if (part.kind === "circle") {
      lines.push({ points: volumeArcPoints(part.cx, part.cy, part.r, 0, Math.PI * 2), closed: true });
      continue;
    }
    if (part.kind === "arc") {
      lines.push({
        points: volumeArcPoints(part.cx, part.cy, part.r, part.from, part.to),
        closed: Boolean(part.close),
      });
    }
  }
  return lines.filter((item) => item.points.length >= 2);
}

// Дуга отрезками. Шаг — доля полного круга, но не меньше двух отрезков: у
// четверти окружности их выходит четыре, и излома на лице вещи не видно.
function volumeArcPoints(cx, cy, r, from, to) {
  const span = Math.abs(to - from);
  const steps = Math.max(2, Math.round((VOLUME_VIEW_STEPS * span) / (Math.PI * 2)));
  const points = [];
  for (let index = 0; index <= steps; index += 1) {
    const angle = from + ((to - from) * index) / steps;
    points.push({ x: cx + Math.cos(angle) * r, y: cy + Math.sin(angle) * r });
  }
  // Полная окружность: последняя точка совпала бы с первой, а замкнутость
  // говорится признаком `closed`, а не дублем вершины.
  if (span >= Math.PI * 2 - 1e-6) points.pop();
  return points;
}

// Прямоугольник со скруглением: углы — те же дуги. Радиус в долях, как у
// плоского интерпретатора, и так же зажат половиной короткой стороны.
function volumeRectPoints(part) {
  const left = part.x;
  const top = part.y;
  const right = part.x + part.width;
  const bottom = part.y + part.height;
  const r = Math.max(0, Math.min(Number(part.radius) || 0, Math.min(Math.abs(part.width), Math.abs(part.height)) / 2));
  if (!(r > 0)) {
    return [
      { x: left, y: top },
      { x: right, y: top },
      { x: right, y: bottom },
      { x: left, y: bottom },
    ];
  }
  const corner = (cx, cy, from, to) => volumeArcPoints(cx, cy, r, from, to);
  return [
    ...corner(left + r, top + r, Math.PI, Math.PI * 1.5),
    ...corner(right - r, top + r, Math.PI * 1.5, Math.PI * 2),
    ...corner(right - r, bottom - r, 0, Math.PI * 0.5),
    ...corner(left + r, bottom - r, Math.PI * 0.5, Math.PI),
  ];
}

/**
 * Доля лица вещи → точка в миллиметрах чертежа и высоте над полом.
 *
 * Доля по высоте берётся **с обратным знаком**: у плоского интерпретатора ось
 * `y` растёт вниз (так устроен холст), а здесь вверх. Без этого решётка
 * кондиционера оказалась бы над индикатором, а клавиша выключателя — под
 * рамкой: изображение рисовалось бы вверх ногами и молча.
 */
export function volumeFacePoint(face, fx, fy) {
  const alongMm = fx * face.widthMm;
  const upMm = -fy * face.heightMm;
  return {
    x: face.origin.x + face.u.x * alongMm + face.v.x * upMm + face.normal.x * VOLUME_VIEW_LIFT_MM,
    y: face.origin.y + face.u.y * alongMm + face.v.y * upMm + face.normal.y * VOLUME_VIEW_LIFT_MM,
    z: face.origin.z + face.u.z * alongMm + face.v.z * upMm + face.normal.z * VOLUME_VIEW_LIFT_MM,
  };
}

/**
 * Контур вещи — её изображением объекта, цветом метки.
 *
 * Изображения нет (тип без имени и с формой, которой изображения не завели) —
 * нет и контура: вещь остаётся своей плашкой цвета категории. Условный знак
 * плана сюда не переносится нарочно: знак читают как обозначение рядом с
 * подписью, а в объёме подписи нет, и знак стал бы украшением.
 */
export function volumeMarkViewLines(place, out = []) {
  if (!place || !place.face || !place.view) return out;
  for (const line of volumeViewPolylines(place.view)) {
    out.push(
      volumeLine(
        line.points.map((point) => volumeFacePoint(place.face, point.x, point.y)),
        place.color,
        {
          closed: line.closed,
          normal: place.face.normal,
          width: VOLUME_VIEW_LINE_PX,
          markId: place.markId,
        },
      ),
    );
  }
  return out;
}

// ——— выделение и связи ———————————————————————————————————————————————————
//
// Выделение в объёме **общее с планом** (слова заказчика): окно и список меток
// смотрят в одно и то же поле состояния, и кто выделил первым — неважно.
// Поэтому здесь только рамка, а живёт выделение там же, где жило.
//
// И рамка, и стрелки лежат **поверх всего** (`VOLUME_LAYER_MARK`) — это прямое
// решение заказчика: «стрелка идёт сквозь стену». Цель в соседней комнате иначе
// пропадала бы за перегородкой вместе с ответом на вопрос, куда связь ведёт.
// Чтобы сквозная линия не врала о том, что видно глазами, связь рисуется
// **дважды**: сплошной в общем потоке (её закрывают стены, как и положено) и
// тонкой пунктирной поверх всего. Там, где связь видна, пунктир ложится на свою
// же сплошную линию и не заметен; там, где она за стеной, остаётся один
// пунктир — он и значит «цель за стеной».

/** Цвет рамки выделения — тот же, что на плане (`drawMarkBody`). */
export const VOLUME_SELECT_COLOR = "#0969DA";
/** Цвета связей — те же, что на плане (`LINK_COLOR` и `LINK_TIE_COLOR`). */
export const VOLUME_LINK_COLOR = "#BF3989";
export const VOLUME_TIE_COLOR = "#0F2E7A";
/** Во сколько глушится поднятое цепочкой, но выделенной метки не касающееся. */
const VOLUME_LINK_FAR = 0.4;
/** Насколько видна сквозь стену та часть связи, которую закрывает геометрия. */
const VOLUME_LINK_THROUGH = 0.55;
const VOLUME_LINK_WIDTH = 2.2;
const VOLUME_LINK_THROUGH_WIDTH = 1.1;
const VOLUME_LINK_DASH = [6, 5];
const VOLUME_SELECT_DASH = [7, 5];
const VOLUME_SELECT_GROW = 1.3;

/** Тот же тон вполсилы: прозрачность пишется в сам цвет. */
export function volumeFade(color, alpha) {
  const rgb = hexToRgb(color) || { r: 120, g: 120, b: 120 };
  return "rgba(" + rgb.r + "," + rgb.g + "," + rgb.b + "," + Math.round(alpha * 100) / 100 + ")";
}

/**
 * Рамка выделенной вещи: по её лицу у точки, по оси у ленты. Пунктир и цвет те
 * же, что у кольца выделения на плане: одна и та же метка не должна выделяться
 * в двух видах по-разному.
 */
export function volumeSelectLines(place, out = []) {
  if (!place) return out;
  if (place.face) {
    const half = VOLUME_SELECT_GROW / 2;
    out.push(
      volumeLine(
        [
          volumeFacePoint(place.face, -half, -half),
          volumeFacePoint(place.face, half, -half),
          volumeFacePoint(place.face, half, half),
          volumeFacePoint(place.face, -half, half),
        ],
        VOLUME_SELECT_COLOR,
        { closed: true, dash: VOLUME_SELECT_DASH, width: 2, layer: VOLUME_LAYER_MARK },
      ),
    );
    return out;
  }
  // Лента: рамки у неё нет, обводится сама — так же, как на плане выделяется
  // линия, а не кольцо вокруг каждой её вершины.
  for (const prism of place.prisms || []) {
    const middleZ = (prism.bottomMm + prism.topMm) / 2;
    out.push(
      volumeLine(
        prism.corners.map((point) => ({ x: point.x, y: point.y, z: middleZ })),
        VOLUME_SELECT_COLOR,
        { closed: true, dash: VOLUME_SELECT_DASH, width: 2, layer: VOLUME_LAYER_MARK },
      ),
    );
  }
  return out;
}

/**
 * **Рамка выбранной клавиши** (таск 177, G274): по самой клавише, а не по лицу
 * вещи.
 *
 * Выбранный канал обязан быть виден глазами — иначе стрелки «только его» читались
 * бы как пропавшие связи. Рамка идёт тем же цветом, что рамка выделения, но
 * сплошной и вплотную по клавише: у вещи рамка снаружи и пунктиром, у клавиши
 * внутри и линией, и спутать их нельзя.
 *
 * Доли клавиши переводятся в доли лица: у модели `z` считается снизу вверх, у
 * лица `fy` — сверху вниз, отсюда `0.5 − z`. Это то же пересчитывание, что в
 * `volumeFacePoint`, и другого места, где оно живёт, нет.
 */
export function volumeChannelLines(place, channel, out = []) {
  if (!place || !place.face || !channel || !place.model) return out;
  const key = (place.model.parts || []).find((part) => part.channel === channel);
  if (!key) return out;
  const left = key.x;
  const right = key.x + key.width;
  const top = 0.5 - (key.z + key.height);
  const bottom = 0.5 - key.z;
  out.push(
    volumeLine(
      [
        volumeFacePoint(place.face, left, top),
        volumeFacePoint(place.face, right, top),
        volumeFacePoint(place.face, right, bottom),
        volumeFacePoint(place.face, left, bottom),
      ],
      VOLUME_SELECT_COLOR,
      { closed: true, width: 2, layer: VOLUME_LAYER_MARK },
    ),
  );
  return out;
}

/**
 * Стрелки связей по правилам плана.
 *
 * Правила, **какие** связи показывать, берутся с плана целиком
 * (`canvas.canvasFrameLinks` → `render.markLinks`): управление — дугой со
 * стрелкой, общее управление — без стрелки (это отношение равных), общий номер
 * — кольцом по своим меткам. Вторых правил здесь не заводится: разойдись они, у
 * одной метки на плане и в объёме оказались бы разные связи.
 *
 * `anchorOf` отвечает, где в объёме стоит метка. Неразмещённой вещи в объёме
 * нет — нет и стрелки к ней: это было бы указание в пустоту. Почему её нет,
 * отвечает список неразмещённых.
 */
/**
 * **Связи одного канала** (таск 177, G274): слова заказчика — «обрабатывай клик
 * на каждый канал отдельно рисуя стрелки только на соответствующий канал».
 *
 * Канал не выбран (`null`) — связи идут как шли, и это обычная жизнь: выделение
 * метки показывает всю её цепь. Канал выбран — остаётся **только управление с
 * этого канала этой метки**, и остаётся оно одно:
 *
 * - общее управление (`ties`) про канал не знает вовсе — это отношение равных
 *   между двумя выключателями, и у него нет стороны «какой клавишей»;
 * - общий номер (`groups`) — тождество меток, тоже не про клавишу;
 * - связи **без канала** у многоклавишной метки — это разметка до каналов, и
 *   показывать их при выбранной первой клавише значило бы сказать «они на
 *   первой», чего в данных нет.
 *
 * Поэтому выбор канала — это **сужение до одной клавиши**, а не подсветка: на
 * кадре остаётся ровно то, чем она управляет. Снять его можно щелчком мимо
 * клавиши — выделение вещи целиком возвращает всю картину.
 *
 * **Одноклавишная метка — исключение, и не домысел** (таск 191, D50). Слова
 * заказчика: «Если в Объёме нажать на клавишу 1 клавишного выключателя, то
 * пишет: Канал 1: на этой клавише нет ни одной нагрузки. Хотя по факту 1 канал
 * там и в „Чем управляет“ не указывается канал. Соответственно выбранное и есть
 * первый канал». У метки с одной клавишей другого канала **не бывает**: связь
 * без номера может принадлежать только ей, и это не догадка, а единственный
 * возможный ответ. Правило таска 177 («связь без канала первой клавише не
 * приписывается») остаётся там, где оно верно, — у двух клавиш и больше, где
 * данные молчат о том, какая из них.
 *
 * Сколько клавиш — говорит `keys`, и считает их `volumeModelKeys` по самому
 * описанию тела: второго счёта клавиш в сборке нет. Не передали — метка
 * считается многоклавишной, то есть осторожной.
 *
 * Чистая и живёт здесь, а не в холсте: правила, **какие** связи бывают,
 * по-прежнему плановые целиком (`canvasFrameLinks`), и второго их хозяина
 * заводить нельзя. Здесь только отбор по каналу — то, чего на плане нет.
 */
export function volumeChannelLinks(links, pick, keys = 0) {
  const empty = { lines: [], ties: [], groups: [], offScheme: [] };
  if (!links) return empty;
  if (!pick || !pick.markId || !pick.channel) return links;
  // Единственная клавиша забирает себе и связи без номера: другого канала у неё
  // нет. У второй и дальше клавиш этого правила быть не может — номер там
  // значит выбор, и выбора в данных не записано.
  const alone = keys === 1 && pick.channel === 1;
  return {
    ...empty,
    lines: (links.lines || []).filter(
      (line) =>
        line.fromId === pick.markId &&
        (line.channel === pick.channel || (alone && (line.channel === null || line.channel === undefined))),
    ),
  };
}

/**
 * **Сколько клавиш нарисовано у вещи** (таск 191, D50).
 *
 * Считается по самому описанию тела — по тем клавишам, которые построил
 * `modelKeys` (`objectModels/power.js`), а не вторым счётом по типу: число
 * каналов у типа и число клавиш на стене расходятся нарочно (у четырёхканальной
 * метки клавиш четыре, у двадцатиканального реле — ни одной, разбор в
 * `power.js`). Спрашивать надо то, по чему человек щёлкает, а щёлкает он по
 * клавише.
 *
 * Неклавишная модель даёт ноль — и ноль здесь значит «правило одной клавиши не
 * про неё», а не «одна клавиша».
 */
export function volumeModelKeys(model) {
  return ((model && model.parts) || []).filter((part) => part.channel).length;
}

export function volumeLinkLines(links, anchorOf, out = []) {
  const pair = (item, color, arrow) => {
    const from = anchorOf(item.fromId);
    const to = anchorOf(item.toId);
    if (!from || !to) return;
    const alpha = item.near === false ? VOLUME_LINK_FAR : 1;
    out.push(
      volumeLine([from, to], alpha === 1 ? color : volumeFade(color, alpha), { width: VOLUME_LINK_WIDTH, arrow }),
    );
    out.push(
      volumeLine([from, to], volumeFade(color, VOLUME_LINK_THROUGH * alpha), {
        width: VOLUME_LINK_THROUGH_WIDTH,
        dash: VOLUME_LINK_DASH,
        arrow,
        layer: VOLUME_LAYER_MARK,
      }),
    );
  };
  for (const line of (links && links.lines) || []) pair(line, VOLUME_LINK_COLOR, true);
  for (const tie of (links && links.ties) || []) pair(tie, VOLUME_TIE_COLOR, false);
  for (const group of (links && links.groups) || []) {
    const points = (group.markIds || []).map((id) => anchorOf(id)).filter(Boolean);
    if (points.length < 2) continue;
    const alpha = group.near === false ? VOLUME_LINK_FAR : 1;
    // Кольцом по углу вокруг середины: тождество — не цепь, у него нет ни
    // начала, ни направления, и замкнутая линия говорит об этом сама.
    const centre = {
      x: points.reduce((sum, point) => sum + point.x, 0) / points.length,
      y: points.reduce((sum, point) => sum + point.y, 0) / points.length,
    };
    const ring = [...points].sort(
      (first, second) =>
        Math.atan2(first.y - centre.y, first.x - centre.x) - Math.atan2(second.y - centre.y, second.x - centre.x),
    );
    out.push(volumeLine(ring, volumeFade(VOLUME_LINK_COLOR, alpha), { closed: true, dash: VOLUME_LINK_DASH, width: 1.4 }));
    out.push(
      volumeLine(ring, volumeFade(VOLUME_LINK_COLOR, VOLUME_LINK_THROUGH * alpha), {
        closed: true,
        dash: VOLUME_LINK_DASH,
        width: 1,
        layer: VOLUME_LAYER_MARK,
      }),
    );
  }
  return out;
}

// ——— сцена ———————————————————————————————————————————————————————————————

/**
 * Вся сцена схемы: грани, препятствия, помещения, границы, где встать.
 *
 * `empty` — объект без чертежа: окно открывается и говорит, что показывать
 * нечего. `notes` — коды того, о чём окно обязано сказать вслух: нет моста к
 * подложке, помещения не обведены, высота не задана.
 *
 * `options.marks` — какие метки ставить (таск 148). Окно отдаёт сюда видимые на
 * плане: фильтр спрятал метку на плане — она не появляется и в объёме, иначе в
 * двух видах одного объекта пришлось бы держать два ответа на вопрос «что
 * показано». Без него берутся все метки схемы.
 *
 * `options.openDoorIds` — какие двери раскрыты (G207). Без него закрыты все, и
 * это умолчание: состояние двери живёт в сеансе окна и в объект не попадает
 * никогда (G68). Поэтому оно и приходит аргументом сборки, а не полем проёма.
 *
 * `options.hiddenObjectIds` — вещи, спрятанные с экрана (таск 154, G223). Той
 * же природы, что раскрытые двери: выбор глаз, живущий в сеансе и в настройках
 * браузера. Спрятанной вещи в сцене нет **совсем** — ни граней, ни
 * препятствия, ни лестницы: сквозь невидимый шкаф человек идёт, не понимая,
 * обо что споткнулся, а лестница, которой не видно, не должна спрашивать про
 * этаж.
 */
export function volumeScene(project, schemeId, options = {}) {
  const scheme = findScheme(project, schemeId);
  if (!scheme) return null;
  const walls = wallsOnScheme(project, schemeId);
  const hidden =
    options.hiddenObjectIds instanceof Set ? options.hiddenObjectIds : new Set(options.hiddenObjectIds || []);
  const objects = schemeObjectsOnScheme(project, schemeId).filter((object) => !hidden.has(object.id));
  const notes = [];
  if (walls.length === 0 && objects.length === 0) {
    // Без чертежа метку ставить не на что: ни стен, ни пола, ни потолка. Это
    // не потеря — объём и так говорит, что показывать нечего.
    return {
      empty: true,
      notes: [],
      faces: [],
      order: null,
      solids: [],
      shadowBoxes: [],
      sunSpots: [],
      landMm: null,
      objectBoxes: [],
      rooms: [],
      boundsMm: null,
      doors: [],
      sheers: [],
      stairs: [],
      marks: [],
      unplaced: [],
      spare: [],
    };
  }
  const rooms = volumeRooms(project, schemeId);
  const schemeHeight = volumeHeightMm(project, schemeId, null);
  if (!schemeHeight.known && !rooms.some((room) => room.heightKnown)) notes.push("noHeight");
  const faces = [];
  const bounds = drawingBoundsMm(project, schemeId);
  // Плита под чертежом — нулевой ярус. Она есть всегда: с обведёнными
  // помещениями закрывает пороги и щели у стен, без них остаётся единственным
  // полом. Потолка в этом случае нет вовсе — накрыть всё одной крышкой значило
  // бы соврать о том, где кончается комната, и отнять обзор со стороны.
  //
  // Цвет у неё зависит от того, **чем она работает** (G237). Помещения обведены
  // — свой пол есть у каждого, и плита остаётся только землёй вокруг дома: тон
  // у неё тот же, что у поля панорамы (`VOLUME_LAND`), и затенение лампой сцены
  // к ней не применяется (`flat`), иначе земля у дома вышла бы вдвое темнее
  // земли за ним. Ровно на этом дом и «летал»: он стоял на тёмно-коричневой
  // доске в габарите чертежа, лежащей посреди зелёного.
  //
  // Помещения не обведены — плита и есть единственный пол, и красится полом:
  // назвать её землёй значило бы сказать, что пола в доме нет.
  //
  // **Плита идёт с выносом** (D43): земля под домом не может кончаться ровно по
  // осям наружных стен — иначе ей не на чем держать тень дома, которая уходит
  // от стены на полторы высоты. Вынос считается от высоты, а не взят на глаз:
  // `VOLUME_LAND_OUT` высот от габарита во все стороны.
  const wallHeights = volumeWallHeights(project, schemeId, schemeHeight.mm);
  const tallest = volumeWallsTopMm(project, schemeId, wallHeights);
  // Прямоугольник плиты, когда она работает землёй (D52): им фон узнаёт, где
  // кончается земля сцены. `null` — плита сама пол, и земли у сцены нет вовсе.
  //
  // `options.upper` — схема показана **этажом стопки, стоящим не на земле**
  // (таск 202). Плиты у такого этажа нет **вовсе** (таск 209, G317): земля у
  // дома одна, под нижним этажом, а перекрытие — это полы его помещений, и
  // второй сплошной плиты по габариту чертежа быть не должно. Именно она
  // раньше затыкала собой дыру двусветного пространства: пол сняли, а плита
  // под ним осталась.
  //
  // Цена названа прямо: где на верхнем этаже помещение **не обведено**, там
  // перекрытия нет и видно насквозь. Это то же правило, что у заказчика в
  // словах — «пол есть во всех замкнутых помещениях», — и другого способа
  // узнать, есть ли там пол, у сборки нет.
  let landMm = null;
  if (bounds && options.upper !== true) {
    const land = rooms.length > 0;
    const shadow = volumeShadowShift(tallest);
    const out = land ? Math.hypot(shadow.x, shadow.y) + VOLUME_LAND_OUT_MM : 0;
    const plate = {
      minX: bounds.minX - out,
      minY: bounds.minY - out,
      maxX: bounds.maxX + out,
      maxY: bounds.maxY + out,
    };
    if (land) landMm = plate;
    faces.push(
      volumeFace(
        volumeClockwise([
          { x: plate.minX, y: plate.minY },
          { x: plate.maxX, y: plate.minY },
          { x: plate.maxX, y: plate.maxY },
          { x: plate.minX, y: plate.maxY },
        ]).map((point) => volumeAt(point, 0)),
        land ? VOLUME_LAND_RGB : VOLUME_FLOOR_RGB,
        { normal: { x: 0, y: 0, z: 1 }, layer: VOLUME_LAYER_BASE, flat: land },
      ),
    );
  }
  // **Тень дома на земле** (дефект D43). Слова заказчика по снимку обзора: «дом
  // всё ещё летает, а не стоит на земле».
  //
  // Разбор числами. Плита и земля сведены в один тон ещё в G237, и сведены
  // верно: замер пикселей живого кадра — `123,160,93` и у самой стены, и в семи
  // метрах от дома, тон в тон. Но ровно поэтому в кадре **не осталось ничего,
  // что говорило бы о поверхности**: плита кончается по осям наружных стен
  // (габарит 9200 × 8700 мм на объекте заказчика), за ней геометрии нет вовсе —
  // поле панорамы рисуется заливкой ниже строки горизонта, а в обзоре (наклон
  // −42°, поле 972 × 778) горизонт стоит на `y = −48` точки, то есть **выше
  // кадра**: вся высота поля залита одним плоским цветом. Ни растяжки, ни
  // затенения (плита `flat`), ни тени — глазу не за что зацепиться, и дом
  // читается наклейкой на зелёном листе.
  //
  // Поэтому в сцену добавлена **тень**: единственная примета касания, которой
  // не было. Кладёт её солнце с неба (`volumeShadowShift`): при его высоте 14°
  // стена 2800 мм даёт тень 11 230 мм, и ложится она ровно прочь от солнца.
  //
  // Тень — это силуэт: выпуклая оболочка габарита стены и того же габарита,
  // сдвинутого на вынос. Рисуется **сплошным** тоном без затенения, поэтому
  // наложение теней соседних стен не темнеет вдвое и дом отбрасывает одно пятно.
  //
  // Кладётся она только на землю — то есть когда помещения обведены и плита
  // работает землёй. Нет обводки — плита сама пол, и тень легла бы внутри дома.
  // Внутри дома её не видно **ярусом** (`VOLUME_LAYER_SHADOW`): полы лежат выше
  // неё по правилу, а не по дальности. На дальность это и было переложено, и
  // отозвалось дефектом D49 — зеленью вместо пола в части комнат.
  //
  // **В сцене лежат габариты, а не грани** (таск 181). Солнце ходит по небу, и
  // тень ходит за ним; пересобирать ради этого весь дом — восемь миллисекунд на
  // объекте заказчика, то есть провал кадра каждую секунду у идущего человека.
  // Поэтому сцена держит то, что от часа не зависит (габарит стены и её
  // высоту), а грани тени собирает `volumeShadowFaces` — вместе со снимком
  // часа, не чаще раза в секунду, и уходят они в кадр теми же `extra`, которыми
  // идут рамка выделения и кружок «вы здесь».
  const shadowBoxes = [];
  if (rooms.length > 0) {
    for (const wall of walls) {
      const vectors = wallVectors(wall);
      if (!vectors) continue;
      const height = wallHeights.get(wall.id) || 0;
      if (!(height > 0)) continue;
      shadowBoxes.push({
        corners: volumeBoxCorners(
          {
            x: Number(wall.aMm.x) + vectors.u.x * (vectors.len / 2),
            y: Number(wall.aMm.y) + vectors.u.y * (vectors.len / 2),
          },
          vectors.u,
          vectors.len,
          Number(wall.thicknessMm),
        ),
        heightMm: height,
      });
    }
  }
  for (const room of rooms) {
    // **Пол помещения — он же перекрытие** (таск 209, G317): одно правило, а не
    // два похожих. Есть пол — есть плита с кромкой, на которой стоит этаж выше;
    // снят — там дыра на два этажа, и край её держат соседние плиты.
    if (room.hasFloor) {
      faces.push(
        // Ярус у пола **телесный** (таск 211): порядок ему считает дерево.
        volumeFace(room.pointsMm.map((point) => volumeAt(point, 0)), VOLUME_FLOOR_RGB, {
          normal: { x: 0, y: 0, z: 1 },
        }),
      );
      volumeSlabFaces(room.pointsMm, 0, faces);
    }
    // **Потолок под дырой двусвета не рисуется** (таск 229, G343): помещение
    // этажом выше без пола — значит перекрытия над этой комнатой нет, и низу
    // плиты, которым её потолок и был, стоять негде. Мерку считает одно место
    // (`volumeCeilingUnderVoid`), доводы ей даёт стопка — как и накрытиям стен.
    if (volumeCeilingUnderVoid(room, options.voids, options.capMm)) continue;
    // **Потолок двусторонний** (таск 211, дефект D62): снизу это потолок
    // комнаты, сверху — крыша. До таска у него была одна сторона, нормалью
    // вниз, и сверху он отбрасывался отбором — поэтому в кадре сверху потолок
    // занимал **ноль процентов**, а человек смотрел прямо в комнату.
    //
    // Почему двусторонняя грань, а не плита с телом, как у пола: плита над
    // каждым помещением встала бы ровно туда, где у этажа выше лежит его
    // собственный пол, — две одинаковые плиты друг в друге, и этажи перестали
    // бы делиться плоскостью (их дерево порядка сшивается по ней, таск 202).
    // Двусторонний потолок не добавляет в сцену **ни одной грани** и держит
    // этажи раздельными: низ перекрытия — это и есть потолок нижнего этажа, а
    // толщину ему даёт плита пола верхнего.
    faces.push(
      volumeFace(
        [...room.pointsMm].reverse().map((point) => volumeAt(point, room.heightMm)),
        VOLUME_CEILING_RGB,
        // **«Снять крышу»** (таск 212, требование G319) — это ровно вторая
        // сторона потолка, и ничего больше. Отметка снята (умолчание) —
        // потолок двусторонний, дом сверху глухой, как с таска 211. Отметка
        // стоит — у потолка остаётся одна сторона, нижняя: изнутри он тот же
        // до грани, а сверху отбор по нормали его не рисует вовсе, и видно
        // планировку. Ни одной грани при этом не прибавляется и не убавляется.
        { normal: { x: 0, y: 0, z: -1 }, both: options.roofOff !== true },
      ),
    );
  }
  if (rooms.length === 0) {
    notes.push(outlinesInOrder(project, schemeId).length > 0 ? "noBridge" : "noRooms");
  }
  const solids = [];
  // Все двери схемы: по этому списку хоткей «все двери» (G210) знает, что
  // открывать, не спрашивая объект второй раз.
  const doors = [];
  // Высоты посчитаны выше, до плиты: по ним идёт вынос земли и тень дома (D43),
  // по ним же сводятся углы (G265) — ус ставится только между стенами одной
  // высоты.
  const miters = volumeWallMiters(walls, (wall) => wallHeights.get(wall.id) || 0);
  for (const wall of walls) {
    // **Накрытые куски стены** (таск 214, дефект D65): там, где у этажа выше
    // стоит его собственная стена, эта уступает ей — накрытый кусок выше
    // перекрытия становится проходом. Считает накрытия стопка (`options.covers`
    // и `options.capMm`): одна схема про соседние этажи не знает ничего, и
    // без стопки этого словаря нет вовсе — тогда всё как было.
    const covers = options.covers instanceof Map ? options.covers.get(wall.id) : null;
    const openings = openingsInWall(project, wall.id);
    for (const opening of openings) {
      // Стеклянная дверь — дверь и здесь (таск 180): её открывают `E`, щелчком
      // и касанием, и `R` открывает её вместе со всеми.
      // Открывается всё, у чего есть полотно (таск 219, G328): распашное,
      // едущее и поднимающееся. До таска список спрашивал «есть ли сторона», и
      // роллетные с секционными в него не попадали — `R` их не трогал, а
      // счётчик «открыто N из M» их не считал.
      if (openingOpens(opening.kind) && opening.id) doors.push(opening.id);
    }
    const own = wallHeights.get(wall.id);
    // **Стена уступает полосе этажа выше** (таск 214, дефект D65). Накрыта
    // верхней стеной — своя строится до потолка своей полосы (`capMm`), а
    // выше стоит стена соседа, в которой и прорезаны его проёмы. Не накрыта —
    // высота своя, как была: простенок двусветной стены честно идёт на всю
    // высоту, и это тот самый случай, который видно на рендерах заказчика.
    const cap = covers && covers.length > 0 ? Math.min(own, Number(options.capMm) || own) : own;
    const height = cap;
    volumeWallFaces(wall, openings, height, faces, options.openDoorIds || null, miters.get(wall.id) || null, rooms);
    const vectors = wallVectors(wall);
    if (!vectors) continue;
    // Куски, которые верхняя стена не накрыла, продолжаются вверх своим телом:
    // проёмов выше перекрытия у них не бывает — чертят их на том плане, где
    // этот кусок стоит.
    if (cap < own) {
      for (const span of volumeWallFree(vectors.len, covers)) {
        const middleMm = (span.fromMm + span.toMm) / 2;
        volumePrismFaces(
          volumeBoxCorners(
            {
              x: Number(wall.aMm.x) + vectors.u.x * middleMm,
              y: Number(wall.aMm.y) + vectors.u.y * middleMm,
            },
            vectors.u,
            span.toMm - span.fromMm,
            Number(wall.thicknessMm),
          ),
          cap,
          own,
          VOLUME_WALL_RGB,
          faces,
        );
      }
    }
    // **Пол под стеной** (дефект D37). Слова заказчика: «под дверными проёмами
    // нет пола».
    //
    // Пол лежит по контурам помещений, то есть кончается у внутренней грани
    // стены. Под самой стеной пола нет никогда, а **проём — это дыра в стене на
    // всю её толщину**, и порога в нём не было тоже. Раньше дыры затыкала плита
    // чертежа, крашенная полом; с тех пор как плита стала землёй (G237), каждая
    // щель читается травой в доме.
    //
    // Поэтому пол кладётся полосой **под всю стену: во всю длину и во всю
    // толщину, поверх проёмов**. Это и есть ответ на порог: он получается сам,
    // одной гранью на стену, и не требует ни разбора проёмов, ни объединения
    // контуров. Снаружи полоса не видна — её ровно накрывает сама стена.
    //
    // `VOLUME_FLOOR_LAP` — напуск по обе стороны: контур помещения обводят по
    // подложке рукой, и промахнуться на сантиметр-другой мимо грани стены
    // обычное дело. Напуск маленький нарочно: пять сантиметров прячутся под
    // стеной и в углах, а сделай его больше — пол полез бы кантом наружу.
    //
    // Нужна полоса только там, где плита стала землёй: без обведённых помещений
    // плита сама пол, и подкладывать под стену нечего.
    if (rooms.length > 0) {
      const middleMm = vectors.len / 2;
      const strip = volumeBoxCorners(
        {
          x: Number(wall.aMm.x) + vectors.u.x * middleMm,
          y: Number(wall.aMm.y) + vectors.u.y * middleMm,
        },
        vectors.u,
        vectors.len + VOLUME_FLOOR_LAP * 2,
        Number(wall.thicknessMm) + VOLUME_FLOOR_LAP * 2,
      );
      faces.push(
        volumeFace(strip.map((point) => volumeAt(point, 0)), VOLUME_FLOOR_RGB, {
          normal: { x: 0, y: 0, z: 1 },
        }),
      );
      // Тело у полосы — такое же, как у пола комнаты (таск 209): иначе
      // перекрытие кончалось бы у контура помещения, а под стеной верхнего
      // этажа на фасаде оставалась бы щель ровно в толщину плиты.
      volumeSlabFaces(strip, 0, faces);
    }
    // Сплошные участки стены — во всю её высоту; низкая перемычка над проёмом
    // (G234) — своим куском от верха проёма до верха стены. У препятствия
    // появились высоты: по ним присевший проходит там, где стоящий не проходит.
    const spans = [
      ...volumeWallSolids(wall, openings).map((span) => ({ ...span, bottomMm: 0, topMm: height })),
      ...volumeWallLintels(openings, height),
    ];
    for (const span of spans) {
      const middle = (span.fromMm + span.toMm) / 2;
      solids.push({
        cx: Number(wall.aMm.x) + vectors.u.x * middle,
        cy: Number(wall.aMm.y) + vectors.u.y * middle,
        ux: vectors.u.x,
        uy: vectors.u.y,
        nx: vectors.n.x,
        ny: vectors.n.y,
        half: (span.toMm - span.fromMm) / 2,
        halfT: Number(wall.thicknessMm) / 2,
        bottomMm: span.bottomMm,
        topMm: span.topMm,
      });
    }
  }
  // Габариты вещей: **не препятствия** (G264), а места, которые заняты.
  // Разница — в следующем абзаце.
  const objectBoxes = [];
  for (const object of objects) {
    // Рисуется модель или габарит — решает одно место (`volumeObjectFaces`).
    //
    // **Сквозь вещи проходят** (G264, таск 178). Слова заказчика: «Сделай что
    // бы объекты можно было проходить на сквозь, убери коллизию». Было
    // наоборот: габарит вещи держал человека, и это было задумано — «пройти
    // между ножек стола так же неверно, как пройти сквозь шкаф».
    //
    // Отменено это не капризом, а тем, ради чего объём и открывают: в нём
    // смотрят метки. Метка за диваном, розетка в тумбе, щит, к которому не
    // подойти вплотную, — каждая вещь отнимала у человека подход к своим же
    // точкам, а обойти её в квартире часто негде. С таска 169 вещи ещё и
    // просвечивают: смотреть сквозь шкаф можно, а подойти нельзя — это разные
    // правила об одном и том же, и заказчик свёл их в одно.
    //
    // **Стены остались**: сквозь них нельзя, это правило таска 146 и его никто
    // не отменял. Вещь — мебель, её двигают; стена — дом.
    //
    // **Лестница и колонна проходятся тоже.** Они вещи каталога и исключением
    // не стали: список исключений завёл бы второго хозяина правила (тот же
    // довод, что у прозрачности в таске 169), а «конструкция» — это не признак
    // данных, а догадка о замысле. Цена названа прямо: сквозь колонну и короб
    // проходят насквозь, а в лестницу входят внутрь марша. Переход по этажам от
    // этого не пострадал — он спрашивается по расстоянию до габарита
    // (`volumeStairNear`), а не по упору в него, и теперь срабатывает ещё
    // вернее: встать можно прямо на лестницу.
    volumeObjectFaces(project, schemeId, object, schemeHeight.mm, faces);
    for (const prism of volumeObjectPrisms(project, schemeId, object, schemeHeight.mm)) {
      if (!volumePrismBlocks(prism)) continue;
      const solid = volumePrismSolid(prism);
      // Габарит остаётся в сцене, но не в `solids`: по нему выбирается место,
      // с которого начинают ходить (`volumeStart`) — вставать внутрь дивана
      // незачем и без столкновений.
      if (solid) objectBoxes.push(solid);
    }
  }
  // Метки — последними: их тела и контуры ложатся в тот же поток граней, что
  // стены и вещи чертежа, и спорят с ними порядком, а не ярусом. Вещь на стене
  // стоит перед стеной — это и значит «перед»; препятствием она при этом не
  // становится (сквозь розетку ходят).
  const marks = volumeMarks(project, schemeId, { marks: options.marks, rooms });
  for (const place of marks.placed) {
    volumeMarkFaces(place, faces);
    volumeMarkViewLines(place, faces);
  }
  // `wallCount` — настоящее число стен чертежа, а не длина `solids`: препятствий
  // больше, потому что проём режет стену на куски, а вещи на полу тоже держат.
  // Окно говорит о чертеже, и путать эти два числа нельзя.
  return {
    empty: false,
    notes,
    faces,
    // Дерево порядка строится здесь, один раз на сцену: кадру остаётся обход.
    //
    // `options.order === false` — сцену собирают **этажом стопки** (таск 202):
    // грани ещё поднимут на базу этажа, и дерево, построенное до подъёма, стало
    // бы врать. Стопка строит его сама, после подъёма, и сшивает этажи
    // плоскостью (`volumeOrderStack`). Полусобранная сцена без дерева годится
    // только ей: кадру её отдавать нельзя.
    order: options.order === false ? null : volumeOrderTree(faces),
    solids,
    // Габариты стен для тени дома (таск 181): час кладёт её сам, см. выше.
    shadowBoxes,
    // Проёмы, через которые солнце кладёт пятно на пол (таск 196). В сцене
    // лежит то, что от часа не зависит — геометрия проёма, комнаты по обе его
    // стороны и штора перед ним; грани кладёт час (`volumeSunSpotFaces`), тем
    // же порядком, что тень дома.
    sunSpots: volumeSunOpenings(project, schemeId, rooms, marks.placed, (wall) => wallHeights.get(wall.id) || 0, {
      openCurtainIds: options.openCurtainIds || null,
      openDoorIds: options.openDoorIds || null,
    }),
    // Шторы схемы (G332): по этому списку окно знает, что можно открыть, и
    // считает «открыто N из M». Тот же отбор, которым свет берёт ткань перед
    // проёмом, — `volumeSheerPlaces`, второго в сборке нет.
    sheers: volumeSheerPlaces(marks.placed).map((place) => place.markId),
    // Земляная плита: её прямоугольник в миллиметрах чертежа — `null`, когда
    // плита работает полом, а не землёй. По нему фон знает, где кончается земля
    // сцены (D52, `volumeGroundLimitDeg`), и второй мерки для этого нет.
    landMm,
    // Занятые места: габариты вещей, которые человека **не держат** (G264), но
    // по которым видно, где в комнате пусто. Ими пользуется только выбор места
    // старта; ходьба, перенос и «тесно» спрашивают `solids`.
    objectBoxes,
    rooms,
    boundsMm: bounds,
    // На сколько нарисованное выходит за габарит чертежа: стена стоит на всю
    // толщину от своей оси, а пол под ней — ещё и с напуском (D37). Обзор
    // «вся схема» вмещает то, что **рисуется**, и без этого числа он резал бы
    // угол у толстых стен — впритык он стоял и до напуска.
    outsetMm: walls.reduce(
      (most, wall) => Math.max(most, Number(wall.thicknessMm) / 2 + (rooms.length > 0 ? VOLUME_FLOOR_LAP : 0)),
      0,
    ),
    heightMm: schemeHeight.mm,
    wallCount: walls.length,
    openingCount: walls.reduce((sum, wall) => sum + openingsInWall(project, wall.id).length, 0),
    doors,
    // Лестницы схемы (таск 149): по ним окно спрашивает про этаж. Лежат в
    // сцене, а не ищутся на каждом шаге, — спрашивается это на каждом шаге, а
    // меняется только вместе с чертежом, то есть вместе со всей сценой.
    stairs: volumeStairs(project, schemeId).filter((stair) => !hidden.has(stair.objectId)),
    marks: marks.placed,
    unplaced: marks.unplaced,
    // Нарисованные запасным габаритом (G215): вещь в сцене есть, а размер её
    // сборка выдумала — окно называет такие вещи вслух.
    spare: marks.spare,
  };
}

/**
 * Какую дверь показывают (G207): ищется по полотну и ручке, сверху вниз — тем
 * же порядком, которым рисовался кадр, только с конца. Запас промаха тот же,
 * что у вещей: полотно в три метра занимает полкадра, а ручка — пару точек, и
 * требовать попадания в саму дверь на другом конце коридора незачем.
 */
export function volumeDoorAt(polygons, x, y, slack = VOLUME_PICK_SLACK_PX) {
  let near = null;
  let gap = slack;
  for (let index = polygons.length - 1; index >= 0; index -= 1) {
    const polygon = polygons[index];
    if (!polygon.door || polygon.stroke) continue;
    if (volumePolygonHit(polygon.xy, x, y)) return polygon.door;
    const centre = volumePolygonCentre(polygon.xy);
    const distance = Math.hypot(centre.x - x, centre.y - y);
    if (distance < gap) {
      gap = distance;
      near = polygon.door;
    }
  }
  return near;
}

/** Где в объёме стоит метка — по её месту в сцене. `null` — не размещена. */
export function volumeMarkAnchor(scene, markId) {
  for (const place of (scene && scene.marks) || []) {
    if (place.markId === markId) return place.anchor;
  }
  return null;
}

/** Размещение метки в сцене по её идентификатору. */
export function volumeMarkPlace(scene, markId) {
  for (const place of (scene && scene.marks) || []) {
    if (place.markId === markId) return place;
  }
  return null;
}

// ——— где встать ——————————————————————————————————————————————————————————

/** Расстояние от точки до препятствия (отрицательное — внутри). */
function volumeGap(solid, x, y) {
  const dx = x - solid.cx;
  const dy = y - solid.cy;
  const along = Math.abs(dx * solid.ux + dy * solid.uy) - solid.half;
  const across = Math.abs(dx * solid.nx + dy * solid.ny) - solid.halfT;
  if (along <= 0 && across <= 0) return Math.max(along, across);
  return Math.hypot(Math.max(along, 0), Math.max(across, 0));
}

/**
 * Держит ли препятствие человека, у которого макушка на `headMm` (G234).
 *
 * Правило то же, что у вещи чертежа (`volumePrismBlocks`), только спрашивается
 * оно не при сборке сцены, а на каждом шаге: присев, человек проходит под тем,
 * что выше его макушки, — и это единственный способ сделать так, чтобы
 * «проходить там, где низко» и «сквозь стены нельзя» были одним счётом, а не
 * двумя.
 *
 * Препятствие без высот (такие строит рука в тестах) держит всегда: `topMm`
 * без значения — это «до потолка», и молча пропускать сквозь него нельзя.
 *
 * **Ноги у спрашивающего всегда на полу**, и других тел тут не бывает. Высота
 * ног была доводом в таске 192, пока летал сам человек; с таска 200 (G304)
 * полёт ушёл в обзор, а камера обзора проходит сквозь стены **всегда** и этого
 * счёта не спрашивает вовсе. Поэтому порог отсчитывается от пола, как до 192.
 */
export function volumeSolidBlocks(solid, headMm = VOLUME_HEAD_MM) {
  const bottom = Number(solid.bottomMm) || 0;
  const top = solid.topMm === undefined || solid.topMm === null ? Infinity : Number(solid.topMm);
  return bottom < headMm && top > VOLUME_STEP_MM;
}

/** Сколько свободного места вокруг точки для человека с макушкой на `headMm`. */
export function volumeFreeMm(solids, x, y, headMm = VOLUME_HEAD_MM) {
  let free = Infinity;
  for (const solid of solids) {
    if (!volumeSolidBlocks(solid, headMm)) continue;
    free = Math.min(free, volumeGap(solid, x, y));
  }
  return free;
}

/**
 * Можно ли здесь встать (G234).
 *
 * Заказчик назвал случай прямо: человек отпустил Control под потолком в
 * 1200 мм. Ответ — **он не встаёт и остаётся присевшим**: протолкнуть макушку
 * сквозь низ шкафа значило бы пустить человека сквозь вещь, а вытолкнуть его в
 * сторону — переставить его туда, куда он не шёл. Он встанет сам, как только
 * выйдет из-под низкого места; окно говорит об этом словом.
 *
 * Считается **только по тем препятствиям, которые мешают именно вставанию**:
 * которые держат стоя и не держат сейчас. Стену, которая держит в любой стойке,
 * спрашивать нельзя не ради скорости: прижатый к ней человек стоит ровно в
 * `VOLUME_BODY_MM` от её грани, и сравнение «на волос ближе или на волос
 * дальше» в double запрещало бы ему вставать у стенки через раз.
 *
 * `options.ghost` — отметка «Проходить сквозь стены» (таск 192, G292): встать
 * можно везде. «Встать негде» — это и есть столкновение с тем, что над головой,
 * и снявший столкновения человек не должен застревать в приседе под вещью,
 * сквозь которую он только что прошёл.
 */
export function volumeCanStand(scene, at, headMm = VOLUME_HEAD_MM, options = {}) {
  if (options.ghost) return true;
  for (const solid of (scene && scene.solids) || []) {
    if (volumeSolidBlocks(solid, headMm)) continue;
    if (!volumeSolidBlocks(solid, VOLUME_HEAD_MM)) continue;
    if (volumeGap(solid, at.x, at.y) < VOLUME_BODY_MM) return false;
  }
  return true;
}

/**
 * Откуда начинать ходить: самое просторное место самой большой комнаты.
 *
 * Серединой контура ограничиться нельзя — у Г-образной кухни она лежит в
 * вырезе, то есть внутри стены. Поэтому по габариту контура идёт сетка проб, и
 * из точек внутри контура берётся та, вокруг которой больше всего места.
 * Взгляд направляется на дальнюю вершину: человек, открывший окно, должен
 * увидеть комнату, а не упереться в ближний угол.
 */
export function volumeStart(scene) {
  // В помещение без пола не встают (таск 209): это дыра на два этажа, и
  // открывать окно, стоя в воздухе над нижним этажом, незачем.
  const rooms = [...(scene.rooms || [])]
    .filter((room) => room.hasFloor !== false)
    .sort((a, b) => volumeArea(b.pointsMm) - volumeArea(a.pointsMm));
  const solids = scene.solids || [];
  // Место выбирается **и по вещам** (G264): сквозь них теперь проходят, но
  // открывать окно с камерой внутри дивана незачем — просторным считается то,
  // где нет ни стены, ни мебели. Выталкивает же человека по-прежнему только
  // стена: вещь не препятствие, и толкаться ей нечем.
  const roomy = [...solids, ...(scene.objectBoxes || [])];
  const candidates = [];
  for (const room of rooms.slice(0, 1)) {
    const xs = room.pointsMm.map((point) => point.x);
    const ys = room.pointsMm.map((point) => point.y);
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
    const steps = 6;
    for (let ix = 1; ix < steps; ix += 1) {
      for (let iy = 1; iy < steps; iy += 1) {
        const point = { x: minX + ((maxX - minX) * ix) / steps, y: minY + ((maxY - minY) * iy) / steps };
        if (!volumePointInside(point, room.pointsMm)) continue;
        candidates.push({ point, room, free: volumeFreeMm(roomy, point.x, point.y) });
      }
    }
  }
  if (candidates.length === 0) {
    const bounds = scene.boundsMm;
    const point = bounds
      ? { x: (bounds.minX + bounds.maxX) / 2, y: (bounds.minY + bounds.maxY) / 2 }
      : { x: 0, y: 0 };
    const pushed = volumePush(solids, point, VOLUME_BODY_MM);
    return { x: pushed.x, y: pushed.y, yaw: 0 };
  }
  candidates.sort((a, b) => b.free - a.free);
  const best = candidates[0];
  const pushed = volumePush(solids, best.point, VOLUME_BODY_MM);
  let far = best.room.pointsMm[0];
  let distance = -1;
  for (const point of best.room.pointsMm) {
    const length = Math.hypot(point.x - pushed.x, point.y - pushed.y);
    if (length > distance) {
      distance = length;
      far = point;
    }
  }
  return { x: pushed.x, y: pushed.y, yaw: Math.atan2(far.y - pushed.y, far.x - pushed.x) };
}

/**
 * Насколько глубоко тело радиуса `radius` сидит в препятствиях: ноль — не сидит
 * вовсе. Мерка та же, по которой выталкивает `volumePush`, и это не удобство, а
 * условие: шаг сверяет «стало ли хуже» ровно с тем, что выталкивание умеет
 * разобрать, — разойдись они, и человек то застревал бы на ровном месте, то
 * проваливался бы в стену.
 */
export function volumeDepthMm(solids, x, y, radius = VOLUME_BODY_MM, headMm = VOLUME_HEAD_MM) {
  let deep = 0;
  for (const solid of solids || []) {
    if (!volumeSolidBlocks(solid, headMm)) continue;
    const dx = x - solid.cx;
    const dy = y - solid.cy;
    const overAlong = solid.half + radius - Math.abs(dx * solid.ux + dy * solid.uy);
    const overAcross = solid.halfT + radius - Math.abs(dx * solid.nx + dy * solid.ny);
    if (overAlong <= 0 || overAcross <= 0) continue;
    deep = Math.max(deep, Math.min(overAlong, overAcross));
  }
  return deep;
}

/**
 * Выталкивание тела из стен. Круг против повёрнутого прямоугольника: из каждого
 * препятствия уходим по той оси, по которой пересечение меньше, — так тело
 * скользит вдоль стены, а не останавливается, уткнувшись.
 *
 * ——— дефект D39: «застревает и начинает прыгать» ——————————————————————————
 *
 * Слова заказчика: «когда ходишь иногда где-то застревает и начинает прыгать,
 * хотя жму движение на клавиатуре». Прыгала не стойка — прыгало **место**.
 *
 * Прежде проходы шли по препятствиям **по очереди**, и каждое двигало тело
 * сразу: последнее слово оставалось за последним в списке. Там, где два
 * препятствия требуют разного, это не сходится никогда, а **чередуется**, и
 * чередуется с частотой кадров. Замер на объекте заказчика (25 стен, 8
 * помещений, сетка проб 50 мм — 32 375 точек):
 *
 *   - **402 точки (1,2 %)**, где четыре прохода не разводят тело **одними
 *     стенами**; с вещами их было 666 (2,1 %) — то есть уборка столкновений у
 *     вещей (G264) убрала треть случаев и не вылечила ни одного;
 *   - разбор одной такой точки: две параллельные стены по 100 мм, оси в 350 мм
 *     друг от друга — просвет между гранями **250 мм** против диаметра тела
 *     **440 мм**. Нижняя стена толкает на +190 мм, верхняя тут же на −190 мм,
 *     и так каждый кадр: человек стоит на месте и дёргается на 190 мм шестьдесят
 *     раз в секунду. Повтори выталкивание хоть двадцать пять раз — остаток тот
 *     же 190: это не «мало проходов», это цикл длиной два;
 *   - второй разбор — стена против габарита вещи: 218 мм, тот же цикл.
 *
 * Чинится это двумя правилами, и оба здесь:
 *
 *   1. **Проход считает все препятствия разом и складывает их требования**
 *      (сумма векторов), а потом двигает тело один раз. Порядок препятствий
 *      перестал решать что-либо: в углу две стены дают диагональ и расходятся
 *      за проход, а в тесном месте их требования гасят друг друга в ноль — и
 *      тело **стоит ровно**, вместо того чтобы прыгать между двумя положениями.
 *   2. **Шаг не принимает положение хуже прежнего** (`volumeStep`): если после
 *      выталкивания тело сидит глубже, чем стояло, шаг не делается вовсе.
 *
 * Угол при этом держится так же, как держался: четыре прохода остались.
 */
export function volumePush(solids, at, radius, headMm = VOLUME_HEAD_MM) {
  let x = at.x;
  let y = at.y;
  for (let pass = 0; pass < VOLUME_PUSH_PASSES; pass += 1) {
    let sx = 0;
    let sy = 0;
    let pressed = false;
    for (const solid of solids) {
      // Присевший проходит под высоким (G234): препятствие, которое кончается
      // ниже его макушки, тела не касается вовсе.
      if (!volumeSolidBlocks(solid, headMm)) continue;
      const dx = x - solid.cx;
      const dy = y - solid.cy;
      const along = dx * solid.ux + dy * solid.uy;
      const across = dx * solid.nx + dy * solid.ny;
      const overAlong = solid.half + radius - Math.abs(along);
      const overAcross = solid.halfT + radius - Math.abs(across);
      if (overAlong <= 0 || overAcross <= 0) continue;
      pressed = true;
      if (overAcross <= overAlong) {
        const sign = across >= 0 ? 1 : -1;
        sx += solid.nx * sign * overAcross;
        sy += solid.ny * sign * overAcross;
      } else {
        const sign = along >= 0 ? 1 : -1;
        sx += solid.ux * sign * overAlong;
        sy += solid.uy * sign * overAlong;
      }
    }
    if (!pressed) break;
    // Требования погасили друг друга: место теснее тела, и уходить отсюда
    // некуда. Стоим — это и есть лекарство от дрожи.
    if (Math.abs(sx) < VOLUME_PUSH_EPS_MM && Math.abs(sy) < VOLUME_PUSH_EPS_MM) break;
    x += sx;
    y += sy;
  }
  return { x, y };
}

/**
 * Шаг с проверкой стен: сдвинулись, потом вытолкнулись.
 *
 * Шаг дробится на куски не длиннее радиуса тела — и это не предосторожность, а
 * необходимость. Выталкивание разбирает **перекрытие**, а не путь: прыгни
 * человек разом дальше, чем толщина перегородки плюс два радиуса, и он
 * окажется по ту сторону, ничего не задев. На бегу (4,8 м/с) кадр длиной в
 * десятую долю секунды — это 480 мм, а перегородка бывает в 50 мм: без дробления
 * сквозь неё проходили бы при любом подвисании вкладки.
 *
 * ——— отметка «Проходить сквозь стены» (таск 192, G292) ———————————————————
 *
 * `options.ghost` — шаг идёт **ровно туда, куда просили**, без дробления и
 * выталкивания. Это и есть вся отмена столкновений, и живёт она здесь, в
 * единственном месте, которое знает, где человек пройдёт; заведи её в поле — и
 * в сборке стало бы два ответа на «куда шагнул».
 *
 * Высоты ног у шага больше нет (таск 200, G304): летал по этому счёту человек,
 * а полёт уехал в обзор, где стены не спрашивают вовсе.
 */
export function volumeStep(scene, at, dx, dy, headMm = VOLUME_HEAD_MM, options = {}) {
  if (options.ghost) return { x: at.x + dx, y: at.y + dy };
  const solids = scene.solids || [];
  const length = Math.hypot(dx, dy);
  const parts = Math.max(1, Math.ceil(length / VOLUME_BODY_MM));
  let point = { x: at.x, y: at.y };
  // Насколько глубоко человек сидит в препятствиях **сейчас**. Обычно ноль;
  // не ноль бывает после переноса кликом, перехода по этажам и правки чертежа
  // под ногами — и тогда выход из этого места тоже должен быть возможен.
  let depth = volumeDepthMm(solids, point.x, point.y, VOLUME_BODY_MM, headMm);
  for (let index = 0; index < parts; index += 1) {
    const want = volumePush(
      solids,
      { x: point.x + dx / parts, y: point.y + dy / parts },
      VOLUME_BODY_MM,
      headMm,
    );
    const deep = volumeDepthMm(solids, want.x, want.y, VOLUME_BODY_MM, headMm);
    // **Хуже не становится** (D39). Выталкивание разобрало не всё — значит
    // место теснее тела, и шаг туда не делается вовсе: человек остаётся там,
    // где стоял, вместо того чтобы дрожать между двумя положениями.
    if (deep > depth + VOLUME_PUSH_EPS_MM) break;
    // **Стало свободнее — идём не глядя.** Это выход из тесного места, куда
    // человека могло занести переносом или правкой чертежа: единственное
    // правило там — «лишь бы наружу».
    if (deep > depth - VOLUME_PUSH_EPS_MM) {
      // **Назад от нажатой клавиши не пятимся** (D39, второе правило). Клин из
      // двух стен умеет вытолкнуть тело дальше, чем был шаг, — и тогда человек
      // скачет между двумя местами, нажимая «вперёд». Скольжение вдоль стены
      // это правило не трогает: там ход поперёк, а не назад.
      const went = (want.x - point.x) * dx + (want.y - point.y) * dy;
      if (went < -VOLUME_PUSH_EPS_MM * length) break;
    }
    point = want;
    depth = deep;
  }
  return point;
}

// ——— стойка (G234, таск 159) ————————————————————————————————————————————
//
// Присед и прыжок — **чистый счёт**, вынесенный сюда целиком: это одна третья
// координата человека, и в обработчике клавиши её не проверить ничем. Поле
// зовёт отсюда четыре функции и не считает сам ни миллиметра.
//
// Стойка — `{crouchMm, liftMm, speedMm}`: насколько присел, насколько оторвался
// от пола и с какой скоростью идёт вверх. В объект из этого не попадает ничего
// (G68) — она живёт в сеансе поверхности, как открытые двери.
//
// **Полёт отсюда ушёл** (таск 200, G304). Таск 192 клал его в ту же `liftMm`,
// и правильно клал: у человека одна третья координата. Но заказчик увидел, что
// летящий сквозь стены человек — это и есть обзор («вид от первого лица при
// включённом полёте и проходить сквозь стены это по факту обзорный вид»), и
// отметку «Летать» убрал. От первого лица осталось то, что было до 192: пробел
// — прыжок, Control — присед. Высота камеры обзора — **её собственная** `z`
// (`around.eye` в поле): она была у обзора всегда, и второго счёта высоты
// таким переездом не завелось — счётов по-прежнему по одному на каждое тело.

/** Стойка, с которой встают на пол: в полный рост и на земле. */
export function volumeStanceStart() {
  return { crouchMm: 0, liftMm: 0, speedMm: 0 };
}

/** Высота глаз в этой стойке: присед опускает, прыжок поднимает. */
export function volumeStanceEye(stance) {
  return VOLUME_EYE_MM - stance.crouchMm + stance.liftMm;
}

/**
 * Макушка в этой стойке — она и решает, где человек пройдёт.
 *
 * **Прыжок макушку не поднимает**, и это решение, а не недосмотр: стоять на
 * вещах в объёме нельзя (пола над полом в сцене нет), и пусти прыжок сквозь
 * низкое препятствие — человек приземлился бы внутри шкафа. Прыжок поднимает
 * глаза, то есть позволяет заглянуть за перегородку; проходимость он не
 * меняет — «сквозь стены нельзя, прыгнув тоже».
 */
export function volumeStanceHead(stance) {
  return VOLUME_HEAD_MM - stance.crouchMm;
}

/**
 * Пол держит — ниже своего пола не опускается никто (G234, G292, G304).
 *
 * Правило **одно на человека и на камеру обзора**, и названо оно здесь затем,
 * чтобы второго не завелось: там, где под полом ничего не нарисовано — ни
 * комнаты, ни земли, одна изнанка плиты, — провалившийся видел бы серое поле
 * вместо объекта. Прыжок таска 159 приземляется по нему, полёт обзора (таск
 * 200) им же останавливается у земли, падение в дыру двусвета (таск 229) им же
 * кончается на полу нижнего этажа.
 *
 * **«Ниже нуля» стало «ниже своего пола»** ровно затем, чтобы падение не
 * завело второго счёта: ноль — это пол того этажа, на котором человек
 * числится, и шагнувшему в дыру полом становится этаж ниже. Разбор — у
 * `volumeFallTo`.
 */
export function volumeGroundMm(mm, floorMm = 0) {
  // `floorMm` — где лежит пол **сцены**: ноль у одной схемы, низ стопки этажей
  // (таск 202), когда камера обходит дом снаружи, и пол **нижнего этажа** у
  // человека, который шагнул в дыру двусвета (таск 229, G342). Умолчание
  // оставляет прежнее правило до знака.
  return Math.max(Number(floorMm) || 0, Number(mm) || 0);
}

// ——— падение в дыру (таск 229, требование G342) ——————————————————————————
//
// Слово заказчика: «Пусть падаем». До таска человек шёл над снятым полом по
// воздуху, и об этом говорила строка.
//
// **Второго правила пола не завелось.** Пол по-прежнему держит на нуле
// (`volumeGroundMm`) — меняется только то, **где для этого человека ноль**:
// шагнул в дыру, и его полом стал пол этажа ниже, то есть `baseMm` того этажа
// в стопке (величина отрицательная). Дальше всё делает прежняя дуга: стойка
// видит, что человек выше своего пола, и роняет его тем же земным ускорением,
// которым приземляется прыжок (таск 159). Прыгнуть в падении нельзя — тот же
// счёт «в воздухе» запрещает и это.
//
// **Смена этажа — в миг приземления**, посреди шага. Пока человек летит, он
// считается по миллиметрам прежнего этажа: сцена стопки рисует все этажи разом
// (таск 202), и падающий видит нижнюю комнату до того, как в неё попадёт.
// Коснулся её пола — этаж под ним меняется: открывается схема нижнего этажа,
// стойка встаёт на её ноль (`volumeStanceOnFloor`), а глаза при этом не
// дёргаются ни на миллиметр, потому что разница баз и есть та высота, которую
// он пролетел. Столкновения всю дорогу считаются по тому этажу, на котором он
// числится, — второго правила «где можно стоять» не заводится, а на новом
// этаже человека выталкивает из стен то же `volumeMoveTo`, которым он выходит
// с лестницы.
//
// **Падать можно только туда, что нарисовано.** Под дырой нет этажа (двусвет
// на нижнем этаже) или этажи не показаны разом — остаётся прежнее поведение:
// человек идёт над дырой, и окно говорит об этом словом. Довод тот же, которым
// пол держит камеру обзора: под полом не нарисовано ничего, и провалившийся
// туда видел бы серое поле вместо объекта.

/**
 * На какой этаж падает человек из точки `at` — или `null`, если не падает.
 *
 * `plan` — план стопки (`volumeFloorPlan`): в нём у каждого этажа своя база и
 * своё смещение в общем плане дома. Ищется **ближайший этаж снизу, у которого
 * под этой точкой есть пол**: снятый пол дырой считается и здесь, поэтому
 * двусвет на два этажа роняет человека одной дугой, а не двумя.
 *
 * **Нижний этаж держит всегда**: под ним земля — плита чертежа, — и падать
 * сквозь его дыру некуда. Это и есть разбор случая «под дырой нет этажа»:
 * `null`, и всё остаётся как было.
 *
 * Точка переводится в координаты того этажа разницей смещений — тем же швом
 * привязки схем (таск 205), которым стопка совмещает этажи; второго счёта
 * совмещения здесь не заводится.
 */
export function volumeFallTo(project, plan, at) {
  const floors = (plan && plan.floors) || [];
  const mineAt = floors.findIndex((item) => item.current);
  if (mineAt < 1 || !at) return null;
  for (let below = mineAt - 1; below >= 0; below -= 1) {
    const item = floors[below];
    const point = { x: at.x - item.shiftMm.x, y: at.y - item.shiftMm.y };
    const room = volumeRooms(project, item.schemeId).find((found) =>
      volumePointInside(point, found.pointsMm),
    );
    // Пол под точкой есть — падаем на него. Комнаты там не обведено вовсе —
    // летим дальше вниз: пола в сцене там нет ни одной грани.
    if (below === 0 || (room && room.hasFloor !== false)) return item;
  }
  return null;
}

/**
 * В воздухе ли человек: прыжок идёт, пока он не вернулся на пол, — а над дырой
 * двусвета его пол лежит ниже нуля (таск 229, G342), и стоящий над ней в
 * воздухе с первого же тика.
 *
 * Скорость считается **любая, а не только вверх**: падающий из дыры идёт вниз,
 * и «скорость есть — значит в воздухе» — то же самое правило, только без
 * знака.
 */
export function volumeStanceAir(stance, floorMm = 0) {
  return stance.liftMm > (Number(floorMm) || 0) || stance.speedMm !== 0;
}

/** Падает ли человек: он уже ниже пола своего этажа (таск 229, G342). */
export function volumeStanceFalling(stance) {
  return stance.liftMm < 0;
}

/**
 * Кончилось ли падение — человек встал на тот пол, который ему считали
 * (таск 229, G342). Спрашивается у отрицательного пола: на своём этаже это
 * «стоит на полу» и значит оно там то же самое.
 */
export function volumeStanceLanded(stance, floorMm) {
  return stance.liftMm <= (Number(floorMm) || 0) && stance.speedMm === 0;
}

/**
 * Стойка на полу нового этажа (таск 229, G342): ноль переехал вместе с
 * человеком, и высоты у него больше нет — он стоит.
 *
 * Присед не трогается: приседая, падают тоже, и вставать за человека здесь
 * никто не должен.
 */
export function volumeStanceOnFloor(stance) {
  return { ...stance, liftMm: 0, speedMm: 0 };
}

/**
 * Нужен ли стойке ещё один тик. Часы в объёме идут, только пока их держат
 * (клавиша, палец на площадке), и прыжок с приседом — третий повод: иначе
 * прыжок замер бы в воздухе у того, кто прыгнул, не идя.
 *
 * Присед, которому **не дали встать**, поводом не считается: он уже стоит на
 * своих 550 мм, и ждать от него нечего — встанет он на том же тике, которым
 * выйдет из-под низкого места.
 */
export function volumeStanceBusy(stance, crouch, floorMm) {
  // Падение — такой же повод, как прыжок: пол под человеком лежит ниже нуля,
  // и часы обязаны идти, пока он не долетит (таск 229, G342).
  if (volumeStanceAir(stance, floorMm)) return true;
  return stance.crouchMm !== (crouch ? VOLUME_CROUCH_MM : 0);
}

/**
 * Прыжок (G234). Разовый: пока человек в воздухе, второго не бывает.
 *
 * **Присев, не прыгают.** Это не придирка к игровым привычкам: присед —
 * единственный способ оказаться там, где над головой низко, и прыжок оттуда
 * ударил бы макушкой в то, под что человек только что пролез.
 */
export function volumeStanceJump(stance, floorMm) {
  // **В падении не прыгают** — и это тот же счёт «в воздухе», а не новый
  // запрет: над дырой двусвета пол лежит ниже нуля, и человек там в воздухе
  // с первого тика (таск 229, G342).
  if (stance.crouchMm > 0 || volumeStanceAir(stance, floorMm)) return stance;
  return { ...stance, speedMm: VOLUME_JUMP_MM_S };
}


/**
 * Шаг стойки за `seconds` секунд: присед едет к цели, прыжок летит по дуге.
 *
 * `crouch` — держат ли Control (или человек застрял под низким и ещё не
 * встал), `canStand` — есть ли над ним место, чтобы выпрямиться. Отказ в
 * подъёме честный: присед **остаётся**, стойка не меняется ни на миллиметр, и
 * сквозь низ шкафа никто не проходит.
 *
 * Полёта здесь больше нет (таск 200, G304): отметку «Летать» заказчик убрал,
 * и `liftMm` значит одно — **отрыв от пола**: вверх его даёт прыжок, вниз —
 * дыра двусвета, в которую человек падает (таск 229, G342). Дуга у них одна,
 * и число у неё одно — `VOLUME_FALL_MM_S2`. Пол, который `liftMm` держит,
 * назван отдельно (`volumeGroundMm`) и зовётся теперь с трёх сторон: отсюда,
 * из полёта камеры обзора и из падения.
 */
export function volumeStanceStep(stance, seconds, options = {}) {
  const span = Math.max(0, Number(seconds) || 0);
  const crouch = Boolean(options.crouch);
  const canStand = options.canStand !== false;
  // `floorMm` — где для этого человека пол: ноль своего этажа или пол этажа
  // ниже, когда он шагнул в дыру двусвета (таск 229, G342). Своей дуги у
  // падения нет — та же, которой приземляется прыжок.
  const floorMm = Number(options.floorMm) || 0;
  const target = crouch ? VOLUME_CROUCH_MM : 0;
  let crouchMm = stance.crouchMm;
  if (target > crouchMm) crouchMm = Math.min(target, crouchMm + VOLUME_CROUCH_MM_S * span);
  else if (target < crouchMm && canStand) crouchMm = Math.max(target, crouchMm - VOLUME_CROUCH_MM_S * span);
  let liftMm = stance.liftMm;
  let speedMm = stance.speedMm;
  if (volumeStanceAir(stance, floorMm)) {
    speedMm -= VOLUME_FALL_MM_S2 * span;
    liftMm += speedMm * span;
    // Приземлились: ниже пола не бывает (`volumeGroundMm` — то же правило, по
    // которому у земли останавливается камера обзора), и скорость гасится
    // здесь же — иначе следующий тик утащил бы человека под пол.
    const landed = liftMm <= floorMm;
    liftMm = volumeGroundMm(liftMm, floorMm);
    if (landed) speedMm = 0;
  }
  return { crouchMm, liftMm, speedMm };
}

/**
 * Куда показали на полу: луч сквозь точку кадра до плоскости пола (G212,
 * «при клике курсором позволяй перемещать»).
 *
 * `null` — луч идёт вверх или вдоль пола и ни во что не упирается. С таска 195
 * это в обзоре бывает: взгляд там задирается к небу, и
 * щелчок по небу никуда не переносит — отвечать на него выдуманной точкой
 * пола было бы хуже, чем не отвечать вовсе.
 *
 * Считается **плоскостью пола, а не гранями сцены**: указывают на место, а не
 * на поверхность, и нажатый кусок стены должен значить «туда, к этой стене», а
 * не «на её гребень». Куда человек встанет на самом деле, решает `volumeMoveTo`.
 */
export function volumeFloorAt(camera, box, x, y) {
  const basis = volumeBasis(camera);
  const focal = volumeFocal(box);
  const right = (x - box.width / 2) / focal;
  const up = (box.height / 2 - y) / focal;
  const direction = {
    x: basis.fwd.x + basis.right.x * right + basis.up.x * up,
    y: basis.fwd.y + basis.right.y * right + basis.up.y * up,
    z: basis.fwd.z + basis.right.z * right + basis.up.z * up,
  };
  if (!(direction.z < -1e-6) || !(camera.at.z > 0)) return null;
  const away = -camera.at.z / direction.z;
  return { x: camera.at.x + direction.x * away, y: camera.at.y + direction.y * away };
}

/**
 * Куда человек встанет, если показали сюда (G212).
 *
 * Правило одно на оба случая, и оно прямо от заказчика: **вплотную**. Показали
 * в стену — тело выталкивается из неё и встаёт у её грани (`volumePush`, тот же
 * счёт, что у ходьбы, — второго правила «где можно стоять» в сборке нет).
 *
 * Показали за пределы плана — точка сперва зажимается габаритом чертежа, и
 * зажимается **внутрь на радиус тела**. Это не запас на всякий случай: габарит
 * идёт по осевым линиям наружных стен, и зажатая ровно по нему точка попадает в
 * середину стены, где выталкивать её равно выгодно в обе стороны — человек
 * оказывался снаружи дома. Шаг внутрь даёт выталкиванию сторону, и выходит
 * обещанное: человек у внутренней грани наружной стены.
 */
export function volumeMoveTo(scene, at, headMm = VOLUME_HEAD_MM) {
  const bounds = scene && scene.boundsMm;
  const inside = (value, min, max) => {
    const from = min + VOLUME_BODY_MM;
    const to = max - VOLUME_BODY_MM;
    if (!(to > from)) return (min + max) / 2;
    return Math.max(from, Math.min(to, value));
  };
  const point = bounds
    ? { x: inside(at.x, bounds.minX, bounds.maxX), y: inside(at.y, bounds.minY, bounds.maxY) }
    : { x: at.x, y: at.y };
  const solids = (scene && scene.solids) || [];
  const pushed = volumePush(solids, point, VOLUME_BODY_MM, headMm);
  if (volumeDepthMm(solids, pushed.x, pushed.y, VOLUME_BODY_MM, headMm) <= 0) return pushed;
  // **Вытолкнуть некуда — ищем рядом** (D39). Показали в место теснее тела: в
  // щель между стеной и перегородкой, в толщу стены на дальнем конце луча, в
  // угол ниши. Прежде человека там и оставляли — он оказывался зажат и дёргался
  // на каждом нажатии; это и был главный вход в дефект, потому что ходьбой в
  // такие места не попасть (в объекте заказчика все 390 щелей закрыты стенами).
  //
  // Поиск — кольцами по 100 мм до трёх метров, шестнадцать направлений в
  // кольце: берётся первое свободное место, то есть **ближайшее**. Три метра —
  // полкомнаты: дальше перенос перестал бы отвечать на «туда».
  const found = volumeFreeSpotNear(solids, pushed, headMm);
  return found || pushed;
}

/** Ближайшее к `at` место, где тело помещается целиком. `null` — не нашлось. */
export function volumeFreeSpotNear(solids, at, headMm = VOLUME_HEAD_MM, reachMm = 3000, stepMm = 100) {
  for (let radius = stepMm; radius <= reachMm; radius += stepMm) {
    for (let turn = 0; turn < 16; turn += 1) {
      const angle = (turn * Math.PI) / 8;
      const spot = { x: at.x + Math.cos(angle) * radius, y: at.y + Math.sin(angle) * radius };
      const pushed = volumePush(solids, spot, VOLUME_BODY_MM, headMm);
      if (volumeDepthMm(solids, pushed.x, pushed.y, VOLUME_BODY_MM, headMm) <= 0) return pushed;
    }
  }
  return null;
}

/**
 * В каком помещении стоит человек — по контурам сцены, а не по `roomAtPoint`:
 * контуры здесь уже переведены в миллиметры, и спрашивается это на каждом
 * шаге. Окно называет комнату вслух — заказчик про обзор сказал «без него не
 * понять, где стоишь», и имя комнаты отвечает на то же самое словом.
 */
export function volumeRoomAt(scene, at) {
  for (const room of scene.rooms || []) {
    if (volumePointInside(at, room.pointsMm)) return room;
  }
  return null;
}

// ——— камера ——————————————————————————————————————————————————————————————

/**
 * Оси камеры по рысканью и наклону. Плановые оси — те же, что у чертежа: `x`
 * вправо, `y` вниз; `z` растёт вверх от пола. Рысканье считается от оси `x` по
 * часовой на плане, наклон — вверх положительный.
 */
export function volumeBasis(camera) {
  const yaw = camera.yaw || 0;
  const pitch = camera.pitch || 0;
  const cosYaw = Math.cos(yaw);
  const sinYaw = Math.sin(yaw);
  const cosPitch = Math.cos(pitch);
  const sinPitch = Math.sin(pitch);
  return {
    fwd: { x: cosYaw * cosPitch, y: sinYaw * cosPitch, z: sinPitch },
    right: { x: -sinYaw, y: cosYaw, z: 0 },
    up: { x: -sinPitch * cosYaw, y: -sinPitch * sinYaw, z: cosPitch },
  };
}

/** Фокус в экранных точках: поле зрения меряется по длинной стороне окна. */
export function volumeFocal(box) {
  const side = Math.max(box.width, box.height);
  return (side / 2) / Math.tan(((VOLUME_FOV_DEG / 2) * Math.PI) / 180);
}

/**
 * Экранная строка горизонта: куда уходит всё, что лежит на уровне глаз.
 * Зависит только от наклона — и поэтому задник, привязанный к ней, рысканья не
 * знает и в перспективе не участвует.
 */
export function volumeHorizon(camera, box) {
  return box.height / 2 + volumeFocal(box) * Math.tan(camera.pitch || 0);
}

function volumeToCamera(point, eye, basis) {
  const dx = point.x - eye.x;
  const dy = point.y - eye.y;
  const dz = point.z - eye.z;
  return {
    x: dx * basis.right.x + dy * basis.right.y + dz * basis.right.z,
    y: dx * basis.up.x + dy * basis.up.y + dz * basis.up.z,
    z: dx * basis.fwd.x + dy * basis.fwd.y + dz * basis.fwd.z,
  };
}

/**
 * Отсечение многоугольника ближней плоскостью. Без него грань, пересекающая
 * плоскость камеры, выворачивается наизнанку через бесконечность — и это не
 * мелкая погрешность, а клякса на весь кадр.
 */
export function volumeClipNear(points, near = VOLUME_NEAR_MM) {
  return volumeClipDepth(points, near, Infinity);
}

/**
 * Отсечение многоугольника слоем глубины `[near, far]` — тем же обходом рёбер,
 * что ближней плоскостью, только с двумя сторонами. Общий случай; кадру нужен
 * его частный — `volumeClipNear`.
 */
export function volumeClipDepth(points, near = VOLUME_NEAR_MM, far = Infinity) {
  const side = (list, keep, cut) => {
    const out = [];
    for (let index = 0; index < list.length; index += 1) {
      const a = list[index];
      const b = list[(index + 1) % list.length];
      const aIn = keep(a);
      const bIn = keep(b);
      if (aIn) out.push(a);
      if (aIn !== bIn) out.push(cut(a, b));
    }
    return out;
  };
  let poly = side(
    points,
    (point) => point.z >= near,
    (a, b) => {
      const t = (near - a.z) / (b.z - a.z);
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: near };
    },
  );
  if (!(far < Infinity) || poly.length < 3) return poly;
  poly = side(
    poly,
    (point) => point.z <= far,
    (a, b) => {
      const t = (far - a.z) / (b.z - a.z);
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: far };
    },
  );
  return poly.length < 3 ? [] : poly;
}

// ——— порядок граней: дерево разбиения (D32, D33) ——————————————————————————
//
// Порядок рисования — не сортировка, а **дерево**, построенное один раз на
// сцену (`volumeOrderTree`) и обойдённое на каждый кадр (`volumeOrderWalk`).
//
// ——— почему не сортировка ————————————————————————————————————————————————
//
// «Художник» сравнивает грани одним числом — дальностью середины, — а
// перекрытие в кадре решает дальность **в пикселе**. У грани, уходящей от
// камеры вдаль, это разные числа, и спор она проигрывает целиком: стена в
// четыре метра серединой оказывается ближе вещи, стоящей у её края (D32,
// «иногда бывает что стены просвечивают»).
//
// Таск 150 лечил это **ломтями**: грань резалась плоскостями равной дальности
// `z = k · 250 мм`, и каждый кусок ехал со своей серединой. Провалы глубже
// полуметра это убрало, но завело свою семью дефектов (D33, слова заказчика:
// «на границах и углах появились треугольные артефакты»):
//
//   — ошибка порядка не исчезла, а измельчала: внутри одного ломтя соседние
//     куски по-прежнему спорят, и спор этот теперь виден **на каждом кадре** —
//     ровной чередой клиньев с шагом ломтя вдоль кромки;
//   — у разрезанной грани появились швы: канва сглаживает края, и два куска
//     общего ребра не складываются в непрозрачный пиксель.
//
// Ни то ни другое мельче шага не чинится: это та же шкала, а не выход.
//
// ——— что вместо ————————————————————————————————————————————————————————
//
// Дерево двоичного разбиения пространства. В узле — плоскость одной из граней;
// всё, что перед ней, в одном поддереве, всё, что за ней, в другом, грани в
// самой плоскости — в узле. Грань, которую плоскость пересекает, режется по ней
// надвое — **по настоящей геометрии, а не по сетке**.
//
// Свойство, ради которого всё затевалось: луч из глаза пересекает плоскость
// узла не больше одного раза, значит **всё, что лежит на стороне глаза, стоит
// на луче раньше** всего, что лежит за плоскостью. Обход «дальнее поддерево,
// потом плоскость, потом ближнее» даёт порядок, верный в каждом пикселе и на
// любом ракурсе — не «ошибка не больше шага», а ошибки нет вовсе.
//
// Цена названа и замерена в отчёте таска: дерево строится при сборке сцены
// (там же, где считаются грани, — на объекте заказчика это единицы
// миллисекунд), резов выходит на порядок меньше, чем давали ломти, а кадр
// вместо сортировки `n log n` получает обход `n` без единого сравнения.
//
// Ярусы (`VOLUME_LAYER_*`) дерево не отменяет: в нём лежит только ярус тел.
// Плита, полы с потолками и указатель «вы здесь» ложатся до и после него по
// прежнему правилу — там спорить не о чем (см. `VOLUME_LAYER_BASE`).
//
// ——— и почему прозрачным вещам не понадобился второй проход ——————————
//
// Таск 169 сделал вещи чертежа полупрозрачными, и прозрачность требует
// рисования **строго от дальних к ближним без пропусков**: смешивание
// некоммутативно, переставь двоих — получишь другой цвет. У «художника» (таск
// 150) этого не было: он сортировал по средней дальности и врал в тех самых
// точках, где грани пересекались, — прозрачность показала бы его ложь цветом,
// а не только порядком.
//
// Дерево даёт ровно то, что нужно, и **ровно то же самое, что давало до
// прозрачности**: обход «дальнее поддерево → своя плоскость → ближнее» — это и
// есть порядок от дальних к ближним, точный в каждом пикселе, потому что
// спорящие грани разрезаны по-настоящему. Поэтому ни отдельного прохода, ни
// сортировки прозрачных, ни разделения потоков здесь нет: **признак
// прозрачности не участвует в порядке вовсе** — он виден только цвету
// (`volumeFill` отдаёт `rgba`) и взгляду (`volumeSightAt` смотрит сквозь).
// Отдельный проход был бы здесь не улучшением, а поломкой: он бы выдернул
// вещь из её настоящего места и поставил прозрачный шкаф **перед** стеной
// соседней комнаты.
//
// Что дерево не обещает и обещать не может — порядок **коплоскостных** граней
// (список `same` в узле): они друг друга не закрывают, и до прозрачности их
// порядок не значил ничего. Прозрачным он тоже не значит ничего, пока
// коплоскостные грани не накладываются друг на друга, — а наложенных
// коплоскостных граней в сцене нет: тела модели стоят рядом, а не в одной
// плоскости поверх друг друга.
//
// Что при этом честно складывается, а не пропадает, — **прозрачность по
// пути**: сквозь шкаф с фасадом луч проходит две лицевые грани (отсеиваются
// только отвёрнутые, а не стоящие друг за другом), и это посчитано в числе
// `VOLUME_CLEAR_ALPHA`.

/** Плоскость грани: нормаль и расстояние до начала координат. */
function volumePlaneOf(face) {
  return {
    x: face.n.x,
    y: face.n.y,
    z: face.n.z,
    d: face.n.x * face.p[0].x + face.n.y * face.p[0].y + face.n.z * face.p[0].z,
  };
}

/** С какой стороны плоскости точка: 1 перед, −1 за, 0 — на ней. */
function volumePointSide(plane, point, eps = VOLUME_PLANE_EPS_MM) {
  const gap = plane.x * point.x + plane.y * point.y + plane.z * point.z - plane.d;
  return gap > eps ? 1 : gap < -eps ? -1 : 0;
}

/**
 * С какой стороны плоскости грань: `1` перед, `−1` за, `0` в самой плоскости,
 * `2` — пересекает, то есть её придётся резать.
 */
export function volumeFaceSide(plane, face) {
  let front = 0;
  let back = 0;
  for (const point of face.p) {
    const side = volumePointSide(plane, point);
    if (side > 0) front += 1;
    else if (side < 0) back += 1;
  }
  if (front > 0 && back > 0) return 2;
  if (front > 0) return 1;
  if (back > 0) return -1;
  return 0;
}

/**
 * Разрез грани плоскостью. Возвращает `{front, back}` — две грани со всеми
 * полями исходной (цвет, ярус, хозяин, полотно) и своими точками.
 *
 * Грань выпуклая или нет — обход один и тот же: вершины раскладываются по
 * сторонам, точка пересечения ребра попадает в обе половины.
 */
export function volumeSplitFace(face, plane) {
  const side = volumeFaceSide(plane, face);
  if (side === 1 || side === 0) return { front: face, back: null };
  if (side === -1) return { front: null, back: face };
  const front = [];
  const back = [];
  const points = face.p;
  for (let index = 0; index < points.length; index += 1) {
    const a = points[index];
    const b = points[(index + 1) % points.length];
    const sa = volumePointSide(plane, a);
    const sb = volumePointSide(plane, b);
    if (sa >= 0) front.push(a);
    if (sa <= 0) back.push(a);
    if (sa * sb < 0) {
      const da = plane.x * a.x + plane.y * a.y + plane.z * a.z - plane.d;
      const db = plane.x * b.x + plane.y * b.y + plane.z * b.z - plane.d;
      const t = da / (da - db);
      const cut = { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: a.z + (b.z - a.z) * t };
      front.push(cut);
      back.push(cut);
    }
  }
  return {
    front: front.length >= 3 ? { ...face, p: front } : null,
    back: back.length >= 3 ? { ...face, p: back } : null,
  };
}

/**
 * Дерево порядка по граням яруса тел. `null` — делить нечего.
 *
 * Строится один раз на сцену и живёт в ней (`scene.order`): сцена пересобирается
 * при правке объекта и при открытии двери, и дерево вместе с ней.
 */
export function volumeOrderTree(faces) {
  const items = [];
  for (const face of faces || []) {
    if (!face || face.line) continue;
    if (face.layer !== undefined && face.layer !== VOLUME_LAYER_BODY) continue;
    items.push(face);
  }
  return volumeOrderNode(items);
}

/**
 * Узел дерева. Плоскость выбирается примеркой: меньше резов, ровнее половины.
 * Грань-кандидат всегда лежит в своей же плоскости, поэтому узел забирает хотя
 * бы одну грань — построение не зацикливается.
 */
function volumeOrderNode(items) {
  if (items.length === 0) return null;
  let best = null;
  const tries = Math.min(items.length, VOLUME_ORDER_TRIES);
  for (let at = 0; at < tries; at += 1) {
    const plane = volumePlaneOf(items[Math.floor((at * items.length) / tries)]);
    let front = 0;
    let back = 0;
    let splits = 0;
    for (const item of items) {
      const side = volumeFaceSide(plane, item);
      if (side === 2) splits += 1;
      else if (side === 1) front += 1;
      else if (side === -1) back += 1;
    }
    if (front === 0 && back === 0 && splits === 0) continue;
    const score = splits * VOLUME_ORDER_SPLIT_COST + Math.abs(front - back);
    if (!best || score < best.score) best = { plane, score };
  }
  // Все грани в одной плоскости: делить нечем, и незачем — коплоскостные грани
  // друг друга не закрывают.
  if (!best) return { plane: volumePlaneOf(items[0]), same: items, front: null, back: null, count: items.length };
  const plane = best.plane;
  const same = [];
  const front = [];
  const back = [];
  for (const item of items) {
    const side = volumeFaceSide(plane, item);
    if (side === 0) {
      same.push(item);
      continue;
    }
    if (side === 1) {
      front.push(item);
      continue;
    }
    if (side === -1) {
      back.push(item);
      continue;
    }
    const cut = volumeSplitFace(item, plane);
    if (cut.front) front.push(cut.front);
    if (cut.back) back.push(cut.back);
  }
  const node = { plane, same, front: volumeOrderNode(front), back: volumeOrderNode(back), count: 0 };
  node.count = same.length + (node.front ? node.front.count : 0) + (node.back ? node.back.count : 0);
  return node;
}

/**
 * Обход дерева от дальнего к ближнему: дальнее поддерево, своя плоскость,
 * ближнее поддерево. Возвращает грани в порядке рисования.
 */
export function volumeOrderWalk(tree, eye, out = []) {
  if (!tree) return out;
  const near = volumePointSide(tree.plane, eye) >= 0;
  volumeOrderWalk(near ? tree.back : tree.front, eye, out);
  for (const face of tree.same) out.push(face);
  volumeOrderWalk(near ? tree.front : tree.back, eye, out);
  return out;
}

/**
 * Сколько граней обход нарисует **раньше** этой точки. Ею встают в очередь те,
 * кого в дереве нет: линии (контур вещи, стрелка связи) — рисунок поверх сцены,
 * резать их по плоскостям нельзя (у ломаной есть концы, а у пунктира — шаг), и
 * место в очереди им считается по середине.
 */
export function volumeOrderRank(tree, eye, point) {
  let node = tree;
  let rank = 0;
  while (node) {
    const near = volumePointSide(node.plane, eye) >= 0;
    const first = near ? node.back : node.front;
    const second = near ? node.front : node.back;
    const side = volumePointSide(node.plane, point);
    const inFirst = near ? side < 0 : side > 0;
    if (inFirst) {
      node = first;
      continue;
    }
    rank += (first ? first.count : 0) + node.same.length;
    node = second;
  }
  return rank;
}

/** Грань яруса тел — та, что лежит в дереве порядка. */
function volumeInTree(face) {
  return !face.line && (face.layer === undefined || face.layer === VOLUME_LAYER_BODY);
}

/** Середина грани или линии: ею считается место в очереди у тех, кого нет в дереве. */
function volumeMiddleOf(points) {
  let x = 0;
  let y = 0;
  let z = 0;
  for (const point of points) {
    x += point.x;
    y += point.y;
    z += point.z;
  }
  return { x: x / points.length, y: y / points.length, z: z / points.length };
}

/**
 * Кадр: грани сцены, переведённые в экранные многоугольники и выложенные в
 * порядке рисования.
 *
 * Ярус тел выкладывает **дерево порядка** (`volumeOrderTree`) — точно, в каждом
 * пикселе и на любом ракурсе. Плита, полы с потолками и указатель «вы здесь»
 * лежат вне дерева, своими ярусами и по дальности: под полом ничего нет, а
 * потолок, видимый снизу, не закрывает ничего, кроме себя, — спорить им не о
 * чем. Будь они в общем потоке, пол комнаты, в которой стоишь, оказался бы
 * ближе дальней стены и закрасил бы её низ.
 *
 * Линии (контур вещи, стрелка связи) в дереве не лежат — их встраивают в
 * очередь по середине (`volumeOrderRank`), а контур вещи ставит на место своим
 * правилом `volumeOutlineOrder`.
 *
 * Невидимые грани отбрасываются по направлению нормали; двусторонние (полотно
 * двери, рама окна) нормаль поворачивают навстречу.
 */
export function volumeFrame(scene, camera, box, extra = null, tint = null) {
  const basis = volumeBasis(camera);
  const focal = volumeFocal(box);
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  const polygons = [];
  // У собранной сцены дерево уже есть; у наскоро составленной (стенд, тест) его
  // строят на месте — кадр обязан быть верным и там.
  const tree = scene.order === undefined ? volumeOrderTree(scene.faces) : scene.order;
  const take = (face, order) =>
    volumeFacePolygons(face, camera, basis, focal, halfWidth, halfHeight, box, polygons, order, tint);
  // Половина — чтобы линия встала **между** гранями, а не спорила с одной из них.
  const rankOf = (face) => volumeOrderRank(tree, camera.at, volumeMiddleOf(face.p)) - 0.5;
  let rank = 0;
  for (const face of volumeOrderWalk(tree, camera.at)) {
    take(face, rank);
    rank += 1;
  }
  for (const face of scene.faces) {
    if (volumeInTree(face)) continue;
    take(face, face.layer === VOLUME_LAYER_BODY ? rankOf(face) : null);
  }
  for (const face of extra || []) {
    take(face, face.layer === VOLUME_LAYER_BODY || face.layer === undefined ? rankOf(face) : null);
  }
  polygons.sort((a, b) => (a.layer === b.layer ? a.order - b.order : a.layer - b.layer));
  return volumeOutlineOrder(polygons);
}

// Вещь на стене рисуется после неё сама: она **и правда** стоит перед
// плоскостью стены — на два миллиметра (`VOLUME_MARK_LIFT_MM`), — а дерево
// порядка смотрит на плоскости, а не на дальность середин. Поэтому
// перестановки «вещь за своим куском стены», которой жили таски 148–150
// (`volumeHostOrder`, метровая сетка стороны стены), здесь больше нет: с точным
// порядком она не помогала, а мешала — вещь вставала перед **чужими** стенами,
// и розетки соседней комнаты просвечивали сквозь перегородку. Замер: 0,028 %
// точек кадра с провалом до шести метров против нуля без неё.

/**
 * Перестановка очереди: `waiting` — карта «за каким многоугольником встать» →
 * список тех, кто встаёт за ним. Всё остальное сохраняет свой порядок.
 *
 * Нужна она контуру вещи (`volumeOutlineOrder`): контур обязан ехать сразу за
 * своим телом, и это правило, а не дальность.
 */
function volumeReorder(polygons, waiting) {
  const moved = new Set();
  for (const list of waiting.values()) for (const index of list) moved.add(index);
  const out = [];
  for (let index = 0; index < polygons.length; index += 1) {
    if (!moved.has(index)) out.push(polygons[index]);
    const list = waiting.get(index);
    if (list) for (const at of list) out.push(polygons[at]);
  }
  return out;
}

/**
 * Контур вещи рисуется **сразу после её тела**, и это правило, а не дальность.
 *
 * Контур поднят над лицом вещи на миллиметр (`VOLUME_VIEW_LIFT_MM`) — то есть
 * лежит в плоскости, параллельной лицу. Сортировка по средней дальности на
 * таком зазоре ничего не решает: у решётки бризера свои точки стоят не там, где
 * середина его плашки, и при взгляде вкось средняя дальность контура бывает
 * больше средней дальности тела. Тогда тело закрашивает собственный контур — тот
 * самый дефект живого прогона таска 148, у которого от решётки оставался один
 * индикатор. Миллиметровым зазором он лечится только случайно, поэтому порядок
 * здесь назван прямо.
 */
function volumeOutlineOrder(polygons) {
  let bodies = null;
  for (let index = 0; index < polygons.length; index += 1) {
    const polygon = polygons[index];
    if (polygon.stroke || !polygon.pick) continue;
    if (!bodies) bodies = new Map();
    bodies.set(polygon.pick, index);
  }
  if (!bodies) return polygons;
  const waiting = new Map();
  let deferred = false;
  for (let index = 0; index < polygons.length; index += 1) {
    const polygon = polygons[index];
    if (!polygon.stroke || !polygon.pick) continue;
    const at = bodies.get(polygon.pick);
    if (at === undefined || at <= index) continue;
    let list = waiting.get(at);
    if (!list) waiting.set(at, (list = []));
    list.push(index);
    deferred = true;
  }
  return deferred ? volumeReorder(polygons, waiting) : polygons;
}

/**
 * Одна грань в экранный многоугольник. Пусто — её не видно: отвёрнута, целиком
 * за ближней плоскостью или целиком за краем окна.
 *
 * Многоугольник ровно один: грань в кадре больше не режется ничем. Резы, если
 * они нужны, сделаны один раз при сборке дерева порядка — по настоящим
 * плоскостям сцены, а не по сетке дальностей (см. `volumeOrderTree`). Шва от
 * них тем меньше, чем меньше резов, и это то же самое число.
 *
 * `order` — место в очереди: ранг из дерева у яруса тел, `null` у всех
 * остальных, и тогда порядок внутри яруса решает дальность, как прежде.
 */
function volumeFacePolygons(face, camera, basis, focal, halfWidth, halfHeight, box, out, order = null, tint = null) {
  if (face.line) {
    const line = volumeLinePolygon(face, camera, basis, focal, halfWidth, halfHeight, box);
    if (line) {
      line.order = order === null ? -line.depth : order;
      out.push(line);
    }
    return out;
  }
  const first = face.p[0];
  const vx = camera.at.x - first.x;
  const vy = camera.at.y - first.y;
  const vz = camera.at.z - first.z;
  let normal = face.n;
  let facing = normal.x * vx + normal.y * vy + normal.z * vz;
  if (face.both && facing < 0) {
    normal = { x: -normal.x, y: -normal.y, z: -normal.z };
    facing = -facing;
  }
  if (facing <= 0) return out;
  const clipped = volumeClipNear(face.p.map((point) => volumeToCamera(point, camera.at, basis)));
  if (clipped.length < 3) return out;
  const xy = [];
  let depth = 0;
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (const point of clipped) {
    const scale = focal / point.z;
    const x = halfWidth + point.x * scale;
    const y = halfHeight - point.y * scale;
    xy.push(x, y);
    depth += point.z;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  if (maxX < 0 || minX > box.width || maxY < 0 || minY > box.height) return out;
  const middle = depth / clipped.length;
  out.push({
    xy,
    depth: middle,
    order: order === null ? -middle : order,
    layer: face.layer,
    fill: volumeFill(face.rgb, face.flat ? 1 : volumeShade(normal), face.alpha === undefined ? 1 : face.alpha, tint),
    // Многоугольник просвечивает (таск 169): взгляд смотрит сквозь него
    // дальше — если за ним есть кому отвечать (таск 189, см. `volumeSightAt`).
    // Рисование об этом не спрашивает — прозрачность уже в цвете.
    clear: Boolean(face.clear),
    pick: face.markId || null,
    door: face.doorId || null,
    // Клавиша выключателя (таск 177): по ней окно отвечает, в какой канал
    // попал щелчок. У остальных многоугольников `null`.
    channel: face.channel === undefined ? null : face.channel,
  });
  return out;
}

/**
 * Линия сцены в экранную ломаную (таск 148).
 *
 * Отличий от грани два. Первое: светлоты у линии нет — контур изображения и
 * стрелка связи рисуются своим цветом, а не поверхностью, повёрнутой к свету.
 * Второе: **за ближнюю плоскость линия не режется, а выбрасывается целиком.**
 * Резать её пришлось бы иначе, чем кольцо грани (у ломаной есть концы, и
 * замкнуть её по кругу значило бы дорисовать отрезок, которого нет), а цена
 * отказа нулевая: контур вещи длиной в полметра оказывается наполовину за
 * спиной только тогда, когда человек уткнулся в него носом.
 */
function volumeLinePolygon(line, camera, basis, focal, halfWidth, halfHeight, box) {
  if (line.n) {
    const first = line.p[0];
    const facing =
      line.n.x * (camera.at.x - first.x) + line.n.y * (camera.at.y - first.y) + line.n.z * (camera.at.z - first.z);
    if (facing <= 0) return null;
  }
  const xy = [];
  let depth = 0;
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (const point of line.p) {
    const at = volumeToCamera(point, camera.at, basis);
    if (at.z < VOLUME_NEAR_MM) return null;
    const scale = focal / at.z;
    const x = halfWidth + at.x * scale;
    const y = halfHeight - at.y * scale;
    xy.push(x, y);
    depth += at.z;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  if (xy.length < 4) return null;
  if (maxX < 0 || minX > box.width || maxY < 0 || minY > box.height) return null;
  return {
    xy,
    depth: depth / line.p.length,
    layer: line.layer,
    stroke: line.color,
    width: line.width,
    closed: line.closed,
    dash: line.dash,
    arrow: line.arrow,
    pick: line.markId || null,
  };
}

/** Стрелка связи в экранных точках: размер у неё постоянный, как у плана. */
const VOLUME_ARROW_PX = 9;
const VOLUME_ARROW_SPREAD = 0.42;

/**
 * Отрисовка кадра. Заливка и обводка тем же цветом: без обводки между
 * соседними гранями остаётся волосяная щель от сглаживания, и стена
 * расчерчивается белыми нитями.
 *
 * Линии (контур вещи, стрелка связи) обводятся своим цветом и своей толщиной и
 * не заливаются вовсе: это рисунок поверх сцены, а не её поверхность.
 */
export function volumeDraw(ctx, polygons) {
  ctx.lineJoin = "round";
  ctx.lineWidth = 1;
  for (const polygon of polygons) {
    const xy = polygon.xy;
    ctx.beginPath();
    ctx.moveTo(xy[0], xy[1]);
    for (let index = 2; index < xy.length; index += 2) ctx.lineTo(xy[index], xy[index + 1]);
    if (!polygon.stroke) {
      ctx.closePath();
      ctx.fillStyle = polygon.fill;
      ctx.strokeStyle = polygon.fill;
      ctx.fill();
      ctx.stroke();
      continue;
    }
    if (polygon.closed) ctx.closePath();
    ctx.save();
    ctx.lineWidth = polygon.width;
    ctx.strokeStyle = polygon.stroke;
    if (polygon.dash) ctx.setLineDash(polygon.dash);
    ctx.stroke();
    if (polygon.arrow) volumeDrawArrow(ctx, xy);
    ctx.restore();
  }
  return polygons.length;
}

// Наконечник стрелки — в экранных точках, по направлению последнего отрезка:
// в объёме он иначе то съёживался бы в точку, то вырастал в парус.
function volumeDrawArrow(ctx, xy) {
  const size = xy.length;
  if (size < 4) return;
  const tipX = xy[size - 2];
  const tipY = xy[size - 1];
  const dx = tipX - xy[size - 4];
  const dy = tipY - xy[size - 3];
  const length = Math.hypot(dx, dy);
  if (!(length > 0)) return;
  const ux = dx / length;
  const uy = dy / length;
  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(tipX - ux * VOLUME_ARROW_PX - uy * VOLUME_ARROW_PX * VOLUME_ARROW_SPREAD, tipY - uy * VOLUME_ARROW_PX + ux * VOLUME_ARROW_PX * VOLUME_ARROW_SPREAD);
  ctx.lineTo(tipX, tipY);
  ctx.lineTo(tipX - ux * VOLUME_ARROW_PX + uy * VOLUME_ARROW_PX * VOLUME_ARROW_SPREAD, tipY - uy * VOLUME_ARROW_PX - ux * VOLUME_ARROW_PX * VOLUME_ARROW_SPREAD);
  ctx.stroke();
}

/** Насколько промахивается рука: розетка в трёх метрах — десяток точек экрана. */
export const VOLUME_PICK_SLACK_PX = 14;

/**
 * Во что попал клик (таск 148): обозначение метки или `null`.
 *
 * Ищется **по телам вещей и сверху вниз** — тем же порядком, которым кадр
 * рисовался, только с конца: что человек видит последним нарисованным, то и
 * под курсором. Контуры и связи в поиске не участвуют: по ним целиться нельзя,
 * а попадание в линию толщиной в точку было бы случайностью.
 *
 * Не попал точно — берётся ближайшая вещь в пределах промаха: розетка с трёх
 * метров занимает десяток точек, и требовать попадания в неё пикселем значило
 * бы сделать выделение недоступным ровно там, где оно нужнее всего.
 */
export function volumePickAt(polygons, x, y, slack = VOLUME_PICK_SLACK_PX) {
  let near = null;
  let gap = slack;
  for (let index = polygons.length - 1; index >= 0; index -= 1) {
    const polygon = polygons[index];
    if (!polygon.pick || polygon.stroke) continue;
    if (volumePolygonHit(polygon.xy, x, y)) return polygon.pick;
    const centre = volumePolygonCentre(polygon.xy);
    const distance = Math.hypot(centre.x - x, centre.y - y);
    if (distance < gap) {
      gap = distance;
      near = polygon.pick;
    }
  }
  return near;
}

/**
 * **Что видно в точке кадра** (G214): обозначение метки, если в этой точке
 * последней нарисована она, иначе `null` — стена, пол, полотно двери.
 *
 * Отличие от `volumePickAt` одно, и оно по существу. Клик — это рука, и ей
 * прощается промах: вещь, до которой десяток точек, считается задетой, а стена
 * перед ней руке не мешает. Прицел — это **взгляд**, и прощать ему нечего: он
 * показывает ровно одну точку кадра, и ответ на вопрос «на что ты смотришь»
 * может быть только один — то, что в этой точке видно. Спрятанную за стеной
 * вещь человек не видит, и выделять её по взгляду было бы обманом.
 *
 * Отвечать на это стало можно только с таском 151: порядок кадра точен в
 * каждом пикселе, и «нарисовано последним» наконец значит «видно».
 *
 * ——— сквозь прозрачную вещь (таск 169, G251) ———
 *
 * Прозрачная грань (вещь чертежа) для взгляда **не существует**: обход идёт
 * дальше, пока не упрётся в непрозрачное. Это и есть просьба заказчика
 * «взаимодействовать с ними»: шкаф просвечивает, за ним видно розетку — значит
 * ответ «на что ты смотришь» — розетка, а не шкаф.
 *
 * Правило «видно — выделяется» при этом не меняется, а исполняется буквально:
 * сквозь прозрачное видно, сквозь стену — нет, и **стена по-прежнему
 * останавливает обход**. Метка за перегородкой невидима и невыделяема, даже
 * если перед перегородкой стоит прозрачный шкаф.
 *
 * Пропустить, а не «спросить ближайшую непрозрачную и выбрать из двух», —
 * потому что выбирать не из чего: **у вещи чертежа хозяина нет вовсе**
 * (`markId` у её граней `null`), и до таска 169 взгляд в шкаф отвечал `null`.
 * Прозрачная грань не отняла ни одного ответа — она только перестала закрывать
 * чужой.
 *
 * Отсюда и ответ на «а если за прозрачной вещью ничего нет»: за ней
 * непрозрачная стена, пол или плита — обход упирается в них и отвечает `null`,
 * ровно как прежде. Для `E` это «тут ничего нет» словами (`volume.aimless`),
 * для щелчка — снятие выделения, как по пустому месту плана. Ни одна точка
 * поля смысла не поменяла, кроме той, где за вещью **и правда** метка.
 *
 * ——— а сквозь тюль взгляд не проходит (таск 189, G286) ———
 *
 * Прозрачная грань пропускает взгляд, **пока у неё нет хозяина**. У шторы он
 * есть: тюль — это сама метка, её выделяют, у неё открываются свойства, по ней
 * щёлкают. Пропусти её — и выделить шторы взглядом стало бы нельзя вовсе:
 * ответом стало бы окно за ними, то есть `null`.
 *
 * Поэтому правило звучит не «прозрачное пропускается», а **«пропускается то,
 * за чем всё равно никого не выделить»**: у вещи чертежа хозяина нет (`markId`
 * её граней — `null`), и пропуск не отнимает ни одного ответа — он только
 * перестаёт закрывать чужой. У метки хозяин есть, и пропуск отнял бы её
 * собственный.
 *
 * Цена названа прямо: **метку, целиком закрытую тюлем, взглядом не выделить** —
 * ответом будет штора. Это ровно то, что было до таска 189 (тогда полотнище
 * было плотным), то есть не потеря, а сохранение: прозрачность поменяла, как
 * штора выглядит, а не что выделяется. Достать метку за шторой по-прежнему
 * может рука — `volumePickAt` прозрачности не спрашивает вовсе, и промах в
 * десяток точек приводит именно её.
 */
export function volumeSightAt(polygons, x, y) {
  for (let index = polygons.length - 1; index >= 0; index -= 1) {
    const polygon = polygons[index];
    if (polygon.stroke || volumeSeeThrough(polygon)) continue;
    if (volumePolygonHit(polygon.xy, x, y)) return polygon.pick || null;
  }
  return null;
}

/**
 * Смотрит ли взгляд сквозь этот многоугольник: прозрачный и бесхозный — да,
 * прозрачная метка — нет. Одно место на взгляд и на клавиши: разойдись они —
 * щелчок выбирал бы канал у выключателя за шторой.
 */
function volumeSeeThrough(polygon) {
  return Boolean(polygon.clear) && !polygon.pick;
}

/**
 * **В какую клавишу попал щелчок** (таск 177, G274): `{markId, channel}` или
 * `null`.
 *
 * Правило то же, что у взгляда (`volumeSightAt`): клавиша должна быть **видна**
 * в этой точке кадра. Промах здесь не прощается, и это по существу: соседние
 * клавиши стоят в десятке миллиметров друг от друга, и «ближайшая в пределах
 * промаха» означала бы, что выбран канал, по которому человек не целился.
 * Выделение самой метки при этом остаётся со своим запасом — промах по клавише
 * просто выделяет вещь целиком, как выделял до каналов.
 */
export function volumeChannelAt(polygons, x, y) {
  for (let index = polygons.length - 1; index >= 0; index -= 1) {
    const polygon = polygons[index];
    if (polygon.stroke || volumeSeeThrough(polygon)) continue;
    if (!volumePolygonHit(polygon.xy, x, y)) continue;
    if (!polygon.pick || !polygon.channel) return null;
    return { markId: polygon.pick, channel: polygon.channel };
  }
  return null;
}

function volumePolygonHit(xy, x, y) {
  let inside = false;
  for (let i = 0, j = xy.length - 2; i < xy.length; j = i, i += 2) {
    const ax = xy[i];
    const ay = xy[i + 1];
    const bx = xy[j];
    const by = xy[j + 1];
    const crosses = ay > y !== by > y;
    if (crosses && x < ((bx - ax) * (y - ay)) / (by - ay) + ax) inside = !inside;
  }
  return inside;
}

function volumePolygonCentre(xy) {
  let sumX = 0;
  let sumY = 0;
  for (let index = 0; index < xy.length; index += 2) {
    sumX += xy[index];
    sumY += xy[index + 1];
  }
  const count = xy.length / 2;
  return { x: sumX / count, y: sumY / count };
}

// ——— фон: панорама вокруг дома ———————————————————————————————————————————
//
// Слова заказчика (G208): «при повороте от 1 лица дом крутится, а фон нет, как
// будто сам дом вращается на местности — не хорошо. А так же в зависимости от
// вертикального наклона двигаются облака и солнце, они должны быть статичны.
// Ну и вращаться в след за поворотом, то есть как реальный фон. И нарисуй
// несколько деревьев и кустарников ближе».
//
// Таск 146 рисовал задник **в экранных точках**: одно и то же дерево на одном и
// том же месте кадра, что бы человек ни делал головой. Исполнитель назвал это
// ценой решения, заказчик цену не принял — и правильно: от такого фона дом и
// правда выглядит вертушкой на местности.
//
// ——— что здесь считается и почему это не вторая сцена —————————————————
//
// Фон — **бесконечно далёкая панорама**: у каждой вещи есть сторона света
// (`az`, та же мера, что рысканье камеры) и высота над горизонтом (`rise`), а
// места в метрах у неё нет вовсе. Точка панорамы попадает на экран **той же
// камерой, что и сцена** (`volumeBasis`, `volumeFocal`), только без переноса:
// направление не зависит от того, где стоит человек, — значит фон не
// приближается шагами и не съезжает от хождения, но поворачивается вслед за
// головой и наклоняется вслед за взглядом, как настоящий.
//
// Второй системы координат из этого не вышло: направление считается тремя
// скалярными произведениями на тот же базис, а числа фона — два угла на вещь.
// Ставить деревья **в саму сцену** далёкими плоскостями было бы дороже и
// неправдивее: плоскость за окном участвовала бы в сортировке граней, лезла бы
// в столкновения и в обзор сверху (где дом видно с крыши, а «задник» оказался
// бы лежащим на земле листом), а деревьев за каждым окном нужно было бы ровно
// столько, сколько окон. Панорама же одна на весь дом и не знает о нём ничего.
//
// ——— горизонт: формула та же, доказательство другое ————————————————————
//
// `volumeHorizon` считает строку горизонта одним числом из наклона и рысканья
// не знает. В таске 146 это было **упрощением**, теперь это **следствие**:
// направление с нулевой высотой над горизонтом даёт на экране
// `y = height / 2 + focal · tg(pitch)` при любой стороне света — то есть ровно
// ту же строку. Поэтому и небо спокойно при наклоне: оно не привязано к
// горизонту долями своей высоты (от этого солнце и ездило), а стоит на своих
// углах и едет вместе со всем кадром.

/**
 * Земля — **один тон от дома до горизонта** (G237). Слова заказчика: «дом как
 * будто летает в воздухе над землей, а не стоит на земле, надо поставить на
 * землю».
 *
 * Разбор у этого короткий и неприятный: **отдельная плоскость под сценой не
 * изменила бы ни одного пикселя**. Бесконечная плоскость на нулевой отметке
 * закрывает на экране ровно то же, что заливка ниже линии горизонта, — а
 * горизонт панорама и так считает той же камерой (`volumeHorizon`). Нарисуй её
 * хоть гранью сцены, хоть задником — пока тон у неё один, картинка та же.
 *
 * Висел дом не поэтому. Висела **плита чертежа**: прямоугольник в габарите
 * чертежа на нулевой отметке, крашенный полом (`VOLUME_FLOOR_RGB`) и
 * затенённый лампой сцены до тёмно-коричневого. Дом стоял на доске, доска
 * лежала на зелёном — и между ними не было ничего общего.
 *
 * Поэтому земля и плита сведены в один тон: поле панорамы залито **плоским**
 * цветом (растяжка от горизонта к низу экрана ушла — она и раньше ничего не
 * говорила, потому что у ровной плоскости светлота не зависит от дальности), а
 * плита красится тем же цветом и **без затенения** (`flat`), когда помещения
 * обведены и свой пол у них есть. Стык при этом не виден нигде: он не на краю
 * габарита чертежа, а там, где земля сходится в линию горизонта.
 *
 * Не обведены помещения — плита остаётся единственным полом и остаётся полом
 * по цвету: назвать её землёй значило бы сказать, что пола в доме нет.
 */
export const VOLUME_LAND_RGB = [123, 160, 93];
const VOLUME_CLOUD = "#ffffff";
const VOLUME_TRUNK = "#6b5134";
const VOLUME_CROWN_FAR = "#6f8f5a";
const VOLUME_CROWN = "#4f7a3c";
const VOLUME_CROWN_DARK = "#3f6632";
const VOLUME_BUSH = "#5c8a41";
// Берёза и ива (просьба заказчика: «добавь ещё несколько вариантов деревьев»).
// Узнаются они не подробностями, а силуэтом и тоном: у берёзы светлый ствол и
// жидкая светлая крона, у ивы широкая крона с прядями, у тополя узкий столб.
const VOLUME_BIRCH_TRUNK = "#e3ded2";
const VOLUME_BIRCH_MARK = "#6b6256";
const VOLUME_BIRCH_CROWN = "#6f9a46";
const VOLUME_WILLOW = "#7aa554";
// Дорога — грунтовая: разметки и обочин у неё нет нарочно (мера «чуть»,
// G231). Вдаль она не только сужается, но и выцветает в дымку, как всё
// далёкое, — поэтому у полосы два цвета, ближний и дальний.
const VOLUME_ROAD_NEAR = "#a1968a";
const VOLUME_ROAD_FAR = "#cdc7bc";
// Вода берёт цвет неба: вблизи насыщенный, у горизонта почти небо.
const VOLUME_RIVER_NEAR = "#6aa3cf";
const VOLUME_RIVER_FAR = "#cde2f1";
// Холмы — дальний план, и цвет у них не зелень, а зелень сквозь воздух:
// дальняя гряда бледнее и синее ближней.
const VOLUME_HILL_FAR = "#aec4bd";
const VOLUME_HILL_NEAR = "#95b291";

/** Ближе этого направление считается ушедшим за край: делить на нуль нельзя. */
const VOLUME_SKY_NEAR = 0.08;

/**
 * **Полдень в среднем**: сторона света, высота над горизонтом и угловой радиус
 * солнца в градусах, при верхе чертежа на север.
 *
 * С таска 190 **место солнца считается по-настоящему** (`volumeSunAt`: дата,
 * время, координаты), и дуга дня отсюда больше не берётся. Остались трое:
 *
 *   - **вынос земляной плиты** — из `rise` выходит самая длинная тень, которую
 *     плита обязана удержать (`volumeShadowShift`), и этот размер часть сцены:
 *     пересчитывать его каждую секунду нельзя, иначе миникарта дышала бы. Ниже
 *     14° тень для этого и не опускается — тем же `volumeShadowShift`;
 *   - **гряда гор** стоит напротив полуденного солнца (G238);
 *   - **угловой размер** диска в кадре (`size`), нарисованный, а не настоящий
 *     (у настоящего 0,26°) — разбор у `VOLUME_MOON_SIZE_DEG`.
 *
 * `az` = 90° — это юг: у панорамы ноль смотрит вправо по листу, а при верхе на
 * север вправо уходит восток, значит юг приходится на 90° (`volumePanoramaAz`).
 * 14° — это **не** высота солнца в полдень (в Москве она от 11° в декабре до
 * 58° в июне), а мера самой длинной тени, которую держит плита: низкое солнце
 * кладёт её на полторы высоты стены, и плита выкроена ровно под это.
 */
export const VOLUME_SUN_AT = { az: 90, rise: 14, size: 2.1 };

const DEG = Math.PI / 180;

/** Облака: сторона света, высота, угловой размер. */
const VOLUME_CLOUDS = [
  { az: 25, rise: 16, size: 7 },
  { az: 70, rise: 9, size: 5 },
  { az: 120, rise: 18, size: 8 },
  { az: 165, rise: 11, size: 5.5 },
  { az: 240, rise: 15, size: 6.5 },
  { az: 285, rise: 8, size: 4.5 },
  { az: 320, rise: 19, size: 7.5 },
];

// ——— вещи фона стоят на земле (таск 199, дефект D53) ————————————————————————
//
// Слова заказчика: «всё эти объекты должны быть на одном уровне с фундаментом.
// по сути на „фундаменте“ стоять. что бы я смотрел вдоль горизонта и всегда
// были видны ровно прямо», и про прежнюю сборку — «когда опускаешься на
// фундамент объекты фона (машинки, деревья) уменьшаются, подлетаешь —
// увеличиваются».
//
// **Это четвёртый заход на одно и то же, и первые три не могли сработать.**
// G237 (таск 157) ставил дом на землю, D43 (178) чинил «дом летает», D52 (196)
// сводил кромку плиты с кольцом фона множителем. Все три правили сцену или
// кольцо, а причина была в другом: **у вещей фона не было дальностей вовсе.**
// Панорама рисовалась на небосводе — у вещи были только сторона света и высота
// над горизонтом, — и «насколько она далеко» выходило из её же роста. Отсюда
// ровно то, что заказчик видит: вещь висит на небосводе, а не стоит на земле, а
// множитель T196, отодвигавший кольцо по высоте глаза, менял её размер при
// подъёме и спуске (0,311 на первом этаже против 1,000 в обзоре).
//
// Теперь **у каждой вещи фона есть место на земле**: `x`, `y` в миллиметрах от
// середины чертежа и высота в миллиметрах. Нулевая отметка у них та же, что у
// фундамента, и проекция та же, что у граней сцены (`volumeGroundPoint`).
// «На одном уровне с фундаментом» выходит само: отошёл — вещь уменьшилась,
// подошёл — выросла, и это правда, а не подгонка. Множителя `volumeGroundScale`
// и кольца больше нет ни одного.
//
// **Небо осталось на бесконечности** (`volumeSkyAim`, `volumeSkyPoint`): солнце,
// луна, звёзды, облака и растяжка неба при ходьбе двигаться не должны — у них
// направление, а не место.
//
// ——— докуда расставлено и почему ——————————————————————————————————————————
//
// Числа подобраны так, чтобы вещь читалась тем, чем она есть, из двух мест
// сразу: с уровня глаз (1,6 м) и из обзора (камера в полутора-четырёх десятках
// метров над домом). Мера одна — **угловой размер с уровня глаз**:
//
//   кусты          38…60 м    1,6…2,4 м   — 2…4°, подлесок у кромки участка;
//   ближние деревья 45…75 м   7…12 м      — 8…14°, «прямо перед глазами»;
//   средний ряд    110…190 м  9…16 м      — 4…7°;
//   дальний ряд    380…700 м  11…18 м     — 1,2…2,5°, обжитой горизонт;
//   дорога         150…900 м  ширина 7 м  — уходит к горизонту;
//   река           220…1200 м ширина 24 м;
//   гряды холмов   1,6 и 3,2 км, 45 и 110 м — 1,6° и 2,0°, «небольшой ландшафт»;
//   горы           7,5 км, 700…1400 м      — 5,3…10,6°, дальний план;
//   улицы города   120…800 м, ширина 14 м;
//   ближние дома   220…300 м, 28…38 м      — 5,3…9,8°, многоэтажка в квартале;
//   дальние дома   600…900 м, 18…28 м      — 1,2…2,7°;
//   машины         95…120 м, 1,5 м         — 0,7…0,9°, пятнышки на парковке.
//
// Ближе 38 м не ставится ничего, и это не вкус: земляная плита сцены (D43)
// выкроена по габариту чертежа плюс вынос под тень, у объекта заказчика это
// круг радиусом 26,5 м. Вещь внутри плиты была бы ею срезана — тем самым швом,
// из-за которого затевался T196. Запас до плиты — `VOLUME_BACKDROP_CLEAR_MM`.

/** Миллиметры в метре: фон размечен метрами, а сцена живёт в миллиметрах. */
const VOLUME_M = 1000;

/**
 * Дальше этого зелень фона бледнеет: триста метров — та дальность, с которой
 * воздух уже заметно съедает цвет, а крона перестаёт читаться отдельными
 * пятнами. До таска 199 то же решала высота основания над горизонтом, потому
 * что настоящей дальности у вещи не было.
 */
const VOLUME_TREE_FAR_MM = 300 * VOLUME_M;

/**
 * Самое близкое, что фон ставит на землю, и запас до кромки плиты.
 *
 * Если чертёж большой (плита радиусом больше, чем ближний куст), **вся**
 * расстановка отъезжает одним множителем — `volumeBackdropPlaces`. Множитель
 * зависит только от размера чертежа и ни от чего больше: ни от камеры, ни от
 * высоты глаза, ни от часа. Именно этим он отличается от отменённого
 * `volumeGroundScale`, который дышал от высоты глаза.
 */
export const VOLUME_BACKDROP_NEAR_MM = 32 * VOLUME_M;
export const VOLUME_BACKDROP_CLEAR_MM = 5 * VOLUME_M;

/** Место на земле: сторона света и дальность в метрах. */
function volumeAway(azDeg, metres) {
  return { x: Math.cos(azDeg * DEG) * metres * VOLUME_M, y: Math.sin(azDeg * DEG) * metres * VOLUME_M };
}

/** Вещь, стоящая на земле: место, высота в миллиметрах и порода. */
function volumeStanding(azDeg, metres, heightM, kind) {
  const spot = volumeAway(azDeg, metres);
  return { x: spot.x, y: spot.y, heightMm: heightM * VOLUME_M, awayMm: metres * VOLUME_M, kind };
}

/**
 * Деревья и кустарники: три дальности по всему кругу.
 *
 * Ближний ряд заказчик просил прямо («что бы я смотрел вдоль горизонта и всегда
 * были видны ровно прямо»), дальний держит горизонт обжитым, когда смотришь
 * между ближними. Бледнее дальнее становится само — по настоящей дальности, а
 * не по высоте основания над горизонтом, как считалось в кольце.
 */
export const VOLUME_TREES = [
  // дальний ряд по всему кругу: 230…430 м
  volumeStanding(10, 320, 14, "tree"),
  volumeStanding(48, 380, 12, "spruce"),
  volumeStanding(95, 265, 16, "poplar"),
  volumeStanding(140, 410, 13, "spruce"),
  volumeStanding(185, 295, 15, "tree"),
  volumeStanding(228, 430, 11, "birch"),
  volumeStanding(262, 240, 18, "spruce"),
  volumeStanding(305, 345, 13, "tree"),
  volumeStanding(345, 395, 15, "spruce"),
  // средний ряд: 70…120 м
  volumeStanding(30, 95, 12, "spruce"),
  volumeStanding(78, 118, 14, "poplar"),
  volumeStanding(112, 78, 10, "tree"),
  volumeStanding(171, 104, 13, "birch"),
  volumeStanding(200, 88, 11, "tree"),
  volumeStanding(275, 72, 9, "spruce"),
  volumeStanding(330, 110, 16, "tree"),
  // Берёзовая роща (таск 181: «плюс ещё немного берёз»): три белых ствола
  // подряд в ближнем ряду и ещё три врозь — в среднем и дальнем.
  volumeStanding(16, 36, 9, "birch"),
  volumeStanding(22, 40, 11, "birch"),
  volumeStanding(28, 34, 8, "birch"),
  volumeStanding(145, 82, 12, "birch"),
  volumeStanding(252, 98, 10, "birch"),
  volumeStanding(68, 280, 12, "birch"),
  // ближний ряд — то, о чём просил заказчик: 33…50 м
  volumeStanding(62, 40, 11, "tree"),
  volumeStanding(128, 44, 10, "birch"),
  volumeStanding(155, 34, 9, "spruce"),
  volumeStanding(212, 50, 12, "poplar"),
  volumeStanding(248, 38, 10, "tree"),
  volumeStanding(352, 47, 12, "tree"),
  // кустарники — ниже деревьев и ближе к земле: 32…45 м
  volumeStanding(44, 35, 2.1, "bush"),
  volumeStanding(88, 32, 1.8, "bush"),
  volumeStanding(133, 42, 2.4, "bush"),
  volumeStanding(176, 33, 1.6, "bush"),
  volumeStanding(219, 38, 2.2, "bush"),
  volumeStanding(295, 32, 1.9, "bush"),
  volumeStanding(315, 45, 2.3, "bush"),
];
/**
 * Узлы полосы, лежащей на земле: середина и половина ширины.
 *
 * У полосы два края, и считаются они **поперёк её же хода** — по направлению от
 * узла к узлу. Поэтому изгиб дороги не растягивает её ширину: семь метров
 * остаются семью метрами и на повороте.
 */
function volumeBandNodes(points, widthM) {
  const middles = points.map(([az, away]) => volumeAway(az, away));
  const half = (widthM / 2) * VOLUME_M;
  return middles.map((spot, index) => {
    const prev = middles[Math.max(0, index - 1)];
    const next = middles[Math.min(middles.length - 1, index + 1)];
    const dx = next.x - prev.x;
    const dy = next.y - prev.y;
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;
    return {
      x: spot.x,
      y: spot.y,
      awayMm: Math.hypot(spot.x, spot.y),
      left: { x: spot.x + nx * half, y: spot.y + ny * half },
      right: { x: spot.x - nx * half, y: spot.y - ny * half },
    };
  });
}

/**
 * Дорога: приходит с запада-северо-запада и уводит на северо-восток. Ширина
 * семь метров — две полосы просёлка; ближнее колено в полутора сотнях метров,
 * дальнее — почти в километре.
 */
export const VOLUME_ROAD = volumeBandNodes(
  [
    [286, 95],
    [300, 135],
    [315, 195],
    [330, 275],
    [345, 370],
    [358, 470],
    [12, 560],
    [26, 640],
  ],
  9,
);

/** Река: с юго-востока к югу, шире дороги и извилистее — вода не спрямлена. */
export const VOLUME_RIVER = volumeBandNodes(
  [
    [118, 105],
    [131, 150],
    [142, 205],
    [156, 275],
    [168, 360],
    [179, 455],
    [191, 560],
    [204, 670],
  ],
  60,
);

/**
 * Гряда холмов (G232): вереница узлов на своей дальности, у каждого высота над
 * землёй. Рисуется силуэтом — низ по земле, верх по гребню.
 *
 * Мера прежняя, «небольшой ландшафт»: дальняя гряда 110 м в 3,2 км (2,0°),
 * ближняя 45 м в 1,6 км (1,6°). Для сравнения, ближнее дерево в полусотне
 * метров — 11°, то есть холмы остались фоном, а не стеной над домом.
 */
function volumeRidge(rises, away, step) {
  return rises.map((rise, index) => {
    const spot = volumeAway((index * 360) / rises.length, away);
    return { x: spot.x, y: spot.y, awayMm: away * VOLUME_M, heightMm: rise * step * VOLUME_M };
  });
}

export const VOLUME_HILLS = [
  {
    far: true,
    color: VOLUME_HILL_FAR,
    awayM: 2400,
    nodes: volumeRidge([1.5, 2.6, 2.1, 1.2, 1.9, 2.4, 1.4, 2.0, 2.6, 1.7, 1.1, 2.2, 1.8, 2.5], 2400, 34),
  },
  {
    far: false,
    color: VOLUME_HILL_NEAR,
    awayM: 1200,
    nodes: volumeRidge([0.9, 0.5, 1.4, 1.6, 0.8, 1.1, 1.5, 0.6, 1.2, 1.55, 0.95, 0.7, 1.35, 1.05], 1200, 22),
  },
];

// ——— заснеженные горы напротив солнца (G238) ——————————————————————————————
//
// Слова заказчика: «напротив солнца на фоне на горизонте нарисуй заснеженные
// вершины гор».
//
// **«Напротив солнца» — буквально**: сторона света у гряды берётся у солнца и
// поворачивается на половину оборота. Поэтому человек, стоящий спиной к солнцу,
// видит горы, и объяснять это ему не нужно. Подвинется солнце — уедут и горы,
// второго числа для этого не заведено.
//
// **Дальше всего.** Порядка по дальности у панорамы нет и не нужно: дальность
// здесь — это **порядок рисования**, записанный один раз в
// `volumeDrawBackdrop`, а не сортировка на каждом кадре. Горы стоят в нём сразу
// после неба: за ними только облака и солнце, а холмы, полосы, зелень и деревья
// ложатся поверх. Гряда от этого уходит за всё, а не торчит перед ближним
// рядом.
//
// **Свет.** Солнце напротив, значит к зрителю гора повёрнута теневой стороной —
// но тень не чернота: камень взят холодным серо-синим, и дальний ряд бледнее
// ближнего, как всё дальнее в этой панораме. Светлая у горы только шапка: снег
// светится и в тени, и этим одним он и показан — «верх вершины светлее
// остального», подробностей не нужно.

const VOLUME_MOUNTAIN_FAR_ROCK = "#9dabbf";
const VOLUME_MOUNTAIN_FAR_SNOW = "#e7eef7";
const VOLUME_MOUNTAIN_ROCK = "#8491a7";
const VOLUME_MOUNTAIN_SNOW = "#f1f6fc";

/**
 * Гряда: несколько вершин разной высоты, перекрывающих друг друга. `at` — сдвиг
 * по стороне света от середины гряды, `height` — высота вершины **в метрах**,
 * `half` — половина ширины подножия в метрах, `snow` — какая доля вершины под
 * снегом.
 *
 * Дальность у обоих рядов одна — 7,5 км; разница в высоте, ширине и цвете.
 * Гора в 1,4 км высотой с этого расстояния видна под 10,6°, то есть выше
 * холмов (2°), но втрое ниже ближнего дерева в полусотне метров (11°): дальний
 * план, а не стена над домом.
 */
function volumeRange(peaks, away, rock, snowColor, far) {
  return peaks.map(([at, height, half, snow]) => {
    const az = (VOLUME_SUN_AT.az + 180 + at + 360) % 360;
    const spot = volumeAway(az, away);
    return {
      x: spot.x,
      y: spot.y,
      awayMm: away * VOLUME_M,
      heightMm: height * VOLUME_M,
      halfMm: half * VOLUME_M,
      snow,
      rock,
      snowColor,
      // Дальний ряд бледнее ближнего, и красит его час (`mood.palette`).
      far: Boolean(far),
    };
  });
}

export const VOLUME_MOUNTAIN_AWAY_M = 7500;

export const VOLUME_MOUNTAINS = [
  // Дальний ряд — выше и бледнее, и он же рисуется первым.
  ...volumeRange(
    [
      [-19, 1150, 1500, 0.34],
      [-4, 1400, 1750, 0.4],
      [13, 1000, 1350, 0.3],
    ],
    VOLUME_MOUNTAIN_AWAY_M,
    VOLUME_MOUNTAIN_FAR_ROCK,
    VOLUME_MOUNTAIN_FAR_SNOW,
    true,
  ),
  // Ближний ряд — ниже и темнее: он перекрывает подножия дальнего.
  ...volumeRange(
    [
      [-27, 760, 1150, 0.26],
      [-11, 940, 1300, 0.3],
      [4, 810, 1250, 0.26],
      [21, 890, 1400, 0.28],
    ],
    VOLUME_MOUNTAIN_AWAY_M,
    VOLUME_MOUNTAIN_ROCK,
    VOLUME_MOUNTAIN_SNOW,
    false,
  ),
];

/**
 * Кусты и деревья **по берегам реки** (G232). Слова заказчика: «а у реки кусты
 * и деревья по берегам».
 *
 * Считаются из самих узлов реки, а не выписаны второй таблицей рядом: сдвинь
 * реку — зелень уйдёт вместе с ней. Правила те же, что были, только в метрах:
 * зелень стоит **у самой кромки** (отступ в полширины реки от края), на
 * **обоих** берегах, а высота падает с дальностью — у ближнего колена ива в
 * восемь метров, у дальнего куст в полтора. Вид чередуется по узлу: ряд
 * одинаковых кустов читался бы забором.
 */
export function volumeRiverGreens(river) {
  const greens = [];
  const kinds = ["bush", "willow", "bush", "birch", "willow", "spruce"];
  const far = river[river.length - 1].awayMm;
  river.forEach((node, index) => {
    // Дальние колена реки у горизонта: там зелень выродилась бы в точку, и её
    // нет вовсе — пустой горизонт честнее мусора на нём.
    if (node.awayMm > far * 0.8) return;
    const share = 1 - node.awayMm / far;
    const heightMm = (1.6 + share * 6.4) * VOLUME_M;
    const bank = (edge, sign, grow, kind) => {
      const dx = edge.x - node.x;
      const dy = edge.y - node.y;
      greens.push({
        x: edge.x + dx * sign,
        y: edge.y + dy * sign,
        awayMm: Math.hypot(edge.x + dx * sign, edge.y + dy * sign),
        heightMm: heightMm * grow,
        kind,
      });
    };
    bank(node.left, 0.35, 1, kinds[index % kinds.length]);
    bank(node.right, 0.35, 0.78, kinds[(index + 1) % kinds.length]);
    // У ближних колен берег **гуще**: там видно отдельные кусты, и один куст на
    // берег читался бы случайной кочкой, а не зарослями у воды.
    if (index > 1) return;
    bank(node.left, 1.1, 0.62, "bush");
    bank(node.right, 1.1, 0.5, "bush");
  });
  return greens;
}

export const VOLUME_RIVER_GREENS = volumeRiverGreens(VOLUME_RIVER);

// ——— две камеры: небо на бесконечности, земля на своих местах ————————————
//
// Прицелов теперь два, и разница между ними — это разница между «направлением»
// и «местом».
//
//   **Небо** (`volumeSkyAim`, `volumeSkyPoint`) знает только направление.
//   Солнце, луна, звёзды, облака и растяжка неба при ходьбе стоять обязаны:
//   отойти от солнца на десять метров нельзя. Множителя `ground`, которым таск
//   196 отодвигал кольцо по высоте глаза, здесь больше нет — он и был дефектом
//   D53.
//
//   **Земля** (`volumeGroundAim`, `volumeGroundPoint`) знает место: точка в
//   миллиметрах чертежа, та же система координат и та же проекция, что у граней
//   сцены. Поэтому дерево в полусотне метров ведёт себя как дерево: подошёл —
//   выросло, отошёл — уменьшилось, поднялся на второй этаж — осталось тем же.

/**
 * Прицел земли: базис камеры, фокус, середина окна и **место камеры**.
 *
 * Считается один раз на кадр, как и небесный. Место здесь обязательно: у вещи
 * фона есть свои координаты, и без места камеры их не во что переводить.
 */
export function volumeGroundAim(camera, box) {
  return {
    basis: volumeBasis(camera),
    focal: volumeFocal(box),
    halfWidth: box.width / 2,
    halfHeight: box.height / 2,
    at: camera.at,
  };
}

/**
 * Точка земли в экран — **той же проекцией, что грани сцены**.
 *
 * `null` — точка за ближней плоскостью (`VOLUME_NEAR_MM`), то есть за спиной
 * или впритык к глазу. На кольце отбрасывать было нечего (у направления нет
 * «за спиной» в половине случаев — есть, но половина круга всегда считалась),
 * а у вещей с настоящими местами за спиной оказывается добрая половина, и это
 * экономит кадр.
 *
 * `scale` — сколько экранных точек даёт **миллиметр** на этой дальности.
 * Отвесный отрезок высотой `h` занимает на экране ровно `h · scale` точек, и
 * этим считаются все размеры вещей фона: высота дерева, ширина дома, кузов
 * машины. Перспектива у них от этого та же, что у стен дома.
 */
export function volumeGroundPoint(aim, xMm, yMm, zMm = 0) {
  const dx = xMm - aim.at.x;
  const dy = yMm - aim.at.y;
  const dz = (zMm || 0) - aim.at.z;
  const { basis, focal } = aim;
  const depth = dx * basis.fwd.x + dy * basis.fwd.y + dz * basis.fwd.z;
  if (!(depth > VOLUME_NEAR_MM)) return null;
  const right = dx * basis.right.x + dy * basis.right.y + dz * basis.right.z;
  const up = dx * basis.up.x + dy * basis.up.y + dz * basis.up.z;
  const scale = focal / depth;
  return { x: aim.halfWidth + right * scale, y: aim.halfHeight - up * scale, scale, depth };
}

/**
 * Насколько человек далёк от земляной плиты в плане: ноль — стоит на ней.
 *
 * Этим числом решается порядок рисования (см. `volumeDrawBackdrop`): вещь фона,
 * которая **ближе** плиты, не может быть закрыта домом — дом стоит на плите.
 */
export function volumePlateGap(land, at) {
  if (!land || !at) return 0;
  const dx = Math.max(Number(land.minX) - at.x, 0, at.x - Number(land.maxX));
  const dy = Math.max(Number(land.minY) - at.y, 0, at.y - Number(land.maxY));
  return Math.hypot(dx, dy);
}

/**
 * Расстановка фона под этот чертёж.
 *
 * Числа таблиц писаны от середины чертежа и рассчитаны на обычную квартиру:
 * ближний куст в 38 м, плита заказчика радиусом 26,5 м. У большого чертежа
 * (ангар, посёлок) плита вырастает, и вещь, писанная на 38 м, оказалась бы
 * внутри неё — то есть срезанной её кромкой. Поэтому вся расстановка отъезжает
 * **одним множителем**, и он зависит **только от размера чертежа**: ни от
 * камеры, ни от высоты глаза, ни от часа. Этим он и отличается от отменённого
 * `volumeGroundScale`, из-за которого фон дышал при подъёме (D53).
 *
 * Множитель — единица в обычном случае, и тогда таблицы отдаются как есть, без
 * копирования.
 */
const VOLUME_BACKDROP_CACHE = new Map();

export function volumeBackdropPush(land) {
  if (!land) return 1;
  const reach = Math.hypot((Number(land.maxX) - Number(land.minX)) / 2, (Number(land.maxY) - Number(land.minY)) / 2);
  if (!(reach > 0)) return 1;
  const want = (reach + VOLUME_BACKDROP_CLEAR_MM) / VOLUME_BACKDROP_NEAR_MM;
  // Шаг множителя — десятая доля: иначе каждый чертёж получал бы свою
  // расстановку, а кэш — свою запись.
  return Math.max(1, Math.ceil(want * 10) / 10);
}

function volumePushSpot(spot, push) {
  return { ...spot, x: spot.x * push, y: spot.y * push, awayMm: (spot.awayMm || 0) * push };
}

function volumePushBand(nodes, push) {
  return nodes.map((node) => ({
    ...volumePushSpot(node, push),
    left: { x: node.left.x * push, y: node.left.y * push },
    right: { x: node.right.x * push, y: node.right.y * push },
  }));
}

/**
 * Вещи фона на земле для этого чертежа. Таблицы — общие, множитель — свой.
 *
 * Высоты **не растягиваются**: отодвинутое дерево остаётся деревом в девять
 * метров, просто видно его мельче. Растянуть высоту значило бы вернуть кольцо,
 * у которого размер зависел не от вещи, а от того, где стоит смотрящий.
 */
export function volumeBackdropPlaces(land) {
  const push = volumeBackdropPush(land);
  const kept = VOLUME_BACKDROP_CACHE.get(push);
  if (kept) return kept;
  const made =
    push === 1
      ? {
          push,
          trees: VOLUME_TREES,
          road: VOLUME_ROAD,
          river: VOLUME_RIVER,
          greens: VOLUME_RIVER_GREENS,
          hills: VOLUME_HILLS,
          mountains: VOLUME_MOUNTAINS,
          city: VOLUME_CITY,
          streets: VOLUME_CITY_STREETS,
          marks: VOLUME_CITY_MARKS,
          park: VOLUME_CITY_PARK,
          banners: VOLUME_CITY_BANNER_PLACES,
          cityGreens: VOLUME_CITY_GREENS,
        }
      : {
          push,
          trees: VOLUME_TREES.map((tree) => volumePushSpot(tree, push)),
          road: volumePushBand(VOLUME_ROAD, push),
          river: volumePushBand(VOLUME_RIVER, push),
          greens: VOLUME_RIVER_GREENS.map((green) => volumePushSpot(green, push)),
          hills: VOLUME_HILLS.map((ridge) => ({
            ...ridge,
            nodes: ridge.nodes.map((node) => volumePushSpot(node, push)),
          })),
          mountains: VOLUME_MOUNTAINS.map((peak) => ({
            ...volumePushSpot(peak, push),
            halfMm: peak.halfMm * push,
          })),
          city: VOLUME_CITY.map((block) => ({
            ...volumePushSpot(block, push),
            halfMm: block.halfMm * push,
            deepMm: block.deepMm * push,
          })),
          streets: VOLUME_CITY_STREETS.map((street) => volumePushBand(street, push)),
          marks: VOLUME_CITY_MARKS.map((street) => volumePushBand(street, push)),
          park: VOLUME_CITY_PARK.map((car) => volumePushSpot(car, push)),
          banners: VOLUME_CITY_BANNER_PLACES.map((banner) => ({
            ...volumePushSpot(banner, push),
            halfMm: banner.halfMm * push,
          })),
          cityGreens: VOLUME_CITY_GREENS.map((green) => volumePushSpot(green, push)),
        };
  VOLUME_BACKDROP_CACHE.set(push, made);
  return made;
}

/**
 * Прицел панорамы: базис камеры, фокус и середина окна. Считается один раз на
 * кадр — все вещи фона смотрят через него.
 *
 * `ground` — множитель, которым земля панорамы отодвинута за кромку земли сцены
 * (D52, `volumeGroundScale`). Единица — прицел, каким он был до таска 196;
 * светило, звёзды и облака смотрят **через него**, а не через земной: небу
 * кромка плиты не указ.
 */
export function volumeSkyAim(camera, box) {
  return {
    basis: volumeBasis(camera),
    focal: volumeFocal(box),
    halfWidth: box.width / 2,
    halfHeight: box.height / 2,
  };
}

/**
 * Направление панорамы в точку экрана. `null` — направление за спиной.
 *
 * `scale` — сколько экранных точек даёт один радиан углового размера рядом с
 * этой точкой: им считаются размеры облака и дерева, и из него само собой
 * выходит, что у края широкого окна вещи крупнее, чем в середине, — так же, как
 * у граней сцены, и ровно потому, что камера одна и та же.
 */
export function volumeSkyPoint(aim, azimuthDeg, riseDeg) {
  const rise = riseDeg * DEG;
  const azimuth = azimuthDeg * DEG;
  const flat = Math.cos(rise);
  const direction = { x: flat * Math.cos(azimuth), y: flat * Math.sin(azimuth), z: Math.sin(rise) };
  const { basis, focal } = aim;
  const depth = direction.x * basis.fwd.x + direction.y * basis.fwd.y + direction.z * basis.fwd.z;
  if (!(depth > VOLUME_SKY_NEAR)) return null;
  const right = direction.x * basis.right.x + direction.y * basis.right.y + direction.z * basis.right.z;
  const up = direction.x * basis.up.x + direction.y * basis.up.y + direction.z * basis.up.z;
  const scale = focal / depth;
  return { x: aim.halfWidth + right * scale, y: aim.halfHeight - up * scale, scale };
}

/**
 * Прогоны полосы: вереницы узлов, попавших в кадр подряд.
 *
 * Узел за спиной `volumeGroundPoint` отдаёт как `null`, и полоса от этого
 * рвётся — у дороги длиной в километр это обычное дело, а у вещей с настоящими
 * местами за спиной оказывается добрая половина. Поэтому полоса рисуется не
 * одним многоугольником, а прогонами: соседние узлы делят ребро ровно, и стыка
 * между ними не видно.
 *
 * Чистая и вынесена наружу: разрыв полосы на краю кадра глазами не поймаешь.
 */
export function volumeStripRuns(aim, nodes) {
  const runs = [];
  let run = null;
  for (const node of nodes) {
    const top = volumeGroundPoint(aim, node.left.x, node.left.y, 0);
    const bottom = volumeGroundPoint(aim, node.right.x, node.right.y, 0);
    if (!top || !bottom) {
      run = null;
      continue;
    }
    if (!run) {
      run = [];
      runs.push(run);
    }
    run.push({ top, bottom });
  }
  return runs.filter((item) => item.length > 1);
}

// Заливка полосы: одна растяжка от ближнего края к дальнему. Ближний край — низ
// первого узла, дальний — верх последнего: так растяжка идёт вдоль полосы, а не
// поперёк, и выцветание получается по дальности, а не по высоте.
function volumeStripFill(ctx, run, near, far) {
  const from = run[0].bottom;
  const to = run[run.length - 1].top;
  const fade = ctx.createLinearGradient(from.x, from.y, to.x, to.y);
  fade.addColorStop(0, near);
  fade.addColorStop(1, far);
  return fade;
}

function volumeDrawStrip(ctx, aim, nodes, paint) {
  for (const run of volumeStripRuns(aim, nodes)) {
    ctx.beginPath();
    ctx.moveTo(run[0].top.x, run[0].top.y);
    for (let index = 1; index < run.length; index += 1) ctx.lineTo(run[index].top.x, run[index].top.y);
    for (let index = run.length - 1; index >= 0; index -= 1) ctx.lineTo(run[index].bottom.x, run[index].bottom.y);
    ctx.closePath();
    ctx.fillStyle = paint(run);
    ctx.fill();
  }
}

/**
 * Гряда холмов силуэтом: низ по земле, верх по гребню. Та же разбивка на
 * прогоны, что у полосы, — гряда идёт по кругу, и половина её за спиной.
 */
function volumeDrawRidge(ctx, aim, ridge, palette) {
  let run = null;
  const runs = [];
  for (const node of ridge.nodes) {
    const foot = volumeGroundPoint(aim, node.x, node.y, 0);
    const crest = volumeGroundPoint(aim, node.x, node.y, node.heightMm);
    if (!foot || !crest) {
      run = null;
      continue;
    }
    if (!run) {
      run = [];
      runs.push(run);
    }
    run.push({ foot, crest });
  }
  for (const line of runs) {
    if (line.length < 2) continue;
    ctx.beginPath();
    ctx.moveTo(line[0].crest.x, line[0].crest.y);
    for (let index = 1; index < line.length; index += 1) ctx.lineTo(line[index].crest.x, line[index].crest.y);
    for (let index = line.length - 1; index >= 0; index -= 1) ctx.lineTo(line[index].foot.x, line[index].foot.y);
    ctx.closePath();
    ctx.fillStyle = ridge.far ? palette.hillFar : palette.hillNear;
    ctx.fill();
  }
}

/**
 * Фон кадра: небо со светилом, звёздами и облаками, земля, а дальше то, что
 * выбрано видом фона (G273) — ничего, природа или город.
 *
 * Возвращается строка горизонта: по ней окно рисует миникарту и подписи, и
 * второго её счёта в сборке нет.
 *
 * `mood` — снимок часа (`volumeMood`), посчитанный **не здесь**: кадр про время
 * не считает ничего, он берёт готовые цвета. `land` — прямоугольник земляной
 * плиты (`scene.landMm`): по нему решается расстановка и порядок рисования.
 *
 * ——— земля до горизонта ———
 *
 * Земля — **одна заливка** ниже строки горизонта, и это буквально та земля,
 * которая до горизонта и доходит: строка горизонта и есть место, куда уходит
 * плоскость на уровне глаз. Сетки узлов здесь нет и не нужно — у ровной земли
 * без рельефа делить нечего, а тысячи точек на кадр стоили бы дороже всего
 * остального фона вместе взятого. Плита сцены (`VOLUME_LAYER_BASE`) лежит
 * внутри этой заливки тем же тоном (G237) и несёт на себе тень дома и
 * солнечные пятна; кромки между ними не видно ни при каком взгляде, потому что
 * это один цвет, покрашенный одним часом.
 *
 * ——— порядок рисования (таск 199) ———
 *
 * Вещи фона **не идут в дерево порядка сцены** (`volumeOrderTree`), и это
 * решение, а не упущение: дерево строится при сборке сцены (9 мс на объекте
 * заказчика), и класть в него десятки вещей фона значило бы пересобирать его
 * при каждой правке чертежа ради того, что от чертежа не зависит. Вместо дерева
 * — **одно правило о дальности, которое всегда верно**:
 *
 *   вещь фона стоит **снаружи плиты**, а дом стоит **на плите**;
 *   значит дом ближе смотрящего только тогда, когда смотрящий **дальше плиты**,
 *   и ровно настолько, насколько вещь ближе её кромки.
 *
 * Отсюда два прохода. `volumeDrawBackdrop` рисует небо, землю и всё, что
 * **дальше** ближней кромки плиты, — дом его закроет, и это правда.
 * `volumeDrawBackdropNear` рисует то, что **ближе** кромки, и зовётся оно уже
 * после сцены: такую вещь дом закрыть не может, она перед ним. Внутри плиты
 * (человек ходит по дому) ближе кромки нет ничего, и второй проход пуст.
 *
 * Цена ошибки названа прямо: вещь, которая дальше ближней кромки, но ближе
 * дальней стены дома, рисуется под домом. Случается это только в обзоре с
 * отлёта, где дом и есть то, на что смотрят.
 */
export function volumeDrawBackdrop(ctx, box, camera, mood = null, land = null) {
  const hour = mood || VOLUME_MOOD_NOON;
  const palette = hour.palette;
  const horizonY = volumeHorizon(camera, box);
  const line = Math.max(-box.height, Math.min(box.height * 2, horizonY));
  const sky = ctx.createLinearGradient(0, Math.min(0, line - box.height), 0, line);
  sky.addColorStop(0, hour.sky.top);
  sky.addColorStop(1, hour.sky.low);
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, box.width, Math.max(0, line));
  // Небо знает направление, земля — место. Разницу между этими двумя прицелами
  // и чинит таск 199 (D53).
  const above = volumeSkyAim(camera, box);
  // Светило и звёзды — до земли: они за горизонтом и обрезаются ею.
  if (hour.stars > 0) volumeDrawStars(ctx, above, hour);
  volumeDrawSun(ctx, above, hour);
  volumeDrawMoon(ctx, above, hour);
  if (hour.kind !== "plain") for (const cloud of VOLUME_CLOUDS) volumeDrawCloud(ctx, above, cloud, palette);
  if (line < box.height) {
    // Земля — плоским тоном (G237): тем же, которым красится плита чертежа, и
    // дом от этого стоит на ней, а не на доске. Час красит обе одной краской
    // (`volumeTintRgb`), поэтому стык не виден и в полночь.
    ctx.fillStyle = palette.land;
    ctx.fillRect(0, Math.max(0, line), box.width, box.height - Math.max(0, line));
  }
  if (hour.kind === "plain") return line;
  volumeDrawGround(ctx, box, camera, hour, land, false);
  return line;
}

/**
 * Второй проход фона: то, что **ближе** кромки плиты. Зовётся после сцены —
 * дом такую вещь закрыть не может (разбор у `volumeDrawBackdrop`).
 *
 * Внутри плиты проход пуст, и это обычный случай: человек ходит по дому.
 */
export function volumeDrawBackdropNear(ctx, box, camera, mood = null, land = null) {
  const hour = mood || VOLUME_MOOD_NOON;
  if (hour.kind === "plain") return;
  if (!(volumePlateGap(land, camera.at) > 0)) return;
  volumeDrawGround(ctx, box, camera, hour, land, true);
}

/**
 * Вещи фона, стоящие на земле, одним правилом на все три вида фона.
 *
 * `near` — какой проход: `false` — всё, что дальше ближней кромки плиты,
 * `true` — что ближе неё.
 *
 * **Порядок внутри прохода — по дальности, от дальнего к ближнему**, и считать
 * его дёшево: дальность у вещи своя, а не выведенная из её роста. Плоское
 * (дорога, река, улицы, разметка) рисуется до стоящего — оно лежит на земле и
 * закрыть собой дерево не может.
 */
function volumeDrawGround(ctx, box, camera, hour, land, near) {
  const palette = hour.palette;
  const aim = volumeGroundAim(camera, box);
  const places = volumeBackdropPlaces(land);
  const gap = volumePlateGap(land, camera.at);
  const at = camera.at;
  const mine = (spot) => {
    if (!(gap > 0)) return !near;
    const away = Math.hypot(spot.x - at.x, spot.y - at.y);
    return near ? away < gap : away >= gap;
  };
  const standing = [];
  const take = (list, paint) => {
    for (let index = 0; index < list.length; index += 1) {
      const spot = list[index];
      if (!mine(spot)) continue;
      standing.push({ depth: Math.hypot(spot.x - at.x, spot.y - at.y), spot, index, paint });
    }
  };
  if (hour.kind === "city") {
    if (!near) {
      for (let index = 0; index < places.streets.length; index += 1) {
        volumeDrawStrip(ctx, aim, places.streets[index], (run) =>
          volumeStripFill(ctx, run, palette.asphalt, palette.asphaltFar),
        );
        volumeDrawStrip(ctx, aim, places.marks[index], () => palette.mark);
      }
    }
    take(places.city, (spot, index) => volumeDrawBlock(ctx, aim, spot, index, hour));
    take(places.park, (spot) => volumeDrawCar(ctx, aim, spot, palette));
    take(places.banners, (spot) => volumeDrawBanner(ctx, aim, spot, hour));
    take(places.cityGreens, (spot) => volumeDrawTree(ctx, aim, spot, palette));
  } else {
    if (!near) {
      // Горы — самое далёкое, что есть в панораме: раньше всего, что стоит на
      // земле (G238). Полосы уходят за гряды, поэтому гряды после них.
      for (const peak of places.mountains) volumeDrawPeak(ctx, aim, peak, palette);
      volumeDrawStrip(ctx, aim, places.road, (run) =>
        volumeStripFill(ctx, run, palette.roadNear, palette.roadFar),
      );
      volumeDrawStrip(ctx, aim, places.river, (run) =>
        volumeStripFill(ctx, run, palette.riverNear, palette.riverFar),
      );
      for (const ridge of places.hills) volumeDrawRidge(ctx, aim, ridge, palette);
    }
    take(places.greens, (spot) => volumeDrawTree(ctx, aim, spot, palette));
    take(places.trees, (spot) => volumeDrawTree(ctx, aim, spot, palette));
  }
  // Порядок внутри прохода — по дальности, от дальнего к ближнему. Считать его
  // дёшево: дальность у вещи своя, а не выведенная из её роста, и сортируются
  // десятки вещей, а не тысячи граней.
  standing.sort((one, two) => two.depth - one.depth);
  for (const item of standing) item.paint(item.spot, item.index);
}

// ——— город (G273) ————————————————————————————————————————————————————————
//
// Улицы, парковка, дома, окна. Порядок тот же по смыслу, что у природы: улицы
// лежат на земле и уходят к горизонту, дома стоят на них, машины — перед
// ближними домами, зелень вдоль улиц. Дальний ряд домов рисуется раньше
// ближнего — он за ним.
//
// **Неоновых вывесок на домах нет** — требование G337 (таск 226) сняло их:
// заказчик завёл их в таске 206 словами «добавь туда рекламные баннеры и
// неоновые вывески», посмотрел город в объёме и решил убрать. Снято начисто:
// ни цвета неона в палитре, ни ветки «если вывеска», ни поля у дома. Щиты у
// дорог остались и ночью по-прежнему не светятся — про них речи не было.
// Светится ночью одно — окна.
/**
 * Дом города — **коробка** (дефект D57): лицо, бок и крыша.
 *
 * Долг таска 199 назывался так: «бок у дома города пропал, дом читается щитом».
 * Заказчик увидел это первым же взглядом — «плоские дома (о чем и говорил)».
 * Теперь у дома есть глубина, и в кадр идут **две стены из четырёх** — те, что
 * повёрнуты к камере; какие именно, решает сама камера, поэтому при облёте дом
 * поворачивается, а не схлопывается.
 *
 * Окна рисуются **на каждой видимой стене** своей сеткой, посчитанной из метров
 * (`VOLUME_CITY_FLOOR_MM`, `VOLUME_CITY_BAY_MM`), — у бока секций меньше, чем у
 * лица, ровно во столько раз, во сколько он у́же.
 *
 * Светящееся окно **не красится часом** (светит — значит не темнеет).
 */
function volumeDrawBlock(ctx, aim, block, index, hour) {
  const palette = hour.palette;
  // Лицо дома стоит поперёк взгляда на него, глубина уходит от середины
  // чертежа: `u` — вдоль лица, `f` — в глубину.
  const len = Math.hypot(block.x, block.y) || 1;
  const fx = block.x / len;
  const fy = block.y / len;
  const ux = -fy;
  const uy = fx;
  const deep = block.deepMm / 2;
  const corner = (alongSign, deepSign) => ({
    x: block.x + ux * block.halfMm * alongSign + fx * deep * deepSign,
    y: block.y + uy * block.halfMm * alongSign + fy * deep * deepSign,
  });
  // Четыре угла коробки в плане: лицо смотрит на дом (к середине чертежа).
  const plan = {
    faceLeft: corner(1, -1),
    faceRight: corner(-1, -1),
    backLeft: corner(1, 1),
    backRight: corner(-1, 1),
  };
  const walls = [
    { from: plan.faceLeft, to: plan.faceRight, wide: block.halfMm * 2, face: true },
    { from: plan.faceRight, to: plan.backRight, wide: block.deepMm, face: false },
    { from: plan.backRight, to: plan.backLeft, wide: block.halfMm * 2, face: false },
    { from: plan.backLeft, to: plan.faceLeft, wide: block.deepMm, face: false },
  ];
  const at = aim.at;
  const shown = [];
  for (const wall of walls) {
    // Стена видна, если её наружная нормаль смотрит на камеру. Обход коробки
    // задан по кругу (лицо → правый бок → зад → левый бок), и при этом обходе
    // наружу смотрит **правый** перпендикуляр ребра: у лица он уходит к
    // середине чертежа, то есть к дому, как и положено лицу.
    const ex = wall.to.x - wall.from.x;
    const ey = wall.to.y - wall.from.y;
    const nx = ey;
    const ny = -ex;
    const mx = (wall.from.x + wall.to.x) / 2;
    const my = (wall.from.y + wall.to.y) / 2;
    if (nx * (at.x - mx) + ny * (at.y - my) <= 0) continue;
    const left = volumeGroundPoint(aim, wall.from.x, wall.from.y, block.heightMm);
    const right = volumeGroundPoint(aim, wall.to.x, wall.to.y, block.heightMm);
    const footLeft = volumeGroundPoint(aim, wall.from.x, wall.from.y, 0);
    const footRight = volumeGroundPoint(aim, wall.to.x, wall.to.y, 0);
    if (!left || !right || !footLeft || !footRight) continue;
    shown.push({ ...wall, left, right, footLeft, footRight, depth: Math.hypot(mx - at.x, my - at.y) });
  }
  if (shown.length === 0) return;
  // Дальняя стена ложится первой: у коробки их видно самое большее две, и
  // спорить им не о чем, кроме порядка.
  shown.sort((one, two) => two.depth - one.depth);
  const lit = hour.cityLit;
  for (let wallIndex = 0; wallIndex < shown.length; wallIndex += 1) {
    const wall = shown[wallIndex];
    const { left, right, footLeft, footRight } = wall;
    // Бок темнее лица: та же мера, что у боковых стен города до таска 206.
    const flat = wall.face || shown.length === 1;
    ctx.fillStyle = flat
      ? block.far
        ? palette.wallFar
        : palette.wall
      : block.far
        ? palette.wallSideFar
        : palette.wallSide;
    ctx.beginPath();
    ctx.moveTo(left.x, left.y);
    ctx.lineTo(right.x, right.y);
    ctx.lineTo(footRight.x, footRight.y);
    ctx.lineTo(footLeft.x, footLeft.y);
    ctx.closePath();
    ctx.fill();
    // Окна: сетка по этажам и секциям, с полями по краям стены. Точки
    // считаются по самой стене (`volumeCitySpot`), поэтому сетка едет вместе с
    // перспективой.
    const bays = Math.max(2, Math.round(wall.wide / VOLUME_CITY_BAY_MM));
    const pad = 0.14;
    const cellX = (1 - pad * 2) / bays;
    const cellY = (1 - pad * 2) / block.floors;
    const seed = index * 4 + wallIndex;
    // Сколько точек занимает окно на этой стене. От этого зависит, рисовать ли
    // каждое окно своим прямоугольником или целым этажом сразу (см. ниже).
    const across = Math.hypot(right.x - left.x, right.y - left.y) / Math.max(1, bays);
    // **Дальний дом рисуется этажами, а не окнами** (цена кадра, таск 206).
    // Окно в полторы точки и так сливается с соседним в полосу, и полоса эта
    // рисуется одной заливкой вместо `bays`; поимённо дорисовываются только
    // **светящиеся** окна — ночью их доля не больше `VOLUME_CITY_LIT_MAX`, а
    // днём нет вовсе. Вблизи (окно шире трёх точек) всё как было: каждое своим.
    const rows = across < VOLUME_CITY_WINDOW_PX;
    for (let floor = 0; floor < block.floors; floor += 1) {
      const sy = pad + cellY * (floor + 0.14);
      if (rows) {
        const a = volumeCitySpot(left, right, footLeft, footRight, pad + cellX * 0.12, sy);
        const b = volumeCitySpot(
          left,
          right,
          footLeft,
          footRight,
          pad + cellX * (bays - 1 + 0.88),
          sy + cellY * 0.72,
        );
        const width = b.x - a.x;
        const height = b.y - a.y;
        if (!(Math.abs(width) > 0.6) || !(Math.abs(height) > 0.6)) continue;
        ctx.fillStyle = palette.glass;
        ctx.fillRect(Math.min(a.x, b.x), Math.min(a.y, b.y), Math.abs(width), Math.abs(height));
      }
      for (let bay = 0; bay < bays; bay += 1) {
        const alight = volumeCityWindowLit(seed, floor, bay, lit);
        if (rows && !alight) continue;
        const sx = pad + cellX * (bay + 0.12);
        const a = volumeCitySpot(left, right, footLeft, footRight, sx, sy);
        const b = volumeCitySpot(left, right, footLeft, footRight, sx + cellX * 0.76, sy + cellY * 0.72);
        const width = b.x - a.x;
        const height = b.y - a.y;
        if (!(Math.abs(width) > 0.6) || !(Math.abs(height) > 0.6)) continue;
        ctx.fillStyle = alight ? VOLUME_CITY_LIGHT : palette.glass;
        ctx.fillRect(Math.min(a.x, b.x), Math.min(a.y, b.y), Math.abs(width), Math.abs(height));
      }
    }
  }
  // Крыша: четырёхугольник по верху коробки. Видна она сверху, а снизу
  // вырождается в черту — и это та самая черта парапета, которой дом отличался
  // от коробки до таска 206.
  const top = [plan.faceLeft, plan.faceRight, plan.backRight, plan.backLeft].map((spot) =>
    volumeGroundPoint(aim, spot.x, spot.y, block.heightMm),
  );
  if (top.every(Boolean)) {
    ctx.fillStyle = block.far ? palette.roof : palette.roof;
    ctx.beginPath();
    ctx.moveTo(top[0].x, top[0].y);
    for (let index2 = 1; index2 < top.length; index2 += 1) ctx.lineTo(top[index2].x, top[index2].y);
    ctx.closePath();
    ctx.fill();
  }
}

/**
 * Рекламный щит у дороги (G310): полотно на двух ногах, поперёк взгляда.
 *
 * Полотно — цветные полосы, и всё: текста на нём нет нарочно, писать на щите
 * значило бы придумывать чужую рекламу. Ночью щит **не светится** — подсветка
 * билборда это отдельная история, и так было с первого дня: заказчик снял с
 * домов неон (G337), а щиты оставил как есть.
 */
function volumeDrawBanner(ctx, aim, banner, hour) {
  const palette = hour.palette;
  const len = Math.hypot(banner.x, banner.y) || 1;
  const ux = -banner.y / len;
  const uy = banner.x / len;
  const edge = (sign, zMm) =>
    volumeGroundPoint(aim, banner.x + ux * banner.halfMm * sign, banner.y + uy * banner.halfMm * sign, zMm);
  const top = banner.bottomMm + banner.heightMm;
  const left = edge(1, top);
  const right = edge(-1, top);
  const footLeft = edge(1, banner.bottomMm);
  const footRight = edge(-1, banner.bottomMm);
  const legLeft = edge(0.62, 0);
  const legRight = edge(-0.62, 0);
  if (!left || !right || !footLeft || !footRight || !legLeft || !legRight) return;
  // Ноги — две черты до земли, толщиной в сотую ширины щита.
  ctx.fillStyle = palette.wallSide;
  const leg = Math.max(1, Math.abs(right.x - left.x) * 0.04);
  for (const [atTop, atFoot] of [
    [footLeft, legLeft],
    [footRight, legRight],
  ]) {
    ctx.fillRect(Math.min(atTop.x, atFoot.x) - leg / 2, Math.min(atTop.y, atFoot.y), leg, Math.abs(atFoot.y - atTop.y));
  }
  const paint = VOLUME_CITY_BANNERS[banner.paint % VOLUME_CITY_BANNERS.length];
  ctx.fillStyle = volumeTintCss(volumeHexRgb(paint.back), hour.tint);
  ctx.beginPath();
  ctx.moveTo(left.x, left.y);
  ctx.lineTo(right.x, right.y);
  ctx.lineTo(footRight.x, footRight.y);
  ctx.lineTo(footLeft.x, footLeft.y);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = volumeTintCss(volumeHexRgb(paint.mark), hour.tint);
  for (const [from, to, thick] of [
    [0.1, 0.66, 0.2],
    [0.1, 0.44, 0.52],
    [0.1, 0.78, 0.74],
  ]) {
    const a = volumeCitySpot(left, right, footLeft, footRight, from, thick);
    const b = volumeCitySpot(left, right, footLeft, footRight, to, thick + 0.14);
    const wide = b.x - a.x;
    const high = b.y - a.y;
    if (!(Math.abs(wide) > 1) || !(Math.abs(high) > 0.8)) continue;
    ctx.fillRect(Math.min(a.x, b.x), Math.min(a.y, b.y), Math.abs(wide), Math.abs(high));
  }
}

/** Точка на лице дома по долям: верх-низ и лево-право, с перспективой. */
function volumeCitySpot(left, right, footLeft, footRight, fx, fy) {
  const topX = left.x + (right.x - left.x) * fx;
  const topY = left.y + (right.y - left.y) * fx;
  const lowX = footLeft.x + (footRight.x - footLeft.x) * fx;
  const lowY = footLeft.y + (footRight.y - footLeft.y) * fx;
  return { x: topX + (lowX - topX) * fy, y: topY + (lowY - topY) * fy };
}

/** Машина: кузов и крыша двумя прямоугольниками — силуэт, а не модель. */
function volumeDrawCar(ctx, aim, spot, palette) {
  const base = volumeGroundPoint(aim, spot.x, spot.y, 0);
  if (!base) return;
  const height = Math.max(3, spot.heightMm * base.scale);
  const width = height * 2.4;
  ctx.fillStyle = palette.car[spot.car % palette.car.length];
  ctx.fillRect(base.x - width / 2, base.y - height * 0.62, width, height * 0.62);
  ctx.fillRect(base.x - width * 0.28, base.y - height, width * 0.56, height * 0.42);
}

/**
 * Звёзды: точки на своих местах, одной яркостью на всё небо.
 *
 * Яркость — доля ночи (`mood.stars`), и она в прозрачности, а не в цвете: небо
 * под ними своё на каждый час, и звезда обязана проступать сквозь сумерки, а
 * не спорить с ними готовым серым.
 */
function volumeDrawStars(ctx, aim, hour) {
  ctx.fillStyle = "rgba(255,255,255," + Math.round(hour.stars * 85) / 100 + ")";
  for (const star of VOLUME_STARS) {
    const at = volumeSkyPoint(aim, star.az, star.rise);
    if (!at) continue;
    const radius = Math.max(0.7, star.size * DEG * at.scale * 0.1);
    ctx.beginPath();
    ctx.arc(at.x, at.y, radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

// Солнце: диск с ореолом. Цвет и место — из снимка часа; у горизонта оно рыжее
// и подрезано полем, под горизонтом его нет вовсе.
function volumeDrawSun(ctx, aim, hour) {
  if (hour.sun.height < -3) return;
  const at = volumeSkyPoint(aim, hour.sun.az, hour.sun.rise);
  if (!at) return;
  const radius = Math.max(4, VOLUME_SUN_AT.size * DEG * at.scale);
  ctx.fillStyle = hour.sunColors.halo;
  ctx.beginPath();
  ctx.arc(at.x, at.y, radius * 2.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = hour.sunColors.body;
  ctx.beginPath();
  ctx.arc(at.x, at.y, radius, 0, Math.PI * 2);
  ctx.fill();
}

/**
 * Месяц: не круг, а серп — заказчик назвал его месяцем, и узнаётся он формой.
 *
 * Фигура приходит готовой ломаной (`volumeMoonShape`) — одной на весь круг фаз
 * (G290), от новолуния до полнолуния и обратно. Рисуется она **одним путём без
 * вырезания**: прежний месяц был разностью двух окружностей в одном пути, и
 * торчащий за диск кусок вырезающей окружности правило непустого обхода
 * заливало — отсюда дефект D48, «две пересекающиеся дуги, фигура похожа на
 * линзу». Заливки «цветом неба» здесь быть не может тем более: под месяцем
 * растяжка, и заплатка плоским цветом была бы видна.
 *
 * Новолуние не рисуется вовсе, и это решение: освещённой доли у него нет, а
 * обведённый контуром тёмный диск был бы выдумкой — в настоящем небе его не
 * видно. Фигура и так сходится в линию сама, порог лишь убирает волосок.
 */
function volumeDrawMoon(ctx, aim, hour) {
  const moon = hour.moon;
  if (moon.rise < -2 || !(moon.glow > 0) || !(moon.lit > VOLUME_MOON_THIN)) return;
  const at = volumeSkyPoint(aim, moon.az, moon.rise);
  if (!at) return;
  const radius = Math.max(4, VOLUME_MOON_SIZE_DEG * DEG * at.scale);
  const shown = Math.max(0.35, Math.min(1, hour.stars + 0.35)) * moon.glow;
  ctx.fillStyle = "rgba(242,243,228," + Math.round(shown * 100) / 100 + ")";
  const edge = volumeMoonShape(radius, moon.edge, moon.tiltDeg);
  ctx.beginPath();
  ctx.moveTo(at.x + edge[0].x, at.y + edge[0].y);
  for (let index = 1; index < edge.length; index += 1) ctx.lineTo(at.x + edge[index].x, at.y + edge[index].y);
  ctx.closePath();
  ctx.fill();
}

// Вершина: треугольник камня и шапка снега на его верхушке. Шапка считается
// **по уже посчитанным точкам** — долей от вершины вниз по обоим склонам, — и
// отдельной стороны света у неё нет: снег лежит на той же горе, а не рядом с
// ней. Низ шапки с изломом, иначе снеговая линия выходит начерченной по
// линейке.
function volumeDrawPeak(ctx, aim, peak, palette) {
  const len = Math.hypot(peak.x, peak.y) || 1;
  const nx = -peak.y / len;
  const ny = peak.x / len;
  const apex = volumeGroundPoint(aim, peak.x, peak.y, peak.heightMm);
  const left = volumeGroundPoint(aim, peak.x + nx * peak.halfMm, peak.y + ny * peak.halfMm, 0);
  const right = volumeGroundPoint(aim, peak.x - nx * peak.halfMm, peak.y - ny * peak.halfMm, 0);
  if (!apex || !left || !right) return;
  ctx.fillStyle = peak.far ? palette.rockFar : palette.rock;
  ctx.beginPath();
  ctx.moveTo(left.x, left.y);
  ctx.lineTo(apex.x, apex.y);
  ctx.lineTo(right.x, right.y);
  ctx.closePath();
  ctx.fill();
  const down = (point) => ({
    x: apex.x + (point.x - apex.x) * peak.snow,
    y: apex.y + (point.y - apex.y) * peak.snow,
  });
  const a = down(left);
  const b = down(right);
  ctx.fillStyle = peak.far ? palette.snowFar : palette.snow;
  ctx.beginPath();
  ctx.moveTo(apex.x, apex.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo((a.x + b.x) / 2, (a.y + b.y) / 2 - (b.y - apex.y) * 0.3);
  ctx.lineTo(a.x, a.y);
  ctx.closePath();
  ctx.fill();
}

function volumeDrawCloud(ctx, aim, cloud, palette) {
  const at = volumeSkyPoint(aim, cloud.az, cloud.rise);
  if (!at) return;
  const radius = Math.max(4, cloud.size * DEG * at.scale * 0.4);
  ctx.fillStyle = palette.cloud;
  ctx.beginPath();
  ctx.arc(at.x - radius, at.y, radius * 0.72, 0, Math.PI * 2);
  ctx.arc(at.x, at.y - radius * 0.3, radius, 0, Math.PI * 2);
  ctx.arc(at.x + radius, at.y, radius * 0.66, 0, Math.PI * 2);
  ctx.fill();
}

// Дерево, ель и куст — тремя кистями по одному и тому же правилу: основание на
// своей высоте над горизонтом, высота угловая. Своей картинки у фона нет
// нарочно: это рисунок за окном, а не часть чертежа.
function volumeDrawTree(ctx, aim, tree, palette) {
  const base = volumeGroundPoint(aim, tree.x, tree.y, 0);
  if (!base) return;
  const height = Math.max(6, tree.heightMm * base.scale);
  // Дальнее — бледнее: зелень у горизонта видна сквозь воздух. Мера теперь
  // настоящая — дальность в метрах, а не высота основания над горизонтом:
  // дальше трёхсот метров зелень блёкнет, ближе остаётся своей.
  const far = tree.awayMm > VOLUME_TREE_FAR_MM;
  if (tree.kind === "bush") {
    const radius = height * 0.5;
    ctx.fillStyle = palette.bush;
    ctx.beginPath();
    ctx.arc(base.x - radius * 0.8, base.y - radius * 0.6, radius * 0.62, 0, Math.PI * 2);
    ctx.arc(base.x + radius * 0.75, base.y - radius * 0.5, radius * 0.56, 0, Math.PI * 2);
    ctx.arc(base.x, base.y - radius * 0.95, radius * 0.78, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  const slim = tree.kind === "spruce" || tree.kind === "poplar" || tree.kind === "birch";
  ctx.fillStyle = tree.kind === "birch" ? palette.birchTrunk : palette.trunk;
  const trunk = Math.max(1, height * (slim ? 0.05 : 0.08));
  const bare = tree.kind === "spruce" ? 0.2 : tree.kind === "poplar" ? 0.3 : tree.kind === "birch" ? 0.58 : 0.45;
  const trunkTop = base.y - height * bare;
  ctx.fillRect(base.x - trunk / 2, trunkTop, trunk, base.y - trunkTop);
  // Берёза узнаётся по стволу, а не по кроне: светлый ствол и чёрточки на нём.
  // Их три, и мельче точки они не бывают — на дальнем ряду чёрточка выродилась
  // бы в мусор, и её там просто нет.
  if (tree.kind === "birch" && trunk > 2) {
    ctx.fillStyle = palette.birchMark;
    for (const part of [0.3, 0.55, 0.78]) {
      const y = base.y - (base.y - trunkTop) * part;
      ctx.fillRect(base.x - trunk / 2, y, trunk * (part > 0.5 ? 0.55 : 0.75), Math.max(1, trunk * 0.3));
    }
  }
  if (tree.kind === "spruce") {
    ctx.fillStyle = far ? palette.crownFar : palette.crownDark;
    const half = height * 0.27;
    for (const level of [0, 1, 2]) {
      const bottom = base.y - height * (0.18 + level * 0.26);
      const top = bottom - height * 0.42;
      const spread = half * (1 - level * 0.22);
      ctx.beginPath();
      ctx.moveTo(base.x - spread, bottom);
      ctx.lineTo(base.x + spread, bottom);
      ctx.lineTo(base.x, top);
      ctx.closePath();
      ctx.fill();
    }
    return;
  }
  // Тополь: узкая высокая крона в одно пятно — силуэт у него такой и есть,
  // и издали он отличается от круглого дерева одним только очерком.
  if (tree.kind === "poplar") {
    ctx.fillStyle = far ? palette.crownFar : palette.crownDark;
    ctx.beginPath();
    ctx.ellipse(base.x, base.y - height * 0.6, height * 0.17, height * 0.44, 0, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  // Ива: широкая плоская крона и три свисающие пряди под ней. Стоит она у
  // воды — там её и ставит берег реки (G232).
  if (tree.kind === "willow") {
    ctx.fillStyle = far ? palette.crownFar : palette.willow;
    const wide = height * 0.46;
    ctx.beginPath();
    ctx.ellipse(base.x, base.y - height * 0.62, wide, height * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();
    for (const side of [-0.72, 0, 0.72]) {
      ctx.beginPath();
      ctx.ellipse(base.x + wide * side, base.y - height * 0.34, wide * 0.22, height * 0.22, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    return;
  }
  // Берёза: крона светлее и жиже круглого дерева — два пятна вместо трёх.
  if (tree.kind === "birch") {
    ctx.fillStyle = far ? palette.crownFar : palette.birchCrown;
    const leaf = height * 0.3;
    ctx.beginPath();
    ctx.ellipse(base.x, base.y - height * 0.78, leaf * 0.85, leaf * 1.15, 0, 0, Math.PI * 2);
    ctx.ellipse(base.x - leaf * 0.55, base.y - height * 0.58, leaf * 0.6, leaf * 0.8, 0, 0, Math.PI * 2);
    ctx.ellipse(base.x + leaf * 0.55, base.y - height * 0.62, leaf * 0.55, leaf * 0.75, 0, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  ctx.fillStyle = far ? palette.crownFar : palette.crown;
  const radius = height * 0.34;
  ctx.beginPath();
  ctx.arc(base.x, base.y - height * 0.66, radius, 0, Math.PI * 2);
  ctx.arc(base.x - radius * 0.72, base.y - height * 0.47, radius * 0.66, 0, Math.PI * 2);
  ctx.arc(base.x + radius * 0.7, base.y - height * 0.5, radius * 0.6, 0, Math.PI * 2);
  ctx.fill();
}

// ——— час суток: одно непрерывное время (таск 181, G282) —————————————————
//
// Слова заказчика: «сразу заложи по фону что бы можно было указывать время
// суток и фон менялся, утро, день, вечер, ночь. при чем плавно менялся. на небе
// должно двигаться солнце днём и месяц ночью… ну и само собой в виде города
// должны загораться окна и т.д. как живой город, и внутри объекта меняться
// освещение». И отдельно: «ночь не сильно тёмная должна быть, что бы было
// понятно что ночь, но различимо всё».
//
// ——— это не четыре картинки ————————————————————————————————————————————
//
// Утро, день, вечер и ночь здесь — **слова, а не состояния**. Считается одно
// число: высота солнца над горизонтом в этот миг. Из неё выходит всё — цвет
// неба, тон комнаты, яркость окон города, звёзды, длина и сила тени, — и
// выходит непрерывно: ни одного `if (ночь)` в рисовании нет. Слово нужно
// только человеку в окне параметров, и считается оно по часам
// (`volumeDayPhase`), а не по высоте: «вечер» наступает в шесть, даже если небо
// ещё светлое.
//
// ——— где темнеет ———————————————————————————————————————————————————————
//
// Ночь — **не завеса поверх кадра**, а доля в цвете каждой грани
// (`volumeTintRgb` в `volumeFill`). Завеса была бы и дешевле, и неправильна
// сразу дважды: она легла бы на небо, которому ночью нужна темнота глубже
// комнатной, и она не дала бы **светящемуся** окну города остаться светящимся —
// а свет в окнах заказчик назвал прямо. Цена у доли в цвете нулевая: три
// умножения на грань в том же счёте, где уже считается светлота лампы.
//
// Потолок доли — `VOLUME_NIGHT_SHARE` = 0,45, и это ответ на «ночь не сильно
// тёмная»: стена 216·212·204 ночью становится 127·128·136 — тёмно-серой, но
// различимой, а метки, их контуры и рамка выделения не темнеют вовсе (контур и
// стрелка — линии, а линии часом не красятся). То есть ночь узнаётся небом и
// тоном, а не потерей зрения.
//
// ——— раз в секунду, а при стоячем времени — никогда ———————————————————
//
// Слово заказчика: «достаточно оптимизировано что бы было, не каждый кадр, а,
// хотя бы раз в секунду». Поэтому всё, что зависит от времени, собрано в один
// снимок — `volumeMood` — и считается не в кадре: поле просит его не чаще раза
// в секунду (`VOLUME_MOOD_MS`) и держит готовым. Кадр берёт готовые цвета и не
// считает про время ничего. При остановленном времени снимок считается **один
// раз**: ни пересчёта, ни перерисовки, ни таймера.

/** Минут в сутках. */
export const VOLUME_DAY_MIN = 1440;
/** Рассвет и закат по умолчанию — слова заказчика: 9:00 и 21:00. */
export const VOLUME_SUNRISE_MIN = 9 * 60;
export const VOLUME_SUNSET_MIN = 21 * 60;
/**
 * Ускорение времени. Числа — слова заказчика (480, а не 280: «это опечатка»), и
 * каждое читается как «во сколько раз время идёт быстрее настоящего»: 60 → сутки
 * за 24 минуты, 120 → за 12, 240 → за 6, 480 → за 3, 960 → за полторы.
 *
 * **Первый пункт — единица** (G287): «добавь в Ускорение пункт первый — без
 * ускорения. При нажатии Сейчас он и должен выбираться и время идти в реальном
 * времени». Единица — это идущее время, а не стоячее: сутки проходят сутки, и
 * таймер снимка часа при ней живёт, как при любом другом ускорении. Стоячее
 * время — это `volumeClockFixed`, и оно устроено иначе.
 */
export const VOLUME_CLOCK_SPEEDS = [1, 60, 120, 240, 480, 960];
export const VOLUME_CLOCK_SPEED_DEFAULT = 60;
/** «Без ускорения» — то, что выбирает кнопка «Сейчас». */
export const VOLUME_CLOCK_SPEED_REAL = 1;
/** Чаще этого фон не пересчитывается — прямое требование заказчика. */
export const VOLUME_MOOD_MS = 1000;
/**
 * То же, но с отметкой «Плавные светила» (таск 192, G292): тридцать кадров в
 * секунду, слова заказчика — «обновляй не раз в секунду, а в 30FPS».
 *
 * Отметка меняет **только частоту** и больше ничего: тот же снимок, та же
 * арифметика, то же правило «при стоячем времени таймера нет вовсе». 33 мс — не
 * круглое число нарочно: 1000/30 = 33,33, и округлять его вверх значило бы
 * отдать заказчику 30,3 кадра вместо 30.
 */
export const VOLUME_MOOD_SMOOTH_MS = Math.round(1000 / 30);

/**
 * Как часто пересчитывается снимок часа. **Один хозяин у этого числа**: поле
 * спрашивает здесь, а не выбирает само — иначе «раз в секунду» и «тридцать раз»
 * жили бы в двух местах.
 *
 * Цена названа числом (замер на объекте заказчика, 25 стен и 86 меток): снимок
 * часа — 7 мкс, грани тени дома — 16 мкс, а сам кадр — 400 мкс. То есть всё
 * время, которое зависит от часа, стоит 5% кадра, и делить снимок на «быстрое»
 * (светило) и «медленное» (тень, свет в окнах) незачем: деление сэкономило бы
 * 20 мкс из 440 и завело бы в сборке вторые часы.
 */
export function volumeMoodMs(smooth) {
  return smooth ? VOLUME_MOOD_SMOOTH_MS : VOLUME_MOOD_MS;
}
/** Тон ночи и его потолок: куда и насколько тянется цвет к полуночи. */
export const VOLUME_NIGHT_RGB = [18, 26, 54];
export const VOLUME_NIGHT_SHARE = 0.45;
/**
 * Угловой размер месяца. Мельче солнца, но обоим он **нарисованный, а не
 * настоящий**: у настоящих светил радиус 0,26°, и в кадре с полем зрения 90°
 * это три точки — пятнышко, у которого не видно ни цвета, ни фазы. Место на
 * небе с таска 190 настоящее (`volumeSunAt`, `volumeMoonAt`), размер — нет, и
 * это разные вопросы.
 */
export const VOLUME_MOON_SIZE_DEG = 1.9;
/**
 * Точек на каждую кромку месяца. Двадцать четыре — это шаг 7,5°: на диске в
 * двадцать точек экрана излома не видно, а ломаная остаётся дешёвой —
 * `volumeMoonShape` отдаёт 48 точек, и это весь счёт месяца в кадре.
 */
export const VOLUME_MOON_STEPS = 24;
/**
 * Тоньше этой освещённой доли месяц не рисуется вовсе — это и есть новолуние.
 * Сотая доля диска на двадцати точках экрана даёт волосок в четверть точки:
 * нарисованный, он читался бы соринкой на стекле, а не луной.
 */
export const VOLUME_MOON_THIN = 0.01;
/** Наклон земной оси: им считаются склонения и солнца, и месяца. */
export const VOLUME_EARTH_TILT_DEG = 23.44;
/**
 * Горизонт, по которому считаются рассвет и закат: −50′ на преломление воздуха
 * и полупоперечник диска (та же мера, что у всех таблиц рассвета). Высота
 * светила отсчитывается **от него**, поэтому ноль высоты приходится ровно на
 * рассвет из подписи окна, а не примерно на него.
 */
export const VOLUME_HORIZON_DEG = -0.833;
/**
 * Дом без координат: широта и склонение, по которым идёт дуга, когда координат
 * у объекта нет. Равноденствие в средней полосе — то есть дуга настоящая, а
 * рассвет с закатом остаются словами заказчика (9:00 и 21:00), на которые она
 * растягивается. Разбор — у `volumeSkyPlace`.
 */
export const VOLUME_SITE_FALLBACK = { latDeg: 55, lonDeg: 0 };
/** Синодический месяц: от новолуния до новолуния. */
export const VOLUME_MOON_MONTH_DAYS = 29.530588853;
/**
 * Опорное новолуние — 6 января 2000 года, 18:14 UTC, в сутках от эпохи. От него
 * считается возраст луны, а из возраста — и фаза, и место на небе.
 */
export const VOLUME_MOON_EPOCH_DAY = Date.UTC(2000, 0, 6, 18, 14) / 86400000;

/** Доля в отрезке, зажатая по краям: ею считается всё непрерывное ниже. */
function volumeShare(value, from, to) {
  if (from === to) return value >= to ? 1 : 0;
  return Math.max(0, Math.min(1, (value - from) / (to - from)));
}

/** Минуты суток у настоящих часов. */
export function volumeDayMinutesOf(date) {
  const at = date || new Date();
  return at.getHours() * 60 + at.getMinutes() + at.getSeconds() / 60;
}

/** Минуты в сутках, с переходом через полночь в обе стороны. */
export function volumeWrapMinutes(minutes) {
  const value = Number(minutes);
  if (!Number.isFinite(value)) return 0;
  return ((value % VOLUME_DAY_MIN) + VOLUME_DAY_MIN) % VOLUME_DAY_MIN;
}

/** Часы и минуты строкой — для контрола с часами и для плашки. */
export function volumeClockText(minutes) {
  const value = volumeWrapMinutes(minutes);
  const hours = Math.floor(value / 60);
  const left = Math.floor(value - hours * 60);
  return String(hours).padStart(2, "0") + ":" + String(left).padStart(2, "0");
}

/** «09:30» → минуты суток. `null` — не время. */
export function volumeClockParse(text) {
  const match = /^\s*(\d{1,2})\s*[:.]\s*(\d{1,2})/.exec(String(text || ""));
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (!(hours >= 0 && hours < 24) || !(minutes >= 0 && minutes < 60)) return null;
  return hours * 60 + minutes;
}

// ——— дата своим числом (таск 190, G289) ————————————————————————————————
//
// Слова заказчика: «для положения солнца дата нужна, пусть отдельное поле будет
// над полем время».
//
// Дата живёт **номером суток** — целым числом суток гражданского календаря от
// эпохи. Не `Date` и не тройкой чисел, и причина простая: часам нужно
// складывать её с минутами и переваливать через полночь одним сложением
// (`volumeClockStamp`), а `Date` для этого пришлось бы собирать и разбирать на
// каждый кадр. Перевод в обе стороны — `volumeDayNumberOf`/`volumeDayDateOf`,
// и считаются они через `Date.UTC`, то есть не зависят ни от часового пояса, ни
// от перехода на летнее время: номер суток — это «какое сегодня число», а не
// «сколько миллисекунд прошло».

/** Номер суток по гражданской дате: целое число суток от эпохи. */
export function volumeDayNumberOf(date) {
  const at = date || new Date();
  return Math.floor(Date.UTC(at.getFullYear(), at.getMonth(), at.getDate()) / 86400000);
}

/**
 * Обратно: `Date` на полдень этих суток по месту.
 *
 * Полдень, а не полночь, нарочно: из этой даты читают год, месяц и число, а
 * полночь в день перехода на летнее время умеет уехать на сутки назад.
 */
export function volumeDayDateOf(dayNumber) {
  const at = new Date((Number(dayNumber) || 0) * 86400000);
  return new Date(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate(), 12);
}

/** «2026-10-20» — то, что просит и отдаёт поле даты. */
export function volumeDateText(dayNumber) {
  const at = volumeDayDateOf(dayNumber);
  return (
    String(at.getFullYear()).padStart(4, "0") +
    "-" +
    String(at.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(at.getDate()).padStart(2, "0")
  );
}

/**
 * **Дата для человека: «20.10.2026»** (таск 191, G300).
 *
 * Строка часов в углу поля читается боковым зрением, пока человек ходит по
 * комнатам, — ей нужен привычный порядок «день, месяц, год», а не ISO. ISO
 * остаётся у поля ввода (`volumeDateText`): его просит сам браузер, и смешивать
 * эти две строки нельзя — одна для машины, другая для глаза.
 */
export function volumeDateShort(dayNumber) {
  const at = volumeDayDateOf(dayNumber);
  return (
    String(at.getDate()).padStart(2, "0") +
    "." +
    String(at.getMonth() + 1).padStart(2, "0") +
    "." +
    String(at.getFullYear()).padStart(4, "0")
  );
}

/** «2026-10-20» → номер суток. `null` — не дата. */
export function volumeDateParse(text) {
  const match = /^\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*$/.exec(String(text || ""));
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!(month >= 1 && month <= 12) || !(day >= 1 && day <= 31)) return null;
  const at = new Date(Date.UTC(year, month - 1, day));
  // Тридцатое февраля браузер молча переносит на март — такую дату не берём.
  if (at.getUTCMonth() !== month - 1 || at.getUTCDate() !== day) return null;
  return Math.floor(at.getTime() / 86400000);
}

/**
 * Часы объёма.
 *
 * Идущее время — **не накопитель, а формула**: `откуда + (сейчас − когда) ×
 * ускорение`. Поэтому пока объём закрыт, ничего не идёт и не считается, а
 * вернувшийся человек видит время, которое «прошло» за его отсутствие, с
 * одного умножения. Накопитель требовал бы живого таймера в закрытом режиме.
 *
 * `fixed` — время стоит: ровно то, что человек поставил, и ни пересчёта, ни
 * таймера.
 */
export function volumeClockNow(nowMs, date, speed = VOLUME_CLOCK_SPEED_DEFAULT) {
  const at = date || new Date();
  return {
    fixed: false,
    fromDay: volumeDayNumberOf(at),
    fromMin: volumeDayMinutesOf(at),
    atMs: Number(nowMs) || 0,
    speed: volumeClockSpeedOf(speed),
  };
}

export function volumeClockFixed(minutes, speed = VOLUME_CLOCK_SPEED_DEFAULT, day = null) {
  return {
    fixed: true,
    fromDay: day === null || day === undefined ? volumeDayNumberOf(new Date()) : Math.round(Number(day) || 0),
    fromMin: volumeWrapMinutes(minutes),
    atMs: 0,
    speed: volumeClockSpeedOf(speed),
  };
}

/** Своё ускорение: чужое число не берётся — у списка ровно шесть пунктов. */
export function volumeClockSpeedOf(speed) {
  const value = Number(speed);
  return VOLUME_CLOCK_SPEEDS.includes(value) ? value : VOLUME_CLOCK_SPEED_DEFAULT;
}

/** Сколько минут занимают сутки при этом ускорении: 1440, 24, 12, 6, 3 и 1,5. */
export function volumeClockDayMinutes(speed) {
  return VOLUME_DAY_MIN / volumeClockSpeedOf(speed);
}

/**
 * Который час и какое число на часах объёма.
 *
 * **Полночь переводит дату** (G289): время идёт формулой, и сутки у неё не
 * последний разряд, а часть того же числа — минуты от начала `fromDay`. Сколько
 * бы их ни набежало, целые сутки уезжают в номер дня, остаток — в часы. При
 * ускорении 960 это случается каждые полторы минуты настоящего времени, и
 * считается тем же одним сложением, что и час.
 */
export function volumeClockStamp(clock, nowMs) {
  if (!clock) return { day: volumeDayNumberOf(new Date()), minutes: VOLUME_SUNRISE_MIN };
  const day = Number.isFinite(Number(clock.fromDay)) ? Number(clock.fromDay) : volumeDayNumberOf(new Date());
  if (clock.fixed) {
    const fixed = volumeWrapMinutes(clock.fromMin);
    return { day: day + Math.floor(Number(clock.fromMin) / VOLUME_DAY_MIN || 0), minutes: fixed };
  }
  const gone = (Number(nowMs) - Number(clock.atMs)) / 60000;
  const total = Number(clock.fromMin) + gone * volumeClockSpeedOf(clock.speed);
  const over = Math.floor(total / VOLUME_DAY_MIN);
  return { day: day + (Number.isFinite(over) ? over : 0), minutes: volumeWrapMinutes(total) };
}

/** Который час на часах объёма. */
export function volumeClockMinutes(clock, nowMs) {
  return volumeClockStamp(clock, nowMs).minutes;
}

/**
 * Сменить ускорение, не сдвинув время: часы перецепляются за ту минуту и то
 * число, которые показывают сейчас. Иначе выбор «быстрее» прыгал бы временем.
 */
export function volumeClockAt(clock, nowMs, speed) {
  const stamp = volumeClockStamp(clock, nowMs);
  if (clock && clock.fixed) return volumeClockFixed(stamp.minutes, speed, stamp.day);
  return { fixed: false, fromDay: stamp.day, fromMin: stamp.minutes, atMs: Number(nowMs) || 0, speed: volumeClockSpeedOf(speed) };
}

/** Поставить другое число, не тронув ни час, ни ход часов. */
export function volumeClockOnDay(clock, nowMs, day) {
  const stamp = volumeClockStamp(clock, nowMs);
  const next = Math.round(Number(day));
  const put = Number.isFinite(next) ? next : stamp.day;
  if (clock && clock.fixed) return volumeClockFixed(stamp.minutes, clock.speed, put);
  return {
    fixed: false,
    fromDay: put,
    fromMin: stamp.minutes,
    atMs: Number(nowMs) || 0,
    speed: volumeClockSpeedOf(clock ? clock.speed : undefined),
  };
}

// ——— место объекта (таск 188) ——————————————————————————————————————————
//
// Координаты и направление верха чертежа — **свойства объекта** (решение
// заказчика в G283 и G284), и живут они в `project.site`. Объём их только
// читает, и читает **чужой дверью**: `projectCoords` и `projectTopAzimuth` —
// единственные хозяева этих полей, они же разбирают мусор и пустоту. Свой
// разбор здесь был бы вторым ответом на вопрос «где стоит дом», и разошёлся бы
// он ровно в тот день, когда формат поправят.
//
// Нет координат — рассвет и закат берутся умолчанием заказчика (9:00 и 21:00),
// нет направления — верх чертежа смотрит на север. Ни одного поля объём не
// создаёт: открыть объём у объекта без свойств — ноль изменений (G68).

/**
 * Место объекта: широта, долгота и направление верха чертежа (в градусах от
 * севера по часовой стрелке).
 */
export function volumeSiteOf(project) {
  const coords = projectCoords(project);
  return {
    latDeg: coords ? coords.lat : null,
    lonDeg: coords ? coords.lon : null,
    topDeg: projectTopAzimuth(project),
  };
}

/**
 * Долгота солнца по эклиптике в этот день года — то, из чего выходит склонение.
 *
 * Счёт тот же, что был у склонения в таске 181 (формула Купера): нуль
 * приходится на весеннее равноденствие, и за год долгота обходит круг. Держать
 * её отдельным числом нужно месяцу: он ходит по той же эклиптике, только
 * опережает солнце на свою фазу.
 */
export function volumeSunLonDeg(date) {
  const at = date || new Date();
  const start = Date.UTC(at.getFullYear(), 0, 1);
  const day = Math.floor((Date.UTC(at.getFullYear(), at.getMonth(), at.getDate()) - start) / 86400000) + 1;
  return (360 / 365) * (284 + day);
}

/** Склонение светила по его долготе на эклиптике: ось Земли наклонена. */
export function volumeDeclDeg(lonDeg) {
  return VOLUME_EARTH_TILT_DEG * Math.sin(Number(lonDeg) * DEG);
}

/**
 * Рассвет и закат — и всё, из чего они выходят.
 *
 * Без координат — умолчание заказчика: 9:00 и 21:00. С координатами — по
 * широте, дню года и долготе, с часовым поясом браузера.
 *
 * Отдаётся **не только пара минут**: в ответе лежат широта, склонение,
 * солнечный полдень, долгота солнца по эклиптике, часовой пояс и номер суток —
 * то есть всё, по чему место светила считает `volumeSunAt`. Так сделано
 * нарочно: подпись и небо обязаны идти от одних и тех же чисел, иначе рассвет
 * из подписи разойдётся с рассветом в кадре — ровно та ошибка, от которой таск
 * 190 и затевался.
 *
 * **Чего здесь нет нарочно:** уравнения времени (до четверти часа у солнечного
 * полудня) и преломления сверх стандартных 50′. Часы объёма — не астрономия, и
 * четверть часа на рассвете видна только в таблице, а не в кадре.
 *
 * Полярный день и полярная ночь не ломают счёт: в первом сутки целиком день, во
 * втором — ночь, и это правда, а не вырождение.
 */
export function volumeDayTimes(site, date) {
  // `Number(null)` — это нуль, то есть экватор: пустые координаты обязаны
  // читаться пустыми, а не нулевой широтой в Атлантике.
  const number = (value) => (value === null || value === undefined || value === "" ? NaN : Number(value));
  const latDeg = site ? number(site.latDeg) : NaN;
  const lonDeg = site ? number(site.lonDeg) : NaN;
  const at = date || new Date();
  // Номер суток и часовой пояс нужны и без координат: по ним считается возраст
  // луны, а он от широты не зависит.
  const day = { dayNumber: volumeDayNumberOf(at), tzHours: -at.getTimezoneOffset() / 60 };
  if (!Number.isFinite(latDeg) || !Number.isFinite(lonDeg) || Math.abs(latDeg) > 90) {
    return { riseMin: VOLUME_SUNRISE_MIN, setMin: VOLUME_SUNSET_MIN, bySite: false, ...day };
  }
  const sunLonDeg = volumeSunLonDeg(at);
  const declDeg = volumeDeclDeg(sunLonDeg);
  const noonMin = (12 - (lonDeg - 15 * day.tzHours) / 15) * 60;
  const place = { bySite: true, latDeg, declDeg, sunLonDeg, noonMin, ...day };
  const cosH = volumeDayCosH(latDeg, declDeg);
  if (!(cosH > -1)) return { riseMin: noonMin - 720, setMin: noonMin + 720, ...place };
  if (!(cosH < 1)) return { riseMin: noonMin, setMin: noonMin, ...place };
  const half = (Math.acos(cosH) / DEG / 15) * 60;
  return { riseMin: noonMin - half, setMin: noonMin + half, ...place };
}

/**
 * Косинус полуденного часового угла: из него выходит половина дня.
 *
 * `cos H₀ = (sin h₀ − sin φ sin δ) / (cos φ cos δ)`, где `h₀` — горизонт с
 * преломлением. За единицу вышло — солнце не встаёт (полярная ночь), ниже минус
 * единицы — не садится (полярный день).
 */
export function volumeDayCosH(latDeg, declDeg) {
  const lat = Number(latDeg) * DEG;
  const decl = Number(declDeg) * DEG;
  return (
    (Math.sin(VOLUME_HORIZON_DEG * DEG) - Math.sin(lat) * Math.sin(decl)) / (Math.cos(lat) * Math.cos(decl))
  );
}

/**
 * Как час называется. Отрезки считаются от рассвета и заката, а не от
 * полуночи: «утро» — это вокруг рассвета, а не «до двенадцати».
 *
 * При умолчании (9:00 и 21:00) выходит: ночь до 8, утро 8–12, день 12–18,
 * вечер 18–22, дальше снова ночь.
 */
export function volumeDayPhase(minutes, times) {
  const rise = times ? Number(times.riseMin) : VOLUME_SUNRISE_MIN;
  const set = times ? Number(times.setMin) : VOLUME_SUNSET_MIN;
  const now = volumeWrapMinutes(minutes);
  const inside = (from, to) => {
    const a = volumeWrapMinutes(from);
    const b = volumeWrapMinutes(to);
    return a <= b ? now >= a && now < b : now >= a || now < b;
  };
  if (inside(rise - 60, rise + 180)) return "morning";
  if (inside(set - 180, set + 60)) return "evening";
  if (inside(rise + 180, set - 180)) return "day";
  return "night";
}

/**
 * Сторона света панорамы из стороны света по компасу.
 *
 * У панорамы `az` — угол в осях чертежа: ноль смотрит вправо по листу, 90° —
 * вниз. У компаса ноль на севере и счёт по часовой стрелке. Верх листа смотрит
 * на `topDeg` (таск 188), значит вправо по листу — это `topDeg + 90°`, и
 * перевод выходит один:
 *
 *     az = компас − topDeg − 90°
 *
 * Проверка: верх на север (`topDeg` = 0), полдень, солнце на юге (компас 180°)
 * — `az` = 90°, то есть вниз по листу. Ровно туда, куда на чертеже с севером
 * вверху смотрит юг.
 */
export function volumePanoramaAz(compassDeg, topDeg = 0) {
  return (((Number(compassDeg) - (Number(topDeg) || 0) - 90) % 360) + 360) % 360;
}

// ——— настоящее место светил (таск 190, G288) ————————————————————————————
//
// Слова заказчика: «почему солнце и луна так низко над горизонтом? это их
// реальное положение по координатам или просто так нарисовал? Надо сделать
// реальное».
//
// До этого таска высота была **числом** (14°), а дуга — половиной синусоиды от
// рассвета к закату. Теперь высота и сторона света считаются по дате, времени и
// координатам объекта, и счёт у солнца с месяцем **один** (`volumeBodyAt`):
// меняются только склонение и часовой угол.
//
// ——— чем считается ————————————————————————————————————————————————————
//
// Склонение — наклон оси, помноженный на синус долготы светила по эклиптике
// (`volumeDeclDeg`); долготу солнца даёт день года (`volumeSunLonDeg`, формула
// Купера, та же, что считала рассвет в таске 181). Высота и азимут — из
// сферического треугольника «полюс — зенит — светило»:
//
//     sin h = sin φ · sin δ + cos φ · cos δ · cos H
//     cos A = (sin δ − sin h · sin φ) / (cos h · cos φ),   A → 360 − A после полудня
//
// где `φ` — широта, `δ` — склонение, `H` — часовой угол (ноль в полдень, 15° на
// час), `A` — азимут от севера по часовой. Из этого и выходит то, чего просил
// заказчик: в Москве 21 июня солнце в полдень стоит на 57°, а 21 декабря — на
// 11°, и обе цифры совпадают со справочными.
//
// ——— почему рассвет сходится ровно ——————————————————————————————————————
//
// Рассвет и закат (таск 181) считаются из **того же** склонения и того же
// горизонта `h₀` = −0,833°: в минуту рассвета `cos H = cos H₀`, то есть высота
// ровно `h₀`. Высота светила на небе отсчитывается от этого же горизонта
// (`height = h − h₀`), поэтому её ноль приходится ровно на рассвет и закат из
// подписи окна — тождеством, а не подгонкой. Проверено тестом до 10⁻⁶ градуса.
//
// ——— без координат ——————————————————————————————————————————————————————
//
// Координат нет — остаются слова заказчика: 9:00 и 21:00. Дуга при этом всё
// равно настоящая: дом ставится на широту 55° в равноденствие
// (`VOLUME_SITE_FALLBACK`), а часовой угол **растягивается** на окно
// 9:00…21:00 — `H = H₀ · (t − полдень) / половина дня`. С координатами половина
// дня и есть `H₀/15` часов, растяжка обращается в единицу, и формула остаётся
// одна на оба случая.

/**
 * Где дом и куда у него смотрит день: широта, склонение, солнечный полдень,
 * половина дня и шаг часового угла.
 *
 * Собирается из `volumeDayTimes`, а чего там нет — берётся умолчанием. Это
 * важно: `times` часто составляют руками (стенд, тест, старый вызов), и такой
 * объект обязан давать настоящую дугу, а не падать.
 */
export function volumeSkyPlace(times) {
  const riseMin = times && Number.isFinite(Number(times.riseMin)) ? Number(times.riseMin) : VOLUME_SUNRISE_MIN;
  const setMin = times && Number.isFinite(Number(times.setMin)) ? Number(times.setMin) : VOLUME_SUNSET_MIN;
  const bySite = Boolean(times && times.bySite && Number.isFinite(Number(times.latDeg)));
  const latDeg = bySite ? Number(times.latDeg) : VOLUME_SITE_FALLBACK.latDeg;
  const declDeg = bySite ? Number(times.declDeg) : 0;
  const sunLonDeg = bySite ? Number(times.sunLonDeg) : 0;
  const noonMin = bySite && Number.isFinite(Number(times.noonMin)) ? Number(times.noonMin) : (riseMin + setMin) / 2;
  const halfMin = (setMin - riseMin) / 2;
  // Шаг часового угла: сколько градусов приходится на минуту. По координатам
  // выходит ровно 0,25° — то есть 15° в час, настоящая угловая скорость; без
  // них окно заказчика растягивает ту же дугу.
  const cosH = volumeDayCosH(latDeg, declDeg);
  const riseAngleDeg = (Math.acos(Math.max(-1, Math.min(1, cosH))) / DEG) || 0;
  return {
    latDeg,
    declDeg,
    sunLonDeg,
    noonMin,
    halfMin,
    hourScale: halfMin > 0 ? riseAngleDeg / halfMin : 0.25,
    dayNumber: times && Number.isFinite(Number(times.dayNumber)) ? Number(times.dayNumber) : 0,
    tzHours: times && Number.isFinite(Number(times.tzHours)) ? Number(times.tzHours) : 0,
  };
}

/** Часовой угол солнца в эту минуту: ноль в полдень, восток в минусе. */
export function volumeHourAngleDeg(minutes, place) {
  const now = volumeWrapMinutes(minutes);
  // Минуты от полудня **ближним путём** через сутки: полдень по долготе может
  // стоять и у полуночи, и путь «через вчера» тогда короче.
  const away = volumeWrapMinutes(now - place.noonMin + VOLUME_DAY_MIN / 2) - VOLUME_DAY_MIN / 2;
  return away * place.hourScale;
}

/**
 * Светило на небе: высота над горизонтом и сторона света по компасу.
 *
 * Счёт один на солнце и на месяц — у них разные склонение и часовой угол, а
 * треугольник тот же. Второго такого счёта в сборке быть не должно: разойдись
 * они, тень поехала бы от одного солнца, а свет в окнах от другого.
 */
export function volumeBodyAt(latDeg, declDeg, hourDeg) {
  const lat = Number(latDeg) * DEG;
  const decl = Number(declDeg) * DEG;
  const hour = (((Number(hourDeg) + 180) % 360) + 360) % 360 - 180;
  const sinAlt = Math.sin(lat) * Math.sin(decl) + Math.cos(lat) * Math.cos(decl) * Math.cos(hour * DEG);
  const altDeg = Math.asin(Math.max(-1, Math.min(1, sinAlt))) / DEG;
  const flat = Math.cos(altDeg * DEG) * Math.cos(lat);
  // В зените (и на полюсе) азимут не определён вовсе: делить не на что. Там
  // берётся полдень — юг в северном полушарии, север в южном.
  const cosAz =
    Math.abs(flat) < 1e-9 ? (lat >= 0 ? -1 : 1) : (Math.sin(decl) - Math.sin(altDeg * DEG) * Math.sin(lat)) / flat;
  const azDeg = Math.acos(Math.max(-1, Math.min(1, cosAz))) / DEG;
  return { altDeg, compassDeg: hour > 0 ? 360 - azDeg : azDeg };
}

/**
 * Где солнце в этот миг.
 *
 * `height` — высота над горизонтом в градусах, и она **уходит в минус**: ею
 * считается вся плавность (сумерки, звёзды, тон комнаты, тень), и обрыв на нуле
 * дал бы ступеньку ровно там, где её лучше всего видно. Ноль высоты — рассвет и
 * закат из подписи окна, ровно те же минуты.
 *
 * Полярный день и полярная ночь выходят из формулы сами: высота просто не
 * пересекает нуль ни разу за сутки. Отдельных ветвей под них больше нет — и это
 * не упрощение, а честность, потому что ветвь говорила бы то же самое.
 */
export function volumeSunAt(minutes, times, topDeg = 0) {
  const place = volumeSkyPlace(times);
  const hourDeg = volumeHourAngleDeg(minutes, place);
  const at = volumeBodyAt(place.latDeg, place.declDeg, hourDeg);
  const height = at.altDeg - VOLUME_HORIZON_DEG;
  return { up: height > 0, height, rise: height, az: volumePanoramaAz(at.compassDeg, topDeg), hourDeg };
}

/**
 * Где месяц и какой он.
 *
 * **Своим путём, а не солнечной дугой** (прямое слово тикета). Всё выходит из
 * одного числа — возраста луны в её месяце (`volumeMoonAgeDays`):
 *
 *   - **элонгация** `360° · возраст / месяц` — насколько луна ушла от солнца к
 *     востоку. Она же двигает луну по небу: часовой угол у неё солнечный минус
 *     элонгация, и за сутки она отстаёт от солнца на 12,2° — то есть всходит
 *     почти на час позже, чем вчера, как и положено;
 *   - **склонение** — та же эклиптика, что у солнца, только долгота своя:
 *     солнечная плюс элонгация. За месяц луна обходит её целиком, поэтому
 *     ходит она то высоко, то низко, а не по одной борозде;
 *   - **фаза** — `edge = cos(элонгация)`, подписанная полуось внутренней кромки
 *     серпа. Новолуние даёт +1 (кромка села на лимб, светить нечему),
 *     четверть — 0 (кромка прямая), полнолуние — −1 (кромка ушла на другой
 *     лимб, диск полон). Освещённая доля из неё же: `(1 − edge)/2`.
 *
 * **Точность.** Это правдоподобие, а не эфемериды, и вот чем за него заплачено:
 * луна идёт средним движением, без эвекции и вариации (до ±6° по долготе),
 * наклон её орбиты в 5,1° опущен (склонение заужено до ±23,4° вместо ±28,6°),
 * параллакса нет. Отсюда: фаза верна до четверти суток возраста, восход и заход
 * — до часа, высота — до пяти градусов. Для кадра, где месяц нарисован в семь
 * раз крупнее настоящего, этого довольно: видно, что серп растёт и убывает, что
 * полная луна стоит всю ночь, а молодая садится вслед за солнцем.
 */
export function volumeMoonAt(minutes, times, topDeg = 0) {
  const place = volumeSkyPlace(times);
  const ageDays = volumeMoonAgeDays(place.dayNumber, minutes, place.tzHours);
  const elongDeg = (360 * ageDays) / VOLUME_MOON_MONTH_DAYS;
  const declDeg = volumeDeclDeg(place.sunLonDeg + elongDeg);
  const at = volumeBodyAt(place.latDeg, declDeg, volumeHourAngleDeg(minutes, place) - elongDeg);
  const height = at.altDeg - VOLUME_HORIZON_DEG;
  const edge = Math.cos(elongDeg * DEG);
  return {
    up: height > 0,
    height,
    rise: height,
    az: volumePanoramaAz(at.compassDeg, topDeg),
    ageDays,
    elongDeg,
    edge,
    lit: (1 - edge) / 2,
  };
}

/**
 * Возраст луны в сутках от новолуния: 0 … 29,53.
 *
 * Считается от опорного новолуния средним месяцем. Настоящие новолуния гуляют
 * вокруг среднего на ±0,3 суток — это 4° фазы, то есть толщина серпа у
 * новолуния, и в кадре такая разница не читается.
 */
export function volumeMoonAgeDays(dayNumber, minutes, tzHours = 0) {
  const day = Number(dayNumber) + (volumeWrapMinutes(minutes) - (Number(tzHours) || 0) * 60) / VOLUME_DAY_MIN;
  const age = (day - VOLUME_MOON_EPOCH_DAY) % VOLUME_MOON_MONTH_DAYS;
  return age < 0 ? age + VOLUME_MOON_MONTH_DAYS : age;
}

/**
 * Куда у месяца смотрит освещённый край: угол от «вверх по экрану» по часовой
 * стрелке.
 *
 * Считается **по настоящим местам обоих светил**, а не назначается: рожки серпа
 * обязаны смотреть прочь от солнца, где бы оно ни стояло — в том числе под
 * горизонтом, откуда подсвечивает молодой месяц снизу.
 *
 * Счёт — три вектора в плоскости неба у месяца: сам месяц `m`, зенит и сторона
 * роста азимута. Направление на солнце, из которого вычтена составляющая вдоль
 * `m`, и даёт освещённую сторону; её угол меряется от зенита. Камера объёма не
 * кренится, поэтому зенит на экране — это «вверх», и угол переносится в кадр
 * как есть.
 */
export function volumeMoonTiltDeg(sun, moon) {
  const dir = (body) => {
    const alt = (Number(body && body.rise) || 0) * DEG;
    const az = (Number(body && body.az) || 0) * DEG;
    const flat = Math.cos(alt);
    return { x: flat * Math.cos(az), y: flat * Math.sin(az), z: Math.sin(alt), az, alt };
  };
  const m = dir(moon);
  const s = dir(sun);
  const dot = s.x * m.x + s.y * m.y + s.z * m.z;
  // Солнце за вычетом составляющей вдоль месяца — это и есть «куда светит».
  const px = s.x - dot * m.x;
  const py = s.y - dot * m.y;
  const pz = s.z - dot * m.z;
  // Зенит в той же плоскости и сторона роста азимута (на экране — вправо).
  const uz = 1 - m.z * m.z;
  const ux = -m.z * m.x;
  const uy = -m.z * m.y;
  const rx = -Math.sin(m.az);
  const ry = Math.cos(m.az);
  const up = px * ux + py * uy + pz * uz;
  const right = px * rx + py * ry;
  return Math.atan2(right, up) / DEG;
}

/**
 * Очерк месяца: замкнутая ломаная вокруг его середины, в точках экрана.
 *
 * **Одна формула на весь круг фаз** (G290) — и это же починка дефекта D48
 * («вместо серпа две пересекающиеся дуги, фигура похожа на линзу»). Прежний
 * месяц рисовался двумя окружностями в одном пути с разным обходом: внутренняя
 * вырезала дыру, но торчала за пределы диска, и торчащий кусок правило непустого
 * обхода заливало — отсюда вторая дуга, выгнутая не в ту сторону.
 *
 * У настоящего серпа кромки две и обе лежат на диске:
 *
 *   - **внешняя** — сам лимб, полуокружность радиуса `R`;
 *   - **внутренняя** — терминатор, то есть окружность раздела света и тени,
 *     повёрнутая к нам ребром: на картинке это **полуэллипс** с той же большой
 *     полуосью `R` и малой `edge · R`.
 *
 * `edge` приходит со знаком (`volumeMoonAt`), и знак — это и есть весь круг
 * фаз: `+1` новолуние, `0` четверть (полуось нулевая, кромка — прямая), `−1`
 * полнолуние. Обе кромки считаются **одной** записью `(edge·R·cos u, R·sin u)`,
 * поэтому через четверть фигура проходит без скачка: полуось меняет знак, а
 * ломаная остаётся той же.
 *
 * `tiltDeg` поворачивает очерк так, чтобы освещённая сторона смотрела на солнце
 * (`volumeMoonTiltDeg`): рожки растущего и убывающего смотрят в разные стороны
 * сами, без ветвей «растёт или убывает».
 */
export function volumeMoonShape(radius, edge, tiltDeg = 0, steps = VOLUME_MOON_STEPS) {
  const turn = Number(tiltDeg) * DEG;
  // Орт освещённой стороны и орт поперёк неё (у экрана ось `y` смотрит вниз).
  const lit = { x: Math.sin(turn), y: -Math.cos(turn) };
  const across = { x: Math.cos(turn), y: Math.sin(turn) };
  const out = [];
  const put = (along, side) => {
    out.push({ x: lit.x * along + across.x * side, y: lit.y * along + across.y * side });
  };
  const count = Math.max(4, Math.round(steps));
  const cut = Math.max(-1, Math.min(1, Number(edge)));
  // Лимб: от рожка к рожку через самую освещённую точку.
  for (let index = 0; index <= count; index += 1) {
    const u = -Math.PI / 2 + (Math.PI * index) / count;
    put(radius * Math.cos(u), radius * Math.sin(u));
  }
  // Терминатор: обратно, той же записью со своей полуосью.
  for (let index = count - 1; index >= 1; index -= 1) {
    const u = -Math.PI / 2 + (Math.PI * index) / count;
    put(radius * cut * Math.cos(u), radius * Math.sin(u));
  }
  return out;
}

/**
 * Насколько стемнело: доля тона ночи в каждой грани.
 *
 * Начинает темнеть не на закате, а когда солнце уже низко (6°): в жизни
 * золотой час темнее полудня, и ступенька ровно на горизонте читалась бы
 * выключателем. Потолок — `VOLUME_NIGHT_SHARE`, и это ответ на «ночь не
 * сильно тёмная».
 */
export function volumeNightShare(height) {
  return VOLUME_NIGHT_SHARE * volumeShare(Number(height) || 0, 6, -8);
}

/**
 * Небо по высоте солнца: верхний и нижний цвет растяжки.
 *
 * Небо **не красится часом** (`volumeTintRgb` к нему не применяется) — у него
 * свои цвета на каждую высоту, и ночью оно темнее комнаты нарочно: иначе ночь
 * не узнавалась бы, а комнату пришлось бы гасить до «ничего не видно».
 *
 * Полуденные цвета — ровно те, что были до таска 181: в полдень фон байт в
 * байт прежний.
 */
const VOLUME_SKY_KEYS = [
  { h: 14, top: [141, 191, 230], low: [220, 234, 244] },
  { h: 6, top: [132, 183, 226], low: [223, 231, 233] },
  { h: 1, top: [111, 159, 203], low: [206, 159, 114] },
  { h: -3, top: [60, 90, 134], low: [150, 104, 92] },
  { h: -7, top: [38, 58, 99], low: [74, 69, 104] },
  { h: -11, top: [15, 24, 48], low: [30, 42, 74] },
];

export function volumeSkyColors(height) {
  const value = Number(height) || 0;
  const keys = VOLUME_SKY_KEYS;
  if (value >= keys[0].h) return { top: keys[0].top, low: keys[0].low };
  for (let index = 1; index < keys.length; index += 1) {
    const upper = keys[index - 1];
    const lower = keys[index];
    if (value < lower.h) continue;
    const share = volumeShare(value, upper.h, lower.h);
    const mix = (a, b) => [
      Math.round(a[0] + (b[0] - a[0]) * share),
      Math.round(a[1] + (b[1] - a[1]) * share),
      Math.round(a[2] + (b[2] - a[2]) * share),
    ];
    return { top: mix(upper.top, lower.top), low: mix(upper.low, lower.low) };
  }
  const last = keys[keys.length - 1];
  return { top: last.top, low: last.low };
}

/** Цвет солнца: белое-жёлтое высоко, рыжее у горизонта. */
function volumeSunColors(height) {
  const share = volumeShare(Number(height) || 0, 10, 0);
  const mix = (a, b) => [
    Math.round(a[0] + (b[0] - a[0]) * share),
    Math.round(a[1] + (b[1] - a[1]) * share),
    Math.round(a[2] + (b[2] - a[2]) * share),
  ];
  const body = mix([255, 243, 196], [255, 164, 86]);
  const halo = mix([255, 243, 196], [255, 136, 70]);
  return { body: "rgb(" + body.join(",") + ")", halo: "rgba(" + halo.join(",") + ",0.35)" };
}

/**
 * Снимок часа: всё, что зависит от времени, в одном объекте.
 *
 * Считается не чаще раза в секунду и **не в кадре**. Кадр берёт отсюда готовые
 * цвета и готовое место светила; при стоячем времени снимок считается один раз
 * и живёт, пока человек не тронет часы.
 */
export function volumeMood(options = {}) {
  const times = options.times || { riseMin: VOLUME_SUNRISE_MIN, setMin: VOLUME_SUNSET_MIN };
  const topDeg = Number(options.topDeg) || 0;
  const minutes = volumeWrapMinutes(options.minutes === undefined ? VOLUME_DAY_MIN / 2 : options.minutes);
  const kind = volumeBackdropKindOf(options.kind);
  const sun = volumeSunAt(minutes, times, topDeg);
  const place = volumeMoonAt(minutes, times, topDeg);
  const share = volumeNightShare(sun.height);
  const tint = { rgb: VOLUME_NIGHT_RGB, share };
  const sky = volumeSkyColors(sun.height);
  // Месяц виден не всегда, когда он над горизонтом: настоящая луна половину
  // месяца стоит в дневном небе и там не читается вовсе. Поэтому у него своя
  // яркость — от высоты **солнца**, как у звёзд, только порог выше: месяц
  // проступает уже в сумерках, когда звёзд ещё нет.
  const moon = {
    ...place,
    tiltDeg: volumeMoonTiltDeg(sun, place),
    glow: volumeShare(sun.height, 3, -4),
  };
  return {
    minutes,
    times,
    topDeg,
    kind,
    phase: volumeDayPhase(minutes, times),
    sun,
    moon,
    tint,
    sky: { top: "rgb(" + sky.top.join(",") + ")", low: "rgb(" + sky.low.join(",") + ")" },
    sunColors: volumeSunColors(sun.height),
    // Звёзды зажигаются после сумерек и только там, где небо уже тёмное.
    stars: volumeShare(sun.height, -2, -7),
    // Окна города: к ночи загораются, днём гаснут (слова заказчика «как живой
    // город»). Доля — сколько окон светится, а какие именно, решает не случай,
    // а сами окна (`volumeCityWindowLit`): иначе они мигали бы каждую секунду.
    cityLit: VOLUME_CITY_LIT_MAX * volumeShare(sun.height, 4, -6),
    // Тень дома: куда её кладёт солнце сейчас и насколько она видна. У
    // горизонта она не тянется в бесконечность, а гаснет — так же плавно, как
    // темнеет небо.
    shadow: { az: sun.az, rise: sun.rise, fade: sun.up ? volumeShare(sun.height, 1, 7) : 0 },
    palette: volumeBackdropPalette(tint),
  };
}

/**
 * Тон часа для вещей панорамы: одна палитра на весь фон, покрашенная один раз
 * вместе со снимком часа.
 *
 * Земля здесь — тот же `VOLUME_LAND_RGB`, что у земляной плиты сцены, и
 * покрашена она тем же `volumeTintRgb`: стык между землёй у дома и землёй за
 * ним не виден ни в полдень, ни в полночь (G237 держится и во времени).
 */
export function volumeBackdropPalette(tint) {
  const css = (hex) => volumeTintCss(volumeHexRgb(hex), tint);
  return {
    land: volumeTintCss(VOLUME_LAND_RGB, tint),
    cloud: css(VOLUME_CLOUD),
    trunk: css(VOLUME_TRUNK),
    crown: css(VOLUME_CROWN),
    crownFar: css(VOLUME_CROWN_FAR),
    crownDark: css(VOLUME_CROWN_DARK),
    bush: css(VOLUME_BUSH),
    birchTrunk: css(VOLUME_BIRCH_TRUNK),
    birchMark: css(VOLUME_BIRCH_MARK),
    birchCrown: css(VOLUME_BIRCH_CROWN),
    willow: css(VOLUME_WILLOW),
    roadNear: css(VOLUME_ROAD_NEAR),
    roadFar: css(VOLUME_ROAD_FAR),
    riverNear: css(VOLUME_RIVER_NEAR),
    riverFar: css(VOLUME_RIVER_FAR),
    hillFar: css(VOLUME_HILL_FAR),
    hillNear: css(VOLUME_HILL_NEAR),
    rock: css(VOLUME_MOUNTAIN_ROCK),
    rockFar: css(VOLUME_MOUNTAIN_FAR_ROCK),
    snow: css(VOLUME_MOUNTAIN_SNOW),
    snowFar: css(VOLUME_MOUNTAIN_FAR_SNOW),
    wall: css(VOLUME_CITY_WALL),
    wallFar: css(VOLUME_CITY_WALL_FAR),
    wallSide: css(VOLUME_CITY_SIDE),
    wallSideFar: css(VOLUME_CITY_SIDE_FAR),
    glass: css(VOLUME_CITY_GLASS),
    roof: css(VOLUME_CITY_ROOF),
    asphalt: css(VOLUME_CITY_ASPHALT),
    asphaltFar: css(VOLUME_CITY_ASPHALT_FAR),
    mark: css(VOLUME_CITY_MARK),
    car: VOLUME_CITY_CARS.map((hex) => css(hex)),
  };
}

/** `#rrggbb` в тройку чисел: палитра фона писана цветами, а час считает числами. */
function volumeHexRgb(hex) {
  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
}

// ——— три фона (G273) ——————————————————————————————————————————————————
//
// Слова заказчика: «Тип фона — Простой…, Природа…, Город…».
//
//   **Простой** — зелёная земля, голубое небо и светило. Больше ничего: ни
//     дороги, ни гор, ни деревьев. Светило заказчик назвал прямо — «на простом
//     отображении фона тоже сделай солнце и луну, что бы было очевидно», — и
//     звёзды оставлены с ним: звёзды это небо, а не пейзаж.
//   **Природа** — то, что было (дорога, река, холмы, горы, зелень), плюс ещё
//     немного берёз.
//   **Город** — многоэтажки, улицы, парковка с машинами. Мера та же, что у
//     «Природы»: узнаваемый силуэт, а не макет города.
//
// Выбор живёт **в настройках браузера**, а не в объекте, и это не мелочь:
// фон — вид, а не свойство квартиры. Уехав в `project.json`, он пришёл бы к
// напарнику вместе с проектом и переставил бы ему картинку за окном; а G68
// потребовал бы миграции ради того, что человек меняет кнопкой. Координаты
// (таск 188) — наоборот, свойство объекта, и живут в нём.

export const VOLUME_BACKDROP_KINDS = ["plain", "nature", "city"];
export const VOLUME_BACKDROP_DEFAULT = "nature";

export function volumeBackdropKindOf(kind) {
  return VOLUME_BACKDROP_KINDS.includes(kind) ? kind : VOLUME_BACKDROP_DEFAULT;
}

// ——— город ———————————————————————————————————————————————————————————————
//
// Дом панорамы — та же вещь, что дерево: сторона света, высота основания,
// угловая высота. Прибавилось одно — **ширина**: у дерева силуэт один на любую
// ширину, а дом без ширины не дом. Поэтому у многоэтажки `half` (половина
// ширины в градусах), и рисуется она четырьмя точками панорамы, как звено
// полосы.
//
// Окна считаются по сетке этажей и секций, и **какое окно светится, решают
// сами окна**, а не случай: `volumeCityWindowLit` — ровная постоянная примесь
// от номера дома, этажа и секции. Поэтому к вечеру окна загораются по одному и
// больше не мигают: доля растёт — зажигаются новые, а зажжённые остаются.
//
// Светящееся окно **не красится часом**: это свет, а не освещённая
// поверхность. Правило простое и сквозное — *светит, значит не темнеет*: так
// же не темнеют солнце, месяц и звёзды, и так же темнеет всё остальное.

const VOLUME_CITY_WALL = "#9aa3b0";
const VOLUME_CITY_WALL_FAR = "#b9c0ca";
const VOLUME_CITY_SIDE = "#7d8694";
const VOLUME_CITY_SIDE_FAR = "#a7afba";
const VOLUME_CITY_GLASS = "#5d6b7d";
const VOLUME_CITY_ROOF = "#6d7684";
const VOLUME_CITY_ASPHALT = "#8d8f92";
const VOLUME_CITY_ASPHALT_FAR = "#c2c4c7";
const VOLUME_CITY_MARK = "#d8dadd";
const VOLUME_CITY_CARS = ["#b5443c", "#3f5e8c", "#d8d9dc", "#4f6f52", "#2f3338"];
/** Свет в окне — он же самое яркое в ночном кадре. */
const VOLUME_CITY_LIGHT = "#ffe6a3";
/** Какая доля окон светится в самую тёмную ночь: дом спит, а не празднует. */
const VOLUME_CITY_LIT_MAX = 0.55;

/**
 * Рекламные щиты у дороги (G310): полотно и краска полос. Текста нет — писать
 * на щите значило бы придумывать чужую рекламу.
 */
const VOLUME_CITY_BANNERS = [
  { back: "#d94f3d", mark: "#ffe8c8" },
  { back: "#2f6fb5", mark: "#eaf3ff" },
  { back: "#f0b429", mark: "#5b3a00" },
  { back: "#3b8f57", mark: "#eafbe8" },
];

/**
 * Многоэтажки по кругу: место на земле, половина ширины лица, половина глубины,
 * высота — и **сетка окон, посчитанная из метров**.
 *
 * ——— отчего дома выглядели сплюснутыми (дефект D57) ———————————————————————
 *
 * Слова заказчика: «по вертикали дома сплюснытые». Беда была **не в высоте и не
 * в дальности**, а в сетке окон: `floors` и `bays` писались руками, порознь от
 * настоящих метров. Замер прежних чисел: высота этажа выходила 3,2…3,8 м (это
 * верно, так и строят), а ширина секции — **8,4…17,3 м**, то есть ячейка окна
 * была вчетверо-впятеро шире себя (отношение 4,0…5,0 у дальнего ряда, 2,5…2,9 у
 * ближнего). Глаз читает масштаб дома по окнам, и дом в ровную горизонтальную
 * полоску читается приплюснутым — хоть ты сделай его вдвое выше.
 *
 * Поэтому сетка больше не пишется руками: **этаж 3,2 м, секция 3,5 м**, и число
 * строк со столбцами выходит делением. Ячейка получается 3,5 × 3,2 — почти
 * квадратной, как в настоящем доме, и пропорции сходятся сами на любой высоте и
 * ширине.
 */
export const VOLUME_CITY_FLOOR_MM = 3200;
export const VOLUME_CITY_BAY_MM = 3500;

/**
 * Ширина окна в экранных точках, ниже которой дом рисуется **этажами, а не
 * окнами**: три точки. Окно у́же трёх точек сливается с соседним в полосу и
 * нарисованное поимённо стоит ровно столько же, сколько нарисованное полосой, —
 * а полоса это одна заливка вместо шести-девяти. Светящиеся окна дорисовываются
 * поверх полосы и тогда: их доля ночью не больше `VOLUME_CITY_LIT_MAX`.
 */
const VOLUME_CITY_WINDOW_PX = 3;

/**
 * Дом — **коробка, а не щит** (дефект D57, долг таска 199). Кроме лица у него
 * есть глубина, и в кадр попадают две стены и крыша: какая из боковых видна,
 * решает сама камера. При облёте дом поворачивается, а не схлопывается.
 *
 * Своего на лице у дома больше ничего нет: вывеску (G310) снял G337, и поля
 * `sign` у записи не стало вовсе — дом описывается местом, габаритом и сеткой
 * окон.
 */
function volumeBlock(az, away, halfM, deepM, heightM, far) {
  const spot = volumeAway(az, away);
  const halfMm = halfM * VOLUME_M;
  const heightMm = heightM * VOLUME_M;
  return {
    x: spot.x,
    y: spot.y,
    awayMm: away * VOLUME_M,
    halfMm,
    deepMm: deepM * VOLUME_M,
    heightMm,
    floors: Math.max(2, Math.round(heightMm / VOLUME_CITY_FLOOR_MM)),
    bays: Math.max(2, Math.round((halfMm * 2) / VOLUME_CITY_BAY_MM)),
    far: Boolean(far),
  };
}

/**
 * Два ряда домов. Ближний стоит в **95…150 м** — это дом через дорогу: сорок
 * метров высоты с уровня глаз дают 23°, и дом занимает треть неба, а не
 * полоску у горизонта (до таска 206 он стоял в 220…300 м и давал 5…10°).
 * Дальний ряд — 260…430 м, он заслоняется ближним и держит горизонт
 * застроенным.
 *
 * Дома **у́же, чем были**: лицо 18…30 м вместо прежних 34…68. Широкая плита в
 * полсотни метров сама по себе читается приземистой, сколько ни добавляй ей
 * высоты.
 */
export const VOLUME_CITY = [
  // дальний ряд — за улицей, бледный
  volumeBlock(8, 330, 13, 11, 30, true),
  volumeBlock(24, 410, 11, 9, 26, true),
  volumeBlock(58, 285, 15, 12, 32, true),
  volumeBlock(96, 370, 12, 10, 28, true),
  volumeBlock(131, 310, 14, 11, 32, true),
  volumeBlock(168, 395, 11, 9, 25, true),
  volumeBlock(205, 265, 16, 12, 33, true),
  volumeBlock(241, 380, 12, 10, 27, true),
  volumeBlock(278, 320, 14, 11, 31, true),
  volumeBlock(316, 425, 11, 9, 24, true),
  volumeBlock(344, 295, 13, 11, 33, true),
  // ближний ряд — высокие, тёмнее и шире
  volumeBlock(40, 120, 11, 14, 40, false),
  volumeBlock(112, 98, 9, 12, 44, false),
  volumeBlock(186, 145, 15, 16, 36, false),
  volumeBlock(258, 110, 10, 13, 46, false),
  volumeBlock(330, 132, 12, 15, 38, false),
];

/**
 * Светится ли это окно при такой доле зажжённых.
 *
 * Чистая и постоянная: номер дома, этаж и секция дают одно и то же число
 * всегда. Случай здесь не годится вовсе — окна мигали бы на каждом снимке
 * часа, то есть каждую секунду.
 */
export function volumeCityWindowLit(block, floor, bay, share) {
  if (!(share > 0)) return false;
  // Перемешивание тремя множителями — обычный целочисленный хэш: соседние окна
  // получают далёкие числа, и свет не выстраивается полосами и лестницами.
  const mixed = ((block + 1) * 73856093) ^ ((floor + 1) * 19349663) ^ ((bay + 1) * 83492791);
  return ((mixed >>> 8) % 1000) / 1000 < share;
}

/**
 * Машины на парковке: место на земле, высота и цвет из палитры. Стоят рядком у
 * ближнего дома — после таска 206 в 45…70 м, а не в сотне: полтора метра
 * высоты дают оттуда 1,2…1,9°, и видно, что это машины, а не точки.
 */
function volumeCar(az, away, heightM, car) {
  const spot = volumeAway(az, away);
  return { x: spot.x, y: spot.y, awayMm: away * VOLUME_M, heightMm: heightM * VOLUME_M, car };
}

export const VOLUME_CITY_PARK = [
  volumeCar(150, 62, 1.5, 0),
  volumeCar(154, 58, 1.5, 1),
  volumeCar(158, 54, 1.6, 2),
  volumeCar(162, 50, 1.6, 3),
  volumeCar(166, 47, 1.7, 4),
  volumeCar(170, 45, 1.7, 1),
  volumeCar(290, 60, 1.5, 2),
  volumeCar(294, 56, 1.6, 0),
  volumeCar(298, 52, 1.6, 4),
  volumeCar(302, 48, 1.7, 3),
];

/**
 * Рекламные щиты у дороги (G310): место, половина ширины полотна, высота
 * полотна и высота его низа над землёй.
 *
 * Стоят они **вдоль улиц**, по которым и расставлены: шесть метров полотна в
 * полусотне метров дают 7°, то есть щит читается щитом, а не пятном. Ноги
 * поднимают полотно на три-четыре метра — так их и ставят, чтобы не мешали
 * тротуару.
 */
function volumeBanner(az, away, halfM, heightM, bottomM, paint) {
  const spot = volumeAway(az, away);
  return {
    x: spot.x,
    y: spot.y,
    awayMm: away * VOLUME_M,
    halfMm: halfM * VOLUME_M,
    heightMm: heightM * VOLUME_M,
    bottomMm: bottomM * VOLUME_M,
    paint,
  };
}

export const VOLUME_CITY_BANNER_PLACES = [
  volumeBanner(140, 52, 3.2, 3.6, 3.4, 0),
  volumeBanner(196, 68, 3.6, 4, 3.8, 1),
  volumeBanner(268, 58, 3, 3.4, 3.2, 2),
  volumeBanner(322, 75, 3.8, 4.2, 4, 3),
  volumeBanner(64, 88, 3.4, 3.8, 3.6, 1),
];

/**
 * Улицы города: те же полосы, что дорога «Природы», только шире и с разметкой.
 * После таска 206 ближнее колено в 55…60 м вместо 120: улица должна лежать
 * перед домами, а не теряться за ними.
 */
export const VOLUME_CITY_STREETS = [
  volumeBandNodes(
    [
      [134, 58],
      [148, 95],
      [163, 150],
      [178, 230],
      [193, 340],
      [208, 480],
    ],
    16,
  ),
  volumeBandNodes(
    [
      [274, 62],
      [288, 100],
      [303, 160],
      [318, 250],
      [333, 370],
      [348, 520],
    ],
    16,
  ),
];

/** Разметка по середине улицы: та же полоса, только в полметра шириной. */
function volumeStreetMarks(street) {
  return street.map((node) => {
    const dx = node.left.x - node.right.x;
    const dy = node.left.y - node.right.y;
    const len = Math.hypot(dx, dy) || 1;
    const half = (0.25 * VOLUME_M) / len;
    return {
      x: node.x,
      y: node.y,
      awayMm: node.awayMm,
      left: { x: node.x + dx * half, y: node.y + dy * half },
      right: { x: node.x - dx * half, y: node.y - dy * half },
    };
  });
}

export const VOLUME_CITY_MARKS = VOLUME_CITY_STREETS.map((street) => volumeStreetMarks(street));

/** Деревья вдоль улиц: город не бетонная коробка, но и не лес. */
export const VOLUME_CITY_GREENS = [
  volumeStanding(143, 66, 9, "tree"),
  volumeStanding(176, 105, 7, "tree"),
  volumeStanding(199, 150, 2.4, "bush"),
  volumeStanding(283, 70, 8.5, "tree"),
  volumeStanding(311, 112, 7.5, "tree"),
  volumeStanding(341, 145, 2.6, "bush"),
];

/** Звёзды: раскиданы по небу раз и навсегда, своей яркости у каждой нет. */
export const VOLUME_STARS = (() => {
  const stars = [];
  // Числа ровные и постоянные: тот же целочисленный хэш, что у окон города.
  for (let index = 0; index < 48; index += 1) {
    const mixed = ((index + 1) * 2654435761) >>> 0;
    stars.push({
      az: (mixed % 3600) / 10,
      rise: 6 + ((mixed >>> 12) % 520) / 10,
      size: 0.8 + ((mixed >>> 22) % 70) / 100,
    });
  }
  return stars;
})();

/** Полдень по умолчанию: фон, который был до таска 181. Им же рисуется кадр,
 * пока снимок часа не посчитан. */
export const VOLUME_MOOD_NOON = volumeMood({
  minutes: (VOLUME_SUNRISE_MIN + VOLUME_SUNSET_MIN) / 2,
  kind: VOLUME_BACKDROP_DEFAULT,
});

// ——— обзор со стороны ————————————————————————————————————————————————————

// ——— предел стояния снят (таск 200, G304) ———————————————————————————————
//
// Таск 195 завёл `volumeAroundStand`: взгляд задирался свободно, а место камеры
// держалось над крышей — ровно затем, чтобы камера не оказалась **внутри**
// стены, где кадр становится серым полем и читается как поломка.
//
// Заказчик этот предел снял сам: «по камере — ок, пусть в стенах оказываемся,
// это ожидаемо». Поэтому **серый кадр внутри стены снова возможен, и это его
// выбор, а не дефект сборки.** Замены пределу нет и заводить её нельзя: ни
// выталкивания камеры из стены, ни гашения ближних граней — обзор получил
// механику полёта (пробел выше, Control ниже, ход по взгляду) и летает сквозь
// стены всегда, потому что камера — не человек.
//
// Что осталось от прежнего устройства: **цель обзора больше не хранится**. У
// обзора хранится место камеры (`eye`), а цель — точка перед ней на
// `distance`, то есть та, в которую она летит. Поэтому «брошенной цели на
// другом конце квартиры» не бывает: вращение крутит точку перед собой, а
// колесо подводит камеру к ней.

/**
 * Где стоит камера, смотрящая на `target` с расстояния `distance`.
 *
 * Этим считают **кадрирование**: «Обзор» ставит камеру на человека, «Вся
 * схема» — на середину чертежа, колесо подводит её к той же цели ближе. Пол
 * держит и здесь (`volumeGroundMm`): задранный взгляд с близкой целью иначе
 * увёл бы камеру под плиту.
 */
export function volumeAroundEye(target, yaw, pitch, distance) {
  const basis = volumeBasis({ yaw, pitch });
  return {
    x: target.x - basis.fwd.x * distance,
    y: target.y - basis.fwd.y * distance,
    z: volumeGroundMm(target.z - basis.fwd.z * distance),
  };
}

/**
 * Цель обзора: точка перед камерой на `distance`. Своей цели обзор не хранит —
 * разбор выше, у `volumeAroundEye`.
 */
export function volumeAroundTarget(eye, yaw, pitch, distance) {
  const basis = volumeBasis({ yaw, pitch });
  return {
    x: eye.x + basis.fwd.x * distance,
    y: eye.y + basis.fwd.y * distance,
    z: eye.z + basis.fwd.z * distance,
  };
}

/** Камера, смотрящая на `target` с расстояния `distance`: место и взгляд. */
export function volumeAroundCamera(target, yaw, pitch, distance) {
  return { at: volumeAroundEye(target, yaw, pitch, distance), yaw, pitch };
}

// ——— одна мера обзора (таск 207, G311 и G312) ————————————————————————————
//
// Слова заказчика: «почему движение мыши с зажатой клавишей перемещает камеру
// вокруг какой-то цели, а не просто поворачивает камеру как при виде от 1
// лица? должно быть так же».
//
// Орбиты больше нет: мышь вертит камеру **на месте**, тем же правилом, что в
// первом лице. Вместе с орбитой ушла и хранимая `distance` — расстояние до
// цели, которую больше никто не обходит. Два смысла у неё оставлять нельзя
// (прямое требование тикета), поэтому смысл один и он **считается, а не
// хранится**: `volumeAroundReach` — докуда обзор достаёт до пола по взгляду.
//
// Этой одной мерой живёт всё, что спрашивало расстояние:
//
//   - **шаг колеса и щипка**: они везут камеру по взгляду на долю меры, то
//     есть приближение больше не упирается в предел и не умирает в комнате;
//   - **свайп двумя пальцами** (`volumeAroundPan`): мера пикселя — `distance /
//     focal`, и с таска 207 это **честная** глубина пола. До него там лежала
//     длина орбитальной руки, которую полёт не трогал: слетев с тридцати
//     метров в комнату, человек возил карту мерой тридцати метров (дефект,
//     заведённый таском 200);
//   - **скорость полёта** (`volumeAroundSpeed`).
//
// Кадрирование («Обзор», «Вся схема») расстоянием по-прежнему **пользуется**,
// но как доводом: поставило место и взгляд — мера посчиталась сама.

/**
 * Докуда обзор достаёт до пола по взгляду — одна мера на приближение, свайп и
 * скорость.
 *
 * Отвесно вниз это высота камеры, наискось — длиннее, в горизонт и вверх пола
 * нет вовсе, и мера берётся по самому пологому взгляду, на котором его ещё
 * считают (`VOLUME_AROUND_TILT_MIN`, тот же предел, что у свайпа). У земли,
 * где до пола ноль, снизу держит `VOLUME_AROUND_MIN_MM`: иначе и колесо, и
 * полёт встали бы намертво ровно там, куда заказчик просил пускать камеру.
 */
export function volumeAroundReach(eye, pitch) {
  const down = Math.max(VOLUME_AROUND_TILT_MIN, -Math.sin(Number(pitch) || 0));
  return volumeAroundDistance((Number(eye && eye.z) || 0) / down);
}

/**
 * Как быстро летит обзор (таск 207, G311): он покрывает то, до чего достаёт,
 * за `VOLUME_AROUND_FLY_S`.
 *
 * **Вблизи точность, издали размах** — и это не две скорости, а одно
 * отношение. Числа на объекте заказчика (квартира 9,8 × 9,9 м):
 *
 *   - «Вся схема» — камера в 18 м над планом, мера 27 м, скорость **18 м/с**:
 *     квартиру пролетает за полсекунды, с Shift — вчетверо быстрее пешехода;
 *   - в комнате на высоте глаз при взгляде чуть вниз мера 4,7 м, скорость
 *     **3,1 м/с** — четверть сверх пешехода, то есть ход, а не рывок;
 *   - у самой земли мера упирается в полтора метра, и скорость была бы
 *     0,9 м/с — медленнее человека. Поэтому снизу её держит **шаг пешехода**:
 *     обзор нигде не ходит медленнее, чем ходит человек.
 *
 * Shift удваивает, как удваивал: бег и полёт — одно и то же движение в разных
 * видах, и второго множителя для обзора не заводится.
 */
export function volumeAroundSpeed(reachMm, run) {
  const want = volumeAroundDistance(reachMm) / VOLUME_AROUND_FLY_S;
  const base = Math.max(VOLUME_WALK_MM_S, want);
  return run ? base * 2 : base;
}

/**
 * Обзор, в котором видно всю схему: цель — середина чертежа, расстояние —
 * такое, чтобы габарит уместился в поле. Окно открывается именно им: заказчик
 * сказал, что показ начинается с общего вида.
 */
export function volumeAroundFit(scene, box) {
  // Габарит в плане: у одной схемы — её чертёж, у стопки этажей — все они
  // вместе (таск 202).
  const bounds = (scene.stackMm && scene.stackMm.boundsMm) || scene.boundsMm;
  // Габарит по вертикали: у одной схемы — её высота от нуля, у стопки этажей
  // (таск 202) — вся она, от пола нижнего этажа до потолка верхнего. Отсчёт
  // идёт от пола открытой схемы, поэтому низ стопки бывает отрицательным, и
  // середина вместе с ним уходит вниз: взять `height / 2` значило бы навести
  // камеру на небо над домом.
  const span = scene.stackMm || { bottomMm: 0, topMm: scene.heightMm || WALL_HEIGHT_FALLBACK_MM };
  const height = Math.max(1, span.topMm - span.bottomMm);
  const middle = (span.topMm + span.bottomMm) / 2;
  if (!bounds) {
    return { target: { x: 0, y: 0, z: middle }, distance: VOLUME_AROUND_NEAR_MM };
  }
  const target = {
    x: (bounds.minX + bounds.maxX) / 2,
    y: (bounds.minY + bounds.maxY) / 2,
    z: middle,
  };
  // Габарит берётся с выносом: стены стоят толщиной за своими осями, пол под
  // ними — с напуском (D37), и всё это обязано попасть в кадр.
  const outset = (scene.outsetMm || 0) * 2;
  const radius = Math.hypot(bounds.widthMm + outset, bounds.heightMm + outset, height) / 2;
  const focal = volumeFocal(box);
  const fit = (radius * focal) / (0.42 * Math.min(box.width, box.height));
  return { target, distance: volumeAroundDistance(fit) };
}

export function volumeAroundDistance(value) {
  return Math.max(VOLUME_AROUND_MIN_MM, Math.min(VOLUME_AROUND_MAX_MM, value));
}

/**
 * Перенос обзора двумя пальцами: ход середины между пальцами — в сдвиг цели по
 * полу, миллиметры (таск 174, требование G256).
 *
 * Слова заказчика: «сделай в объеме на мобильном интерфейсе что бы карта в
 * режиме сверху двигалась 2 пальцами». Сам жест разбирает общий `gestures.js`
 * (`gesturePinchStep` отдаёт и множитель масштаба, и ход середины) — а перевести
 * этот ход в миллиметры может только камера: это её счёт, и он здесь.
 *
 * Тем же ходом возит и двухпальцевый свайп трекпада (таск 195, требование
 * G299): жест разбирает тот же `gestures.js` (`gestureWheel` отдаёт `pan` с
 * готовым ходом в экранных точках), а перевод в миллиметры здесь один на оба
 * устройства.
 *
 * Правило — **пол едет за пальцами**: куда ушла середина, туда уехала карта, а
 * камера на столько же в обратную сторону. Ответ — сдвиг **по полу**, и высота
 * камеры им не меняется: вверх и вниз обзор ходит пробелом и Control (таск
 * 200), а свайп — это «скролл», слово заказчика.
 *
 * Мера одного пикселя — `distance / focal`: ширина пикселя на той глубине, где
 * лежит цель. Отошли дальше — палец возит крупнее, и это ровно то, что видно
 * глазом.
 *
 * Поперёк взгляда счёт точный: камера не кренится, и экранное «вправо» лежит
 * на полу целиком. Вдоль — в сторону взгляда, положенного на пол, и с
 * поправкой на наклон: пол на экране сжат ровно во столько, во сколько короче
 * единицы экранный «верх», положенный на пол (это синус наклона). Без поправки
 * карта отставала бы от пальца вверх-вниз, хотя поперёк шла бы вровень.
 *
 * Сторона берётся у **взгляда**, а не у «верха» (таск 195): у задранного
 * взгляда горизонтальная часть «верха» разворачивается назад, и карта поехала
 * бы от пальца в обратную сторону. На опущенном взгляде — а другого до таска
 * 195 в обзоре не было — обе стороны это одно и то же направление, и числа от
 * замены не изменились ни на бит.
 *
 * Поправка **ограничена** `VOLUME_AROUND_TILT_MIN`: у почти
 * горизонтального взгляда она уходит в бесконечность — пол под пальцем там
 * лежит у горизонта, то есть в километрах, — и один мах уносил бы обзор
 * неизвестно куда. Положе двадцати градусов карта просто отстаёт от пальца, и
 * это по-прежнему управляемо.
 */
export function volumeAroundPan(view, box, panX, panY) {
  const distance = Number(view && view.distance) || 0;
  const focal = box ? volumeFocal(box) : 0;
  if (!(distance > 0) || !(focal > 0)) return { dx: 0, dy: 0 };
  const perPixel = distance / focal;
  const basis = volumeBasis({ yaw: view.yaw, pitch: view.pitch });
  // Взгляд, положенный на пол, — сторона сдвига вдоль. У отвесного взгляда
  // класть нечего (он сам отвесный), и сторону даёт рысканье — то же самое
  // направление в пределе.
  const flat = Math.hypot(basis.fwd.x, basis.fwd.y);
  const forward =
    flat > 1e-9
      ? { x: basis.fwd.x / flat, y: basis.fwd.y / flat }
      : { x: Math.cos(view.yaw || 0), y: Math.sin(view.yaw || 0) };
  // Экранный «верх», положенный на пол: его длина и есть мера сжатия пола
  // (синус наклона). Знака у неё нет — сторону уже дал взгляд.
  const lean = Math.hypot(basis.up.x, basis.up.y);
  const tilt = Math.max(VOLUME_AROUND_TILT_MIN, lean);
  const across = -(Number(panX) || 0) * perPixel;
  const along = ((Number(panY) || 0) * perPixel) / tilt;
  return {
    dx: basis.right.x * across + forward.x * along,
    dy: basis.right.y * across + forward.y * along,
  };
}

/**
 * Где стоит человек — кружок на полу и треугольник взгляда.
 *
 * Заказчик про обзор: «без него не понять, где стоишь». Значит обзор обязан
 * показать не только комнату, но и самого смотрящего — иначе он отвечает на
 * половину вопроса. Кружок лежит чуть выше пола и идёт **последним ярусом**,
 * поверх всего: ближняя стена под углом прячет за собой полосу пола метра в
 * три, и указатель, который она закрывает, бесполезен.
 *
 * Радиус — `VOLUME_MARKER_MM`, и он вдвое меньше прежнего (G212: «Позицию на
 * схеме на обзорном виде сделай меньше»). Кружок в 320 мм на обзоре квартиры
 * закрывал собой полметра пола — то есть ровно то место, куда человек
 * собирался перейти кликом.
 */
export function volumeMarkerFaces(at, yaw, out = [], radiusMm = VOLUME_MARKER_MM) {
  const radius = radiusMm;
  const lift = 15;
  const circle = [];
  const steps = 14;
  for (let index = 0; index < steps; index += 1) {
    const angle = (index / steps) * Math.PI * 2;
    circle.push({ x: at.x + Math.cos(angle) * radius, y: at.y + Math.sin(angle) * radius, z: lift });
  }
  out.push(volumeFace(volumeClockwise(circle).map((point) => ({ ...point, z: lift })), VOLUME_MARKER_RGB, {
    normal: { x: 0, y: 0, z: 1 },
    layer: VOLUME_LAYER_MARK,
  }));
  const tip = { x: at.x + Math.cos(yaw) * radius * 2.4, y: at.y + Math.sin(yaw) * radius * 2.4, z: lift };
  const left = {
    x: at.x + Math.cos(yaw + Math.PI / 2) * radius * 0.62,
    y: at.y + Math.sin(yaw + Math.PI / 2) * radius * 0.62,
    z: lift,
  };
  const right = {
    x: at.x + Math.cos(yaw - Math.PI / 2) * radius * 0.62,
    y: at.y + Math.sin(yaw - Math.PI / 2) * radius * 0.62,
    z: lift,
  };
  out.push(volumeFace(volumeClockwise([tip, left, right]).map((point) => ({ ...point, z: lift })), VOLUME_MARKER_RGB, {
    normal: { x: 0, y: 0, z: 1 },
    layer: VOLUME_LAYER_MARK,
  }));
  return out;
}
